window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["L2"]={"deck":"L2","slides":[{"p":1,"title":"2강 표지, 실내건축시공실무 총론","terms":["시공"],"pass1":[{"kind":"say","lines":["2강은 인테리어 공사 한 건이 처음부터 끝까지 어떻게 굴러가는지 배워요.","오늘부터 계속 외울 주문은 '사람 → 방식 → 입찰 → 계획 → 관리 → 준공' 이에요.","**시공**이 무엇인지, 누가 어떤 일을 하는지부터 차근차근 볼게요."]},{"kind":"points","head":"표지가 알려 주는 것","items":["과목 이름은 실내디자인 시공과 실무 (Interior Design Construction and Practice)","이 덩어리 이름은 '#1 실내건축시공실무 총론' 이에요.","아래쪽 참고문헌 네 권은 외우지 않아도 돼요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"say","lines":["왼쪽 사진은 비계, 즉 높은 곳에서 일하려고 세우는 임시 발판이에요.","2강 뒷부분 가설공사에서 다시 만나니 눈에만 익혀 두세요."]},{"kind":"points","head":"총론에서 배우는 **시공**의 자리","items":["설계가 끝나고 도면이 나온 다음, 실제로 공간을 만드는 단계가 **시공**이에요.","총론은 그 시공 한 건의 '서류와 사람' 쪽 이야기예요.","뒤에 나오는 가설공사, 철거공사가 현장에서 몸으로 하는 첫 작업이에요."]}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.0,0.0,0.5,1.0],"c":[0,0.0,0.55,1],"r":0.9778,"img":"img/L2/walk/p001_20_01.jpg","say":"왼쪽 사진은 비계, 즉 높은 곳에서 일하려고 세우는 임시 발판이에요. 2강 가설공사에서 다시 만나요."},{"b":[0.52,0.33,0.1,0.04],"c":[0.47,0.295,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p001_20_02.jpg","say":"2026-2. 이 강의가 열리는 학기예요."},{"b":[0.52,0.405,0.27,0.1],"c":[0.5065,0.389,0.297,0.132],"r":4.0,"img":"img/L2/walk/p001_20_03.jpg","say":"과목 이름이에요. 실내디자인 시공과 실무, Interior Design Construction and Practice."},{"b":[0.52,0.545,0.17,0.04],"c":[0.505,0.51,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p001_20_04.jpg","say":"이 덩어리 이름, #1 실내건축시공실무 총론이에요. 2강은 여기서 시작해요."},{"b":[0.735,0.855,0.25,0.1],"c":[0.7225,0.839,0.275,0.132],"r":3.7037,"img":"img/L2/walk/p001_20_05.jpg","say":"참고문헌 네 권이에요. 외우지 않아도 돼요."}]}},{"p":2,"title":"시공의 뜻과 총론 여덟 덩어리","terms":["시공","client, owner","designer","construction supervisor","builder, contractor","labor, worker","직영공사","도급","Turn-key","open competitive bidding","private competitive bidding","selective bidding","optional contract"],"pass1":[{"kind":"say","lines":["이 쪽은 2강 전체의 목차예요. 여덟 덩어리가 순서대로 적혀 있어요.","**시공**이란 재료와 제품으로 사람이 쓸 공간을 실제로 만드는 일이에요.","여덟 덩어리는 결국 '사람 → 방식 → 입찰 → 계획 → 관리 → 준공' 순서예요."]},{"kind":"points","head":"여덟 덩어리 이름만 먼저","items":["1 공사관계자, 2 시공방식, 3 시공사 선정 방식, 4 입찰 프로세스","5 공사계약, 6 공사계획, 7 시공관리, 8 준공","앞 네 개는 '누가, 어떻게 맡기나', 뒤 네 개는 '어떻게 굴리고 끝내나' 예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**시공**의 정의, 슬라이드 문장 그대로","items":["각종 재료와 제품을 사용하여 인간의 생활 목적에 적합한 공간을 구축하는 기술적, 경제적 활동과정","기능, 구조, 미 세 가지 요소를 갖춘 공간을 최적의 비용으로 지정한 시간 내에 구현하는 것","시공의 목적은 사용자의 요구를 수용하고 최선의 결과를 이루도록 하는 것"]},{"kind":"points","head":"시공을 하려면 먼저 하는 일","items":["설계도서의 해독, 즉 도면과 시방서를 읽어 내는 일","공사물량의 산출과 공사비 산출","공정계획 수립, 그리고 이것을 바탕으로 공사계획 수립","그다음 인력, 자재, 장비를 동원해 공사를 해요."]},{"kind":"bg","src":"배경 지식","lines":["건설산업기본법 시행령은 시공관리업무를 이렇게 정의해요.","'건설공사의 현장에서 공사의 설계서 검토, 조정, 시공, 공정 또는 품질의 관리,","검사, 검측, 감리, 기술지도 등 시공과 직접 관련되어 행하여지는 업무'"]},{"kind":"points","head":"여덟 덩어리 속 내용 미리 보기","items":["1 공사관계자: **발주자(client, owner)**, **설계자(designer)**, **감리자(construction supervisor)**","1 공사관계자에 **시공자(builder, contractor)** 와 **노무자(labor, worker)** 도 들어가요.","2 시공방식: **직영공사**, **도급**공사, **턴키(Turn-key)** 도급","3 시공사 선정: **공개경쟁입찰(open competitive bidding)**, **제한경쟁입찰(private competitive bidding)**","3 시공사 선정에 **지명경쟁입찰(selective bidding)** 과 **수의계약(optional contract)** 도 있어요.","4 입찰 프로세스: 입찰공고부터 재입찰까지"]},{"kind":"points","head":"여덟 덩어리 속 내용 미리 보기, 뒷부분","items":["5 공사계약: 계약과 계약서","6 공사계획: 현장 조사, 관련법규 검토, 실행내역서, 공정계획","7 시공관리: 착공 준비, 착공, 현장관리, 안전관리, 품질관리, 자재관리","8 준공: 준공청소, 준공정산, 준공검사, 유지관리 계획"]}],"pass3":[{"kind":"check","q":"슬라이드가 말하는 시공이 갖춰야 할 세 가지 요소는?","choices":["속도, 비용, 안전","기능, 구조, 미","재료, 인력, 장비","설계, 시공, 감리"],"a":1,"why":"기능, 구조, 미의 세 가지 요소를 갖춘 공간을 최적의 비용으로 지정한 시간 내에 구현하는 것이 **시공**이에요."},{"kind":"english","head":"시험 답안에 그대로 쓸 문장","en":"시공이란 각종 재료와 제품을 사용하여 인간의 생활 목적에 적합한 공간을 구축하는 기술적, 경제적 활동과정이다.","ko":"재료와 제품 → 사람이 쓸 공간 → 기술과 돈이 드는 과정, 이 세 토막으로 외워요.","tip":"덧붙일 한 줄: 기능, 구조, 미를 갖춘 공간을 최적의 비용으로 정해진 시간 안에 구현한다."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0551],"c":[0,0.0208,0.2111,0.0871],"r":4.3087,"img":"img/L2/walk/p002_h.jpg"},"parts":[{"b":[0.02,0.105,0.72,0.035],"c":[0,0.0425,0.792,0.16],"r":8.8,"img":"img/L2/walk/p002_20_01.jpg","say":"**시공**의 정의 한 줄이에요. 재료와 제품으로 사람의 생활 목적에 맞는 공간을 구축하는 활동과정이에요."},{"b":[0.02,0.152,0.68,0.035],"c":[0,0.0939,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p002_20_02.jpg","say":"기능, 구조, 미의 세 가지 요소를 최적의 비용으로 지정한 시간 내에 구현한다는 줄이에요."},{"b":[0.02,0.288,0.95,0.075],"c":[0,0.2199,1,0.2111],"r":8.4215,"img":"img/L2/walk/p002_20_03.jpg","say":"건설산업기본법 시행령이 정한 시공관리업무의 정의예요."},{"b":[0.035,0.393,0.11,0.03],"c":[0,0.353,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p002_20_04.jpg","say":"여기부터 아래가 [총론 구성 내용], 즉 2강의 목차예요."},{"b":[0.036,0.44,0.38,0.48],"c":[0.017,0.416,0.418,0.528],"r":1.4074,"img":"img/L2/walk/p002_20_05.jpg","say":"왼쪽 줄 1부터 5까지: 공사관계자, 시공방식, 시공사 선정 방식, 입찰 프로세스, 공사계약."},{"b":[0.44,0.44,0.55,0.36],"c":[0.395,0.422,0.605,0.396],"r":2.716,"img":"img/L2/walk/p002_20_06.jpg","say":"오른쪽 줄 6부터 8까지: 공사계획, 시공관리, 준공."}]}},{"p":3,"title":"공사관계자 1, 발주자와 설계자와 감리자","terms":["client, owner","designer","construction supervisor","builder, contractor","도급"],"pass1":[{"kind":"analogy","head":"공사는 집 짓는 한 판의 게임이에요","scene":"식당에 비유하면 이래요.","map":[["**발주자(client, owner)**","돈 내고 주문하는 손님, 계약서의 갑"],["**설계자(designer)**","메뉴를 그려 주는 사람"],["**감리자(construction supervisor)**","주문대로 만들었는지 보는 심사위원"],["**시공자(builder, contractor)**","실제로 요리하는 요리사"]]},{"kind":"say","lines":["이 쪽에는 앞의 세 사람, 발주자와 설계자와 감리자가 나와요.","요리사인 **시공자(builder, contractor)** 는 다음 쪽에서 만나요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**발주자(client, owner)** 를 한 줄로","items":["인테리어 디자인 공사를 주문하는 자, 또는 공사업자에게 **도급**하는 자","건축주 또는 시행자라고도 불러요. 슬라이드의 건축주 한자는 健築主로 잘못 적혀 있어요.","개인, 법인, 공공단체, 정부기관 등 공사 시행의 주체가 되고 계약상 갑에 해당해요."]},{"kind":"points","head":"**설계자(designer)** 와 **감리자(construction supervisor)** 의 일","items":["설계자는 기술력과 창의력을 바탕으로 설계 도서를 작성해요.","설계자는 그 설계도서에 의도한 디자인을 해설하며 지도, 자문도 해요.","감리자는 관련법규와 용역 계약 내용에 따라 설계도서대로 시공되는지 확인해요.","감리자는 품질관리, 공사관리, 안전관리에 대하여 지도, 감독해요."]},{"kind":"points","head":"공사 순서에서 세 사람의 자리","items":["**발주자(client, owner)** 가 먼저 있어야 공사가 생겨요. 돈과 요구를 가진 사람이에요.","**설계자(designer)** 가 도면을 그려야 시공할 내용이 정해져요.","**감리자(construction supervisor)** 는 시공 중에 붙어서 도면대로 되는지 봐요."]}],"pass3":[{"kind":"check","q":"시공 계약에서 갑에 해당하며 공사를 주문하는 자는?","choices":["**원도급자**","**감리자(construction supervisor)**","**설계자(designer)**","**발주자(client, owner)**"],"a":3,"why":"발주자는 공사를 주문하거나 **도급**하는 자로 건축주, 시행자라고도 하며 계약상 갑이에요."},{"kind":"warn","head":"여기서 잘 틀려요","items":["인테리어 디자인은 의무 감리제도가 '없어요'. 그래도 품질관리를 위해 시행해요.","**설계자(designer)** 는 도면을 그리는 사람, **감리자(construction supervisor)** 는 도면대로 됐는지 보는 사람이에요.","슬라이드 p3의 건축주 한자 健築主는 建築主의 오타예요. 뜻은 발주자와 같아요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p003_h.jpg"},"parts":[{"b":[0.03,0.145,0.67,0.165],"c":[0,0.129,0.737,0.197],"r":6.6509,"img":"img/L2/walk/p003_20_01.jpg","say":"**발주자(client, owner)**, 공사를 주문하거나 공사업자에게 **도급**하는 사람. 건축주 또는 시행자라고도 하고 계약상 갑이에요."},{"b":[0.03,0.33,0.67,0.1],"c":[0,0.3056,0.737,0.1489],"r":8.7993,"img":"img/L2/walk/p003_20_02.jpg","say":"**설계자(designer)**, 설계 도서를 작성하고 그 도면에 담긴 디자인을 해설하며 지도, 자문하는 사람이나 회사예요."},{"b":[0.03,0.43,0.67,0.13],"c":[0,0.414,0.737,0.162],"r":8.0878,"img":"img/L2/walk/p003_20_03.jpg","say":"**감리자(construction supervisor)** 는 공사 주체로부터 위촉되고, 설계도서 내용대로 시공되는지 확인해요."},{"b":[0.03,0.555,0.67,0.08],"c":[0,0.5206,0.737,0.1489],"r":8.7993,"img":"img/L2/walk/p003_20_04.jpg","say":"인테리어 디자인에는 의무 감리제도가 없어요. 그래도 품질관리를 위해 감리를 시행해요."}]}},{"p":4,"title":"공사관계자 2, 시공자와 도급자, 그리고 노무자","terms":["builder, contractor","원도급자","하도급자","labor, worker","직용 노무자","정용 노무자","임시고용 노무자","client, owner","도급"],"pass1":[{"kind":"analogy","head":"요리사 쪽 사람들을 갈라 봐요","scene":"식당 비유를 이어서요.","map":[["**원도급자**","손님과 직접 계약한 주방장"],["**하도급자**","주방장이 따로 부른 전문 요리사"],["**직용 노무자**","주방장이 직접 뽑은 보조"],["**정용 노무자**","전문 요리사 밑에 늘 붙어 있는 숙련 기술자"]]},{"kind":"say","lines":["**시공자(builder, contractor)** 는 공사 전체를 책임지는 사람이에요.","그 아래로 **원도급자**, **하도급자**, 그리고 **노무자(labor, worker)** 가 이어져요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**시공자(builder, contractor)** 를 한 줄로","items":["공사의 제반 업무를 담당하는 책임자, 공사관리자라고도 해요.","회사에 의뢰하는 경우에는 시공사라고 불러요. 도급자와 같은 말이에요.","**발주자(client, owner)** 가 제시한 설계도서에 따라 구조, 마감, 전기, 설비, 가구, 조경까지 맡아요.","공사의 해체, 설치 공사 및 유지보수의 책임을 맡아 시행해요."]},{"kind":"compare","head":"**원도급자** 와 **하도급자** 가르기","cols":["구분","누구와 계약","무엇을 하나"],"rows":[["**원도급자**","**발주자(client, owner)** 와 직접 계약","최상의 주문자, 공사 전체를 받는 시공업자"],["**하도급자**","**원도급자** 와 계약","공사 일부분을 직종별로 분할 **도급**받는 전문업자, 협력업체"]]},{"kind":"points","head":"왜 **하도급자** 가 필요할까요","items":["공사가 복잡하고 다양해져서 **원도급자** 의 직영만으로는 곤란한 경우가 생겨요.","그래서 직종에 따라 해당 전문업자에게 다시 도급하는 방식이 하도급이에요."]},{"kind":"compare","head":"**노무자(labor, worker)** 세 가지, 슬라이드 표 그대로","cols":["구분","의미","주된 특징","예시"],"rows":[["**직용 노무자**","**원도급자** 가 직접 고용한 노무자","원도급자에게 직접 임금을 받으며 잡역 등 미숙련 노무자가 많음","현장 정리, 자재 운반, 청소를 원도급 건설사가 직접 채용한 경우"],["**정용 노무자**","전문업자나 **하도급자** 에게 계속 소속된 기능 노무자","특정 공종의 숙련공이며 현장에 출근한 일수인 출역일수에 따라 임금을 받음","목공, 철근공, 미장공, 타일공, 용접공"],["**임시고용 노무자**","필요한 기간에만 일시적으로 고용되는 노무자","날품, 일용 형태가 많고 단순 작업이나 기능공의 보조 업무를 담당","작업량이 많은 날 하루(일급단위) 고용한 자재 운반 보조원"]]},{"kind":"points","head":"**노무자(labor, worker)** 의 다른 구분","items":["일하는 내용으로는 기능공, 조력공, 견습공 또는 조력인부로 나눠요.","고용의 형태로는 직용, 정용, 임시고용으로 나눠요. 표에 나온 세 가지가 이것이에요.","노무자는 작업지시서나 작업 감독의 지시에 따라 일하고 그 일에 대한 보수를 받아요."]}],"pass3":[{"kind":"check","q":"특정 공종의 숙련공으로 전문업자에게 계속 소속되어 출역일수에 따라 임금을 받는 노무자는?","choices":["**직용 노무자**","조력인부","**임시고용 노무자**","**정용 노무자**"],"a":3,"why":"직용은 **원도급자** 가 직접 고용한 미숙련 인력이 많고, 임시고용은 날품, 일용 형태예요."},{"kind":"warn","head":"헷갈리는 짝 정리","items":["**원도급자** 는 발주자와 '직접' 계약, **하도급자** 는 원도급자에게 '다시' 받은 협력업체예요.","**직용 노무자** 는 원도급사가 '직'접 고용(청소, 운반), **정용 노무자** 는 전문업체에 '정'해진 소속 숙련공이에요.","출역일수라는 단어가 나오면 정용 노무자예요."]},{"kind":"english","head":"목록형 서술 대비 문장","en":"공사관계자는 발주자, 설계자, 감리자, 시공자, 노무자의 다섯이다.","ko":"노무자의 고용 형태는 직용, 정용, 임시고용의 세 가지로 구분한다.","tip":"'발설감시노' 다섯 글자로 순서를 외우고, 노무자는 '직정임' 으로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2775,0.1498],"c":[0,0.0208,0.3052,0.1818],"r":2.9845,"img":"img/L2/walk/p004_h.jpg"},"parts":[{"b":[0.03,0.195,0.69,0.12],"c":[0,0.1783,0.759,0.1533],"r":8.8019,"img":"img/L2/walk/p004_20_01.jpg","say":"1.1.4 **시공자(builder, contractor)**. 공사의 제반 업무를 담당하는 책임자, 공사관리자라고도 해요."},{"b":[0.043,0.33,0.857,0.15],"c":[0.0001,0.3098,0.9427,0.1905],"r":8.7974,"img":"img/L2/walk/p004_20_02.jpg","say":"네모 상자 안이 **원도급자** 와 **하도급자** 의 구별이에요. 원도급은 발주자와 직접, 하도급은 원도급자에게 다시 받아요."},{"b":[0.03,0.52,0.6,0.11],"c":[0.0,0.504,0.66,0.142],"r":8.2629,"img":"img/L2/walk/p004_20_03.jpg","say":"1.1.5 **노무자(labor, worker)**. 지시에 따라 노동에 종사하고 보수를 받는 사람이에요."},{"b":[0.046,0.675,0.853,0.04],"c":[0.0033,0.6002,0.9383,0.1896],"r":8.7979,"img":"img/L2/walk/p004_20_04.jpg","say":"표의 머리줄이에요. 구분, 의미, 주된 특징, 예시 네 칸으로 되어 있어요."},{"b":[0.046,0.715,0.853,0.07],"c":[0.0033,0.6552,0.9383,0.1896],"r":8.7979,"img":"img/L2/walk/p004_20_05.jpg","say":"**직용 노무자** 줄. **원도급자** 가 직접 고용하고 잡역 등 미숙련이 많아요."},{"b":[0.046,0.782,0.853,0.13],"c":[0.0033,0.7522,0.9383,0.1896],"r":8.7979,"img":"img/L2/walk/p004_20_06.jpg","say":"**정용 노무자** 줄(출역일수에 따라 임금)과 **임시고용 노무자** 줄(날품, 일용)이에요."}]}},{"p":5,"title":"공사관계자 조직도 한눈에 보기","terms":["client, owner","designer","construction supervisor","builder, contractor","원도급자","하도급자","labor, worker","직용 노무자","정용 노무자","임시고용 노무자"],"pass1":[{"kind":"say","lines":["이 쪽은 앞에서 배운 사람들을 한 장의 조직도로 묶은 그림이에요.","왼쪽에 **발주자(client, owner)**, 가운데 **원도급자**, 오른쪽 **하도급자** 순서예요.","화살표는 '누가 누구에게 일을 맡기는가' 를 가리켜요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"그림이 알려 주는 규모별 차이","items":["큰 프로젝트에서는 설계사, 감리사, 시공사가 각각 따로 선정돼요.","보통의 작은 프로젝트는 **원도급자** 인 한 회사에 설계팀, 감리팀, 시공팀이 다 소속돼 있어요.","그래서 작은 인테리어 현장에서는 한 회사 사람이 여러 역할을 겸해요."]},{"kind":"points","head":"노무자가 붙는 자리를 다시 확인","items":["**원도급자** 쪽에 붙는 노무자는 **직용 노무자** 와 **임시고용 노무자** 예요.","**하도급자** 쪽에 붙는 노무자는 **정용 노무자** 와 **임시고용 노무자** 예요.","임시고용은 양쪽 모두에 나온다는 점이 이 그림의 핵심이에요."]}],"pass3":[{"kind":"check","q":"작은 인테리어 프로젝트에 대한 설명으로 옳은 것은?","choices":["설계사, 감리사, 시공사를 반드시 따로 선정한다","**원도급자** 인 한 회사에 설계팀, 감리팀, 시공팀이 함께 소속된 경우가 많다","**하도급자** 없이 **발주자(client, owner)** 가 모두 직접 한다","**감리자(construction supervisor)** 를 법으로 반드시 두어야 한다"],"a":1,"why":"큰 프로젝트는 각각 선정하지만 작은 프로젝트는 한 회사에 팀으로 다 들어 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2775,0.1498],"c":[0,0.0208,0.3052,0.1818],"r":2.9845,"img":"img/L2/walk/p005_h.jpg"},"parts":[{"b":[0.19,0.39,0.11,0.08],"c":[0.145,0.374,0.2,0.112],"r":3.1746,"img":"img/L2/walk/p005_20_01.jpg","say":"고객(Client), 즉 **발주자(client, owner)**. 여기서 모든 화살표가 시작해요."},{"b":[0.32,0.24,0.21,0.54],"c":[0.308,0.213,0.234,0.594],"r":0.7003,"img":"img/L2/walk/p005_20_02.jpg","say":"**원도급자** 상자. 안에 **설계자(designer)**, **감리자(construction supervisor)**, **시공자(builder, contractor)** 가 모두 들어 있어요."},{"b":[0.335,0.49,0.18,0.28],"c":[0.323,0.474,0.204,0.312],"r":1.1624,"img":"img/L2/walk/p005_20_03.jpg","say":"원도급자 안쪽 진한 상자가 시공자의 **노무자(labor, worker)**, 즉 **직용 노무자** 와 **임시고용 노무자** 예요."},{"b":[0.56,0.24,0.2,0.33],"c":[0.548,0.2235,0.224,0.363],"r":1.097,"img":"img/L2/walk/p005_20_04.jpg","say":"**하도급자**(협력업체) 상자. 여기 붙은 노무자는 **정용 노무자** 와 **임시고용 노무자** 예요."},{"b":[0.32,0.79,0.32,0.13],"c":[0.304,0.774,0.352,0.162],"r":3.8628,"img":"img/L2/walk/p005_20_05.jpg","say":"아래 주석: 큰 프로젝트는 설계사, 감리사, 시공사를 따로 뽑지만 작은 프로젝트는 한 회사가 다 해요."}]}},{"p":6,"title":"시공방식 1, 직영공사와 도급공사","terms":["직영공사","도급","client, owner","builder, contractor","원도급자","하도급자","designer","직용 노무자"],"pass1":[{"kind":"analogy","head":"맡기는 방법은 크게 두 가지예요","scene":"이사할 때를 떠올려 보세요.","map":[["**직영공사**","내가 트럭 빌리고 사람 불러서 직접 옮기기, 셀프 인테리어"],["**도급**공사","이삿짐센터에 통째로 맡기고 돈 주기"]]},{"kind":"say","lines":["**직영공사** 는 **발주자(client, owner)** 가 직접 다 챙기는 방식이에요.","**도급**공사는 **시공자(builder, contractor)** 에게 맡기고 대금을 주는 계약이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**직영공사** 를 한 줄로","items":["**발주자(client, owner)** 가 시공 계획을 세우고 직접 재료구입, 노무자고용, 시공기계 및 가설재를 마련해요.","그리고 일체의 공사를 직접 관리, 감독해요. 슬라이드에 '셀프 인테리어?' 라고 적혀 있어요.","공사비를 절감할 수도 있어요. 중간에 이윤을 붙이는 사람이 없으니까요."]},{"kind":"points","head":"**직영공사** 의 문제점, 시험에 잘 나와요","items":["전문지식과 관리능력이 부족한 경우 완성도가 저하돼요.","오히려 공사비가 증가할 수 있어요.","공사기간이 연장될 수 있어요.","하자보수 이행 등에 문제가 생길 수 있어요."]},{"kind":"points","head":"**도급** 의 법적 정의","items":["민법 664조: 당사자 일방이 어느 일을 완성할 것을 약정하고,","상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 성립되는 계약이에요.","시공회사가 공사의 시공을 맡고 **발주자(client, owner)** 가 그 대금을 지불하기로 약정하는 것이 도급공사의 계약이에요."]},{"kind":"compare","head":"그림 두 개 비교하기","cols":["구분","발주자가 상대하는 곳","그다음"],"rows":[["**직영공사**","공종별 전문업체, 공종별 작업자, **직용 노무자**, 자재 공급 업체, 장비와 가설재 임대업체","발주자가 이 모두를 직접 관리, 감독"],["**도급**공사","**설계자(designer)**, 그리고 **시공자(builder, contractor)** 인 **원도급자**","원도급자가 **하도급자**(협력업체) 에게 다시 맡김"]]}],"pass3":[{"kind":"check","q":"**직영공사** 의 단점으로 옳지 않은 것은?","choices":["완성도가 저하될 수 있다","**도급** 자의 이윤이 가산된다","공사비가 오히려 증가할 수 있다","공사기간이 연장될 수 있다"],"a":1,"why":"이윤 가산은 도급의 특징이에요. 직영공사는 중간 이윤이 없어서 공사비 절감 여지가 있는 쪽이에요."},{"kind":"check","q":"**도급** 의 정의를 규정하고 있는 법 조항은?","choices":["건축법 시행령 제3조의2","건설산업기본법 시행령 별표4","민법 664조","산업안전보건법"],"a":2,"why":"민법 664조예요. '664' 숫자만 따로 외워 두세요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1484],"c":[0,0.0208,0.2111,0.1804],"r":2.0803,"img":"img/L2/walk/p006_h.jpg"},"parts":[{"b":[0.03,0.19,0.87,0.08],"c":[0,0.1333,0.957,0.1933],"r":8.8015,"img":"img/L2/walk/p006_20_01.jpg","say":"1.2.1 **직영공사**. 발주자가 직접 재료구입, 노무자고용, 시공기계와 가설재를 마련해 직접 관리, 감독해요."},{"b":[0.03,0.335,0.87,0.08],"c":[0,0.2783,0.957,0.1933],"r":8.8015,"img":"img/L2/walk/p006_20_02.jpg","say":"1.2.2 도급공사. **도급** 의 정의가 민법 664조에 있다는 줄이에요."},{"b":[0.089,0.46,0.25,0.23],"c":[0.0765,0.444,0.275,0.262],"r":1.866,"img":"img/L2/walk/p006_20_03.jpg","say":"왼쪽 그림이 **직영공사**. 발주자가 전문업체, 작업자, **직용 노무자**, 자재와 장비 업체를 모두 직접 상대해요."},{"b":[0.505,0.465,0.41,0.19],"c":[0.4845,0.449,0.451,0.222],"r":3.6116,"img":"img/L2/walk/p006_20_04.jpg","say":"오른쪽 그림이 도급공사. 발주자는 **설계자(designer)** 와 **원도급자** 만 상대하고, 원도급자가 **하도급자** 에게 넘겨요."}]}},{"p":7,"title":"공사시행방식에 따른 도급 1, 일식도급과 분할도급","terms":["도급","일식도급","분할도급","공종별 도급","공정별 도급","공구별 도급","원도급자","하도급자","client, owner"],"pass1":[{"kind":"analogy","head":"공사를 통째로 줄까, 쪼개서 줄까","scene":"피자를 떠올려 보세요.","map":[["**일식도급**","피자 한 판을 통째로 한 사람에게"],["**분할도급**","조각조각 잘라서 여러 사람에게"]]},{"kind":"say","lines":["**일식도급** 은 총괄도급이라고도 하고 가장 일반적인 방법이에요.","**분할도급** 은 나누는 기준에 따라 **공종별 도급**, **공정별 도급**, **공구별 도급** 으로 갈려요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**일식도급**(총괄도급) 을 한 줄로","items":["한 공사의 전부를 한 도급자에게 맡겨 재료, 노무, 현장시공업무 일체를 일괄하여 시행시키는 방법이에요.","**발주자(client, owner)** 는 설계에 따른 시공 여부를 확인하고 작업 내용에 대한 지도 감리를 해요.","도급계약 시 공사비가 확정되고 책임이 명료하여 공사관리가 용이해요.","도급자의 이윤이 가산되지만 일반적으로 이용되는 방법이에요. 설계는 포함되지 않아요."]},{"kind":"points","head":"**분할도급** 을 한 줄로","items":["공사를 유형에 따라 세분하여 각기 따로 도급자를 선정해 **도급**계약을 맺는 방식이에요.","공종별, 공정별 또는 공구별로 나눠요.","재료와 노무 일체를 도급으로 하는 방식과, 재료는 발주자가 주고 노무만 도급하는 방식이 있어요.","**원도급자** 가 **하도급자** 를 쓸 때 많이 이용돼요."]},{"kind":"compare","head":"**분할도급** 세 가지, 나누는 기준이 다 달라요","cols":["구분","나누는 기준","특징"],"rows":[["**공종별 도급**","공사의 종류(금속, 목공, 설비, 전기, 창호, 가구)","가장 기본적인 방법. 기술이 전문화되지만 공사 관리가 복잡하고 가설과 시공 기계 설치가 중복될 수 있음"],["**공정별 도급**","공사의 과정(설계는 계획, 기본, 실시 / 시공은 골조와 마감 또는 공사기간)","후속공사가 다른 업자로 변경되면 공사의 연계가 원활하지 않을 수 있음"],["**공구별 도급**","대규모 면적 공사의 지역","기술 수준이 유사한 다수 업체와 계약해 경쟁 유도, 공사기일 단축, 시공기술 향상을 기대"]]},{"kind":"points","head":"공사 순서에서의 자리","items":["**발주자(client, owner)** 가 시공사를 고르기 전에 '어떻게 나눠 맡길까' 를 먼저 정해요.","이 결정이 끝나야 입찰공고에 공사 범위를 적을 수 있어요.","인테리어 현장에서는 **일식도급** 으로 한 회사에 맡기고, 그 회사가 공종별로 하도급을 주는 모양이 흔해요."]}],"pass3":[{"kind":"check","q":"대규모 면적의 공사에서 지역별로 공사를 분리하여 업체 간 경쟁을 유도하는 도급은?","choices":["**공구별 도급**","**공종별 도급**","**의무공동도급**","**공정별 도급**"],"a":0,"why":"공구는 '구'역이에요. 기술 수준이 유사한 다수 업체와 계약해 공기 단축, 기술 향상을 기대해요."},{"kind":"warn","head":"세 글자만 바꿔서 나오니 조심","items":["공'종'은 '종'류(목공, 전기), 공'정'은 과'정'(골조, 마감), 공'구'는 '구'역(대규모 면적)이에요.","**일식도급** 은 '통째', 가장 일반적, 설계는 포함되지 않아요.","설계까지 함께 맡기는 것은 일식도급이 아니라 턴키예요."]},{"kind":"english","head":"목록형 서술 대비 문장","en":"공사시행방식에 따른 도급은 일식도급, 분할도급, 공동도급의 세 가지이다.","ko":"분할도급은 다시 공종별, 공정별, 공구별 도급공사로 나뉜다.","tip":"'일분공' 세 글자, 그리고 분할은 '종정구' 세 글자로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.21,0.1918],"c":[0,0.0208,0.234,0.2238],"r":1.8588,"img":"img/L2/walk/p007_h.jpg"},"parts":[{"b":[0.032,0.24,0.67,0.175],"c":[0,0.224,0.737,0.207],"r":6.3296,"img":"img/L2/walk/p007_20_01.jpg","say":"(1) **일식도급**(총괄도급). 설계는 포함 아님, 가장 일반적인 방법이라는 메모가 제목 옆에 붙어 있어요."},{"b":[0.032,0.443,0.755,0.13],"c":[0,0.4241,0.8305,0.1678],"r":8.7988,"img":"img/L2/walk/p007_20_02.jpg","say":"(2) **분할도급**. 공사를 유형에 따라 세분해 각기 따로 도급자를 선정해요."},{"b":[0.013,0.61,0.286,0.327],"c":[0,0.5937,0.3146,0.3597],"r":1.5549,"img":"img/L2/walk/p007_20_03.jpg","say":"왼쪽 상자 ① **공종별 도급** 공사. 가장 기본적인 방법이에요. 금속, 목공, 설비, 전기, 창호, 가구로 나눠요."},{"b":[0.301,0.61,0.36,0.327],"c":[0.283,0.5937,0.396,0.3597],"r":1.9572,"img":"img/L2/walk/p007_20_04.jpg","say":"가운데 상자 ② **공정별 도급** 공사. 계획, 기본, 실시 또는 골조와 마감처럼 과정별로 나눠요."},{"b":[0.664,0.61,0.325,0.327],"c":[0.6425,0.5937,0.3575,0.3597],"r":1.7669,"img":"img/L2/walk/p007_20_05.jpg","say":"오른쪽 상자 ③ **공구별 도급** 공사. 대규모 면적의 공사를 지역별로 나눠요."}]}},{"p":8,"title":"공사시행방식에 따른 도급 2, 공동도급","terms":["공동도급","공동이행방식","분담이행방식","의무공동도급","도급","분할도급","일식도급"],"pass1":[{"kind":"say","lines":["**공동도급** 은 여러 회사가 힘을 합쳐 한 회사처럼 공사를 받는 방식이에요.","아파트 이름이 '래미안 푸르지오' 처럼 두 개 붙은 것을 본 적 있죠. 그게 공동도급이에요.","합치는 모양에 따라 **공동이행방식**, **분담이행방식**, **의무공동도급** 으로 나뉘어요."]},{"kind":"analogy","head":"셋을 그림으로 구별해요","scene":"조별 과제에 비유하면요.","map":[["**공동이행방식**","같은 전공 친구들이 과제 전체를 함께 하기"],["**분담이행방식**","전공이 다른 친구들이 파트를 나눠 맡기"],["**의무공동도급**","그 동네 친구를 꼭 한 명 끼워야 하는 규칙"]]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**공동도급** 을 한 줄로","items":["대규모 공사의 시공에 대하여 여러 회사가 공동출자형태를 조직하는 것이에요.","그렇게 해서 한 회사의 입장에서 공사를 수급하고 시공을 해요.","공사 수급의 경쟁완화 수단이 되며 각 시공업체의 장점을 취할 수 있어요.","각 사의 자금 부담을 줄이고 위험 또한 분담으로 부담을 줄일 수 있어요."]},{"kind":"compare","head":"**공동도급** 세 가지 가르기","cols":["구분","누가 모이나","핵심"],"rows":[["**공동이행방식**","같은 업종을 가진 두 개 이상의 업체","공동수급체를 구성하고 일정한 출자비율에 따라 자금, 인력, 장비를 공동 투입해 공사 전체를 함께 수행. 예: 래미안 + 푸르지오"],["**분담이행방식**","서로 다른 업종을 가진 두 개 이상의 업체","공사의 내용을 나누어 공동으로 참여. 예: 실내건축공사 A업체 + 기계설비공사 B업체, 전문 기술이 다름"],["**의무공동도급**","타 지역 업체 + 그 지역 업체","지방자치단체가 지역제한 없이 발주할 때 현장이 있는 시, 도에 본점을 둔 지역업체 1개사 이상을 참여시킴"]]},{"kind":"points","head":"**의무공동도급** 의 목적과 예외","items":["지역 건설업체의 수주 기회 확대와 지역경제 활성화가 목적이에요.","다만 해당 지역에 공사 수행 자격을 갖춘 업체가 10개 미만인 경우 등에는 적용하지 않을 수 있어요.","'10개 미만' 이라는 숫자를 기억해 두세요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**공동도급** 은 **일식도급**, **분할도급** 과 같은 층, 즉 공사시행방식에 따른 분류예요.","대규모 아파트 공사처럼 한 회사가 감당하기 힘든 규모에서 입찰 전에 공동수급체를 만들어요.","그다음 그 공동수급체가 한 덩어리로 입찰에 참가해요."]}],"pass3":[{"kind":"check","q":"같은 업종의 두 개 이상 업체가 출자비율에 따라 자금, 인력, 장비를 공동 투입하는 방식은?","choices":["**분담이행방식**","**의무공동도급**","**공구별 도급**","**공동이행방식**"],"a":3,"why":"예로 래미안 + 푸르지오가 있어요. 서로 다른 업종이 내용을 나누면 분담이행방식이에요."},{"kind":"warn","head":"슬라이드 오타와 숫자","items":["슬라이드 p8의 '분담이해방식' 은 **분담이행방식** 의 오타예요. 시험에는 분담이행방식으로 나와요.","**공동이행방식** 은 '같은' 업종, **분담이행방식** 은 '다른' 업종이에요.","**의무공동도급** 은 지역 업체가 10개 미만이면 적용하지 않을 수 있어요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.21,0.2438],"c":[0,0.0208,0.234,0.2758],"r":1.5083,"img":"img/L2/walk/p008_h.jpg"},"parts":[{"b":[0.032,0.288,0.635,0.125],"c":[0.0003,0.272,0.6985,0.157],"r":7.9094,"img":"img/L2/walk/p008_20_01.jpg","say":"(3) **공동도급** 의 정의 세 줄이에요. 여러 회사가 공동출자형태를 조직해 한 회사처럼 공사를 수급해요."},{"b":[0.018,0.43,0.315,0.525],"c":[0.0022,0.4037,0.3465,0.5775],"r":1.0667,"img":"img/L2/walk/p008_20_02.jpg","say":"왼쪽 상자 ① **공동이행방식**. 같은 업종 두 곳이 공동수급체를 만들어요. 아래 그림은 A업체와 B업체가 한 공사를 함께 잡은 모양이에요."},{"b":[0.336,0.43,0.315,0.525],"c":[0.3203,0.4037,0.3465,0.5775],"r":1.0667,"img":"img/L2/walk/p008_20_03.jpg","say":"가운데 상자 ② 분담이해방식. **분담이행방식** 의 오타예요. 실내건축공사 A업체와 기계설비공사 B업체처럼 업종이 달라요."},{"b":[0.654,0.43,0.33,0.525],"c":[0.637,0.4037,0.363,0.5775],"r":1.1175,"img":"img/L2/walk/p008_20_04.jpg","say":"오른쪽 상자 ③ **의무공동도급**. 타 지역 A업체에 지역 B업체를 의무로 끼워요. 자격 업체가 10개 미만이면 적용하지 않을 수 있어요."}]}},{"p":9,"title":"공사비 지급 방식에 따른 도급, 정액과 단가와 실비정산","terms":["정액도급","단가도급","실비정산보수가산도급","도급","client, owner"],"pass1":[{"kind":"analogy","head":"돈을 어떻게 주기로 했는가","scene":"식당에서 계산하는 방법에 비유해요.","map":[["**정액도급**","정식 한 상 값을 미리 딱 정해 놓기"],["**단가도급**","고기 100그램당 값만 정하고 먹은 만큼 계산"],["**실비정산보수가산도급**","재료 영수증 그대로 내고 수고비를 더 얹어 주기"]]},{"kind":"say","lines":["앞 쪽은 '일을 어떻게 나눌까', 이 쪽은 '돈을 어떻게 줄까' 예요.","**정액도급** 이 가장 일반적이고, 보통 계약금, 중도금, 잔금으로 나눠 계약해요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**정액도급** 을 한 줄로","items":["공사비 총액을 확정하여 계약하는 것이에요.","공사관리업무가 간편하고, 도급업자는 자금 공사계획 수립이 명확해 공사원가를 절감하려 노력하게 돼요.","단점: 공사변경에 따른 도급액의 증감이 곤란하고, 이윤관계로 공사가 조악해질 우려가 있어요.","그래서 장기 공사기간 및 설계변경 가능성이 많은 공사에는 부적당해요."]},{"kind":"points","head":"**단가도급** 을 한 줄로","items":["공사 물량 또는 단위공사부분에 대한 단가만을 확정해요.","공사가 완료되면 실시수량, 즉 실제 시공된 수량의 확정에 따라 정산해요.","공사의 빠른 착공이 가능해요. 단가만 정하면 바로 시작할 수 있으니까요.","단순한 작업의 단일공사 이외에는 일반적으로 채용되지 않아요."]},{"kind":"steps","head":"**단가도급** 계산 예시, 슬라이드 그대로","steps":["바닥 타일 시공 단가를 1제곱미터당 50,000원으로 계약해요.","공사 완료 후 실제 시공면적을 재니 120제곱미터였어요.","50,000원 곱하기 120은 6,000,000원이에요.","즉 단가 곱하기 실제 시공된 수량, 완성된 작업량 기준으로 지급해요."],"answer":"공사비는 6,000,000원이에요."},{"kind":"points","head":"**실비정산보수가산도급** 을 한 줄로","items":["실제 공사의 인건비와 재료비 등을 건축주와 도급자가 확인하여 정산해요.","그리고 약정에 의한 비율 또는 정액의 보수를 도급자에게 지불해요.","과도한 덤핑에 따른 부실공사를 방지할 수 있고 **발주자(client, owner)** 는 적정비용에 요구품질을 확보해요.","다만 도급자는 비율보수가 보장되어 공사비 절감의 노력이 없어질 수 있어요."]},{"kind":"steps","head":"**실비정산보수가산도급** 계산 예시, 슬라이드 그대로","steps":["재료비 6,000만 원, 노무비 3,000만 원, 장비와 경비 1,000만 원이 실제로 들었어요.","실제 공사원가는 총 1억 원이에요.","여기에 시공자 보수 1,000만 원을 더해요.","총 1억 1,000만 원, 실제로 투입된 비용을 기준으로 지급해요."],"answer":"총 지급액은 1억 1,000만 원이에요."}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"바닥 타일 단가 1제곱미터당 50,000원으로 계약하고 실제 시공면적 120제곱미터로 정산하는 방식과 금액은?","qko":"단가만 정해 놓고 실제로 깐 면적으로 계산하면 얼마일까요.","solve":["돈 주는 방식이 '단가만 확정' 이므로 **단가도급** 이에요.","공식은 단가 곱하기 실제 시공된 수량이에요.","50,000 곱하기 120은 6,000,000이에요."],"answer":"**단가도급**, 6,000,000원이에요."},{"kind":"check","q":"**실비정산보수가산도급** 의 특징으로 옳지 않은 것은?","choices":["도급자가 공사비 절감에 가장 적극적이다","시공업자에게 적정 이윤이 보장된다","과도한 덤핑에 따른 부실공사를 방지할 수 있다","실제 인건비와 재료비를 확인하여 정산한다"],"a":0,"why":"비율보수가 보장되어 수준 높은 시공은 가능하지만 공사비 절감의 노력이 없어질 수 있어요."},{"kind":"warn","head":"헷갈리는 짝","items":["**정액도급** 은 총액 확정이라 설계변경이 많으면 부적당해요.","**단가도급** 은 단가 곱하기 '수량', **실비정산보수가산도급** 은 실제 공사'비' 더하기 보수예요.","공사 기간이 길거나 복잡한 변경이 예상되면 정액도급을 피해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2266,0.1599],"c":[0,0.0208,0.2506,0.1919],"r":2.3216,"img":"img/L2/walk/p009_h.jpg"},"parts":[{"b":[0.032,0.21,0.835,0.125],"c":[0,0.1797,0.9185,0.1856],"r":8.7979,"img":"img/L2/walk/p009_20_01.jpg","say":"(1) **정액도급**. 제목 옆에 '일반적인 방법, 주로 계약금, 중도금, 잔금으로 나누어 계약함' 이라고 적혀 있어요."},{"b":[0.032,0.373,0.7,0.1],"c":[0,0.3452,0.77,0.1556],"r":8.7975,"img":"img/L2/walk/p009_20_02.jpg","say":"(2) **단가도급**. 단가만 확정하고 실시수량의 확정에 따라 정산해요."},{"b":[0.046,0.515,0.615,0.075],"c":[0.0152,0.4842,0.6765,0.1367],"r":8.7979,"img":"img/L2/walk/p009_20_03.jpg","say":"단가도급 계산 그림. 단가 곱하기 실제 시공된 수량이에요. 50,000원 곱하기 120제곱미터는 6,000,000원이에요."},{"b":[0.018,0.645,0.74,0.17],"c":[0,0.629,0.814,0.202],"r":7.1639,"img":"img/L2/walk/p009_20_04.jpg","say":"(3) **실비정산보수가산도급**. 실제 인건비와 재료비를 확인해 정산하고 약정한 보수를 지불해요."},{"b":[0.05,0.848,0.74,0.075],"c":[0.013,0.8033,0.814,0.1645],"r":8.797,"img":"img/L2/walk/p009_20_05.jpg","say":"실비정산 계산 그림. 실제 공사비 더하기 시공자 보수예요. 1억 원 더하기 1,000만 원은 1억 1,000만 원이에요."}]}},{"p":10,"title":"턴키 도급과 시공방식 전체 나무","terms":["Turn-key","직영공사","도급","일식도급","분할도급","공동도급","정액도급","단가도급","실비정산보수가산도급","client, owner","하도급자"],"pass1":[{"kind":"analogy","head":"턴키라는 이름의 뜻","scene":"이름 그대로 읽으면 쉬워요.","map":[["Turn","열쇠를 돌린다"],["Key","열쇠"],["**턴키(Turn-key)**","열쇠를 열고 들어가서 바로 쓸 수 있는 상태로 넘겨주기"]]},{"kind":"recap","items":["1.2 시공방식 전체를 한 줄로 정리하면","시공방식은 **직영공사**, **도급** 방식, **턴키(Turn-key)** 방식의 셋이에요.","도급 방식은 다시 공사 시행 방식과 공사비 지급 방식으로 갈려요.","공사 시행 방식: **일식도급**, **분할도급**, **공동도급**","공사비 지급 방식: **정액도급**, **단가도급**, **실비정산보수가산도급**"]}],"pass2":[{"kind":"points","head":"**턴키(Turn-key)** 도급을 한 줄로","items":["모든 요소를 포괄하는 도급계약 방식이에요.","**발주자(client, owner)** 가 바로 사용할 수 있도록 모든 것을 조달하여 완성하고 시공자가 인도해요.","일반적으로 설계와 시공을 함께 발주하는 일괄 입찰의 뜻으로 사용돼요.","열쇠를 열고 들어가서 바로 사용할 수 있는 상태로 인도한다는 의미예요."]},{"kind":"look","walked":1},{"kind":"compare","head":"**턴키(Turn-key)** 와 **일식도급** 은 뭐가 다를까","cols":["구분","설계 포함?","계약 상대"],"rows":[["**일식도급**","설계는 포함되지 않아요","공사 전부를 한 도급자에게"],["**턴키(Turn-key)**","설계와 시공을 함께 발주해요","모든 것을 조달하는 턴키 사업자에게"]]}],"pass3":[{"kind":"check","q":"설계와 시공을 함께 발주하는 일괄 입찰의 뜻으로 쓰이며 바로 사용할 수 있는 상태로 인도하는 방식은?","choices":["**공정별 도급**","**일식도급**","**직영공사**","**턴키(Turn-key)** 도급"],"a":3,"why":"턴키는 모든 요소를 포괄해 발주자가 바로 사용할 수 있도록 완성해 인도해요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"공사 시공방식은 직영방식, 도급방식, 턴키방식으로 나뉜다.","ko":"도급방식은 공사 시행 방식(일식, 분할, 공동)과 공사비 지급 방식(정액, 단가, 실비정산보수가산)으로 구분한다.","tip":"'직도턴' 세 글자, 시행은 '일분공', 지급은 '정단실' 로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1312],"c":[0,0.0208,0.2111,0.1632],"r":2.2996,"img":"img/L2/walk/p010_h.jpg"},"parts":[{"b":[0.7,0.17,0.22,0.27],"c":[0.688,0.154,0.244,0.302],"r":1.4364,"img":"img/L2/walk/p010_21_01.jpg","say":"오른쪽 위 턴키 도급 공사 그림. 발주자가 턴키 사업자 한 곳과만 계약하고, 그 회사 안에 설계팀, 현장관리팀, 시공팀, 품질과 안전관리팀이 다 있어요."},{"b":[0.7,0.39,0.22,0.06],"c":[0.688,0.365,0.244,0.11],"r":3.9434,"img":"img/L2/walk/p010_21_02.jpg","say":"그 아래 공종별 **하도급자**. 턴키 사업자가 공종별로 다시 나눠 줘요."},{"b":[0.22,0.52,0.11,0.07],"c":[0.175,0.5,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p010_21_03.jpg","say":"아래 나무 그림의 첫 갈래, **직영공사** 방식이에요."},{"b":[0.44,0.62,0.11,0.07],"c":[0.395,0.6,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p010_21_04.jpg","say":"가운데 갈래 **도급** 방식. 여기서 다시 둘로 갈려요."},{"b":[0.58,0.49,0.1,0.19],"c":[0.53,0.474,0.2,0.222],"r":1.6016,"img":"img/L2/walk/p010_21_05.jpg","say":"공사 시행 방식 쪽 열매: **일식도급**, **분할도급**, **공동도급**"},{"b":[0.58,0.72,0.15,0.19],"c":[0.555,0.704,0.2,0.222],"r":1.6016,"img":"img/L2/walk/p010_21_06.jpg","say":"공사비 지급 방식 쪽 열매: **정액도급**, **단가도급**, **실비정산보수가산도급**"}]}},{"p":11,"title":"시공사 선정 방식 네 가지","terms":["open competitive bidding","private competitive bidding","selective bidding","optional contract","client, owner","시공"],"pass1":[{"kind":"analogy","head":"문이 점점 좁아져요","scene":"참가할 수 있는 회사의 수로 보면 순서가 보여요.","map":[["**공개경쟁입찰(open competitive bidding)**","누구나 들어오는 활짝 열린 문"],["**제한경쟁입찰(private competitive bidding)**","조건에 맞는 회사만 들어오는 문"],["**지명경쟁입찰(selective bidding)**","초대장을 받은 회사만 들어오는 문"],["**수의계약(optional contract)**","한 회사만 콕 찍어 부르는 문"]]},{"kind":"say","lines":["**발주자(client, owner)** 가 **시공** 을 맡길 회사를 고르는 네 가지 방법이에요.","뒤로 갈수록 경쟁은 줄고 담합 위험은 커져요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"compare","head":"네 가지를 한 표로","cols":["방식","누가 참가하나","좋은 점과 걱정되는 점"],"rows":[["**공개경쟁입찰(open competitive bidding)**","내용과 조건을 모두 공개해 유자격자는 모두","참가 기회 확대, 투명 관리로 담합 가능성 감소. 과도한 경쟁 유발, 부적격 업체 응찰로 부실공사 우려"],["**제한경쟁입찰(private competitive bidding)**","사업추진실적, 사업수주액, 기술보유상황, 재무상태 등으로 제한한 업체","불성실하고 능력 없는 자를 배제해 공개성, 공정성, 경제성을 유지"],["**지명경쟁입찰(selective bidding)**","발주자가 지명한 특정 다수인","특수한 설비, 기술, 자재, 물품, 실적이 있어야 목적 달성이 가능할 때 적용. 담합의 우려가 있음"],["**수의계약(optional contract)**","적합하다고 판단한 하나의 업체","개인 발주자는 적용 제한이 없고 정부나 공공기관은 일정 금액 이하에만 적용"]]},{"kind":"points","head":"**제한경쟁입찰(private competitive bidding)** 의 제한 기준","items":["주로 사업추진실적, 사업수주액, 기술보유상황, 재무상태 등에 제한을 둬요.","시공 능력 공시액, 도급한도액, 실적, 기술보유상황 같은 일정한 기준으로 제한해요.","다음 두 쪽에 나오는 실제 공고문을 보면 '건설공사실적확인서' 가 그 증거 서류예요."]},{"kind":"points","head":"**수의계약(optional contract)** 을 쓰는 경우","items":["원칙은 일반 **공개경쟁입찰(open competitive bidding)** 로 사업자를 선정해요.","다만 특허, 신기술 등이 필요해 경쟁이 불가능하다고 판단되는 경우에 적용해요.","이미 진행 중인 공사와 연속되어야 하는 종속공사, 추가공사 등 소규모 공사에도 적용 가능해요.","**발주자(client, owner)** 는 시공회사의 신용, 자산, 공사경력, 보유기재, 자재, 기술을 고려해 결정해요."]}],"pass3":[{"kind":"check","q":"특정 다수인을 지명하여 그 업체만 입찰에 참가시키며 담합의 우려가 있는 방식은?","choices":["**제한경쟁입찰(private competitive bidding)**","**공개경쟁입찰(open competitive bidding)**","**수의계약(optional contract)**","**지명경쟁입찰(selective bidding)**"],"a":3,"why":"특수 설비, 기술, 실적이 있어야 계약목적 달성이 가능한 경우에 적용해요."},{"kind":"warn","head":"슬라이드 표기와 헷갈리는 짝","items":["**제한경쟁입찰** 의 영문이 슬라이드에는 private competitive bidding 으로 적혀 있어요. 시험은 슬라이드대로 나올 수 있어요.","제한은 '조건' 을 걸고 해당되면 누구나, 지명은 발주자가 '이름을 찍어' 초대예요.","정부나 공공기관의 **수의계약(optional contract)** 은 금액 제한이 '있어요'."]},{"kind":"english","head":"목록형 서술 대비 문장","en":"시공사 선정 방식은 공개경쟁입찰, 제한경쟁입찰, 지명경쟁입찰, 수의계약의 네 가지이다.","ko":"공개는 모두, 제한은 조건, 지명은 초대, 수의는 하나.","tip":"'공제지수' 네 글자로 문이 좁아지는 순서를 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p011_h.jpg"},"parts":[{"b":[0.025,0.148,0.71,0.175],"c":[0,0.132,0.781,0.207],"r":6.7075,"img":"img/L2/walk/p011_20_01.jpg","say":"1.3.1 **공개경쟁입찰(open competitive bidding)**. 유자격자는 모두 참가. 담합 가능성은 줄지만 과도한 경쟁과 부실공사 우려가 있어요."},{"b":[0.025,0.352,0.82,0.175],"c":[0,0.336,0.902,0.207],"r":7.7466,"img":"img/L2/walk/p011_20_02.jpg","say":"1.3.2 **제한경쟁입찰(private competitive bidding)**. 실적, 수주액, 기술보유상황, 재무상태로 참여업체 범위를 제한해요."},{"b":[0.025,0.557,0.765,0.155],"c":[0,0.541,0.8415,0.187],"r":8.0,"img":"img/L2/walk/p011_20_03.jpg","say":"1.3.3 **지명경쟁입찰(selective bidding)**. 특정 다수인을 지명해요. 아래 분홍 글씨로 '담합의 우려가 있다' 고 적혀 있어요."},{"b":[0.025,0.72,0.825,0.215],"c":[0,0.704,0.9075,0.247],"r":6.5317,"img":"img/L2/walk/p011_20_04.jpg","say":"1.3.4 **수의계약(optional contract)**. 하나의 업체를 지정. 개인 발주자는 제한 없고 공공기관은 일정 금액 이하만이에요."}]}},{"p":12,"title":"공개경쟁입찰 실제 공고문 보기","terms":["open competitive bidding","bid bond","on-site orientation"],"pass1":[{"kind":"say","lines":["이 쪽은 실제 **공개경쟁입찰(open competitive bidding)** 공고문 사진이에요.","글자가 작아서 다 읽을 필요는 없어요. 어디에 무엇이 적히는지만 보면 돼요.","맨 위 표가 일정, 가운데가 자격, 아래가 제출서류예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"공고문에서 읽어 둘 숫자","items":["**입찰보증금(bid bond)** 은 입찰금액의 5/100, 즉 5% 이상이에요.","낙찰 후 7일 이내에 계약을 체결해야 해요.","계약을 체결하지 않으면 낙찰이 무효가 되고 입찰보증금은 발주처에 귀속돼요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**공개경쟁입찰(open competitive bidding)** 공고가 나가면 입찰 절차가 시작돼요.","공고 → 참가신청 → **현장설명(on-site orientation)** → 투찰 → 개찰과 낙찰 → 계약 순서예요.","이 흐름은 p18 그림에서 한 번 더 정리해요."]}],"pass3":[{"kind":"check","q":"**입찰보증금(bid bond)** 은 원칙적으로 입찰금액의 얼마 이상인가요?","choices":["100분의 1","100분의 3","100분의 5","100분의 10"],"a":2,"why":"100분의 5, 즉 5% 이상이에요. 공고문에도 5/100 이상이라고 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p012_h.jpg"},"parts":[{"b":[0.3,0.148,0.55,0.1],"c":[0.2725,0.132,0.605,0.132],"r":8.1481,"img":"img/L2/walk/p012_20_01.jpg","say":"맨 위 표: 입찰건명, **현장설명(on-site orientation)** 일시, 입찰등록, 입찰일시가 나란히 적혀 있어요."},{"b":[0.3,0.255,0.42,0.035],"c":[0.279,0.2175,0.462,0.11],"r":7.4667,"img":"img/L2/walk/p012_20_02.jpg","say":"표 아래 한 줄: 현장설명 참가는 필수 사항이라고 못 박아 두었어요."},{"b":[0.3,0.55,0.4,0.035],"c":[0.28,0.5125,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p012_20_03.jpg","say":"5번 **입찰보증금(bid bond)**: 낙찰자 입찰금액의 5/100 이상을 이행입찰보증보험증권으로 제출해요."},{"b":[0.3,0.6,0.28,0.17],"c":[0.286,0.584,0.308,0.202],"r":2.7107,"img":"img/L2/walk/p012_20_04.jpg","say":"6번 제출서류: 입찰참가신청서, 사업자등록증, 보증보험증권, 면허증, 인감증명서, 위임장, 입찰서."},{"b":[0.3,0.92,0.55,0.05],"c":[0.2725,0.8778,0.605,0.1222],"r":8.8016,"img":"img/L2/walk/p012_20_05.jpg","say":"맨 아래: 낙찰자는 낙찰 후 7일 이내에 계약을 체결해야 하고, 안 하면 입찰보증금이 귀속돼요."}]}},{"p":13,"title":"제한경쟁입찰 실제 공고문 1","terms":["private competitive bidding","공동이행방식","on-site orientation"],"pass1":[{"kind":"say","lines":["**제한경쟁입찰(private competitive bidding)** 실제 공고문의 첫 번째 예시예요.","슬라이드에 '공사실적!' 이라고 크게 적혀 있어요. 그게 제한의 열쇠예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"이 공고문이 건 제한","items":["제출서류 7번에 건설공사실적확인서가 있어요.","조건은 공고일부터 5년간 단일 연면적 5,000제곱미터 이상 실적이에요.","즉 실적이 모자라면 아예 입찰에 못 들어와요. 이것이 **제한경쟁입찰(private competitive bidding)** 이에요."]},{"kind":"points","head":"공고문에서 같이 표시된 것","items":["표 안에 **현장설명(on-site orientation)** 일시와 장소가 적혀 있어요.","비고 칸에 '필요시 **공동이행방식** 이 가능' 이라고 적혀 있어요.","참가자격에는 건축사면허, 감리업 등록, 정보통신, 소방 관련 등록 여부가 줄줄이 나와요."]}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0551],"c":[0,0.0208,0.2111,0.0871],"r":4.3087,"img":"img/L2/walk/p013_h.jpg"},"parts":[{"b":[0.318,0.111,0.54,0.11],"c":[0.291,0.095,0.594,0.142],"r":7.4366,"img":"img/L2/walk/p013_20_01.jpg","say":"맨 위 표: 입찰건명, **현장설명(on-site orientation)** 일시와 장소, 입찰등록, 입찰일시가 나란히 있어요."},{"b":[0.757,0.15,0.1,0.055],"c":[0.707,0.1225,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p013_20_02.jpg","say":"비고 칸에 '필요시 **공동이행방식** 이 가능' 이라고 적혀 있어요."},{"b":[0.313,0.25,0.545,0.25],"c":[0.2858,0.234,0.5995,0.282],"r":3.7794,"img":"img/L2/walk/p013_20_03.jpg","say":"2. 입찰 참가자격. 건축사면허, 감리업, 정보통신, 소방 관련 등록 여부가 줄줄이 나와요."},{"b":[0.313,0.645,0.41,0.03],"c":[0.2925,0.605,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p013_20_04.jpg","say":"5. 입찰보증금: 낙찰자 입찰금액의 5/100 이상이에요."},{"b":[0.316,0.813,0.365,0.035],"c":[0.2978,0.7755,0.4015,0.11],"r":6.4889,"img":"img/L2/walk/p013_20_05.jpg","say":"제출서류 7번 건설공사실적확인서. 공고일부터 5년간 단일 연면적 5,000제곱미터 이상이 이 공고의 제한이에요."},{"b":[0.313,0.935,0.545,0.05],"c":[0.2858,0.8789,0.5995,0.1211],"r":8.8008,"img":"img/L2/walk/p013_20_06.jpg","say":"맨 아래: 낙찰 후 7일 이내에 계약을 체결해야 하고, 안 하면 입찰보증금이 귀속돼요."}]}},{"p":14,"title":"제한경쟁입찰 실제 공고문 2","terms":["private competitive bidding","총액입찰","on-site orientation"],"pass1":[{"kind":"say","lines":["**제한경쟁입찰(private competitive bidding)** 두 번째 예시예요.","앞 예시와 같은 자리에 '공사실적!' 표시가 있어요. 숫자만 달라요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"이 공고문이 건 제한","items":["제출서류 8번 건설공사실적확인서, 공고일부터 3년간 단일공사로 10억 원 이상이에요.","앞 예시는 5년간 연면적 5,000제곱미터, 이번은 3년간 10억 원이에요.","기간과 기준은 공사마다 다르게 정한다는 것만 알면 돼요."]},{"kind":"points","head":"비고 칸과 필수 사항","items":["비고에 '설계도면에 의한 **총액입찰** 서, 설계금액은 미공개' 라고 적혀 있어요.","본 공사는 **현장설명(on-site orientation)** 참석이 의무사항이라고 적혀 있어요.","**총액입찰** 은 세부내역 없이 전체 금액만 적어 내는 방식이에요. p17에서 자세히 봐요."]}],"pass3":[{"kind":"check","q":"두 제한경쟁입찰 공고문이 참가를 제한할 때 공통으로 사용한 서류는?","choices":["안전관리계획서","건설공사실적확인서","품질시험계획서","직접시공계획서"],"a":1,"why":"예시1은 5년간 연면적 5,000제곱미터 이상, 예시2는 3년간 10억 원 이상 실적을 요구했어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p014_h.jpg"},"parts":[{"b":[0.318,0.145,0.55,0.115],"c":[0.2905,0.129,0.605,0.147],"r":7.3167,"img":"img/L2/walk/p014_20_01.jpg","say":"맨 위 표: 입찰건명, **현장설명(on-site orientation)**, 입찰등록, 입찰일시, 비고가 있어요."},{"b":[0.812,0.163,0.06,0.055],"c":[0.742,0.1355,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p014_20_02.jpg","say":"비고 칸에 '설계도면에 의한 **총액입찰** 서, 설계금액은 미공개' 라고 적혀 있어요."},{"b":[0.516,0.26,0.26,0.032],"c":[0.503,0.221,0.286,0.11],"r":4.6222,"img":"img/L2/walk/p014_20_03.jpg","say":"표 아래 한 줄: 본 공사는 현장설명 참석이 의무사항이에요."},{"b":[0.313,0.59,0.41,0.03],"c":[0.2925,0.55,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p014_20_04.jpg","say":"5. 입찰보증금: 낙찰자 입찰금액의 5/100 이상이에요. 앞 예시와 같아요."},{"b":[0.316,0.782,0.36,0.032],"c":[0.298,0.743,0.396,0.11],"r":6.4,"img":"img/L2/walk/p014_20_05.jpg","say":"제출서류 8번 건설공사실적확인서. 공고일부터 3년간 단일공사로 10억 원 이상이 이 공고의 제한이에요."},{"b":[0.313,0.905,0.55,0.075],"c":[0.2855,0.8778,0.605,0.1222],"r":8.8016,"img":"img/L2/walk/p014_20_06.jpg","say":"맨 아래: 낙찰 후 7일 이내 계약 체결, 안 하면 낙찰 무효와 입찰보증금 귀속이에요."}]}},{"p":15,"title":"입찰 프로세스 1, 공고와 참가신청과 보증금","terms":["bid bond","open competitive bidding","client, owner"],"pass1":[{"kind":"say","lines":["입찰은 정해진 순서대로 굴러가요. 이 쪽은 그 앞의 세 단계예요.","입찰공고 → 입찰참가신청 → **입찰보증금(bid bond)** 납부 순서예요.","주문으로 외워요. '공신보P현투낙계' 의 앞 세 글자예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"1단계 입찰공고에 적는 것","items":["공사 현장에 대한 입찰을 실시하려고 작성하고, 입찰 신청을 모집하는 서류예요.","입찰건명, 계약의 목적물, 입찰 일시와 장소, 참가 자격, **입찰보증금(bid bond)**, 입찰 무효에 관한 내용을 적어요.","발주처의 명칭과 연락처를 포함해요.","공고 방법은 조달청 나라장터, 발주처의 인터넷 홈페이지 게시 등이에요."]},{"kind":"points","head":"2단계 입찰참가신청","items":["입찰참가신청 마감일까지 입찰참가신청서 등을 발주처에 제출해요.","입찰참가 신청을 한 자가 아니면 입찰에 참가할 수 없어요.","담합, 계약관련 서류의 부정한 사용, 정당한 사유 없이 적격심사서류를 내지 않은 업체는 참가 제한을 받아요."]},{"kind":"points","head":"3단계 **입찰보증금(bid bond)**, 숫자 문제 단골","items":["낙찰 후 계약을 성실하게 체결할 것을 담보하기 위해 납부하는 보증금이에요.","원칙적으로 입찰금액의 100분의 5, 즉 5% 이상이에요.","현금, 지급보증서, 보증보험증권, 공제조합 보증서 등으로 납부할 수 있어요.","신청마감일 또는 입찰일 전일까지 입찰참가신청서와 함께 납부해야 해요."]},{"kind":"points","head":"내지 않으면 어떻게 되나","items":["낙찰자가 정당한 사유 없이 계약을 체결하지 않으면 입찰보증금은 국가 또는 지방자치단체에 귀속돼요.","즉 **발주자(client, owner)** 가 가져가요. 돌려받지 못해요.","이 돈은 '계약을 꼭 하겠다' 는 약속의 담보예요."]}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"경쟁입찰 참가자가 낙찰 후 계약을 성실히 체결할 것을 담보하기 위해 내는 보증금은 입찰금액의 몇 퍼센트 이상인가?","qko":"입찰보증금은 얼마 이상 내야 할까요.","solve":["슬라이드 문장은 '입찰금액의 100분의 5 (5%) 이상' 이에요.","100분의 5를 퍼센트로 바꾸면 5퍼센트예요."],"answer":"5퍼센트 이상이에요."},{"kind":"check","q":"**입찰보증금(bid bond)** 에 대한 설명으로 옳은 것은?","choices":["낙찰자가 계약을 체결하지 않으면 입찰자에게 반환된다","원칙적으로 입찰금액의 100분의 5 이상이다","현금으로만 납부할 수 있다","계약 체결 후에 납부한다"],"a":1,"why":"5% 이상이고 현금, 지급보증서, 보증보험증권 등으로 납부해요. 계약을 안 하면 국가나 지자체에 귀속돼요."},{"kind":"warn","head":"슬라이드 오타 주의","items":["p15의 '입찰참가신청을 해한다' 는 '하여야 한다' 의 오타예요. 뜻은 신청을 해야 한다는 것이에요.","입찰보증금은 계약 후가 아니라 입찰 '전' 에 내요.","**공개경쟁입찰(open competitive bidding)** 이든 제한경쟁이든 보증금 기준은 같아요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p015_h.jpg"},"parts":[{"b":[0.025,0.148,0.895,0.175],"c":[0,0.132,0.9845,0.207],"r":8.4552,"img":"img/L2/walk/p015_20_01.jpg","say":"1.4.1 입찰공고. 입찰건명, 계약의 목적물, 일시와 장소, 참가 자격, **입찰보증금(bid bond)**, 입찰 무효를 적어요."},{"b":[0.025,0.352,0.845,0.175],"c":[0,0.336,0.9295,0.207],"r":7.9828,"img":"img/L2/walk/p015_20_02.jpg","say":"1.4.2 입찰참가신청. 마감일까지 신청서를 내야 하고, 신청한 자가 아니면 입찰에 참가할 수 없어요."},{"b":[0.025,0.555,0.285,0.035],"c":[0.0107,0.5175,0.3135,0.11],"r":5.0667,"img":"img/L2/walk/p015_20_03.jpg","say":"1.4.3 **입찰보증금(bid bond)**. 영문으로 bid bond, bidding deposit 이라고 적혀 있어요."},{"b":[0.032,0.605,0.835,0.08],"c":[0,0.5522,0.9185,0.1856],"r":8.7979,"img":"img/L2/walk/p015_20_04.jpg","say":"낙찰자가 정당한 사유 없이 계약을 체결하지 않으면 국가 또는 지방자치단체에 귀속돼요."},{"b":[0.032,0.695,0.7,0.032],"c":[0,0.6332,0.77,0.1556],"r":8.7975,"img":"img/L2/walk/p015_20_05.jpg","say":"숫자 문제 단골: 입찰금액의 100분의 5, 즉 5퍼센트 이상이에요."},{"b":[0.032,0.742,0.52,0.032],"c":[0.006,0.7002,0.572,0.1156],"r":8.7966,"img":"img/L2/walk/p015_20_06.jpg","say":"납부 시기: 신청마감일 또는 입찰일 전일까지 신청서와 함께 내요."}]}},{"p":16,"title":"입찰 프로세스 2, 사전심사(PQ)와 현장설명","terms":["PQ","on-site orientation","bid bond"],"pass1":[{"kind":"analogy","head":"오디션에 비유하면","scene":"입찰을 오디션이라고 생각해 봐요.","map":[["**입찰참가자격 사전심사(PQ)**","본선 전에 보는 예선"],["**현장설명(on-site orientation)**","무대에 미리 올라가 보는 리허설"]]},{"kind":"say","lines":["**입찰참가자격 사전심사(PQ)** 는 능력 없는 회사를 미리 거르는 제도예요.","**현장설명(on-site orientation)** 은 도면에 못 적은 것을 현장에서 말로 알려 주는 자리예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**입찰참가자격 사전심사(PQ)** 를 한 줄로","items":["PQ는 Prequalification 의 약자예요.","부실공사를 방지하기 위해 입찰 전에 미리 공사수행능력 등을 심사해요.","일정수준 이상의 능력을 갖춘 자에게만 입찰에 참가할 자격을 부여하는 제도예요.","원칙적으로 발주기관이 필요에 따라 실시하지만, 관계 법령이 정한 일부 공사에는 의무적으로 적용돼요."]},{"kind":"points","head":"PQ가 심사하는 것과 문제점","items":["공사 수행 실적, 기술력, 재무 상태, 과거의 계약이행 성실도와 법령 준수 여부를 심사해요.","일정 기준을 통과한 업체에만 입찰참가자격을 줘요.","다만 과거 실적과 재무상태의 비중이 높으면 신규업체와 중소업체에 불리해요.","그래서 입찰시장의 진입장벽이 될 수 있다는 지적이 있어요."]},{"kind":"points","head":"**현장설명(on-site orientation)** 을 한 줄로","items":["입찰참가신청자에게 설계도서에 나타낼 수 없는 사항 등을 현지에서 보충 설명하는 것이에요.","준비하는 자료: 설계내역서, 도면, 단가산출서, 시방서, 조감도.","시방서는 시공 방법을 정리한 도서예요.","발주처 관계자가 공사의 특기사항, 단가산출 방법, 현장상황 등을 설명해요."]},{"kind":"points","head":"**현장설명(on-site orientation)** 에서 참가자가 할 일","items":["대리인계, 기술자 수첩사본, 위임장, 재직증명을 제출해요.","참석자 명단에 회사명, 사업자등록번호, 대표자명, 참석자명, 연락처를 적고 서명 날인해요.","발주처는 참가자의 신원을 확인해요. 이때 종종 실측과 사진 촬영이 가능해요.","관급공사는 필요성이 없다고 인정되면 생략하거나 설계도서 열람으로 갈음할 수 있어요."]}],"pass3":[{"kind":"check","q":"입찰 전에 공사수행능력을 심사하여 일정 수준 이상의 업체에만 입찰 자격을 주는 제도는?","choices":["**입찰참가자격 사전심사(PQ)**","**내역입찰**","**재공고입찰**","**현장설명(on-site orientation)**"],"a":0,"why":"PQ는 Prequalification 이에요. 실적과 재무상태 비중이 높으면 신규, 중소업체에 진입장벽이 될 수 있어요."},{"kind":"english","head":"단답 대비 문장","en":"입찰참가자격 사전심사를 영문 약자로 PQ, 원어로 Prequalification 이라 한다.","ko":"부실공사를 방지하려고 입찰 전에 공사수행능력을 미리 심사하는 제도이다.","tip":"'Pre(미리) + qualification(자격)' 으로 뜻을 붙여 외워요."},{"kind":"warn","head":"자리를 헷갈리지 마세요","items":["**입찰참가자격 사전심사(PQ)** 는 **입찰보증금(bid bond)** 다음, **현장설명(on-site orientation)** 앞이에요.","현장설명은 '설계도서에 나타낼 수 없는' 사항을 보충하는 자리예요.","현장설명 참석이 의무인 공고도 있어요. p13, p14 공고문에서 보았죠."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p016_h.jpg"},"parts":[{"b":[0.025,0.148,0.82,0.185],"c":[0,0.132,0.902,0.217],"r":7.3897,"img":"img/L2/walk/p016_20_01.jpg","say":"1.4.4 **입찰참가자격 사전심사(PQ)**. 제목에 PQ : Prequalification 이라고 영문이 함께 적혀 있어요."},{"b":[0.025,0.39,0.85,0.135],"c":[0,0.363,0.935,0.1889],"r":8.7995,"img":"img/L2/walk/p016_20_02.jpg","say":"1.4.5 **현장설명(on-site orientation)**. 설계도서에 나타낼 수 없는 사항을 현지에서 보충 설명해요."},{"b":[0.032,0.535,0.85,0.032],"c":[0,0.4565,0.935,0.1889],"r":8.7995,"img":"img/L2/walk/p016_20_03.jpg","say":"관급공사는 필요성이 없다고 인정되면 생략하거나 설계도서 열람으로 갈음할 수 있어요."},{"b":[0.032,0.58,0.87,0.075],"c":[0,0.5208,0.957,0.1933],"r":8.8015,"img":"img/L2/walk/p016_20_04.jpg","say":"참가자는 대리인계, 기술자 수첩사본, 위임장, 재직증명을 내고 참석자 명단에 적고 서명 날인해요."},{"b":[0.139,0.665,0.635,0.3],"c":[0.1073,0.649,0.6985,0.332],"r":3.7403,"img":"img/L2/walk/p016_20_05.jpg","say":"아래 사진 세 장이 실제 현장설명 모습이에요. 강당에서 듣기도 하고 현장에 모여 듣기도 해요."}]}},{"p":17,"title":"입찰 프로세스 3, 총액입찰과 내역입찰, 그리고 재입찰","terms":["총액입찰","내역입찰","유찰","rebidding","재공고입찰","optional contract"],"pass1":[{"kind":"analogy","head":"가격표를 어떻게 내는가","scene":"장을 볼 때에 비유해요.","map":[["**총액입찰**","'다 해서 10만 원' 이라고 총액만 적어 내기"],["**내역입찰**","'사과 3천 원, 배 5천 원' 처럼 품목별 단가까지 적어 내기"]]},{"kind":"say","lines":["금액을 적어 내는 것을 투찰이라고 해요.","낙찰자가 안 나오면 **유찰** 이고, 그러면 **재입찰(rebidding)** 이나 **재공고입찰** 로 가요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"입찰에 참가하는 방법","items":["관급공사의 입찰은 원칙적으로 국가종합전자조달시스템(나라장터) 등 전자조달시스템으로 진행해요.","공사 특성이나 절차상 필요하면 입찰서를 직접 또는 우편으로 제출하게 할 수 있어요.","전자입찰은 입찰 장소에 가지 않고 인터넷으로 참여하는 방식이에요."]},{"kind":"compare","head":"**총액입찰** 과 **내역입찰**, 숫자로 갈려요","cols":["구분","무엇을 적어 내나","적용 기준"],"rows":[["**총액입찰**","세부 산출내역을 내지 않고 입찰서에 공사 전체의 총액만 기재","추정가격 100억 원 미만의 공사. 낙찰자는 착공신고서를 낼 때 산출내역서를 제출"],["**내역입찰**","발주기관이 제시한 물량내역서의 각 공종에 단가를 기재해 산출내역서를 작성, 입찰서와 함께 제출","관급공사에서 원칙적으로 추정가격 100억 원 이상인 공사"]]},{"kind":"points","head":"**유찰**, **재입찰(rebidding)**, **재공고입찰**","items":["입찰이 성립하지 않거나 낙찰자가 결정되지 않은 경우를 **유찰** 이라고 해요.","유찰된 경우 기존 입찰조건을 유지한 채 다시 투찰하게 하는 것이 **재입찰(rebidding)** 이에요.","재입찰은 새로운 입찰로 보지 않으며 입찰횟수의 제한을 받지 않아요.","입찰공고부터 다시 하여 절차를 새로 진행하는 것은 **재공고입찰** 이에요."]},{"kind":"points","head":"그래도 낙찰자가 없으면","items":["**재공고입찰** 에서도 입찰이 성립하지 않거나 낙찰자가 없는 경우가 있어요.","그때는 관계 법령에 따라 **수의계약(optional contract)** 을 체결할 수 있어요.","즉 경쟁이 안 되면 마지막에 한 업체와 직접 계약하는 길이 열려요."]}],"pass3":[{"kind":"check","q":"관급공사에서 원칙적으로 추정가격 100억 원 이상인 공사에 적용하는 입찰 방식은?","choices":["**총액입찰**","**지명경쟁입찰(selective bidding)**","**내역입찰**","**재입찰(rebidding)**"],"a":2,"why":"100억 원 미만은 일반적으로 총액입찰, 100억 원 이상은 내역입찰이에요."},{"kind":"check","q":"**재입찰(rebidding)** 에 대한 설명으로 옳은 것은?","choices":["새로운 입찰로 보며 횟수 제한이 있다","입찰공고부터 다시 한다","기존 입찰조건을 유지한 채 다시 투찰하게 한다","**유찰** 되지 않아도 할 수 있다"],"a":2,"why":"재입찰은 새로운 입찰로 보지 않고 횟수 제한도 없어요. 공고부터 다시 하면 재공고입찰이에요."},{"kind":"warn","head":"헷갈리는 짝","items":["**재입찰(rebidding)** 은 같은 조건으로 '다시 투찰', **재공고입찰** 은 '공고부터' 다시예요.","**총액입찰** 은 100억 원 '미만', **내역입찰** 은 100억 원 '이상' 이에요.","총액입찰 낙찰자도 착공신고서를 낼 때는 산출내역서를 제출해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0551],"c":[0,0.0208,0.2111,0.0871],"r":4.3087,"img":"img/L2/walk/p017_h.jpg"},"parts":[{"b":[0.025,0.148,0.665,0.225],"c":[0,0.132,0.7315,0.257],"r":5.0601,"img":"img/L2/walk/p017_20_01.jpg","say":"1.4.6 입찰참가(bid, tender). 관급공사는 원칙적으로 나라장터 등 전자조달시스템으로 진행해요."},{"b":[0.69,0.1,0.3,0.3],"c":[0.67,0.084,0.33,0.332],"r":1.7671,"img":"img/L2/walk/p017_20_02.jpg","say":"오른쪽 화면 캡처가 국가종합전자조달 나라장터예요. 여기서 공고를 검색하고 전자로 투찰해요."},{"b":[0.032,0.382,0.645,0.125],"c":[0,0.366,0.7095,0.157],"r":8.034,"img":"img/L2/walk/p017_20_03.jpg","say":"1) **총액입찰**. 세부 산출내역 없이 총액만 기재. 추정가격 100억 원 미만 공사예요."},{"b":[0.032,0.54,0.68,0.125],"c":[0,0.524,0.748,0.157],"r":8.4699,"img":"img/L2/walk/p017_20_04.jpg","say":"2) **내역입찰**. 물량내역서의 각 공종에 단가를 기재해요. 관급공사는 100억 원 이상이에요."},{"b":[0.025,0.71,0.825,0.13],"c":[0,0.6833,0.9075,0.1833],"r":8.8016,"img":"img/L2/walk/p017_20_05.jpg","say":"1.4.7 재입찰(rebidding). **유찰** 되면 기존 조건을 유지한 채 다시 투찰하는 것이 **재입찰(rebidding)** 이에요."},{"b":[0.032,0.853,0.825,0.085],"c":[0,0.8038,0.9075,0.1833],"r":8.8016,"img":"img/L2/walk/p017_20_06.jpg","say":"공고부터 다시 하면 **재공고입찰**. 그래도 낙찰자가 없으면 **수의계약(optional contract)** 을 체결할 수 있어요."}]}},{"p":18,"title":"입찰 프로세스 전체 흐름도","terms":["on-site orientation","유찰","rebidding","재공고입찰","bid bond","PQ"],"pass1":[{"kind":"say","lines":["이 쪽은 입찰 전체를 한 장의 흐름도로 묶은 그림이에요.","왼쪽 줄이 발주처가 하는 일, 오른쪽 줄이 시공사가 하는 일이에요.","점선은 '같은 단계에서 서로 마주 본다' 는 뜻이에요."]},{"kind":"points","head":"입찰 순서 주문","items":["공고, 신청, 보증금, PQ, 현장설명, 투찰, 낙찰, 계약","앞 글자만 따서 '공신보P현투낙계' 로 외워요.","이 여덟 글자가 입찰 문제의 순서 나열 답이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"steps","head":"흐름을 여덟 단계로 다시 쓰기","steps":["발주처가 입찰공고를 냅니다.","시공사가 입찰 참가 신청을 하고 **입찰보증금(bid bond)** 을 냅니다.","필요한 공사는 **입찰참가자격 사전심사(PQ)** 를 거칩니다.","**현장설명(on-site orientation)** 에 참석합니다.","시공사가 입찰 금액을 산정해 입찰서를 제출합니다(투찰).","발주처가 개찰해 낙찰자를 결정하고 계약을 체결합니다."],"answer":"낙찰자가 없으면 **유찰** 이 되고 **재입찰(rebidding)** 또는 **재공고입찰** 로 돌아가요."}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"다음 입찰 절차를 순서대로 나열하시오. 현장설명, 입찰공고, 계약 체결, 입찰참가신청, 개찰과 낙찰자 결정, 투찰","qko":"입찰은 어떤 순서로 굴러가나요.","solve":["주문 '공신보P현투낙계' 를 떠올려요.","공고 → 참가신청(보증금) → PQ → 현장설명 → 투찰 → 개찰과 낙찰 → 계약이에요.","보기에 PQ와 보증금이 없으니 그 둘은 빼고 적어요."],"answer":"입찰공고 → 입찰참가신청 → **현장설명(on-site orientation)** → 투찰 → 개찰과 낙찰자 결정 → 계약 체결"},{"kind":"check","q":"낙찰자가 결정되지 않아 **유찰** 되었을 때, 공고부터 다시 진행하는 것은?","choices":["**재입찰(rebidding)**","**재공고입찰**","투찰","개찰"],"a":1,"why":"같은 조건으로 다시 투찰하게 하면 재입찰, 공고부터 다시 하면 재공고입찰이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p018_h.jpg"},"parts":[{"b":[0.28,0.215,0.44,0.045],"c":[0.258,0.1825,0.484,0.11],"r":7.8222,"img":"img/L2/walk/p018_20_01.jpg","say":"맨 위 두 기둥: 왼쪽이 발주처, 오른쪽이 시공사예요."},{"b":[0.39,0.31,0.13,0.05],"c":[0.355,0.28,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p018_20_02.jpg","say":"발주처가 입찰공고를 내면서 시작해요."},{"b":[0.39,0.385,0.31,0.05],"c":[0.3745,0.355,0.341,0.11],"r":5.5111,"img":"img/L2/walk/p018_20_03.jpg","say":"발주처는 입찰 참가 접수, 시공사는 입찰 참가 신청을 해요. 이때 **입찰보증금(bid bond)** 도 내요."},{"b":[0.39,0.46,0.31,0.05],"c":[0.3745,0.43,0.341,0.11],"r":5.5111,"img":"img/L2/walk/p018_20_04.jpg","say":"**현장설명(on-site orientation)** 자리. 발주처가 설명하고 시공사가 참석해요. 앞에 **입찰참가자격 사전심사(PQ)** 가 있는 공사도 있어요."},{"b":[0.39,0.535,0.31,0.12],"c":[0.3745,0.519,0.341,0.152],"r":3.9883,"img":"img/L2/walk/p018_20_05.jpg","say":"시공사가 입찰 금액을 산정해 입찰서를 제출(투찰)하고, 발주처가 접수해 개찰해요."},{"b":[0.29,0.47,0.12,0.19],"c":[0.25,0.454,0.2,0.222],"r":1.6016,"img":"img/L2/walk/p018_20_06.jpg","say":"낙찰자가 없으면 **유찰**. 같은 조건으로 다시 하면 **재입찰(rebidding)**, 공고부터 다시 하면 **재공고입찰** 이에요."}]}},{"p":19,"title":"공사 계약과 계약서","terms":["contract","contract document","수급인","간인","client, owner","builder, contractor","하자담보책임기간"],"pass1":[{"kind":"analogy","head":"계약서는 게임의 룰을 적은 종이예요","scene":"친구와 내기를 할 때를 떠올려 보세요.","map":[["**계약(contract)**","서로 지켜야 할 의무를 정하는 것"],["**계약서(contract document)**","그 약속을 글로 적어 증거로 남긴 종이"],["**간인**","종이를 바꿔치기 못 하게 장과 장 사이에 찍는 도장"]]},{"kind":"say","lines":["입찰이 끝나고 낙찰자가 정해지면 바로 이 **계약(contract)** 단계로 와요.","계약서를 쓰고 도장을 찍는 순간부터 법이 양쪽을 붙잡아 줘요."]}],"pass2":[{"kind":"points","head":"**계약(contract)** 을 한 줄로","items":["서로 연관되는 사람이나 조직 사이에 상호 지켜야 할 의무를 정하는 것이에요.","인테리어에서는 설계와 시공을 위하여 **발주자(client, owner)** 와 공급자 또는 도급자 사이에 체결돼요.","**계약서(contract document)** 를 쓰고 계약이 체결되면 쌍방의 관계가 법률적으로 확정돼요.","계약으로 생기는 법률 효과는 당사자 간 권리와 의무의 발생, 변경, 소멸이에요."]},{"kind":"points","head":"**계약서(contract document)** 에 적는 주요 내용","items":["발주자와 도급자, 공사명, 내용, 금액, 기간","대금 지급 시기와 방법","발주자와 도급자의 책임, 분쟁해결방법","**하자담보책임기간**, 즉 하자보수기간"]},{"kind":"look","walked":1},{"kind":"points","head":"공사 순서에서의 자리","items":["개찰과 낙찰자 결정이 끝나면 **계약(contract)** 을 체결해요.","계약이 끝나야 **시공자(builder, contractor)** 가 공사 계획을 세우고 착공 준비에 들어가요.","즉 계약은 입찰(앞)과 공사계획(뒤) 사이에 끼어 있어요."]}],"pass3":[{"kind":"check","q":"공사 **계약서(contract document)** 에 대한 설명으로 옳지 않은 것은?","choices":["최종 계약서는 2부 작성하여 각 1부씩 보관한다","**간인** 이 없어도 계약의 효력에는 영향이 없다","갑과 을 표기는 법적 의무이다","특약사항을 추가할 수 있다"],"a":2,"why":"갑, 을 표기는 편의상 쓰는 것이고 법적 의무가 아니에요."},{"kind":"english","head":"서술형 대비 문장","en":"계약서에는 발주자와 도급자, 공사명, 내용, 금액, 기간, 대금 지급 시기와 방법을 적는다.","ko":"여기에 양쪽의 책임, 분쟁해결방법, 하자보수기간을 더해 쓴다.","tip":"'사람, 공사, 돈, 기간, 책임, 분쟁, 하자' 일곱 토막으로 외워요."},{"kind":"warn","head":"법적 의무가 아닌 것 두 개","items":["'갑' 과 '을' 이라는 표기는 법적 의무가 아니에요.","**간인** 도 법적 의무가 아니에요. 위, 변조 방지를 위한 실무 관행이에요.","반대로 계약서를 2부 만들어 각 1부씩 보관한다는 것은 자주 나오는 숫자예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.8186,0.4992],"c":[0,0.0119,0.9004,0.5491],"r":2.9152,"img":"img/L2/walk/p019_h.jpg"},"parts":[{"b":[0.04,0.555,0.62,0.065],"c":[0.009,0.5186,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_01.jpg","say":"갑과 을 표시는 편의상 쓰는 것이고 법적 의무는 아니에요. 맡기는 쪽이 **발주자(client, owner)**(도급인), 수행하는 쪽이 **수급인** 이에요."},{"b":[0.04,0.645,0.62,0.07],"c":[0.009,0.6111,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_02.jpg","say":"계약서는 법률문서예요. 분쟁 시 계약서, 설계도서, 견적서, 특약사항을 기준으로 책임과 범위를 판단해요."},{"b":[0.04,0.735,0.62,0.035],"c":[0.009,0.6836,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_03.jpg","say":"표준서식을 참고하되 협의로 내용을 조정하고 특약사항을 추가할 수 있어요."},{"b":[0.04,0.778,0.62,0.033],"c":[0.009,0.7256,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_04.jpg","say":"최종 계약서는 2부 작성해 발주자와 **수급인** 이 서명 또는 날인하고 각 1부씩 보관해요."},{"b":[0.04,0.835,0.62,0.037],"c":[0.009,0.7846,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_05.jpg","say":"공사대금 지급, 하자보수, 손해배상, 비밀유지 등 일부 조항은 계약 종료 후에도 지속될 수 있어요."},{"b":[0.04,0.878,0.62,0.037],"c":[0.009,0.8276,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p019_22_06.jpg","say":"**간인** 은 법적 의무가 아니고 없어도 효력에 영향이 없지만 위, 변조 방지를 위해 실무상 씁니다."}]}},{"p":20,"title":"계약서 사례 1, 공사도급계약서","terms":["contract document","정액도급","client, owner","수급인"],"pass1":[{"kind":"say","lines":["실제 공사도급계약서 세 장을 펼쳐 놓은 사진이에요.","슬라이드에 '어떤 종류의 도급 계약 방식일까?' 라는 질문이 적혀 있어요.","힌트는 제3조 도급액 부분이에요. 총액으로 정해 두었어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"힌트가 가리키는 답","items":["제3조 도급액에 '총액 일금 OOO원정으로 산정하여 다음 각호에 따라 현금 지불한다' 라고 적혀 있어요.","금액 총액을 미리 확정했으니 **정액도급** 이에요.","정액도급은 계약금(선급금), 중도금, 잔금으로 나누어 지불하는 것이 일반적이에요."]},{"kind":"points","head":"이 **계약서(contract document)** 의 조문 흐름","items":["제1조 계약의 목적, 제2조 공사명, 제3조 도급액, 제4조 공사기간, 제5조 선급금 공제","제6조 공사 관리자, 제7조 공사자재, 제8조 설계변경, 제9조 양도금지, 제10조 감독","제11조 안전의무, 제13조 공사완료(검사), 제14조 해지, 제15조 기타사항","제16조 분쟁해결, 제17조 특약사항"]},{"kind":"points","head":"맨 뒤 장에서 확인할 것","items":["'본 계약서 2통을 작성하여 각각 서명 날인한 후 갑과 을이 각각 1통씩 보관한다' 라고 적혀 있어요.","아래에 갑(**발주자(client, owner)**) 과 을(**수급인**) 의 주소, 회사명, 대표자, 연락처 칸이 있어요.","제17조 특약사항이 본문과 어긋나면 특약사항이 우선한다고 적혀 있어요."]}],"pass3":[{"kind":"check","q":"도급액을 총액 일금 OOO원정으로 산정한 이 계약서는 공사비 지급 방식으로 어떤 도급인가요?","choices":["단가도급","**정액도급**","실비정산보수가산도급","분할도급"],"a":1,"why":"총액을 미리 확정했으니 정액도급이에요. 보통 선급금, 중도금, 잔금으로 나누어 지불해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p020_h.jpg"},"parts":[{"b":[0.105,0.16,0.15,0.042],"c":[0.08,0.126,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p020_20_01.jpg","say":"맨 위 분홍 질문: 어떤 종류의 도급 계약 방식일까, 공사비 지급 방식에 따라 분류한다면."},{"b":[0.105,0.452,0.21,0.03],"c":[0.093,0.412,0.234,0.11],"r":3.7818,"img":"img/L2/walk/p020_20_02.jpg","say":"제3조 도급액. 총액 일금 OOO원정으로 산정한다고 적혀 있어요. 그래서 **정액도급** 이에요."},{"b":[0.105,0.48,0.21,0.06],"c":[0.093,0.455,0.234,0.11],"r":3.7818,"img":"img/L2/walk/p020_20_03.jpg","say":"그 아래가 선급금, 중도금, 잔금으로 나누어 지불하는 각호예요."},{"b":[0.33,0.71,0.31,0.032],"c":[0.3145,0.671,0.341,0.11],"r":5.5111,"img":"img/L2/walk/p020_20_04.jpg","say":"가운데 장 제13조 공사완료. 작업의 합격 여부를 검사해야 한다고 적혀 있어요."},{"b":[0.688,0.482,0.06,0.026],"c":[0.618,0.44,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p020_20_05.jpg","say":"오른쪽 장 제17조 특약사항. 본문과 어긋나면 특약사항이 우선해요."},{"b":[0.688,0.616,0.29,0.035],"c":[0.6735,0.5785,0.319,0.11],"r":5.1556,"img":"img/L2/walk/p020_20_06.jpg","say":"맨 아래: 본 **계약서(contract document)** 2통을 작성해 갑과 을이 각각 1통씩 보관해요."}]}},{"p":21,"title":"계약서 사례 2, 인테리어공사 표준계약서","terms":["contract document","하자담보책임기간","client, owner","수급인"],"pass1":[{"kind":"say","lines":["이번에는 인테리어공사 표준계약서 사진이에요.","왼쪽이 공사개요와 대금 지급 시기, 오른쪽이 계약일반조건이에요.","슬라이드는 제3조 하자보수 부분을 짚으며 '하자보수 기간?' 이라고 물어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왼쪽 장에서 읽을 것","items":["맨 위에 '당사자는 계약을 체결하고 계약서 2부를 작성하여 각각 1부씩 보관한다' 라고 적혀 있어요.","공사개요 표에 공사명, 공사장소(면적), 공사기간(착공, 준공)이 있어요.","공사대금 표는 1차부터 5차까지, 내역 칸에 선급금부터 잔금까지 적게 되어 있어요.","대금 지급을 지연하면 지연일수에 대하여 연 10퍼센트의 지연이자를 지급해야 해요."]},{"kind":"points","head":"오른쪽 계약일반조건에서 읽을 것","items":["제1조 공사내역, 제2조 공사내용의 변경과 조정, 제3조 하자보수, 제4조 이행지체","제3조: 을은 공사 완료 후 12개월 이내에 발생한 일부 또는 전부에 대해 보수 책임이 있어요.","12개월은 곧 1년, 일반 실내건축공사의 **하자담보책임기간** 과 같아요.","다만 갑과 을이 하자보수를 위한 기간의 연장 또는 단축을 별도로 합의할 수 있어요."]},{"kind":"points","head":"이행지체와 해제","items":["제4조: 공사 기한 내에 완성하지 못하면 지체일당 공사금액의 2/1,000에 해당하는 금액을 지급해야 해요.","천재지변 등 불가항력이면 즉시 통보하고 기간의 연장을 요청해요.","제5조는 **발주자(client, owner)** 나 **수급인** 이 계약을 해제할 수 있는 경우를 적어 두었어요."]}],"pass3":[{"kind":"check","q":"이 표준계약서 제3조가 정한 하자보수 책임 기간은?","choices":["6개월","12개월","24개월","36개월"],"a":1,"why":"공사 완료 후 12개월, 즉 1년이에요. 일반 실내건축공사의 **하자담보책임기간** 과 같아요."},{"kind":"warn","head":"계약서에서 자주 물어보는 숫자","items":["**계약서(contract document)** 는 2부 작성, 각 1부씩 보관이에요.","이 표준계약서의 하자보수는 공사 완료 후 12개월이에요.","대금 지급 지연 시 지연이자 10퍼센트, 공사 지체 시 하루 2/1,000 이라는 숫자도 적혀 있어요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p021_h.jpg"},"parts":[{"b":[0.038,0.325,0.215,0.03],"c":[0.026,0.285,0.239,0.11],"r":3.8626,"img":"img/L2/walk/p021_20_01.jpg","say":"맨 위 한 줄: 계약서 2부를 작성하여 각각 1부씩 보관한다고 적혀 있어요."},{"b":[0.048,0.378,0.285,0.122],"c":[0.0338,0.362,0.3135,0.154],"r":3.619,"img":"img/L2/walk/p021_20_02.jpg","say":"공사개요 표. 공사명, 공사장소(면적), 공사기간(착공과 준공)이 들어가요."},{"b":[0.048,0.568,0.275,0.175],"c":[0.0342,0.552,0.3025,0.207],"r":2.598,"img":"img/L2/walk/p021_20_03.jpg","say":"공사대금 표. 대금 지급 시기가 1차부터 5차까지 있고 내역 칸에 선급금부터 잔금까지 적어요."},{"b":[0.038,0.745,0.3,0.04],"c":[0.023,0.71,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p021_20_04.jpg","say":"그 아래: 대금 지급을 지연하면 연 10퍼센트의 지연이자를 지급해야 해요."},{"b":[0.362,0.438,0.155,0.045],"c":[0.3395,0.4055,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p021_20_05.jpg","say":"오른쪽 장 제3조 하자보수. 공사 완료 후 12개월 이내에 발생한 하자에 대해 보수 책임이 있어요."},{"b":[0.362,0.485,0.285,0.055],"c":[0.3477,0.4575,0.3135,0.11],"r":5.0667,"img":"img/L2/walk/p021_20_06.jpg","say":"제4조 이행지체. 기한 내에 완성하지 못하면 지체일당 공사금액의 2/1,000을 지급해요."}]}},{"p":22,"title":"참고자료, 건설공사의 하자담보책임기간","terms":["하자담보책임기간"],"pass1":[{"kind":"say","lines":["**하자담보책임기간** 이 법에 어떻게 정해져 있는지 보여 주는 참고 자료예요.","이 쪽은 건설산업기본법 시행령 별표4, 건설공사의 종류별 하자담보책임기간이에요.","표 전체를 외울 필요는 없어요. 왼쪽 파란 글씨 세 줄만 챙기면 돼요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왼쪽에 정리된 세 줄, 이것이 핵심","items":["일반 실내건축공사의 **하자담보책임기간** 은 1년이에요.","신축 공동주택의 사업주체가 시공한 마감공사는 공동주택관리법에 따라 2년이에요.","입주자가 별도로 시행한 아파트 인테리어 공사는 일반 실내건축공사 기준과 계약서상 보증기간을 확인해야 해요."]},{"kind":"points","head":"표에서 우리 과목과 관련된 칸","items":["표 오른쪽 15번 전문공사 항목 첫 줄에 '실내건축 1년' 이 네모로 표시되어 있어요.","같은 전문공사 안에서도 방수 3년, 철근콘크리트 3년처럼 항목마다 달라요.","자료 출처는 국가법령정보센터(www.law.go.kr)예요."]},{"kind":"bg","src":"배경 지식","lines":["하자담보책임은 '공사가 끝난 뒤 생긴 문제를 누가 고쳐 주느냐' 를 정한 규칙이에요.","이 기간 안에 생긴 하자는 시공한 쪽이 고쳐 줘야 해요.","그래서 계약서에 하자보수기간을 반드시 적어 둬요."]}],"pass3":[{"kind":"check","q":"일반 실내건축공사의 **하자담보책임기간** 으로 슬라이드에 제시된 것은?","choices":["3년","2년","5년","1년"],"a":3,"why":"일반 실내건축공사 1년, 신축 공동주택 사업주체가 시공한 마감공사는 2년이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.6491,0.0612],"c":[0,0.0208,0.714,0.0932],"r":13.6195,"img":"img/L2/walk/p022_h.jpg"},"parts":[{"b":[0.025,0.1,0.215,0.185],"c":[0.013,0.084,0.239,0.217],"r":1.958,"img":"img/L2/walk/p022_20_01.jpg","say":"왼쪽 위: 건설산업기본법 시행령 별표4, 건설공사의 종류별 **하자담보책임기간** 이라는 표라는 뜻이에요."},{"b":[0.025,0.395,0.255,0.255],"c":[0.0122,0.379,0.2805,0.287],"r":1.7375,"img":"img/L2/walk/p022_20_02.jpg","say":"왼쪽 파란 세 줄이 시험에 나오는 답이에요. 일반 실내건축공사 1년, 신축 공동주택 마감공사 2년."},{"b":[0.285,0.138,0.325,0.785],"c":[0.2687,0.0987,0.3575,0.8635],"r":0.736,"img":"img/L2/walk/p022_20_03.jpg","say":"가운데 표: 1 교량부터 13 기타 토목공사까지. 맨 오른쪽 칸이 책임기간이에요."},{"b":[0.642,0.138,0.33,0.16],"c":[0.6255,0.122,0.363,0.192],"r":3.3611,"img":"img/L2/walk/p022_20_04.jpg","say":"오른쪽 표 14 건축. 대형공공성 건축물의 기둥과 내력벽은 10년이에요."},{"b":[0.712,0.303,0.26,0.03],"c":[0.699,0.263,0.286,0.11],"r":4.6222,"img":"img/L2/walk/p022_20_05.jpg","say":"15 전문공사의 ① 실내건축에 네모가 쳐져 있어요. 1년이에요."},{"b":[0.645,0.828,0.325,0.072],"c":[0.6287,0.809,0.3575,0.11],"r":5.7778,"img":"img/L2/walk/p022_20_06.jpg","say":"맨 아래 비고: 두 공종 이상이 복합된 공사는 각각의 세부 공종별 기간으로 해요."}]}},{"p":23,"title":"참고자료, 실내건축 쪽 담보책임기간 표 1","terms":["하자담보책임기간"],"pass1":[{"kind":"say","lines":["이번에는 공동주택관리법 시행령 별표4, 시설공사별 담보책임기간 표예요.","아파트 같은 공동주택에 적용되는 표예요.","왼쪽 설명 세 줄은 앞 쪽과 똑같아요. 그만큼 중요하다는 뜻이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"표의 앞부분에서 읽을 기간","items":["1번 마감공사(미장, 수장, 도장, 도배, 타일, 석공사, 옥내가구, 주방기구, 가전제품)는 2년이에요.","2번 옥외급수, 위생 관련 공사부터 12번 지능형 홈네트워크 설비공사까지는 3년이에요.","즉 실내 마감은 2년, 설비 계통은 3년이라고 크게 잡아 두면 돼요."]},{"kind":"points","head":"왼쪽 설명 세 줄 다시","items":["일반 실내건축공사의 **하자담보책임기간** 은 1년이에요.","신축 공동주택의 사업주체가 시공한 마감공사는 공동주택관리법에 따라 2년이에요.","입주자가 별도로 시행한 아파트 인테리어 공사는 일반 기준과 계약서상 보증기간을 확인해요."]}],"pass3":[{"kind":"check","q":"신축 공동주택의 사업주체가 시공한 마감공사의 담보책임기간은?","choices":["1년","2년","3년","5년"],"a":1,"why":"공동주택관리법에 따라 2년이에요. 일반 실내건축공사는 1년이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0432],"c":[0,0.0208,0.2111,0.0752],"r":4.9905,"img":"img/L2/walk/p023_h.jpg"},"parts":[{"b":[0.025,0.1,0.215,0.14],"c":[0.013,0.084,0.239,0.172],"r":2.4703,"img":"img/L2/walk/p023_20_01.jpg","say":"왼쪽 위: 공동주택관리법 시행령 별표4, 시설공사별 담보책임기간이에요. 아파트에 적용돼요."},{"b":[0.021,0.39,0.26,0.27],"c":[0.008,0.374,0.286,0.302],"r":1.6836,"img":"img/L2/walk/p023_20_02.jpg","say":"왼쪽 파란 세 줄. 앞 쪽과 똑같아요. 이 세 줄만 외우면 돼요."},{"b":[0.278,0.11,0.318,0.255],"c":[0.2621,0.094,0.3498,0.287],"r":2.1668,"img":"img/L2/walk/p023_20_03.jpg","say":"표 1번 마감공사. 미장, 수장, 도장, 도배, 타일, 석공사, 옥내가구, 주방기구, 가전제품이 2년이에요."},{"b":[0.278,0.365,0.318,0.59],"c":[0.2621,0.3355,0.3498,0.649],"r":0.9582,"img":"img/L2/walk/p023_20_04.jpg","say":"표 2번 옥외급수와 위생부터 6번 목공사까지. 오른쪽 기간 칸이 3년이에요."},{"b":[0.605,0.082,0.322,0.872],"c":[0.5795,0.0384,0.373,0.9592],"r":0.6913,"img":"img/L2/walk/p023_20_05.jpg","say":"오른쪽 표 7번 창호부터 12번 지능형 홈네트워크까지. 역시 3년이에요."}]}},{"p":24,"title":"참고자료, 실내건축 쪽 담보책임기간 표 2","terms":["하자담보책임기간"],"pass1":[{"kind":"say","lines":["앞 쪽과 같은 표의 뒷부분이에요. 왼쪽 설명은 그대로예요.","번호가 13번부터 21번까지 이어지고 오른쪽에 기간이 적혀 있어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"표의 뒷부분에서 읽을 기간","items":["13번 소방시설공사, 14번 단열공사, 15번 잡공사는 3년이에요.","16번 대지조성공사부터 21번 방수공사까지는 5년이에요.","비고에 지반공사의 담보책임기간은 10년이라고 적혀 있어요.","즉 이 표의 기간은 2년, 3년, 5년, 10년 네 종류예요."]},{"kind":"points","head":"우리가 실제로 외울 것","items":["표를 통째로 외우지 않아요. 왼쪽 세 줄만 답으로 쓰면 돼요.","일반 실내건축공사 1년, 신축 공동주택 마감공사 2년이에요.","**하자담보책임기간** 문제는 이 두 숫자에서 거의 다 나와요."]}],"pass3":[{"kind":"warn","head":"슬라이드가 같은 내용을 두 번 보여 줘요","items":["p23과 p24는 왼쪽 설명이 완전히 같고 오른쪽 표 그림만 달라요.","p23은 표 앞부분(2년, 3년), p24는 뒷부분(3년, 5년, 10년)이에요.","시험에 나오는 것은 표가 아니라 '일반 1년, 신축 공동주택 마감 2년' 이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2368,0.0932],"c":[0,0.0208,0.2608,0.1252],"r":3.7032,"img":"img/L2/walk/p024_h.jpg"},"parts":[{"b":[0.025,0.132,0.215,0.11],"c":[0.013,0.116,0.239,0.142],"r":2.9922,"img":"img/L2/walk/p024_20_01.jpg","say":"왼쪽 위: 앞 쪽과 같은 공동주택관리법 시행령 별표4예요."},{"b":[0.021,0.39,0.26,0.27],"c":[0.008,0.374,0.286,0.302],"r":1.6836,"img":"img/L2/walk/p024_20_02.jpg","say":"왼쪽 파란 세 줄도 앞 쪽과 글자 하나 다르지 않아요. 여기가 시험 답이에요."},{"b":[0.305,0.148,0.34,0.19],"c":[0.288,0.132,0.374,0.222],"r":2.995,"img":"img/L2/walk/p024_20_03.jpg","say":"표 13번 소방시설공사, 14번 단열공사, 15번 잡공사. 오른쪽 기간 칸이 3년이에요."},{"b":[0.305,0.338,0.34,0.545],"c":[0.288,0.3108,0.374,0.5995],"r":1.1091,"img":"img/L2/walk/p024_20_04.jpg","say":"16번 대지조성공사부터 21번 방수공사까지. 오른쪽 기간 칸이 5년이에요."},{"b":[0.305,0.884,0.66,0.066],"c":[0.272,0.8437,0.726,0.1467],"r":8.798,"img":"img/L2/walk/p024_20_05.jpg","say":"맨 아래 비고: 기초공사와 지정공사 등 지반공사는 담보책임기간이 10년이에요."}]}},{"p":25,"title":"계약서 사례 3, 공사도급표준계약서","terms":["contract document","하자담보책임기간","수급인"],"pass1":[{"kind":"say","lines":["세 번째 계약서 사례는 관공서에서 쓰는 공사도급표준계약서예요.","앞의 두 사례와 달리 계약 상대가 중앙관서의 장(계약담당공무원)이에요.","한 장짜리 표 모양이라 항목을 찾기 쉬워요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"표 안의 항목들","items":["발주처, 계약상대자(상호, 주소, 대표자, 법인등록번호, 전화번호)","공사명, 계약금액, 총공사부기금액, 계약보증금","현장, 지체상금율, 물가변동계약금액조정방법, 착공년월일, 준공년월일, 기타사항"]},{"kind":"points","head":"숫자로 적힌 것","items":["지체상금율은 1,000분의 1이라고 인쇄되어 있어요.","물가변동계약금액조정방법은 지수조정율이에요.","하자담보책임 표의 **하자담보책임기간** 칸에 1년이 적혀 있어요.","하자보수보증금율(퍼센트)과 금액을 공종별로 적게 되어 있어요."]},{"kind":"points","head":"맨 아래 문구","items":["중앙관서의 장(계약담당공무원)과 계약상대자가 대등한 입장에서 도급계약을 체결한다고 적혀 있어요.","이 계약의 증거로서 **계약서(contract document)** 를 작성하여 당사자가 기명날인한 후 각각 1통씩 보관해요.","여기서도 계약상대자, 즉 **수급인** 쪽과 발주처 쪽이 한 통씩 나눠 가져요."]}],"pass3":[{"kind":"check","q":"공사도급표준계약서에 인쇄된 지체상금율은?","choices":["100분의 1","1,000분의 1","10,000분의 1","100분의 5"],"a":1,"why":"1,000분의 1이에요. 하자담보책임기간 칸에는 1년이 적혀 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1059],"c":[0,0.0208,0.2111,0.1379],"r":2.7215,"img":"img/L2/walk/p025_h.jpg"},"parts":[{"b":[0.05,0.224,0.275,0.045],"c":[0.0362,0.1915,0.3025,0.11],"r":4.8889,"img":"img/L2/walk/p025_20_01.jpg","say":"맨 위: 공사도급표준계약서라는 제목과 계약번호, 공고번호 칸이에요."},{"b":[0.05,0.274,0.275,0.065],"c":[0.0362,0.2515,0.3025,0.11],"r":4.8889,"img":"img/L2/walk/p025_20_02.jpg","say":"계약상대자 칸. 상호, 주소, 대표자, 법인등록번호, 전화번호를 적어요."},{"b":[0.05,0.346,0.275,0.075],"c":[0.0362,0.3285,0.3025,0.11],"r":4.8889,"img":"img/L2/walk/p025_20_03.jpg","say":"공사명, 계약금액, 총공사부기금액, 계약보증금 칸이에요. 금액은 모두 VAT 포함으로 적어요."},{"b":[0.05,0.418,0.275,0.062],"c":[0.0362,0.394,0.3025,0.11],"r":4.8889,"img":"img/L2/walk/p025_20_04.jpg","say":"지체상금율 칸에 1,000분의 1, 물가변동계약금액조정방법 칸에 지수조정율이 인쇄되어 있어요."},{"b":[0.05,0.542,0.275,0.115],"c":[0.0362,0.526,0.3025,0.147],"r":3.6584,"img":"img/L2/walk/p025_20_05.jpg","say":"하자담보책임 표. 공종별 계약금액, 하자보수보증금율과 금액, **하자담보책임기간** 칸에 1년이 적혀 있어요."},{"b":[0.05,0.662,0.275,0.09],"c":[0.0362,0.646,0.3025,0.122],"r":4.408,"img":"img/L2/walk/p025_20_06.jpg","say":"맨 아래: 중앙관서의 장(계약담당공무원)과 계약상대자가 기명날인하고 각각 1통씩 보관해요."}]}},{"p":26,"title":"공사 계획 1, 현장 조사 및 분석","terms":["대수선","건축물대장","client, owner"],"pass1":[{"kind":"analogy","head":"공사 전 현장 답사는 여행 전 지도 보기예요","scene":"모르고 가면 낭패를 봐요.","map":[["현장에서 직접 확인","치수, 층고, 개구부, 분전함처럼 가 봐야 아는 것"],["사무실에서 확인","용도, 허가 여부처럼 서류로 아는 것"]]},{"kind":"say","lines":["계약이 끝나면 바로 공사 계획이에요. 그 첫 단추가 현장 조사 및 분석이에요.","공사 착수 이전에 현장을 방문하고 전체 배경과 공간 상황을 면밀하게 조사해요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"현장에서 직접 확인하는 것","items":["설계 내용을 구현하기에 문제점이 없는지, 목적, 성격, 기능, 용도, 요구사항을 검토해요.","대상지와 주변 환경의 상호 영향, 입지조건과 주변 시설, 이용 특성을 분석해요.","소음, 진동, 분진 등 공해가 예상되면 인근 학교, 병원 등의 피해 가능성을 조사해요.","그럴 때는 사전 양해 또는 공사협정 등의 대비 방안을 세워요."]},{"kind":"points","head":"사무실에서도 확인할 수 있는 것","items":["전년도 통계를 기준으로 공사기간 동안의 기상 조건을 조사해요.","강우와 태풍 시기에는 자재 반입이나 외부와 연계된 공사가 어려울 수 있어요.","겨울 한파는 공사 중 동파의 우려가 있어요.","건축물의 기존 용도가 공사의 용도에 저촉되지 않는지 **건축물대장** 으로 검토해요."]},{"kind":"points","head":"최초 현장 방문 체크리스트, 슬라이드 상자 그대로","items":["공사 범위의 치수, 층고, 개구부 사이즈 실측","건물 관리자, 시설 담당자 연락처 및 공사관리 규정 확인","주변 교통상황 확인(자재 입고 시 필요)","상하수도관, 가스, 전기 분전함 위치와 용량 확인, 주변 민원 예상 요소 확인"]},{"kind":"bg","src":"배경 지식","lines":["현장 실측 때는 공간의 사이즈만 재는 것이 아니에요.","전기 분전함의 위치, 내부 및 외부 사진, 전기 용량까지 확인해야 해요.","전기 용량이 모자라면 나중에 에어컨이나 주방 기기를 못 쓰는 일이 생겨요."]}],"pass3":[{"kind":"check","q":"건축물의 용도를 확인할 수 있는 서류와 온라인 발급처가 바르게 연결된 것은?","choices":["**건축물대장**, 나라장터","시방서, 세움터","등기부등본, 나라장터","**건축물대장**, 정부24 또는 세움터"],"a":3,"why":"건축물대장은 정부24 또는 세움터에서 온라인 발급, 열람할 수 있고 관공서에서 직접 발급도 가능해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1498],"c":[0,0.0208,0.2111,0.1818],"r":2.0643,"img":"img/L2/walk/p026_h.jpg"},"parts":[{"b":[0.03,0.195,0.87,0.045],"c":[0,0.1208,0.957,0.1933],"r":8.8015,"img":"img/L2/walk/p026_20_01.jpg","say":"공사 착수 이전에 현장을 방문하고 전체적인 배경과 공간적 범위의 상황을 면밀하게 조사해요."},{"b":[0.03,0.325,0.75,0.045],"c":[0,0.2642,0.825,0.1667],"r":8.7982,"img":"img/L2/walk/p026_20_02.jpg","say":"현장 사진촬영과 함께 실측을 하고 지리적 위치, 교통 요소, 주변 입지조건도 파악해요."},{"b":[0.03,0.37,0.75,0.045],"c":[0,0.3092,0.825,0.1667],"r":8.7982,"img":"img/L2/walk/p026_20_03.jpg","say":"기존 시설물, 상하수도, 전기, 통신, 가스의 유무와 위치, 형태를 조사해 지장을 주면 이설을 준비해요."},{"b":[0.03,0.555,0.75,0.045],"c":[0,0.4942,0.825,0.1667],"r":8.7982,"img":"img/L2/walk/p026_20_04.jpg","say":"용도변경이나 **대수선** 에 해당하면 허가 또는 신고 등 행정절차를 검토해요."},{"b":[0.03,0.645,0.75,0.045],"c":[0,0.5842,0.825,0.1667],"r":8.7982,"img":"img/L2/walk/p026_20_05.jpg","say":"건축물의 용도는 **건축물대장** 으로 확인해요. 정부24 또는 세움터에서 온라인 발급, 열람이 가능해요."},{"b":[0.035,0.735,0.26,0.24],"c":[0.022,0.719,0.286,0.272],"r":1.8693,"img":"img/L2/walk/p026_20_06.jpg","say":"왼쪽 아래 파란 상자가 최초 현장 방문 체크리스트예요."}]}},{"p":27,"title":"대수선의 범위, 30제곱미터와 3개","terms":["대수선"],"pass1":[{"kind":"say","lines":["앞 쪽에서 '용도변경이나 **대수선** 이면 허가나 신고가 필요하다' 고 했죠.","그럼 **대수선** 이 뭔지 알아야 해요. 이 쪽이 그 답이에요.","건축법 시행령 제3조의2에 아홉 가지가 적혀 있어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**대수선** 의 뜻","items":["아래 아홉 가지 중 하나에 해당하는 경우예요.","단, 증축, 개축, 재축에 해당하지 않는 것이어야 해요.","즉 건물을 늘리거나 새로 짓는 것이 아니라 크게 손보는 것이 대수선이에요."]},{"kind":"compare","head":"아홉 가지를 숫자로 묶어 보기","cols":["기준 숫자","해당하는 것"],"rows":[["30제곱미터 이상","내력벽을 증설, 해체하거나 그 벽면적을 30제곱미터 이상 수선 또는 변경"],["30제곱미터 이상","건축물 외벽에 사용하는 마감재료를 증설, 해체하거나 벽면적 30제곱미터 이상 수선 또는 변경"],["세 개 이상","기둥을 증설, 해체하거나 세 개 이상 수선 또는 변경"],["세 개 이상","보를 증설, 해체하거나 세 개 이상 수선 또는 변경"],["세 개 이상","지붕틀을 증설, 해체하거나 세 개 이상 수선 또는 변경(한옥은 서까래 제외)"],["숫자 없음","방화벽 또는 방화구획을 위한 바닥이나 벽, 주계단과 피난계단과 특별피난계단, 다가구주택 가구 간 경계벽"]]},{"kind":"points","head":"놓치기 쉬운 조항","items":["7번은 2019년 10월 22일에 삭제되어 지금은 없어요.","8번 다가구주택의 가구 간 경계벽, 다세대주택의 세대 간 경계벽도 **대수선** 이에요.","즉 옆집과 나를 가르는 벽을 건드리면 신고 대상이 될 수 있어요."]}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"건축법 시행령상 대수선에 해당하지 않는 것을 고르시오.","qko":"어디까지 손봐야 대수선일까요.","solve":["내력벽과 외벽 마감재료는 벽면적 30제곱미터 이상이어야 해요.","기둥, 보, 지붕틀은 세 개 이상이어야 해요.","그러므로 기둥을 '두 개' 수선하는 것은 대수선이 아니에요."],"answer":"기둥 두 개를 수선하는 것은 **대수선** 이 아니에요."},{"kind":"english","head":"단답 대비 숫자","en":"대수선 기준은 내력벽과 외벽 마감재료 30제곱미터 이상, 기둥과 보와 지붕틀 세 개 이상이다.","ko":"면적으로 세는 것과 개수로 세는 것을 갈라서 외운다.","tip":"'벽은 30, 기둥과 보는 3' 이라고 짧게 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1498],"c":[0,0.0208,0.2111,0.1818],"r":2.0643,"img":"img/L2/walk/p027_h.jpg"},"parts":[{"b":[0.025,0.19,0.6,0.032],"c":[0,0.1393,0.66,0.1333],"r":8.8022,"img":"img/L2/walk/p027_20_01.jpg","say":"맨 위 한 줄: 용도변경이나 **대수선** 에 해당하면 허가 또는 신고 등 행정절차를 검토해요."},{"b":[0.163,0.333,0.63,0.072],"c":[0.1315,0.299,0.693,0.14],"r":8.8,"img":"img/L2/walk/p027_20_02.jpg","say":"상자 제목: 건축법 시행령 제3조의 2 (대수선의 범위). 증축, 개축, 재축에 해당하지 않는 것이에요."},{"b":[0.166,0.426,0.62,0.03],"c":[0.135,0.3721,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p027_20_03.jpg","say":"1번. 내력벽을 증설, 해체하거나 벽면적 30제곱미터 이상 수선 또는 변경하는 것."},{"b":[0.166,0.473,0.66,0.125],"c":[0.133,0.457,0.726,0.157],"r":8.2208,"img":"img/L2/walk/p027_20_04.jpg","say":"2, 3, 4번. 기둥, 보, 지붕틀을 증설, 해체하거나 세 개 이상 수선 또는 변경하는 것."},{"b":[0.166,0.612,0.6,0.12],"c":[0.136,0.596,0.66,0.152],"r":7.7193,"img":"img/L2/walk/p027_20_05.jpg","say":"5, 6번은 방화벽과 방화구획, 주계단과 피난계단. 7번은 2019년에 삭제되어 회색 줄이 그어져 있어요."},{"b":[0.166,0.75,0.6,0.08],"c":[0.136,0.7233,0.66,0.1333],"r":8.8022,"img":"img/L2/walk/p027_20_06.jpg","say":"8번 가구 간과 세대 간 경계벽, 9번 외벽 마감재료 30제곱미터 이상이에요."}]}},{"p":28,"title":"공사 계획 2, 관련 법규 검토","terms":["사용승인","대수선","건축물대장"],"pass1":[{"kind":"say","lines":["현장을 봤으면 이번에는 법을 봐야 해요.","현장과 예정 공사에 대하여 관련 법규와 법령을 이해하고 분석해 시공 과정에 적용해요.","이름이 어렵지만 '무엇을 건드리면 신고해야 하나' 를 미리 확인하는 일이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"실내건축 시공과 관련된 주요 법령 여덟 가지","items":["건축법, 건설산업기본법","소방시설 설치 및 관리에 관한 법률, 산업안전보건법","근로기준법, 소음 및 진동관리법","폐기물관리법, 장애인과 노인과 임산부 등의 편의증진 보장에 관한 법률"]},{"kind":"points","head":"**사용승인** 과 허가, 신고","items":["건축주는 건축허가 또는 신고 대상 공사를 완료한 후 관계 서류를 제출해 **사용승인** 을 받아야 해요.","원칙적으로 사용승인을 받기 전에는 건축물을 사용할 수 없어요.","용도를 변경하거나 **대수선** 에 해당하는 공사를 할 때는 허가, 신고 또는 **건축물대장** 변경 절차를 거쳐요.","그리고 관계 법령의 기준에 맞게 시공해야 해요."]},{"kind":"points","head":"시공자에게 지워진 의무","items":["공사 시공자는 계약과 관계 법령에 따라 건축물을 적법하게 시공하여 건축주에게 인도해요.","공사현장의 위해와 산업재해를 방지하기 위한 안전조치를 해야 해요.","이 안전조치 이야기가 뒤에 나올 안전관리로 이어져요."]}],"pass3":[{"kind":"check","q":"건축허가 또는 신고 대상 공사를 완료한 후 받아야 하며, 받기 전에는 건축물을 사용할 수 없는 절차는?","choices":["착공신고","**사용승인**","준공청소","**대수선** 신고"],"a":1,"why":"사용승인을 받기 전에는 원칙적으로 건축물을 사용할 수 없어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1498],"c":[0,0.0208,0.2111,0.1818],"r":2.0643,"img":"img/L2/walk/p028_h.jpg"},"parts":[{"b":[0.025,0.195,0.47,0.032],"c":[0.0015,0.156,0.517,0.11],"r":8.3556,"img":"img/L2/walk/p028_20_01.jpg","say":"첫 줄: 현장과 예정 공사에 대하여 관련 법규와 법령을 이해하고 분석해 시공 과정에 적용해요."},{"b":[0.025,0.242,0.81,0.078],"c":[0,0.191,0.891,0.18],"r":8.8,"img":"img/L2/walk/p028_20_02.jpg","say":"둘째 덩어리: 주요 법령 여덟 개가 낫표 안에 나열되어 있어요. 건축법부터 편의증진 보장법까지예요."},{"b":[0.025,0.336,0.8,0.033],"c":[0,0.2636,0.88,0.1778],"r":8.7989,"img":"img/L2/walk/p028_20_03.jpg","say":"셋째 줄: 건축주는 공사를 완료한 후 **사용승인** 을 받아야 하고, 받기 전에는 건축물을 사용할 수 없어요."},{"b":[0.025,0.38,0.81,0.078],"c":[0,0.329,0.891,0.18],"r":8.8,"img":"img/L2/walk/p028_20_04.jpg","say":"넷째 덩어리: 용도변경이나 **대수선** 이면 허가, 신고 또는 **건축물대장** 변경 절차를 거쳐요."},{"b":[0.025,0.476,0.8,0.033],"c":[0,0.4036,0.88,0.1778],"r":8.7989,"img":"img/L2/walk/p028_20_05.jpg","say":"마지막 줄: 시공자는 적법하게 시공해 인도하고, 위해와 산업재해를 막는 안전조치를 해야 해요."}]}},{"p":29,"title":"공사 실행내역서, 회사만 아는 진짜 예산","terms":["실행내역서","직접공사비","간접공사비","현장경비","일반관리비","공사원가"],"pass1":[{"kind":"analogy","head":"실행내역서는 우리 집 진짜 가계부예요","scene":"손님에게 보여 주는 견적서와 달라요.","map":[["계약금액","손님에게 받기로 한 돈"],["**실행내역서**","그 안에서 실제로 쓸 돈을 우리끼리만 적어 둔 표"],["대외비","절대 밖에 보여 주면 안 되는 서류"]]},{"kind":"say","lines":["슬라이드에 '절대 외부에 노출되지 않도록 관리를 철저히 한다(대외비)' 라고 적혀 있어요.","**실행내역서** 는 착공 전에 만드는 예산 계획서예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**실행내역서** 를 한 줄로","items":["착공 전에 계약금액의 검토를 통하여 실제 공사에 투입할 실행 예산계획을 수립하는 것이에요.","시공 기간 안에 최적으로 필요한 재료를 쓰고 최소의 장비와 인력으로 공사를 완성하는 것이 목표예요.","공사 실행 내역은 시공 계약금액에서 **일반관리비** 와 이윤을 제외한 **공사원가** 에 해당해요.","공사원가는 재료비, 노무비, 외주비, 경비, **간접공사비**, **현장경비** 예요."]},{"kind":"points","head":"작성할 때의 준비 사항과 주의 사항","items":["설계도서를 상세하게 점검하고 공간별, 공종별로 작성해요.","공사기일, 대금지불조건, 지급자재, 별도공사 등 계약조건을 검토해요.","현장 상황과 조건에 맞는 단가를 적용하고, 공종별 누락이나 중복이 없게 산출해요.","단가조사와 분석을 하고 단가를 결정해요."]},{"kind":"points","head":"항목별로 값을 정하는 방법","items":["물가자료정보 등을 조사하여 재료비를 산정해요.","시중노임단가, 실적노임단가를 참고하여 노무비를 산정해요.","**현장경비** 를 산정하고, 각종 보험료와 **일반관리비** 와 이윤 등 항목별 비용을 산정해요.","하청공사는 해당 업체의 견적을 받아 실행계획과 비교 검토해요."]},{"kind":"points","head":"오른쪽 그림에서 빨간 테두리가 가리키는 것","items":["그림의 빨간 네모 안쪽이 바로 공사 실행 내역이에요.","**직접공사비**(재료비, 노무비, 외주비, 경비) 와 **간접공사비**, **현장경비** 까지가 들어가요.","빨간 네모 밖의 **일반관리비** 와 부가이윤은 실행 내역에 들어가지 않아요.","슬라이드 메모대로 '이것만 갖고 다님' 이 실행내역서예요."]}],"pass3":[{"kind":"check","q":"공사 **실행내역서** 에 대한 설명으로 옳은 것은?","choices":["계약금액에서 **일반관리비** 와 이윤을 제외한 **공사원가** 에 해당한다","외부에 공개하여 투명하게 관리한다","준공 후에 작성한다","일반관리비를 반드시 포함한다"],"a":0,"why":"실행내역은 착공 전에 작성하고 대외비로 관리해요."},{"kind":"warn","head":"슬라이드 문장이 어색한 곳","items":["p29의 '공사 실행내역을 원가관리의 중요 요소이다' 는 조사가 틀린 문장이에요.","'공사 실행내역은 원가관리의 중요 요소이다' 로 읽으면 돼요.","**실행내역서** 는 착공 '전' 에 만들고 대외비예요. 준공 후가 아니에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0862],"c":[0,0.0208,0.2111,0.1182],"r":3.175,"img":"img/L2/walk/p029_h.jpg"},"parts":[{"b":[0.118,0.125,0.22,0.028],"c":[0.106,0.084,0.244,0.11],"r":3.9434,"img":"img/L2/walk/p029_20_01.jpg","say":"제목 옆 분홍 메모: 절대 외부에 노출되지 않도록 관리를 철저히 한다, 대외비예요."},{"b":[0.025,0.198,0.49,0.032],"c":[0.0005,0.159,0.539,0.11],"r":8.7111,"img":"img/L2/walk/p029_20_02.jpg","say":"첫 줄: 착공 전에 계약금액을 검토해 실제 공사에 투입할 실행 예산계획을 세워요."},{"b":[0.025,0.38,0.62,0.033],"c":[0,0.3276,0.682,0.1378],"r":8.7986,"img":"img/L2/walk/p029_20_03.jpg","say":"중요한 줄: 공사 실행 내역은 계약금액에서 **일반관리비** 와 이윤을 제외한 **공사원가** 에 해당해요."},{"b":[0.025,0.428,0.45,0.033],"c":[0.0025,0.3895,0.495,0.11],"r":8.0,"img":"img/L2/walk/p029_20_04.jpg","say":"그 아래: 공사원가는 재료비, 노무비, 외주비, 경비, **간접공사비**, **현장경비** 예요."},{"b":[0.034,0.476,0.375,0.46],"c":[0.0153,0.453,0.4125,0.506],"r":1.4493,"img":"img/L2/walk/p029_20_05.jpg","say":"왼쪽 파란 상자가 준비 사항과 주의 사항 열 줄이에요. 단가 조사부터 하청 견적 비교까지 있어요."},{"b":[0.466,0.46,0.38,0.477],"c":[0.447,0.4362,0.418,0.5247],"r":1.4163,"img":"img/L2/walk/p029_20_06.jpg","say":"오른쪽 그림이 공사 원가의 구성. 빨간 테두리 안쪽이 공사 실행 내역이고 '이것만 갖고 다님' 이라고 적혀 있어요."}]}},{"p":30,"title":"공사원가 양파 까기, 직접공사비에서 총원가까지","terms":["직접공사비","공통 가설비","간접공사비","순공사비","현장경비","공사원가","일반관리비","총원가","실행내역서"],"pass1":[{"kind":"analogy","head":"공사원가는 양파예요","scene":"안에서 바깥으로 한 겹씩 싸여 있어요.","map":[["1겹 **직접공사비**","재료비, 노무비, 외주비, 경비"],["2겹 **순공사비**","거기에 **공통 가설비** 와 **간접공사비** 를 더한 것"],["3겹 **공사원가**","거기에 **현장경비** 를 더한 것"],["4겹 **총원가**","거기에 **일반관리비** 를 더한 것"]]},{"kind":"say","lines":["주문으로 외워요. '재노외경 → 간접 → 현장 → 일반 → 이윤'.","안에서 밖으로, 현장에서 본사로 점점 멀어지는 순서예요.","이 쪽에는 실내건축기사 출제 내용이라는 표시가 붙어 있어요."]}],"pass2":[{"kind":"compare","head":"네 단계를 한 표로","cols":["단계","무엇을 더하나","설명"],"rows":[["1) **직접공사비**","재료비, 노무비, 외주비, 경비","공사 목적물을 시공하기 위해 직접 소비된 것을 확인할 수 있는 비용. 직접 노무비, 직접 인건비, 직접 경비로 구분"],["2) **순공사비**","**공통 가설비** 와 **간접공사비**","간접공사비는 직접 공사현장에 시공되는 것이 아니고 여러 시공 부분에 공통으로 쓰임"],["3) **공사원가**","**현장경비**","현장경비는 인건비와 기타 경비로 구분되며 작업현장의 실질 발생비용에 따라 정함"],["4) **총원가**","**일반관리비**","일반관리비는 현장 투입 금액 이외에 시공업체의 기업 경영을 유지하기 위해 지출하는 금액"]]},{"kind":"points","head":"**간접공사비** 를 자세히","items":["각 시공 부분에 대하여 공통으로 사용되는 비용이에요.","항목으로는 재료비, 노무비, 경비를 적용하지만 직접 수량을 적용하지 않아요.","비율로 계산하여 산출해요. 슬라이드 메모로 '전체의 몇 프로' 라고 적혀 있어요.","그래서 간접 재료비, 간접 노무비, 기타 경비로 구분해요."]},{"kind":"points","head":"**공통 가설비** 와 기타 경비의 내용","items":["공통 가설비는 현장 가설사무실, 보양, 안전시설 등이에요.","간접 공사비는 현장관리 인건비, 운반비, 전력과 용수비 등이에요.","기타 경비는 공사준비비, 가설비, 운송비, 안전관리비, 전력과 용수 사용료, 기술관리비 등이에요.","**현장경비** 는 현장관리 인력의 인건비, 통신비, 여비교통비 등이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"공사원가 구성에서 안쪽부터 바깥쪽으로 쌓이는 순서를 쓰시오.","qko":"어떤 비용 위에 어떤 비용이 얹히는 순서일까요.","solve":["가장 안쪽은 공사에 직접 쓴 돈, 즉 **직접공사비** 예요.","거기에 **공통 가설비** 와 **간접공사비** 를 더하면 **순공사비** 예요.","거기에 **현장경비** 를 더하면 **공사원가** 예요.","거기에 **일반관리비** 를 더하면 **총원가**, 이윤과 부가가치세를 더하면 계약금액이에요."],"answer":"**직접공사비** → **순공사비** → **공사원가** → **총원가** → 계약금액 순서예요."},{"kind":"check","q":"**직접공사비** 를 구성하는 항목이 아닌 것은?","choices":["재료비","외주비","**일반관리비**","경비"],"a":2,"why":"직접공사비는 재료비, 노무비, 외주비, 경비예요. 일반관리비는 **총원가** 단계에서 더해져요."},{"kind":"english","head":"서술형 대비 문장","en":"직접공사비는 재료비, 노무비, 외주비, 경비이고 여기에 공통 가설비와 간접공사비를 더하면 순공사비이다.","ko":"순공사비에 현장경비를 더하면 공사원가, 공사원가에 일반관리비를 더하면 총원가이다.","tip":"주문 '재노외경 → 간접 → 현장 → 일반 → 이윤' 을 그대로 문장으로 풀어 쓰면 돼요."},{"kind":"warn","head":"한 글자 차이로 갈려요","items":["**순공사비** 는 **직접공사비** 에 **공통 가설비** 와 **간접공사비** 를 더한 것이에요.","**공사원가** 는 거기에 **현장경비** 를 더한 것이에요. 일반관리비는 아직 안 들어가요.","**실행내역서** 는 계약금액에서 일반관리비와 이윤을 뺀 공사원가에 해당해요."]}],"walk":{"head":null,"parts":[{"b":[0.635,0.015,0.035,0.49],"c":[0.5477,0,0.2096,0.539],"r":0.6913,"img":"img/L2/walk/p030_23_01.jpg","say":"가장 왼쪽 기둥이 공사비, 즉 계약금액이에요. 모든 것을 감싸요."},{"b":[0.692,0.015,0.035,0.49],"c":[0.6047,0,0.2096,0.539],"r":0.6913,"img":"img/L2/walk/p030_23_02.jpg","say":"4) **총원가**. 여기까지가 **일반관리비** 를 포함한 금액이에요."},{"b":[0.737,0.015,0.035,0.44],"c":[0.6545,0,0.2,0.484],"r":0.7346,"img":"img/L2/walk/p030_23_03.jpg","say":"3) **공사원가**. **현장경비** 까지 포함해요."},{"b":[0.782,0.015,0.035,0.38],"c":[0.6995,0,0.2,0.418],"r":0.8506,"img":"img/L2/walk/p030_23_04.jpg","say":"2) **순공사비**. **간접공사비** 까지 포함해요."},{"b":[0.826,0.015,0.035,0.26],"c":[0.7435,0,0.2,0.292],"r":1.2177,"img":"img/L2/walk/p030_23_05.jpg","say":"1) **직접공사비**. 오른쪽의 재료비, 노무비, 외주비, 경비 네 칸을 묶은 것이에요."},{"b":[0.865,0.015,0.12,0.26],"c":[0.8,0,0.2,0.292],"r":1.2177,"img":"img/L2/walk/p030_23_06.jpg","say":"맨 오른쪽 네 칸이 재료비, 노무비, 외주비(하도급), 경비(전기세, 기름값)예요."}]}},{"p":31,"title":"공정 계획, 언제 무엇을 할지 짜기","terms":["공정계획","바차트 공정표","네트워크 공정표"],"pass1":[{"kind":"analogy","head":"공정계획은 요리 순서표예요","scene":"저녁 한 상을 차린다고 생각해 봐요.","map":[["**공정계획**","국을 먼저 올리고 그동안 채소를 썰어 두는 계획"],["요소","언제, 무엇을, 얼마나, 몇 사람이"],["수단","사람, 장비, 돈, 재료"]]},{"kind":"say","lines":["계약과 계획이 끝나면 '언제 무엇을 할지' 를 정해야 해요. 그게 **공정계획** 이에요.","계약부터 착공, 시공, 준공까지 정해진 기간 안에 좋은 품질로 안전하게 진행되도록 짜요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**공정계획** 을 한 줄로","items":["계약으로부터 착공, 시공, 준공의 과정까지의 계획이에요.","지정된 공사 기간 내에 좋은 품질로 안전하게 공사가 진행되도록 계획하는 것이에요.","시공자는 공사의 규모, 시공 정밀도, 공사기일, 현장상황, 공사수량을 엄밀히 조사해요.","그리고 주어진 기한 내에 정밀한 실시 공정을 세워야 해요."]},{"kind":"compare","head":"요소 네 가지와 수단 네 가지","cols":["구분","네 가지"],"rows":[["**공정계획** 의 요소","공사의 시기, 공사의 내용, 공사의 수량, 공사인력"],["공정관리의 수단","인력, 장비, 자금, 자원"]]},{"kind":"points","head":"공정 계획 작성 방법","items":["공사를 각 작업 내용별로 분류하고 각 작업의 소요기간을 산정해요.","작업 간의 선후관계를 분석하여 착수와 완료 시점을 계획해요.","자재의 조달, 반입 일정과 공종별 인력, 장비의 투입계획을 수립해요.","전체 공정표와 주요 공종별 세부 공정표를 만들고 주간, 월간 공정표로 진도를 관리해요."]},{"kind":"points","head":"공정에 반영할 현실적인 조건","items":["공휴일, 현장 작업 제한시간 등 실제 작업이 제한되는 조건을 넣어요.","외부환경의 영향을 받는 공사는 최근 기상자료와 계절적 특성을 검토해요.","호우, 한파 등에 따른 공정 지연에 대비해요.","공정계획은 계약공기를 준수하면서 품질, 안전, 원가를 고려해 합리적으로 수립해요."]},{"kind":"points","head":"공기를 줄여야 할 때와 공정표의 종류","items":["작업인원 조정, 작업시간 조정, 장비 추가 투입으로 공기를 단축할 수 있어요.","공장제작 후 현장조립, 공법 개선, 작업의 병행도 방법이에요.","공정표에는 횡선식, 사선식, 열기식, 네트워크식 등이 있어요.","횡선식 공정표는 막대공정표 또는 **바차트 공정표(Bar chart)** 라고도 해요. 다른 하나가 **네트워크 공정표** 예요."]}],"pass3":[{"kind":"check","q":"**공정계획** 의 요소 네 가지로 옳은 것은?","choices":["인력, 장비, 자금, 자원","공사의 시기, 내용, 수량, 인력","품질, 안전, 원가, 공정","재료비, 노무비, 외주비, 경비"],"a":1,"why":"요소는 시기, 내용, 수량, 인력이고 공정관리의 '수단' 이 인력, 장비, 자금, 자원이에요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"공정계획의 요소는 공사의 시기, 내용, 수량, 인력이고 공정관리의 수단은 인력, 장비, 자금, 자원이다.","ko":"공정표에는 횡선식, 사선식, 열기식, 네트워크식이 있으며 횡선식을 막대공정표 또는 바차트라고 한다.","tip":"요소는 '시내수인', 수단은 '인장자자', 공정표는 '횡사열네' 로 외워요."},{"kind":"warn","head":"요소와 수단을 바꿔 내요","items":["요소는 '공사의' 시기, 내용, 수량, 인력이에요.","수단은 인력, 장비, 자금, 자원이에요. 인력만 양쪽에 다 들어가서 헷갈려요.","횡선식 = 막대공정표 = **바차트 공정표(Bar chart)** 는 같은 말이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2346,0.1498],"c":[0,0.0208,0.2586,0.1818],"r":2.5288,"img":"img/L2/walk/p031_h.jpg"},"parts":[{"b":[0.025,0.198,0.7,0.032],"c":[0,0.1362,0.77,0.1556],"r":8.7975,"img":"img/L2/walk/p031_20_01.jpg","say":"첫 줄: **공정계획** 은 계약부터 착공, 시공, 준공까지 기간 내에 좋은 품질로 안전하게 진행되도록 계획하는 것이에요."},{"b":[0.025,0.243,0.38,0.032],"c":[0.006,0.204,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p031_20_02.jpg","say":"둘째 줄이 요소 네 가지예요. 공사의 시기, 내용, 수량, 인력."},{"b":[0.025,0.29,0.3,0.032],"c":[0.01,0.251,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p031_20_03.jpg","say":"셋째 줄이 수단 네 가지예요. 인력, 장비, 자금, 자원. 요소와 헷갈리지 마세요."},{"b":[0.039,0.454,0.6,0.19],"c":[0.009,0.438,0.66,0.222],"r":5.2853,"img":"img/L2/walk/p031_20_04.jpg","say":"상자 위쪽 다섯 줄이 공정 계획 작성 방법이에요. 분류와 소요기간, 선후관계, 자재와 인력 투입, 공정표, 공휴일까지예요."},{"b":[0.039,0.655,0.61,0.105],"c":[0.0085,0.639,0.671,0.137],"r":8.7072,"img":"img/L2/walk/p031_20_05.jpg","say":"상자 아래: 기상자료 검토, 품질과 안전과 원가를 고려한 합리적 수립, 그리고 공기를 단축하는 방법들이에요."},{"b":[0.039,0.776,0.58,0.034],"c":[0.01,0.7286,0.638,0.1289],"r":8.7992,"img":"img/L2/walk/p031_20_06.jpg","say":"맨 마지막 줄: 공정표에는 횡선식, 사선식, 열기식, 네트워크식이 있고 횡선식이 **바차트 공정표(Bar chart)** 예요."}]}},{"p":32,"title":"네트워크 공정표와 바차트 공정표","terms":["네트워크 공정표","바차트 공정표","공정계획"],"pass1":[{"kind":"compare","head":"두 공정표를 한 줄로 가르면","cols":["공정표","무엇을 보여 주나"],"rows":[["**네트워크 공정표**","공사를 어떤 순서로 해야 하는지 선으로 연결해서 보여 줘요"],["**바차트 공정표(Bar chart)**","언제 시작해서 언제 끝나는가를 보여 줘요"]]},{"kind":"say","lines":["이 쪽에도 실내건축기사 출제 내용이라는 표시가 붙어 있어요.","네트워크는 '관계' 가 보이고, 바차트는 '날짜' 가 보인다고 외워요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**네트워크 공정표** 를 한 줄로","items":["공정을 세분류하고 작업의 시작과 완료에 대하여 내용과 소요시간을 표시해요.","작업의 단계별 연계를 원과 화살표로 표기하는 방식이에요.","대규모 프로젝트나 공사의 복잡성이 높은 현장에서 주로 사용해요."]},{"kind":"compare","head":"장점과 단점을 마주 놓기","cols":["구분","장점","단점"],"rows":[["**네트워크 공정표**","공사 전체의 파악이 용이하고 작업 간의 상호 관계가 명확","공정표 작성의 시간이 다소 소요되고 제작의 전문성이 필요"],["**바차트 공정표(Bar chart)**","각 공정이 일목요연하게 표시되고 착수일과 완료일의 판단이 용이","각 공종의 상호관계를 확인하기 어렵고 정밀하지 못함"]]},{"kind":"points","head":"**바차트 공정표(Bar chart)** 를 한 줄로","items":["공사종목을 시공 순서에 따라 각 공종의 내용을 세로에 기입해요.","가로에는 막대로 각 공종의 시작부터 종료까지를 표시해요.","슬라이드 메모대로 실제 인테리어 현장에서는 바차트 공정표를 더 많이 써요."]},{"kind":"points","head":"공정표에 함께 담아야 하는 내용","items":["각각의 **공정계획** 과 아울러 인력의 수요 계획, 장비투입 계획","동력 및 용수계획, 자재 구입과 현장 반입 계획","자금 입수 및 지출 계획, 품질관리 계획","즉 공정표는 날짜표가 아니라 '계획 묶음' 이에요."]}],"pass3":[{"kind":"exam","src":"기출 모양 연습문제","q":"네트워크 공정표와 바차트 공정표를 비교하여 장단점을 서술하시오.","qko":"두 공정표의 좋은 점과 나쁜 점을 나란히 쓰는 문제예요.","solve":["네트워크는 원과 화살표로 연계를 표시해요.","장점은 전체 파악이 쉽고 상호 관계가 명확, 단점은 작성 시간과 전문성이 필요해요.","바차트는 세로에 공종, 가로에 막대로 기간을 표시해요.","장점은 일목요연하고 착수일과 완료일 판단이 쉬움, 단점은 상호관계 확인이 어렵고 정밀하지 못함이에요."],"answer":"네트워크는 관계가 보이지만 만들기 어렵고, 바차트는 날짜가 보이지만 관계가 안 보여요. 현장에서는 바차트를 더 많이 써요."},{"kind":"check","q":"**바차트 공정표(Bar chart)** 에 대한 설명으로 옳지 않은 것은?","choices":["각 공정이 일목요연하게 표시된다","착수일과 완료일의 판단이 용이하다","각 공종의 상호관계를 확인하기 쉽고 정밀하다","횡선식 공정표, 막대공정표라고도 한다"],"a":2,"why":"바차트는 상호관계 확인이 어렵고 정밀하지 못해요. 그것이 **네트워크 공정표** 의 장점이에요."},{"kind":"warn","head":"헷갈리는 짝","items":["**네트워크 공정표** 는 원과 화살표, '관계' 가 보이고 작성이 어려워요.","**바차트 공정표(Bar chart)** 는 가로 막대, '날짜' 가 보이고 현장에서 더 많이 써요.","기사 시험에 자주 나오는 쪽은 네트워크 공정표예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2346,0.1498],"c":[0,0.0208,0.2586,0.1818],"r":2.5288,"img":"img/L2/walk/p032_h.jpg"},"parts":[{"b":[0.025,0.194,0.49,0.034],"c":[0.0005,0.156,0.539,0.11],"r":8.7111,"img":"img/L2/walk/p032_20_01.jpg","say":"1) **네트워크 공정표** 제목. 옆에 실내건축기사 출제 내용, 대규모 프로젝트에서 주로 사용이라고 적혀 있어요."},{"b":[0.025,0.241,0.67,0.13],"c":[0,0.225,0.737,0.162],"r":8.0878,"img":"img/L2/walk/p032_20_02.jpg","say":"정의와 장단점 세 줄. 원과 화살표로 연계를 표기하고, 상호 관계가 명확하지만 작성 시간과 전문성이 필요해요."},{"b":[0.734,0.241,0.175,0.073],"c":[0.7215,0.2225,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p032_20_03.jpg","say":"오른쪽 설명 상자: 공사를 어떤 순서로 해야 하는지 선으로 연결해서 보여 주는 공정표예요."},{"b":[0.025,0.441,0.655,0.173],"c":[0,0.425,0.7205,0.205],"r":6.2482,"img":"img/L2/walk/p032_20_04.jpg","say":"2) **바차트 공정표(Bar chart)**. 세로에 공종, 가로에 막대. 착수일과 완료일 판단은 쉽지만 상호관계 확인이 어려워요."},{"b":[0.734,0.498,0.166,0.065],"c":[0.717,0.4755,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p032_20_05.jpg","say":"오른쪽 설명 상자: 언제 시작해서 언제 끝나는가를 보여 주는 공정표예요."},{"b":[0.036,0.717,0.6,0.093],"c":[0.006,0.6968,0.66,0.1333],"r":8.8022,"img":"img/L2/walk/p032_20_06.jpg","say":"아래 파란 상자: 공정표에는 인력 수요, 장비투입, 동력과 용수, 자재 구입과 반입, 자금, 품질관리 계획이 포함돼요."}]}},{"p":33,"title":"네트워크 공정표 이해하기, 경로와 주공정선","terms":["네트워크 공정표","주공정선","여유시간"],"pass1":[{"kind":"say","lines":["작은 사무실 인테리어 공사를 예로 들어 **네트워크 공정표** 를 풀어 주는 쪽이에요.","철거 → 전기 배선 → 천장과 벽체 마감 → 도장 → 준공 이 기본 순서예요.","그런데 실제 공사에는 동시에 할 수 있는 작업이 있어요. 거기서 경로가 갈려요."]},{"kind":"points","head":"네트워크 공정표의 핵심은 세 가지","items":["선행관계: 무엇이 먼저 끝나야 하는가","병행작업: 무엇을 동시에 할 수 있는가","**주공정선(Critical Path)**: 어떤 작업이 늦어지면 전체 공사가 늦어지는가"]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"그림이 말하는 선후관계","items":["철거가 끝나야 전기와 설비 작업을 시작할 수 있어요.","전기와 설비는 서로 동시에 진행할 수 있어요.","두 작업이 모두 끝나야 천장과 벽체 마감을 시작할 수 있어요.","마감이 끝나야 도장, 도장이 끝나야 준공이에요."]},{"kind":"compare","head":"작업과 기간과 선행 작업 표","cols":["작업","기간","선행 작업"],"rows":[["철거","2일","없음"],["전기 배선","3일","철거"],["설비 배관","2일","철거"],["천장, 벽체 마감","3일","전기, 설비"],["도장","2일","천장, 벽체 마감"]]},{"kind":"steps","head":"두 경로를 각각 더해 보기","steps":["경로 A: 철거 2일 + 전기 3일 + 마감 3일 + 도장 2일","2 더하기 3 더하기 3 더하기 2는 10, 즉 10일이에요.","경로 B: 철거 2일 + 설비 2일 + 마감 3일 + 도장 2일","2 더하기 2 더하기 3 더하기 2는 9, 즉 9일이에요.","A가 더 기니까 A가 **주공정선(Critical Path)** 이에요."],"answer":"**주공정선(Critical Path)** 은 철거 → 전기 → 마감 → 도장, 총 10일이에요."},{"kind":"points","head":"**여유시간(Float)** 이 생기는 이유","items":["설비 공정은 2일짜리인데 같이 진행되는 전기 공정은 3일이에요.","설비가 하루 정도 늦어져도 전기가 끝나는 시점까지 따라잡으면 준공일에 영향이 없어요.","이 여유를 **여유시간(Float)** 이라고 하고 Slack이라고도 해요.","반대로 주공정선에 있는 공정이 하루 늦어지면 전체 공사도 하루 늦어질 가능성이 커요."]}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"철거 2일 → 전기 3일 → 마감 3일 → 도장 2일 경로와 철거 2일 → 설비 2일 → 마감 3일 → 도장 2일 경로가 있을 때 주공정선의 총 기간은?","qko":"두 길 중 어느 쪽이 더 오래 걸릴까요.","solve":["경로 A를 더하면 2 + 3 + 3 + 2 = 10일이에요.","경로 B를 더하면 2 + 2 + 3 + 2 = 9일이에요.","**주공정선(Critical Path)** 은 더 긴 쪽이에요."],"answer":"10일이에요. 두 경로의 차이 1일이 설비 쪽의 **여유시간(Float)** 이에요."},{"kind":"check","q":"**주공정선(Critical Path)** 에 있지 않은 작업에 대한 설명으로 옳은 것은?","choices":["절대로 늦어지면 안 된다","**여유시간(Float)** 안에서 늦어져도 준공일에 영향을 주지 않을 수 있다","기간이 가장 길다","동시에 진행할 수 없다"],"a":1,"why":"예시의 설비 배관은 전기 배선보다 1일 짧아 하루 여유가 있어요. 이 여유를 Float 또는 Slack이라고 해요."}],"walk":{"head":{"b":[0.0092,0.0337,0.5646,0.0513],"c":[0,0.0177,0.6211,0.0833],"r":13.2554,"img":"img/L2/walk/p033_h.jpg"},"parts":[{"b":[0.034,0.363,0.285,0.037],"c":[0.0197,0.3265,0.3135,0.11],"r":5.0667,"img":"img/L2/walk/p033_20_01.jpg","say":"왼쪽 파란 상자: 철거 → 전기 배선 → 천장과 벽체 마감 → 도장 → 준공. 일렬로 놓은 기본 순서예요."},{"b":[0.028,0.56,0.365,0.098],"c":[0.0098,0.544,0.4015,0.13],"r":5.4906,"img":"img/L2/walk/p033_20_02.jpg","say":"왼쪽 그림: 철거 뒤에 전기 배선과 설비 배관이 위아래로 갈라졌다가 마감에서 다시 만나요. 이것이 병행작업이에요."},{"b":[0.028,0.697,0.28,0.112],"c":[0.014,0.681,0.308,0.144],"r":3.8025,"img":"img/L2/walk/p033_20_03.jpg","say":"그 아래 ①②③: 철거가 끝나야 전기와 설비를 시작하고, 둘 다 끝나야 마감을 시작할 수 있어요."},{"b":[0.415,0.087,0.205,0.237],"c":[0.403,0.071,0.229,0.269],"r":1.5134,"img":"img/L2/walk/p033_20_04.jpg","say":"오른쪽 위 표: 작업, 기간, 선행 작업. 철거 2일, 전기 3일, 설비 2일, 마감 3일, 도장 2일이에요."},{"b":[0.623,0.11,0.365,0.185],"c":[0.5985,0.094,0.4015,0.217],"r":3.2893,"img":"img/L2/walk/p033_20_05.jpg","say":"같은 그림에 기간이 붙었어요. 전기 위에 3일, 설비 아래에 2일이 적혀 있어요."},{"b":[0.417,0.403,0.337,0.081],"c":[0.4002,0.387,0.3707,0.113],"r":5.8321,"img":"img/L2/walk/p033_20_06.jpg","say":"경로 A는 10일, 경로 B는 9일. A가 더 길어 **주공정선(Critical Path)** 이 되고 차이 1일이 **여유시간(Float)** 이에요."}]}},{"p":34,"title":"네트워크 공정표 실제 예시 그림","terms":["네트워크 공정표","주공정선"],"pass1":[{"kind":"say","lines":["실제 현장에서 쓰는 **네트워크 공정표** 사진이에요. 단지별 공정표예요.","글자가 아주 작아서 읽으려 하지 말고 모양만 봐요.","동그라미가 줄줄이 이어지고 화살표로 연결된 모습이 네트워크 공정표의 얼굴이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"이 그림에서 볼 것 세 가지","items":["맨 위 가로줄이 연도와 월이에요. 시간이 왼쪽에서 오른쪽으로 흘러요.","왼쪽 세로줄이 공종 이름이에요. 공통가설, 토공사, 기초, 골조, 마감 순서로 적혀 있어요.","노란 동그라미가 작업의 시작과 완료 지점, 선이 작업의 연결이에요."]},{"kind":"points","head":"범례가 알려 주는 것","items":["그림 안 작은 범례에 예정, 실시, CP 세 가지가 있어요.","CP가 바로 **주공정선(Critical Path)** 이에요. 색이 다른 선으로 표시해요.","세 블록(건설사 세 곳)을 나란히 그려서 서로 비교할 수 있게 했어요."]},{"kind":"points","head":"왜 이런 그림이 필요할까","items":["작업이 수백 개면 어느 작업이 늦어졌을 때 무엇이 따라 밀리는지 눈으로 봐야 해요.","**네트워크 공정표** 는 그 연결을 보여 줘서 전체 파악이 쉬워요.","대신 이렇게 만들려면 시간과 전문성이 필요해요. 그래서 작은 인테리어 현장에서는 잘 안 써요."]}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.555,0.042,0.135,0.032],"c":[0.5225,0.003,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p034_20_01.jpg","say":"맨 위 제목: 단지별 공정표예요. 아파트 재개발 현장의 실제 **네트워크 공정표** 예요."},{"b":[0.245,0.072,0.735,0.07],"c":[0.1915,0.0253,0.8085,0.1633],"r":8.8018,"img":"img/L2/walk/p034_20_02.jpg","say":"맨 위 가로줄이 시간 축이에요. 연도와 월이 왼쪽에서 오른쪽으로 흘러가요."},{"b":[0.245,0.14,0.056,0.82],"c":[0.0976,0.098,0.3508,0.902],"r":0.6914,"img":"img/L2/walk/p034_20_03.jpg","say":"맨 왼쪽 세로줄이 공종 이름이에요. 공통가설, 토공사, 기초, 골조, 마감 순서로 적혀 있어요."},{"b":[0.322,0.276,0.042,0.068],"c":[0.243,0.255,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p034_20_04.jpg","say":"작은 범례 상자. 예정, 실시, 그리고 CP가 있어요. CP가 **주공정선(Critical Path)** 이에요."},{"b":[0.245,0.14,0.735,0.26],"c":[0.1915,0.124,0.8085,0.292],"r":4.9224,"img":"img/L2/walk/p034_20_05.jpg","say":"첫 번째 블록 전체. 노란 동그라미가 작업의 시작과 완료 지점, 선이 작업의 연결이에요."}]}},{"p":35,"title":"바차트 공정표 실제 예시 그림","terms":["바차트 공정표","네트워크 공정표"],"pass1":[{"kind":"say","lines":["이번에는 실제 **바차트 공정표(Bar chart)** 사진이에요.","왼쪽에 공종 이름이 세로로 쭉 적혀 있고, 오른쪽에 날짜가 가로로 적혀 있어요.","가로 막대가 '이 공종은 이 날부터 이 날까지' 를 보여 줘요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"세로 칸에 적힌 공종들","items":["설계 및 공사계약, 가설공사와 일시공사, 경량공사, 목공사, 설비공사","용접공사, 습식공사, 전기와 조명공사, 금속과 유리공사, 도장공사","필름공사, 타일공사, 바닥공사, 가구공사, 기타공사, 준공청소","아래쪽에 간판공사, 주방가구, 집기렌탈, 소방공사, 전기증설공사, 냉난방공사가 따로 묶여 있어요."]},{"kind":"points","head":"가로 칸에 적힌 시간","items":["맨 위에 MONTH, WEEK, DAY 세 줄이 있어요. 6월과 7월 두 달짜리 공정표예요.","요일까지 적혀 있고 일요일은 빨간색으로 표시되어 있어요.","즉 공휴일과 작업 제한 조건이 공정에 반영되어 있어요."]},{"kind":"points","head":"이 그림으로 알 수 있는 것과 없는 것","items":["알 수 있는 것: 어느 공종이 언제 시작해서 언제 끝나는가.","알 수 없는 것: 왜 그 순서인가, 어느 작업이 늦으면 전체가 밀리는가.","그래서 **바차트 공정표(Bar chart)** 는 날짜가 보이고 **네트워크 공정표** 는 관계가 보여요.","실제 인테리어 현장에서 훨씬 많이 쓰는 쪽은 바차트예요."]}],"pass3":[{"kind":"check","q":"실제 인테리어 현장에서 더 많이 쓰는 공정표와 그 이유로 알맞은 것은?","choices":["**네트워크 공정표**, 작성이 쉬워서","**바차트 공정표(Bar chart)**, 착수일과 완료일 판단이 쉬워서","**네트워크 공정표**, 날짜가 잘 보여서","**바차트 공정표(Bar chart)**, 상호관계가 잘 보여서"],"a":1,"why":"바차트는 일목요연하고 착수일, 완료일 판단이 쉬워요. 상호관계가 보이는 쪽은 네트워크예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2346,0.1993],"c":[0,0.0208,0.2586,0.2313],"r":1.9876,"img":"img/L2/walk/p035_h.jpg"},"parts":[{"b":[0.062,0.257,0.866,0.06],"c":[0.0187,0.1908,0.9526,0.1925],"r":8.7975,"img":"img/L2/walk/p035_20_01.jpg","say":"맨 위 머리줄: MONTH, WEEK, DAY 세 줄이에요. 6월과 7월 두 달짜리이고 일요일은 빨간색이에요."},{"b":[0.062,0.315,0.138,0.425],"c":[0.031,0.2937,0.2,0.4675],"r":0.7605,"img":"img/L2/walk/p035_20_02.jpg","say":"맨 왼쪽 세로줄이 공종이에요. 설계 및 공사계약부터 준공청소까지 시공 순서대로 적혀 있어요."},{"b":[0.2,0.315,0.69,0.425],"c":[0.1655,0.2937,0.759,0.4675],"r":2.8863,"img":"img/L2/walk/p035_20_03.jpg","say":"가운데가 가로 막대예요. 막대의 왼쪽 끝이 착수일, 오른쪽 끝이 완료일이에요."},{"b":[0.062,0.747,0.866,0.203],"c":[0.0187,0.731,0.9526,0.235],"r":7.2064,"img":"img/L2/walk/p035_20_04.jpg","say":"아래쪽 따로 묶인 줄들. 간판공사, 주방가구, 집기렌탈, 소방공사, 전기증설공사, 냉난방공사예요."}]}},{"p":36,"title":"시공 관리의 목적과 착공 준비","terms":["시공관리","착공","현장소장","공정관리","품질관리","안전관리","원가관리","실행내역서","바차트 공정표"],"pass1":[{"kind":"analogy","head":"시공관리의 목적 네 가지는 부사 네 개예요","scene":"슬라이드가 친절하게 짝을 지어 두었어요.","map":[["신속하게","**공정관리**"],["우수하게","**품질관리**"],["안전하게","**안전관리**"],["경제적으로","**원가관리**"]]},{"kind":"say","lines":["계획이 끝났으니 이제 진짜 공사를 시작해요. 그 앞 단계가 **착공** 준비예요.","주문으로 보면 '사람 → 방식 → 입찰 → 계획 → 관리 → 준공' 의 '관리' 로 들어온 거예요."]}],"pass2":[{"kind":"points","head":"**시공관리** 의 목적","items":["공사에 영향을 미치는 요소는 예산, 인력, 자재, 공법, 일정 등이에요.","이러한 생산 수단으로 신속하게(**공정관리**), 우수하게(**품질관리**) 공사를 해요.","그리고 안전하게(**안전관리**), 경제적으로(**원가관리**) 해요.","이 네 가지 목적을 달성하려고 노력하는 것이 시공관리의 목적이에요."]},{"kind":"points","head":"**착공** 일에 관한 숫자","items":["공사 계약에는 착공일이 명시되고, 지정된 일자를 지키지 못하면 제한 사항이 따라요.","착공일이 명시되지 않은 경우라 하더라도 일반적으로는 5일 이내에 착공하여야 해요.","'5일 이내' 는 단답형으로 자주 나오는 숫자예요."]},{"kind":"look","walked":1},{"kind":"points","head":"순서가 왜 중요할까","items":["슬라이드 오른쪽에 '누가?', '언제?' 라는 메모가 붙어 있어요.","'누가' 가 먼저예요. 담당자 구성이 가장 먼저 결정되어야 해요.","그다음 '언제' 예요. 공정계획에 따라 인력과 장비와 자재 투입 시기를 정해요.","이때 만드는 공정표가 보통 **바차트 공정표(Bar chart)** 모양이에요."]},{"kind":"points","head":"공사예산과 **실행내역서** 의 관계","items":["착공 준비에서 공사예산의 수입과 지출을 편성해요.","그 바탕이 앞 단원에서 배운 **실행내역서**, 즉 실제로 쓸 돈을 적은 대외비 문서예요.","실행내역서가 있어야 하도급 업체와의 금액을 정할 수 있어요."]}],"pass3":[{"kind":"check","q":"**착공** 일이 명시되지 않은 경우 일반적으로 착공해야 하는 기간은?","choices":["14일 이내","5일 이내","7일 이내","3일 이내"],"a":1,"why":"착공일이 명시되지 않아도 일반적으로 5일 이내에 착공해야 해요."},{"kind":"check","q":"착공 준비에서 가장 먼저 결정되어야 하는 것은?","choices":["현장에 투입하는 담당자의 구성","하도급 업체 선정","자재 구매 계획","공사 알림판 게시"],"a":0,"why":"**현장소장**, 현장기사, 직용 인력 구성이 먼저 정해지고 그다음 각종 계획을 세워요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"시공관리의 목적은 신속하게(공정관리), 우수하게(품질관리), 안전하게(안전관리), 경제적으로(원가관리)이다.","ko":"공사에 영향을 미치는 요소는 예산, 인력, 자재, 공법, 일정 등이다.","tip":"'신우안경' 네 글자로 부사를 외우고 괄호 안 관리 이름을 붙여요."}],"walk":{"head":{"b":[0.0092,0.0368,0.815,0.4829],"c":[0,0.0127,0.8965,0.5312],"r":3.0003,"img":"img/L2/walk/p036_h.jpg"},"parts":[{"b":[0.04,0.53,0.68,0.045],"c":[0.006,0.4769,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_01.jpg","say":"가장 먼저: 현장에 투입하는 담당자의 구성이에요. **현장소장** 과 현장기사 및 직용 인력이 기본이 돼요."},{"b":[0.04,0.565,0.68,0.045],"c":[0.006,0.5119,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_02.jpg","say":"다음: 시공 인력, 소요 장비, 자재 구매 및 투입 계획과 안전관리 계획, 품질관리 계획을 세워요."},{"b":[0.04,0.605,0.68,0.035],"c":[0.006,0.5469,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_03.jpg","say":"공사예산의 수입과 지출을 편성하고 공종에 따라 하도급 업체를 선정해요."},{"b":[0.04,0.643,0.68,0.035],"c":[0.006,0.5849,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_04.jpg","say":"현장 작업을 지원하는 가설물 설치, 그리고 동력과 용수와 통신의 수속과 설치를 준비해요."},{"b":[0.04,0.68,0.68,0.035],"c":[0.006,0.6219,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_05.jpg","say":"법규에 따른 승인 수속을 진행하고 민원에 대비한 사전 협조와 동의를 구해요."},{"b":[0.04,0.718,0.68,0.035],"c":[0.006,0.6599,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p036_22_06.jpg","say":"공사 알림판 또는 공사 안내서의 게시를 준비해요."}]}},{"p":37,"title":"착공과 착공서류","terms":["착공","착공계","현장대리인","예정공정표","산출내역서","직접시공계획서","바차트 공정표","실행내역서","안전관리","품질관리"],"pass1":[{"kind":"say","lines":["**착공** 은 공사에 착수하여 실제 시공을 시작하는 것이에요.","건축법에 따른 건축허가, 신고 대상 공사는 착수 전에 허가권자에게 착공신고를 해야 해요.","공공기관이나 기업과 계약한 공사는 발주처에 여러 가지 착공서류를 내요."]},{"kind":"points","head":"서류 이름 세 개만 먼저","items":["**착공계**: 언제부터 시작해 언제 끝낼지 알리는 서류","**현장대리인** 지정신고서: 공사 담당자가 누구인지 알리는 서류","**예정공정표**: 며칠에 무엇을 하는지 적은 표"]}],"pass2":[{"kind":"points","head":"**착공계** 에 적는 것","items":["착공계 또는 착공신고서에는 건축주의 인적 사항을 적어요.","대지 위치, 지번 등의 기본 사항을 빠짐없이 기재해야 해요.","착공 예정일, 설계자, 공사시공자 등에 관한 내용을 정확하게 작성해요.","인테리어 공사도 내용과 규모, 발주처 및 계약조건에 따라 필요한 착공 절차를 확인해 이행해요."]},{"kind":"look","walked":1},{"kind":"points","head":"나머지 착공서류","items":["착공서류 제출 공문(발주처 요구 시), 고용과 산재보험 가입 관련 증명서","**안전관리** 계획서 및 **품질관리** 계획서, 품질시험계획서(법정 또는 계약상 대상공사)","산업안전보건관리비 관련 서류, 환경관리비 사용계획서","공사의 종류, 규모 및 발주기관의 계약조건에 따라 제출서류가 달라질 수 있어요."]},{"kind":"compare","head":"이름이 비슷한 내역서 세 개 가르기","cols":["이름","누구에게","무엇을 담나"],"rows":[["**산출내역서**","발주처에게 제출","계약금액이 어떤 공종, 수량, 단가로 짜였는지"],["**실행내역서**","회사 안에서만 보는 대외비","실제 공사에 투입할 예산, 계약금액에서 일반관리비와 이윤을 뺀 공사원가"],["**예정공정표**","발주처에게 제출","며칠에 무엇을 할지. 보통 **바차트 공정표(Bar chart)** 모양"]]}],"pass3":[{"kind":"check","q":"공사를 전부 하도급으로 넘기지 않고 어떤 부분을 직접 시공할지 발주자에게 밝히는 서류는?","choices":["**산출내역서**","**예정공정표**","**직접시공계획서**","**착공계**"],"a":2,"why":"법정 대상공사에서 내는 서류예요. 계약금액 구성을 밝히는 것은 산출내역서예요."},{"kind":"warn","head":"착공 전 현장사진을 왜 찍을까","items":["공사 중에 파손 문제가 생기거나 원상복구를 할 때 증빙자료가 돼요.","특히 엘리베이터는 자재를 나르다 흠집이 잘 나서 꼭 미리 찍어 둬요.","**착공계** 와 **현장대리인** 지정신고서는 거의 모든 현장에서 같이 내는 한 쌍이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.8598,0.4392],"c":[0,0.0149,0.9458,0.4831],"r":3.4805,"img":"img/L2/walk/p037_h.jpg"},"parts":[{"b":[0.515,0.478,0.38,0.03],"c":[0.496,0.438,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_01.jpg","say":"**착공계**(착공신고서): 언제부터 공사를 시작하고 언제까지 끝낼 예정인지 알려요."},{"b":[0.515,0.516,0.38,0.03],"c":[0.496,0.476,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_02.jpg","say":"**현장대리인**(현장기술자) 지정신고서와 자격, 경력 증빙서류: 공사 담당자가 누구인지 알려요."},{"b":[0.515,0.556,0.38,0.03],"c":[0.496,0.516,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_03.jpg","say":"**예정공정표**: 며칠에 무엇을 하고 며칠에 무엇을 하는지 적어요."},{"b":[0.515,0.597,0.38,0.03],"c":[0.496,0.557,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_04.jpg","say":"공정별 인력 및 장비투입계획서: 전기 공사하는 날에는 몇 명이 들어오고 어떤 장비가 들어오는지 적어요."},{"b":[0.515,0.637,0.38,0.065],"c":[0.496,0.6145,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_05.jpg","say":"**산출내역서**: 계약금액이 어떤 공종, 수량, 단가로 구성되어 있는지 서로 확정하려고 내요. 착공 전 현장사진: 파손이나 원상복구 때 증빙자료가 돼요."},{"b":[0.515,0.755,0.38,0.035],"c":[0.496,0.7175,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p037_21_06.jpg","say":"**직접시공계획서**: 공사를 전부 하도급으로 넘기지 않고 어떤 부분을 직접 시공할지 밝히는 법정 서류예요."}]}},{"p":38,"title":"착공계와 현장대리인계 실제 양식","terms":["착공계","현장대리인","착공"],"pass1":[{"kind":"say","lines":["앞 쪽에서 이름만 들은 서류의 실제 모양이에요.","왼쪽이 **착공계**, 오른쪽이 **현장대리인** 계예요.","둘 다 한 장짜리 아주 짧은 서류예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왼쪽 **착공계** 의 칸 다섯 개","items":["1. 공사명, 2. 계약금액(일금 OOO원정)","3. 계약년월일, 4. **착공** 년월일, 5. 준공년월일","아래에 '상기와 같이 착공계를 제출합니다' 와 날짜, 주소, 상호, 대표이사, 전화, 팩스 칸이 있어요.","즉 착공계는 '언제 시작해서 언제 끝낼지' 를 알리는 서류라는 것이 한눈에 보여요."]},{"kind":"points","head":"오른쪽 **현장대리인** 계의 칸","items":["1. 공사명, 2. 공사위치, 3. 현장대리인(주소, 상호, 직위)","기술자격종목 및 등급, 발급번호를 적어요.","'상기공사에 대하여 위 사람을 현장대리인으로 선정하였으므로 현장 대리인계를 제출합니다' 라고 적혀 있어요.","그래서 자격과 경력 증빙서류를 함께 내야 해요."]}],"pass3":[{"kind":"check","q":"현장대리인계에 반드시 적어야 하는 항목으로 슬라이드 양식에 있는 것은?","choices":["하자담보책임기간","기술자격종목 및 등급과 발급번호","지체상금율","예정공정표"],"a":1,"why":"**현장대리인** 은 자격이 있는 기술자여야 해서 자격종목, 등급, 발급번호를 적어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1894,0.1842],"c":[0,0.0208,0.2134,0.2162],"r":1.7548,"img":"img/L2/walk/p038_h.jpg"},"parts":[{"b":[0.3,0.245,0.125,0.048],"c":[0.2625,0.214,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p038_20_01.jpg","say":"왼쪽 서식의 제목, **착공계** 예요. 착공신고서라고도 해요."},{"b":[0.238,0.346,0.235,0.186],"c":[0.226,0.33,0.259,0.218],"r":2.1121,"img":"img/L2/walk/p038_20_02.jpg","say":"1 공사명, 2 계약금액, 3 계약년월일, 4 **착공** 년월일, 5 준공년월일. 언제 시작해 언제 끝낼지를 적는 서류예요."},{"b":[0.228,0.57,0.265,0.19],"c":[0.2148,0.554,0.2915,0.222],"r":2.3343,"img":"img/L2/walk/p038_20_03.jpg","say":"'상기와 같이 착공계를 제출합니다' 아래로 날짜, 주소, 상호, 대표이사, 전화, 팩스 칸이 있어요."},{"b":[0.622,0.223,0.16,0.045],"c":[0.602,0.1905,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p038_20_04.jpg","say":"오른쪽 서식의 제목, **현장대리인** 계예요."},{"b":[0.578,0.295,0.265,0.236],"c":[0.5647,0.279,0.2915,0.268],"r":1.9337,"img":"img/L2/walk/p038_20_05.jpg","say":"1 공사명, 2 공사위치, 3 현장대리인(주소, 상호, 직위). 그 아래 기술자격종목 및 등급과 발급번호를 적어요."},{"b":[0.578,0.58,0.258,0.048],"c":[0.5651,0.549,0.2838,0.11],"r":4.5867,"img":"img/L2/walk/p038_20_06.jpg","say":"'위 사람을 현장대리인으로 선정하였으므로 현장 대리인계를 제출합니다' 라는 문구예요."}]}},{"p":39,"title":"현장관리와 현장관리자의 주요 업무 1, 공정관리와 품질관리","terms":["현장소장","공정관리","품질관리","안전관리","원가관리","현장운영관리","예정공정표","바차트 공정표"],"pass1":[{"kind":"say","lines":["이 쪽에는 별표 표시가 붙어 있어요. 시험에 꼭 나온다는 뜻이에요.","**현장소장** 이 하는 일은 딱 다섯 가지로 정리돼요.","**공정관리**, **품질관리**, **안전관리**, **원가관리**, **현장운영관리** 예요."]},{"kind":"points","head":"다섯 가지를 한 줄씩","items":["**공정관리**: 날짜를 지키게 하기","**품질관리**: 잘 만들었는지 보기","**안전관리**: 다치지 않게 하기","**원가관리**: 돈이 새지 않게 하기, **현장운영관리**: 사람과 물건을 굴리기"]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"현장관리를 한 줄로","items":["현장에서는 설계도서와 계약조건에 따라 공사가 적정하게 수행되도록 관리해요.","관리 대상은 공정, 품질, 안전, 원가, 인력, 자재 등이에요.","인테리어 현장에서는 현장을 총괄하는 담당자를 **현장소장**, 현장관리자 또는 현장책임자라고 불러요.","현장의 규모와 공사의 특성에 따라 필요한 관리조직을 구성하여 운영해요."]},{"kind":"points","head":"**현장소장** 의 자리","items":["본사와 협조하면서 공사 전반을 관리해요.","회사의 현장 책임자로서 발주처, 설계자, 협력업체와 업무를 조정해요.","즉 위로는 본사와 발주처, 아래로는 협력업체 사이에 서 있어요."]},{"kind":"points","head":"1. **공정관리**","items":["계약에 의해 정해진 공사기간에 준하여 **예정공정표** 에 따라 공사 진척을 관리해요.","그 예정공정표는 현장에서 보통 **바차트 공정표(Bar chart)** 로 붙여 놓아요.","공사기간 단축을 위해 노력해요.","공정별 작업내용과 작업순서를 조정하고 작업지시를 해요."]},{"kind":"points","head":"2. **품질관리**","items":["공사의 질적 향상이 목적이에요.","고품질의 목적을 기준으로 KS 기준과 건축 기본법에 명시된 바에 따라 관리해요.","품질의 향상과 기준의 확립을 위하여 관리하고, 품질관리자의 선임이 필요한 경우도 있어요.","설계도서, 시방서, 계약조건에 따라 시공되고 있는지 확인하고 불량시공은 시정 및 재발방지 조치를 해요."]}],"pass3":[{"kind":"check","q":"**공정관리** 에 대한 설명으로 옳은 것은?","choices":["KS 기준에 따라 품질의 향상을 관리한다","**예정공정표** 에 따라 공사 진척을 관리하고 작업지시를 한다","현장 예산의 심사와 승인을 한다","작업인력의 배치와 근태를 관리한다"],"a":1,"why":"KS 기준은 **품질관리**, 예산 심사는 **원가관리**, 근태는 **현장운영관리** 예요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"현장관리자의 주요 업무는 공정관리, 품질관리, 안전관리, 원가관리, 현장운영관리의 다섯 가지이다.","ko":"공정은 날짜, 품질은 기준, 안전은 사고 예방, 원가는 비용, 현장운영은 사람과 자재이다.","tip":"'공품안원현' 다섯 글자로 외워요. 별표가 붙은 쪽이라 꼭 나와요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1503],"c":[0,0.0208,0.2111,0.1823],"r":2.0586,"img":"img/L2/walk/p039_h.jpg"},"parts":[{"b":[0.025,0.194,0.625,0.176],"c":[0,0.178,0.6875,0.208],"r":5.8761,"img":"img/L2/walk/p039_20_01.jpg","say":"위쪽 네 줄이 현장관리의 뜻이에요. 공정, 품질, 안전, 원가, 인력, 자재를 관리하고 총괄하는 사람이 **현장소장** 이에요."},{"b":[0.04,0.432,0.16,0.034],"c":[0.02,0.394,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p039_20_02.jpg","say":"상자 제목: 현장관리자의 주요 업무 5가지. 왼쪽 위에 붙은 별표가 시험에 나온다는 표시예요."},{"b":[0.04,0.476,0.565,0.129],"c":[0.0117,0.46,0.6215,0.161],"r":6.8627,"img":"img/L2/walk/p039_20_03.jpg","say":"1. **공정관리**. **예정공정표** 에 따라 진척을 관리하고 작업내용과 작업순서를 조정하며 작업지시를 해요."},{"b":[0.04,0.618,0.71,0.122],"c":[0.0045,0.6001,0.781,0.1578],"r":8.7988,"img":"img/L2/walk/p039_20_04.jpg","say":"2. **품질관리**. KS 기준과 건축 기본법에 따라 품질의 향상과 기준의 확립을 위하여 관리해요."},{"b":[0.04,0.757,0.375,0.079],"c":[0.0213,0.741,0.4125,0.111],"r":6.6066,"img":"img/L2/walk/p039_20_05.jpg","say":"품질관리의 나머지 두 줄. 설계도서, 시방서, 계약조건대로인지 확인하고 불량시공은 시정과 재발방지 조치를 해요."}]}},{"p":40,"title":"현장관리자의 주요 업무 2, 안전관리와 원가관리와 현장운영관리","terms":["안전관리","원가관리","현장운영관리","안전사고","현장소장","실행내역서"],"pass1":[{"kind":"say","lines":["앞 쪽에 이어 별표가 붙은 쪽이에요. 나머지 세 가지 업무가 나와요.","**안전관리**, **원가관리**, **현장운영관리** 예요.","오른쪽 사진 세 장은 현장 정리 정돈을 보여 줘요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"3. **안전관리** 의 세 가지 정리정돈 규칙","items":["시공에 사용하는 각종 자재는 공사에 지장을 주지 않도록 배치해요.","공구들과 장비는 일정장소에 질서 있게 비치하여 현장을 혼잡하지 않도록 해요.","현장에서는 폐자재들이 나오는 즉시 마대를 이용하여 정리해요."]},{"kind":"points","head":"4. **원가관리** 를 자세히","items":["목적물의 시공에서 최소의 비용으로 최대의 효과를 노리려고 원가관리를 철저히 해요.","그래서 공사비를 절감시켜요. 기준이 되는 것이 착공 전에 만든 **실행내역서** 예요.","협력업체가 제출한 공사비 지불청구서, 자재 납품업체, 각종 공과금을 심사하고 승인해요."]},{"kind":"points","head":"5. **현장운영관리** 를 자세히","items":["공정별 작업인력의 배치와 근태를 관리해요.","자재와 장비의 반입, 사용 및 보관상태를 관리해요.","공사 중 발생하는 문제를 파악하고 발주처, 설계자, 협력업체와 조정해요.","설계변경이 필요하면 임의로 변경하지 않고 발주처 및 설계자와 협의한 후 시공해요."]}],"pass3":[{"kind":"check","q":"설계변경이 필요한 경우 **현장소장** 이 해야 할 일로 옳은 것은?","choices":["판단하여 임의로 변경한 뒤 보고한다","발주처 및 설계자와 협의한 후 시공한다","협력업체에 맡긴다","준공 후에 도면만 고친다"],"a":1,"why":"임의로 변경하지 않고 발주처 및 설계자와 협의한 후 시공해요."},{"kind":"exam","src":"문제은행 l23","q":"시공관리에서 현장관리자의 주요 업무 5가지를 쓰고 간단히 설명하시오.","qko":"현장소장이 하는 일 다섯 가지를 적는 문제예요.","solve":["**공정관리**: 예정공정표에 따른 진척 관리, 작업순서 조정, 작업지시","**품질관리**: 설계도서, 시방서, 계약조건대로 시공되는지 확인하고 불량시공 시정","**안전관리**: 공사 전, 중, 후 **안전사고** 예방과 정리정돈, 폐기물 처리 관리","**원가관리**: 최소 비용으로 최대 효과, 현장 예산 심사와 승인","**현장운영관리**: 인력 배치와 근태, 자재와 장비 관리, 설계변경은 협의 후 시공"],"answer":"공정관리, 품질관리, 안전관리, 원가관리, 현장운영관리의 다섯 가지예요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.307,0.72,0.1],"c":[0.004,0.277,0.792,0.16],"r":8.8,"img":"img/L2/walk/p040_20_01.jpg","say":"3. **안전관리**: 공사 전, 공사 중, 공사 후에 **안전사고** 예방을 주목적으로 해요. 공사의 종류와 금액에 따라 적용기준이 달라요."},{"b":[0.04,0.425,0.72,0.11],"c":[0.004,0.4,0.792,0.16],"r":8.8,"img":"img/L2/walk/p040_20_02.jpg","say":"현장의 안전, 정리정돈, 폐기물 처리 상태를 관리해요. 자재는 지장 없게 배치, 공구와 장비는 일정장소에, 폐자재는 즉시 마대로 정리해요."},{"b":[0.04,0.556,0.72,0.115],"c":[0.004,0.5335,0.792,0.16],"r":8.8,"img":"img/L2/walk/p040_20_03.jpg","say":"4. **원가관리**: 최소의 비용으로 최대의 효과를 노려 공사비를 절감해요. 공사비 지불청구서와 현장 예산을 심사, 승인해요."},{"b":[0.04,0.694,0.72,0.165],"c":[0.004,0.678,0.792,0.197],"r":7.1472,"img":"img/L2/walk/p040_20_04.jpg","say":"5. **현장운영관리**: 인력 배치와 근태, 자재와 장비의 반입과 보관을 관리하고 문제를 발주처, 설계자, 협력업체와 조정해요."},{"b":[0.797,0.019,0.18,0.94],"c":[0.5979,0,0.4021,1],"r":0.7148,"img":"img/L2/walk/p040_20_05.jpg","say":"오른쪽 사진 세 장이 '현장 정리 정돈' 이에요. 자재와 공구가 흩어져 있으면 사고가 나요."}]}},{"p":41,"title":"공사현장 작업일지 양식","terms":["공사 작업일지","현장대리인","현장운영관리"],"pass1":[{"kind":"say","lines":["현장에서 매일 쓰는 기록지 두 가지 양식이에요.","왼쪽이 공사일보, 오른쪽이 **공사 작업일지** 예요.","오늘 무엇을 했고 내일 무엇을 할지, 몇 명이 나왔는지를 적어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"왼쪽 공사일보의 칸","items":["맨 위 금일 작업내용과 명일 작업내용, 즉 오늘 한 일과 내일 할 일을 나란히 적어요.","가운데 출력현황: 분야별로 기공과 조공의 인원을 적어요. 기공은 기술자, 조공은 보조예요.","분야 칸에는 직원, 직영, 금속, 전기 등이 적혀 있어요.","아래에 장비 작업현황과 자재 반입현황 표가 있어요."]},{"kind":"points","head":"오른쪽 **공사 작업일지** 의 칸","items":["공사명, 일자, 요일, 날씨, 기온(최고와 최저)을 적어요.","작성자는 **현장대리인**, 확인자는 감독자이고 각각 인 또는 서명을 해요.","1. 공사추진상황: 공종별 설계량, 단위, 전일까지 작업량, 금일작업량, 누계 작업량","2. 장비투입상황, 3. 인력투입상황(보통인부, 특별인부), 4. 주요작업 참여자명단"]},{"kind":"points","head":"왜 이런 기록을 남길까","items":["**현장운영관리** 에서 인력의 배치와 근태를 관리하려면 매일 기록이 필요해요.","나중에 공정이 늦어졌을 때 왜 늦었는지 증거가 돼요.","날씨와 기온을 적어 두면 호우나 한파로 작업이 막힌 날을 설명할 수 있어요."]}],"pass3":[{"kind":"check","q":"공사일보 출력현황 표에서 '기공' 과 '조공' 은 각각 무엇을 뜻하나요?","choices":["발주자와 시공자","기술자와 보조","정규직과 임시직","실내와 실외"],"a":1,"why":"기공은 기술자, 조공은 보조 인력이에요. 분야별로 몇 명씩 나왔는지 적어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0551],"c":[0,0.0208,0.2111,0.0871],"r":4.3087,"img":"img/L2/walk/p041_h.jpg"},"parts":[{"b":[0.37,0.14,0.09,0.037],"c":[0.315,0.1035,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p041_20_01.jpg","say":"왼쪽 서식의 제목, 공사일보예요. 오른쪽 위에 현장명과 년월일 칸이 있어요."},{"b":[0.25,0.236,0.29,0.217],"c":[0.2355,0.22,0.319,0.249],"r":2.2776,"img":"img/L2/walk/p041_20_02.jpg","say":"맨 윗칸이 금일 작업내용과 명일 작업내용이에요. 오늘 한 일과 내일 할 일을 나란히 적어요."},{"b":[0.25,0.451,0.29,0.192],"c":[0.2355,0.435,0.319,0.224],"r":2.5317,"img":"img/L2/walk/p041_20_03.jpg","say":"가운데 출력현황. 분야별로 기공(기술자)과 조공(보조)의 인원을 적고 합계를 내요."},{"b":[0.25,0.646,0.29,0.24],"c":[0.2355,0.63,0.319,0.272],"r":2.085,"img":"img/L2/walk/p041_20_04.jpg","say":"아래쪽 장비 작업현황과 자재 반입현황 표예요."},{"b":[0.623,0.114,0.3,0.145],"c":[0.608,0.098,0.33,0.177],"r":3.3145,"img":"img/L2/walk/p041_20_05.jpg","say":"오른쪽 **공사 작업일지**. 공사명, 일자, 요일, 날씨, 기온을 적고 작성자는 **현장대리인**, 확인자는 감독자예요."},{"b":[0.623,0.264,0.3,0.64],"c":[0.608,0.232,0.33,0.704],"r":0.8333,"img":"img/L2/walk/p041_20_06.jpg","say":"1 공사추진상황, 2 장비투입상황, 3 인력투입상황, 4 주요작업 참여자명단 네 개 표가 이어져요."}]}},{"p":42,"title":"안전관리와 안전사고의 유형","terms":["안전관리","안전사고","안전모","안전대"],"pass1":[{"kind":"say","lines":["여기서부터 안전관리예요. 시험에 목록형으로 잘 나오는 부분이에요.","**안전관리** 는 사고와 재해를 미연에 방지하기 위해 필요한 사항을 정하고 관리하는 것이에요.","공사현장의 **안전사고** 는 근로자의 부주의로 생기는 비율이 매우 높아요."]},{"kind":"points","head":"현장이 위험한 이유","items":["소음, 진동, 분진이 생기고 조명부족, 환기 불량, 시공재료 냄새로 작업환경이 열악해요.","인화성물질, 전기 누전과 감전, 장비 자체의 위험이 있어요.","높은 곳에서 일하면 작업자와 자재와 장비의 추락도 예상돼요.","도난과 호우, 홍수, 태풍, 혹서, 한파 같은 자연재해도 대비해야 해요."]}],"pass2":[{"kind":"points","head":"**안전관리** 의 근거와 방법","items":["산업안전보건법에 의하여 안전 관리비를 사용해요.","개인 보호구의 착용, 안전 시설물 설치로 낙하, 추락, 감전을 막아요.","안전교육을 통하여 **안전사고** 를 예방해요."]},{"kind":"points","head":"**안전사고** 를 줄이는 첫걸음은 교육","items":["**안전모** 나 **안전대** 를 착용하지 않거나 위험지역에서 관리수칙을 따르지 않아 사고가 나요.","안전교육은 현장에서 요구되는 기준에 의해 주기적으로 모든 근로자에게 실시해요.","특히 현장경험이 부족한 신규 기능 인력이나 외국인근로자에게 실증적 교육을 확대해야 해요."]},{"kind":"look","walked":1},{"kind":"compare","head":"**안전사고** 유형을 원인으로 묶어 보기","cols":["묶음","해당하는 유형"],"rows":[["사람의 부주의","기계기구 조작 미숙, 재료 운반 시 부주의, 안전장구 미착용, 안전수칙 준수 소홀"],["물질 관리 소홀","유독물 관리 소홀로 약물중독, 난로와 전열기 관리소홀, 인화성 물질 보관 소홀"],["떨어짐과 전기","낙하물, 추락, 감전사고"],["불","도장공사 시 화재"]]}],"pass3":[{"kind":"check","q":"공사현장 **안전사고** 의 원인에 대한 설명으로 옳은 것은?","choices":["장비 결함이 대부분이다","근로자의 부주의에 의해 발생하는 비율이 매우 높다","날씨 때문에 생기는 것이 대부분이다","설계 잘못이 대부분이다"],"a":1,"why":"그래서 주기적인 안전교육이 중요하고, 특히 신규 인력과 외국인근로자 교육을 확대해야 해요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"안전관리는 사고와 재해를 미연에 방지하기 위하여 필요한 사항을 정하고 관리함을 목적으로 한다.","ko":"산업안전보건법에 따라 안전관리비 사용, 개인 보호구 착용, 안전 시설물, 안전교육으로 안전사고를 예방한다.","tip":"'법, 돈, 보호구, 시설, 교육' 다섯 토막으로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.7211,0.4344],"c":[0,0.0151,0.7932,0.4779],"r":2.9507,"img":"img/L2/walk/p042_h.jpg"},"parts":[{"b":[0.03,0.485,0.9,0.05],"c":[0,0.41,0.99,0.2],"r":8.8,"img":"img/L2/walk/p042_22_01.jpg","say":"이 문장이 핵심이에요. 공사현장의 **안전사고** 는 근로자의 부주의에 의해 발생하는 비율이 매우 높아요."},{"b":[0.035,0.672,0.28,0.095],"c":[0.021,0.656,0.308,0.127],"r":4.3115,"img":"img/L2/walk/p042_22_02.jpg","say":"왼쪽 줄 위: 목공, 철공 등 각종 기계기구 조작 미숙, 재료 운반 시 부주의, 작업 중 안전장구 미착용"},{"b":[0.035,0.77,0.28,0.175],"c":[0.021,0.754,0.308,0.207],"r":2.6452,"img":"img/L2/walk/p042_22_03.jpg","say":"왼쪽 줄 아래: 화공약품과 농약 등 유독물 관리 소홀로 약물중독, 난로와 전열기 관리소홀, 유류와 도료와 알콜과 신나 보관 소홀, 시설물 파손"},{"b":[0.315,0.672,0.29,0.14],"c":[0.3005,0.656,0.319,0.172],"r":3.2972,"img":"img/L2/walk/p042_22_04.jpg","say":"오른쪽 줄 위: 상단에서 떨어지는 낙하물, 높은 곳 작업 시 추락, 전기에 의한 감전사고, 도장공사 시 화재"},{"b":[0.315,0.81,0.29,0.08],"c":[0.3005,0.794,0.319,0.112],"r":5.0635,"img":"img/L2/walk/p042_22_05.jpg","say":"오른쪽 줄 아래: 수시 안전교육 미흡과 안전수칙 준수 소홀, 현장 부근 지상과 지하의 기존시설에 지장"}]}},{"p":43,"title":"공사현장 안전관리 수칙","terms":["안전관리","가설울타리","가설칸막이","낙하물 방지망","안전모","안전대"],"pass1":[{"kind":"say","lines":["현장에서 반드시 지켜야 할 **안전관리** 수칙 아홉 줄이에요.","시작은 출입금지 구역 설정이에요. 공사 관계자 이외의 출입을 통제해요.","목록형 서술로 '안전관리 수칙을 아는 대로 쓰시오' 가 나오기 좋은 쪽이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"출입금지 구역과 게시","items":["시공자는 인적, 물적 재해와 화재 등 예방을 위해 출입금지 구역을 설정해요.","공사 관계자 이외의 출입을 통제하는 것이 시작이에요.","**안전관리** 수칙 및 안전관리자의 인적사항을 시공현장 내 여러 사람이 잘 볼 수 있는 위치에 게시해요."]},{"kind":"points","head":"설치물 세 가지의 자리","items":["**가설울타리** 는 현장 주위를 둘러막아 사람이 못 들어오게 해요.","**가설칸막이** 는 공사 구역과 계속 쓰는 구역을 갈라 줘요. 백화점 리모델링에서 많이 봐요.","**낙하물 방지망** 은 위에서 떨어지는 물건을 받아 줘요.","세 가지 모두 건축법 규정에 따라 설치하고, 본 공사가 끝나면 걷어 내는 가설물이에요."]},{"kind":"bg","src":"배경 지식","lines":["대기업 백화점, 쇼핑몰 등의 내부공사에서는 매일 아침마다 안전교육을 실시해요.","영업 중인 건물 안에서 공사를 하니 손님과 섞이지 않게 관리가 더 엄격해요."]}],"pass3":[{"kind":"check","q":"**안전관리** 수칙상 공사현장 주위에 설치해야 하는 것으로 슬라이드에 적힌 것은?","choices":["추락 방호망과 안전펜스","**가설울타리** 와 **가설칸막이** 및 **낙하물 방지망**","소화기와 방화수","안전표시와 무재해 기록판"],"a":1,"why":"건축법 규정에 따라 가설울타리, 가설칸막이, 낙하물 방지망을 설치해요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"작업요원은 안전모, 안전대 및 로프, 보호안경 등 안전장비를 반드시 착용하여야 한다.","ko":"가연성 액체나 인화, 폭발 위험 물질은 다른 자재와 분리하고 열과 화기와 직사광선을 피해 보관한다.","tip":"'울타리, 표시, 교육, 장비, 중량물, 인화물, 고압선, 게시' 여덟 토막으로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.8996,0.2412],"c":[0,0.0208,0.9896,0.2732],"r":6.4396,"img":"img/L2/walk/p043_h.jpg"},"parts":[{"b":[0.03,0.325,0.78,0.045],"c":[0,0.2608,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_01.jpg","say":"공사현장 주위에는 건축법 규정에 따른 **가설울타리** 와 **가설칸막이** 및 **낙하물 방지망** 을 설치해요."},{"b":[0.03,0.372,0.78,0.045],"c":[0,0.3078,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_02.jpg","say":"위험이 예상되는 장소에 '위험 표시' 와 '안전작업요령' 을 부착해야 해요."},{"b":[0.03,0.41,0.78,0.09],"c":[0,0.3683,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_03.jpg","say":"작업요원에게 안전교육을 실시하고, **안전모**, **안전대** 및 로프, 보호안경 등 안전장비를 반드시 착용하게 해요."},{"b":[0.03,0.505,0.78,0.045],"c":[0,0.4408,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_04.jpg","say":"시멘트, 철근 및 골재 등 중량물은 무너져 내리지 않도록 안전하게 저장해요."},{"b":[0.03,0.552,0.78,0.045],"c":[0,0.4878,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_05.jpg","say":"가연성 액체나 인화, 폭발 위험 물질은 다른 자재와 분리하고 열과 화기와 직사광선을 피해 환기가 잘되는 곳에 보관해요."},{"b":[0.03,0.6,0.78,0.11],"c":[0,0.5683,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p043_20_06.jpg","say":"고압선이 있으면 위험표지와 절연시설 등 안전조치를 하고, 발주기관이나 감독관 요구사항은 즉시 조치하며, 안전관리수칙과 안전관리자 인적사항을 잘 보이는 곳에 게시해요."}]}},{"p":44,"title":"안전점검과 화재예방 기본 수칙","terms":["안전점검","화재예방","소방안전관리감독자","안전관리"],"pass1":[{"kind":"points","head":"**안전점검** 은 세 가지로 나뉘어요","items":["이 세 개는 단답형 단골이에요.","일상점검","정기점검","수시점검"]},{"kind":"say","lines":["이 쪽은 **안전점검** 과 **화재예방** 기본 수칙 두 덩어리예요.","용접과 도장을 같이 하면 안 된다는 규칙이 특히 자주 나와요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**안전점검** 의 중점관리 사항","items":["작업인력에 대한 **안전관리** 부터 시작해요.","가설시설물의 발판, 발디딤 등에 대한 견고성 확인이 필요해요.","개구부, 맨홀, 고소지역 난간 등에 안전망 및 안전표시판을 설치해요.","위험기계 안전장치, 전기와 조명 설치 상태 점검, 인화물질 격리조치, 정리 정돈과 청소와 청결 유지예요."]},{"kind":"points","head":"실내작업장에서 꼭 해야 하는 세 가지","items":["비상 시 근로자에게 신속하게 알리기 위한 경보용 설비 또는 기구를 설치하고 대피요령 교육을 실시해요.","비상구의 문은 실내에서 항상 열 수 있는 구조로 하고, 내부 및 외부에 비상구 표시를 해요.","밀폐된 공간은 유해가스가 제거되도록 강제 급기 및 배기 장치를 설치해요."]},{"kind":"points","head":"**화재예방** 기본 수칙","items":["용접작업은 불꽃과 불똥이 발생하므로 작업자 중 **소방안전관리감독자** 를 지정해요.","그리고 페인트 도장, 우레탄 발포 등 화재 가능성이 있는 작업과 병행하지 않도록 공정을 조정해요.","인화성, 폭발성, 가연성 물질은 필요한 양만 두고 별도의 안전한 장소에 보관해요.","작업장 내에서 모닥불 또는 흡연행위를 일체 금지해요."]},{"kind":"points","head":"**화재예방** 을 위한 시설과 협조","items":["충분한 수량의 소화기 및 방화수 등 소방 도구를 비치해요.","화기를 쓰거나 화재 위험이 있는 작업 시에는 소형소화기를 휴대하도록 해요.","주요 공사는 인근 소방서와 유기적인 협조체제를 구축해 소방대책을 강구해요.","소방차의 통행이 자유롭도록 소방통로를 개설, 유지하고 공사장 규모에 따라 임시 소방시설 설치기준을 적용해요."]}],"pass3":[{"kind":"check","q":"**화재예방** 기본 수칙상 용접작업과 병행하지 않도록 공정을 조정해야 하는 작업은?","choices":["페인트 도장, 우레탄 발포","석고보드 재단, 운반","먹매김, 실측","준공청소, 보양"],"a":0,"why":"용접은 불꽃과 불똥이 발생하므로 화재 가능성이 있는 도장, 우레탄 발포와 병행하지 않아요."},{"kind":"check","q":"**안전점검** 의 분류로 옳은 것은?","choices":["전수점검, 발췌점검","일상점검, 정기점검, 수시점검","사전점검, 사후점검","자체점검, 위탁점검"],"a":1,"why":"일상, 정기, 수시 세 가지예요. 전수와 발췌는 자재 품질검사 쪽 용어예요."},{"kind":"warn","head":"실내작업장에서 잘 틀리는 문장","items":["비상구의 문은 보안을 위해 잠그는 것이 아니라 실내에서 '항상 열 수 있는' 구조로 해요.","밀폐된 공간에서는 환기가 저절로 되지 않으니 '강제' 급기 및 배기 장치를 설치해요.","용접은 **소방안전관리감독자** 를 지정하고 도장, 우레탄 발포와 병행 금지예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1944],"c":[0,0.0208,0.2111,0.2264],"r":1.6576,"img":"img/L2/walk/p044_h.jpg"},"parts":[{"b":[0.03,0.235,0.78,0.04],"c":[0,0.1683,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p044_20_01.jpg","say":"작업 중 **안전점검** 은 일상점검, 정기점검, 수시점검으로 분류하여 실시해요."},{"b":[0.03,0.27,0.78,0.085],"c":[0,0.2258,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p044_20_02.jpg","say":"중점관리 사항: 가설시설물의 발판과 발디딤 견고성, 개구부와 맨홀과 고소지역 난간의 안전망과 안전표시판, 위험기계 안전장치, 전기와 조명 점검, 인화물질 격리, 정리 정돈."},{"b":[0.03,0.375,0.78,0.11],"c":[0,0.3433,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p044_20_03.jpg","say":"실내작업장에는 경보용 설비나 기구를 두고 대피요령 교육을 해요. 비상구의 문은 실내에서 항상 열 수 있는 구조로 하고 안팎에 비상구 표시를 해요. 밀폐 공간에는 강제 급기와 배기 장치를 설치해요."},{"b":[0.03,0.575,0.78,0.045],"c":[0,0.5108,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p044_20_04.jpg","say":"**화재예방** 기본 수칙: 근로자에게 주기적으로 소방교육 및 비상훈련을 실시해요."},{"b":[0.03,0.615,0.78,0.045],"c":[0,0.5508,0.858,0.1733],"r":8.8017,"img":"img/L2/walk/p044_20_05.jpg","say":"용접작업은 **소방안전관리감독자** 를 지정하고, 페인트 도장과 우레탄 발포 작업과 병행하지 않도록 공정을 조정해요."},{"b":[0.03,0.66,0.78,0.29],"c":[0,0.644,0.858,0.322],"r":4.7371,"img":"img/L2/walk/p044_20_06.jpg","say":"인화성과 폭발성 물질은 필요한 양만 두고 별도 보관, 모닥불과 흡연 금지, 소화기와 방화수 비치, 소방서 협조체제, 소방통로 개설, 임시 소방시설 설치기준 적용."}]}},{"p":45,"title":"소화기 및 방화수 비치 참고 사진","terms":["화재예방","안전관리"],"pass1":[{"kind":"say","lines":["앞 쪽 **화재예방** 기본 수칙에 나온 소화기와 방화수의 실제 모습이에요.","글자는 거의 없고 사진 세 장뿐이에요.","'현장에 이런 것이 놓여 있구나' 정도만 눈에 담으면 돼요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"사진 세 장이 보여 주는 것","items":["왼쪽: 빨간 받침 위에 소화기 한 대와 방화수 통 하나를 나란히 놓은 기본 세트예요.","가운데: 바퀴가 달린 이동식 소화장비함이에요. 소화기 여러 대와 방화수 통이 함께 실려 있어요.","오른쪽: 용접 작업 옆에 둔 이동식 방화차예요. 파란 물통과 노란 경고 입간판이 보여요."]},{"kind":"points","head":"왜 용접 옆에 물통이 있을까","items":["용접은 불꽃과 불똥이 튀어서 **화재예방** 의 가장 큰 관심 대상이에요.","그래서 화기를 사용하는 작업 시에는 소형소화기를 휴대하도록 하고 방화수도 가까이 둬요.","**안전관리** 는 사고가 난 뒤가 아니라 나기 전에 갖춰 두는 일이에요."]}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1956],"c":[0,0.0208,0.2111,0.2276],"r":1.6489,"img":"img/L2/walk/p045_h.jpg"},"parts":[{"b":[0.055,0.3,0.17,0.034],"c":[0.04,0.262,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p045_20_01.jpg","say":"제목 한 줄: 소화기 및 방화수 비치 참고 사진이에요."},{"b":[0.054,0.35,0.307,0.41],"c":[0.0386,0.3295,0.3377,0.451],"r":1.3312,"img":"img/L2/walk/p045_20_02.jpg","say":"왼쪽: 빨간 받침 위에 소화기 한 대와 방화수 통 하나를 놓은 기본 세트예요."},{"b":[0.362,0.35,0.31,0.41],"c":[0.3465,0.3295,0.341,0.451],"r":1.3442,"img":"img/L2/walk/p045_20_03.jpg","say":"가운데: 바퀴가 달린 이동식 소화장비함. 소화기 여러 대와 방화수 통이 함께 실려 있어요."},{"b":[0.673,0.35,0.245,0.41],"c":[0.6608,0.3295,0.2695,0.451],"r":1.0623,"img":"img/L2/walk/p045_20_04.jpg","say":"오른쪽: 용접 작업 옆에 둔 이동식 방화차예요. 화기를 쓰는 작업에는 가까이 두어야 해요."}]}},{"p":46,"title":"안전시설 및 장구 1, 안전펜스와 바리케이트","terms":["안전펜스","바리케이트","안전관리"],"pass1":[{"kind":"say","lines":["여기서부터 안전시설과 안전장구를 하나씩 봐요. 사진이 많아 쉬워요.","첫 번째는 **안전펜스** 및 **바리케이트** 예요.","둘 다 '여기 들어오지 마세요' 라고 말해 주는 물건이에요."]}],"pass2":[{"kind":"points","head":"안전시설이 왜 중요해졌나","items":["인테리어공사 현장 내에서 안전 확보가 기본적인 것으로 인식되어 가고 있어요.","그에 따라 안전을 확보하기 위한 시설의 중요성도 확대되고 있어요.","시공 현장에서 **안전관리** 를 위한 각종 시설은 위험 요소가 생길 수 있는 모든 장소에 설치해야 해요."]},{"kind":"points","head":"**안전펜스** 및 **바리케이트** 를 한 줄로","items":["안전한 작업을 위하여 공사 관계자 이외의 접근을 제한해요.","그리고 작업 현장의 영역을 표시하기 위하여 설치해요.","스틸과 플라스틱 재질의 제품으로 연결할 수 있도록 제작된 제품들이 쓰여요.","안전펜스와 바리케이트는 고정식과 이동식이 있어요."]},{"kind":"look","walked":1},{"kind":"compare","head":"**안전펜스** 와 **바리케이트** 의 쓰임","cols":["구분","언제 쓰나"],"rows":[["고정식","공사 기간 내내 같은 자리를 막을 때"],["이동식","작업 위치가 바뀌는 날마다 옮겨 가며 막을 때"]]}],"pass3":[{"kind":"check","q":"공사 관계자 이외의 접근을 제한하고 작업 현장의 영역을 표시하기 위해 설치하는 것은?","choices":["**안전펜스** 및 **바리케이트**","낙하물 방지망","추락 방호망","안전대"],"a":0,"why":"스틸과 플라스틱 재질로 만들고 고정식과 이동식이 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.7209,0.4372],"c":[0,0.015,0.793,0.4809],"r":2.9315,"img":"img/L2/walk/p046_h.jpg"},"parts":[{"b":[0.036,0.487,0.24,0.3],"c":[0.024,0.471,0.264,0.332],"r":1.4137,"img":"img/L2/walk/p046_22_01.jpg","say":"**안전펜스**. '안전 제일' 이라고 적힌 주황색 울타리예요. 옆으로 계속 이어 붙일 수 있어요."},{"b":[0.286,0.487,0.09,0.3],"c":[0.231,0.471,0.2,0.332],"r":1.071,"img":"img/L2/walk/p046_22_02.jpg","say":"입간판. '공사중' 이라고 적어 세워 두는 접이식 표지예요."},{"b":[0.396,0.487,0.07,0.3],"c":[0.331,0.471,0.2,0.332],"r":1.071,"img":"img/L2/walk/p046_22_03.jpg","say":"칼라콘. 흔히 라바콘이라고 부르는 원뿔이에요. 이동식 **바리케이트** 로 써요."}]}},{"p":47,"title":"안전시설 및 장구 2, 낙하물 방지망","terms":["낙하물 방지망","안전사고"],"pass1":[{"kind":"say","lines":["**낙하물 방지망** 은 위에서 떨어지는 물건을 받아 주는 그물이에요.","떨어지는 것이 물건이면 낙하물 방지망, 사람이면 다음 쪽의 추락 방호망이에요.","이름에 '낙하물' 이 들어 있으니 물건 쪽이라고 외워요."]}],"pass2":[{"kind":"points","head":"**낙하물 방지망** 을 한 줄로","items":["공사현장에서 낙하물에 의한 사고 및 추락의 위험에 대비하여 설치해요.","건물의 내외부에 설치해요.","실내 현장에서는 아트리움과 같은 개구부에도 설치해요.","부실하게 설치되면 **안전사고** 가 발생할 수 있으므로 항상 규격품을 사용하여야 해요."]},{"kind":"look","walked":1},{"kind":"points","head":"실내 현장에서의 자리","items":["아트리움처럼 층이 뚫려 있는 공간은 위층에서 떨어뜨린 공구가 아래층 사람을 칠 수 있어요.","그래서 개구부마다 **낙하물 방지망** 을 쳐요.","가설공사에서 세우는 가설울타리, 가설칸막이와 한 묶음으로 같이 설치해요."]}],"pass3":[{"kind":"check","q":"**낙하물 방지망** 에 대한 설명으로 옳지 않은 것은?","choices":["건물의 내외부에 설치한다","실내에서는 아트리움 같은 개구부에도 설치한다","현장에서 남는 그물로 적당히 만들어 쓴다","낙하물에 의한 사고와 추락 위험에 대비한다"],"a":2,"why":"부실하게 설치되면 안전사고가 생기므로 항상 규격품을 사용해야 해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.8149,0.3315],"c":[0,0.0203,0.8964,0.3647],"r":4.3696,"img":"img/L2/walk/p047_h.jpg"},"parts":[{"b":[0.061,0.456,0.2,0.42],"c":[0.049,0.435,0.224,0.462],"r":0.862,"img":"img/L2/walk/p047_21_01.jpg","say":"건물의 옥외 **낙하물 방지망**. 외벽 전체를 초록 그물로 감싸요."},{"b":[0.266,0.453,0.31,0.42],"c":[0.2505,0.432,0.341,0.462],"r":1.3122,"img":"img/L2/walk/p047_21_02.jpg","say":"가설계단과 낙하물 방지망. 계단 옆과 위를 그물로 둘러 물건이 떨어져도 밖으로 안 나가게 해요."},{"b":[0.586,0.453,0.312,0.42],"c":[0.5704,0.432,0.3432,0.462],"r":1.3206,"img":"img/L2/walk/p047_21_03.jpg","say":"대형 개구부와 낙하물 방지망. 실내 바닥에 뚫린 큰 구멍 위에 그물을 팽팽하게 치고 위험 표지를 붙였어요."}]}},{"p":48,"title":"안전시설 및 장구 3, 추락 방호망","terms":["추락 방호망","낙하물 방지망","안전대"],"pass1":[{"kind":"say","lines":["**추락 방호망** 은 사람이 떨어질 때 받아 주는 그물이에요.","높이 위치한 작업장에서 작업할 때 설치하는 시설이에요.","앞 쪽의 낙하물 방지망은 물건, 이번 쪽은 사람이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**추락 방호망** 을 한 줄로","items":["높이 위치한 작업장에서 작업할 때 사람이 떨어지면 추락을 방호하는 시설이에요.","오른쪽 위 사진처럼 실제로 사람이 그물 위에 떨어져 걸린 모습이 실려 있어요.","철골공사 중에 안전망을 설치한 사진도 함께 있어요."]},{"kind":"compare","head":"**추락 방호망** 과 **낙하물 방지망** 가르기","cols":["구분","무엇을 받나","어디에"],"rows":[["**추락 방호망**","사람","높이 위치한 작업장 아래"],["**낙하물 방지망**","물건","건물의 내외부, 실내 개구부"]]},{"kind":"points","head":"사진에서 볼 것","items":["가운데 사진에 수직보호망, 수직형 추락방망, 추락방호망이라는 이름이 따로 적혀 있어요.","오른쪽 사진에는 허술하게 설치된 보호망을 빨간 점선으로 표시해 두었어요.","즉 그물은 걸어 두는 것만으로 끝이 아니라 제대로 팽팽하게 매야 해요.","추락 위험이 있는 곳에서는 **안전대** 착용도 함께 해야 해요."]}],"pass3":[{"kind":"check","q":"높이 위치한 작업장에서 사람이 떨어질 때 받아 주는 시설은?","choices":["**낙하물 방지망**","**추락 방호망**","안전펜스","가설칸막이"],"a":1,"why":"사람은 추락 방호망, 물건은 낙하물 방지망이에요."},{"kind":"warn","head":"이름이 비슷한 그물 두 개","items":["'낙하물' 이 들어가면 물건을 받는 **낙하물 방지망** 이에요.","'추락' 이 들어가면 사람을 받는 **추락 방호망** 이에요.","둘 다 규격품을 제대로 설치해야 제 역할을 해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.0372],"c":[0,0.0208,0.2111,0.0692],"r":5.4232,"img":"img/L2/walk/p048_h.jpg"},"parts":[{"b":[0.025,0.283,0.4,0.034],"c":[0.005,0.245,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p048_20_01.jpg","say":"정의 한 줄: 높이 위치한 작업장에서 작업 시 사람이 떨어질 때 추락을 방호하는 시설이에요."},{"b":[0.754,0.076,0.188,0.33],"c":[0.742,0.0595,0.212,0.363],"r":1.0383,"img":"img/L2/walk/p048_20_02.jpg","say":"오른쪽 위: 실제로 사람이 **추락 방호망** 위에 떨어져 걸린 모습이에요. 다리만 보여요."},{"b":[0.043,0.426,0.337,0.486],"c":[0.0262,0.4017,0.3707,0.5346],"r":1.2327,"img":"img/L2/walk/p048_20_03.jpg","say":"왼쪽 아래: 철골공사 중의 안전망 설치. 초록 그물을 층 사이에 팽팽하게 쳐 두었어요."},{"b":[0.393,0.426,0.278,0.486],"c":[0.3791,0.4017,0.3058,0.5346],"r":1.0169,"img":"img/L2/walk/p048_20_04.jpg","say":"가운데: 수직보호망, 수직형 추락방망, 추락방호망이라고 이름이 따로 붙어 있어요."},{"b":[0.686,0.426,0.258,0.486],"c":[0.6731,0.4017,0.2838,0.5346],"r":0.9438,"img":"img/L2/walk/p048_20_05.jpg","say":"오른쪽: 빨간 점선 안이 허술하게 설치된 보호망이에요. 걸어 두기만 해서는 안 돼요."}]}},{"p":49,"title":"안전시설 및 장구 4, 안전표시","terms":["안전표시","안전사고"],"pass1":[{"kind":"say","lines":["**안전표시** 는 포스터, 스티커, 휘장 등으로 만들어요.","현장에서 '조심하세요' 라고 눈으로 말해 주는 물건이에요.","무재해 기록판도 안전표시의 한 종류예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**안전표시** 를 한 줄로","items":["안전표시에는 포스터, 스티커, 휘장 등이 있어요.","**안전사고** 가 발생할 수 있는 가능성이 있는 곳이나 작업자의 통행이 많은 장소에 게시해요.","작업자에게 안전에 대한 주의를 환기시키기 위하여 사용해요.","무재해, 안전사고 예방, 현장 정리 정돈 등 안전확보를 위한 표어나 구호로 구성되어 있어요."]},{"kind":"points","head":"사진에서 볼 수 있는 것","items":["왼쪽의 무재해 기록판: 목표 일수와 달성 일수, 시작일과 현재 날짜를 전광판으로 보여 줘요.","오른쪽 위 세 장: 위험 접근금지(엘리베이터), 위험 접근금지(추락 주의), 위험 추락주의 표지예요.","오른쪽 아래: '시작 전에 안전점검 끝난 후에 확인점검', '주의 접근시 머리조심', '감전주의' 표지예요.","색과 큰 글씨로 멀리서도 보이게 만든 것이 공통점이에요."]}],"pass3":[{"kind":"check","q":"**안전표시** 를 게시하는 장소로 슬라이드에 적힌 것은?","choices":["사무실 책상 위","**안전사고** 가능성이 있는 곳이나 작업자의 통행이 많은 장소","자재 창고 안쪽","발주처 회의실"],"a":1,"why":"작업자에게 안전에 대한 주의를 환기시키려고 눈에 잘 띄는 곳에 붙여요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2381],"c":[0,0.0208,0.2111,0.2701],"r":1.3894,"img":"img/L2/walk/p049_h.jpg"},"parts":[{"b":[0.025,0.279,0.86,0.124],"c":[0,0.2454,0.946,0.1911],"r":8.8005,"img":"img/L2/walk/p049_20_01.jpg","say":"정의 세 줄: **안전표시** 는 포스터, 스티커, 휘장 등으로 만들고 통행이 많은 장소에 게시해요."},{"b":[0.043,0.489,0.24,0.34],"c":[0.031,0.472,0.264,0.374],"r":1.2549,"img":"img/L2/walk/p049_20_02.jpg","say":"왼쪽 사진: 무재해 기록판. 목표 일수와 달성 일수, 시작일과 현재 날짜를 전광판으로 보여 줘요."},{"b":[0.288,0.464,0.213,0.372],"c":[0.276,0.4454,0.237,0.4092],"r":1.0297,"img":"img/L2/walk/p049_20_03.jpg","say":"가운데 사진: 또 다른 무재해기록판이에요. '안전은 생명 방심은 사고' 라는 구호가 적혀 있어요."},{"b":[0.54,0.426,0.253,0.25],"c":[0.5274,0.41,0.2783,0.282],"r":1.7545,"img":"img/L2/walk/p049_20_04.jpg","say":"오른쪽 위 세 장: 위험 접근금지(엘리베이터), 위험 접근금지(추락 주의), 위험 추락주의 표지예요."},{"b":[0.54,0.688,0.353,0.217],"c":[0.5224,0.672,0.3883,0.249],"r":2.7723,"img":"img/L2/walk/p049_20_05.jpg","say":"오른쪽 아래 세 장: '시작 전에 안전점검, 끝난 후에 확인점검', '접근시 머리조심', '감전주의' 예요."}]}},{"p":50,"title":"안전시설 및 장구 5, 안전모","terms":["안전모","안전대","낙하물 방지망"],"pass1":[{"kind":"say","lines":["**안전모** 는 현장에서 가장 먼저 쓰는 안전장구예요.","낙하물로부터 보호하고, 작업자가 추락했을 때 머리를 보호해요.","현장 내에서 작업하는 모든 작업자가 반드시 착용해야 해요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**안전모** 를 한 줄로","items":["현장에서 발생할 수 있는 낙하물로부터 보호하는 안전장구예요.","작업자가 추락하였을 때 머리를 보호하기 위하여 착용해요.","현장 내에서 작업하는 모든 작업자들이 반드시 착용하여야 해요.","**낙하물 방지망** 이 시설로 막는 것이라면 안전모는 몸에 쓰는 것이에요."]},{"kind":"points","head":"사진에서 볼 것, 안전모를 제대로 쓰는 법","items":["왼쪽 사진은 안전모를 뒤집어 안쪽을 보여 줘요. 머리에 닿는 끈과 고정 장치가 있어요.","오른쪽 사진에는 '머리 고정대' 라는 화살표가 붙어 있어요.","머리 고정대를 조여야 안전모가 흔들리지 않고 충격을 제대로 받아 줘요.","턱끈도 반드시 채워야 떨어질 때 벗겨지지 않아요."]},{"kind":"compare","head":"반드시 착용해야 하는 장구 두 가지","cols":["장구","무엇을 막나","누가"],"rows":[["**안전모**","낙하물과 추락 시 머리 부상","현장 내 모든 작업자"],["**안전대**","높은 곳에서의 추락","높은 곳에서 작업하는 작업자"]]}],"pass3":[{"kind":"check","q":"**안전모** 에 대한 설명으로 옳은 것은?","choices":["관리자만 착용한다","현장 내에서 작업하는 모든 작업자가 반드시 착용한다","높은 곳에서만 착용한다","여름에는 생략할 수 있다"],"a":1,"why":"낙하물로부터 보호하고 추락 시 머리를 보호하므로 모든 작업자가 반드시 착용해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2381],"c":[0,0.0208,0.2111,0.2701],"r":1.3894,"img":"img/L2/walk/p050_h.jpg"},"parts":[{"b":[0.025,0.279,0.61,0.078],"c":[0,0.2502,0.671,0.1356],"r":8.7971,"img":"img/L2/walk/p050_20_01.jpg","say":"정의 두 줄: 낙하물로부터 보호하고 추락 시 머리를 보호해요. 모든 작업자가 반드시 착용해야 해요."},{"b":[0.043,0.39,0.428,0.407],"c":[0.0216,0.3697,0.4708,0.4477],"r":1.8695,"img":"img/L2/walk/p050_20_02.jpg","say":"왼쪽 사진: **안전모** 를 뒤집어 안쪽을 보여 줘요. 머리에 닿는 끈과 고정 장치가 보여요."},{"b":[0.486,0.397,0.341,0.399],"c":[0.4689,0.377,0.3751,0.4389],"r":1.5194,"img":"img/L2/walk/p050_20_03.jpg","say":"오른쪽 사진: 실제로 쓴 모습이에요. 턱끈을 채워야 떨어질 때 벗겨지지 않아요."},{"b":[0.738,0.681,0.085,0.047],"c":[0.6805,0.6495,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p050_20_04.jpg","say":"사진 속 라벨이 가리키는 곳이 머리 고정대예요. 여기를 조여야 안전모가 흔들리지 않아요."}]}},{"p":51,"title":"안전시설 및 장구 6, 안전 조끼","terms":["안전 조끼","안전모","안전표시"],"pass1":[{"kind":"say","lines":["**안전 조끼** 는 작업자를 눈에 잘 띄게 만드는 옷이에요.","현장 작업복은 대부분 어둡거나 탁한 색이라 잘 안 보여요.","그래서 밝은 색 조끼를 덧입어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"**안전 조끼** 를 한 줄로","items":["현장에서 작업자의 작업복은 현장의 속성상 대부분 어둡거나 탁한 색상이에요.","그래서 명시성이 떨어지는 현상이 나타나요. 명시성은 '눈에 잘 띄는 정도' 예요.","이러한 현상을 보완하여 작업자의 명시성을 높여 안전을 확보할 수 있는 색상의 안전조끼를 착용해요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 두 장은 형광 연두색 조끼예요. 가슴과 등에 은색 반사 띠가 둘려 있어요.","반사 띠는 어두운 곳에서 불빛을 받으면 빛나서 더 잘 보여요.","오른쪽은 빨간 조끼예요. '신호수', '화재감시자' 라고 글자가 적혀 있어요.","즉 조끼는 색으로 눈에 띄게 하고 글자로 역할을 알려 주는 **안전표시** 역할도 해요."]},{"kind":"points","head":"공사 현장에서 함께 쓰는 짝","items":["**안전모** 는 머리, **안전 조끼** 는 몸이에요.","머리부터 발끝까지 순서로 외우면 안전모, 보호면, 방진 마스크, 안전 조끼로 이어져요.","그다음이 안전대, 각반, 안전화예요. 뒤쪽 세 개는 다음 쪽들에서 만나요."]}],"pass3":[{"kind":"check","q":"**안전 조끼** 를 착용하는 이유로 옳은 것은?","choices":["보온을 위해","작업자의 명시성을 높여 안전을 확보하려고","주머니가 많아서","비를 막으려고"],"a":1,"why":"현장 작업복이 어둡거나 탁해서 잘 안 보이는 문제를 보완해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2381],"c":[0,0.0208,0.2111,0.2701],"r":1.3894,"img":"img/L2/walk/p051_h.jpg"},"parts":[{"b":[0.025,0.279,0.625,0.078],"c":[0,0.2486,0.6875,0.1389],"r":8.7993,"img":"img/L2/walk/p051_20_01.jpg","say":"정의 두 줄: 작업복이 어둡거나 탁해 명시성이 떨어지니 눈에 잘 띄는 색상의 **안전 조끼** 를 입어요."},{"b":[0.036,0.394,0.53,0.51],"c":[0.0095,0.3685,0.583,0.561],"r":1.8475,"img":"img/L2/walk/p051_20_02.jpg","say":"왼쪽 두 장: 형광 연두색 조끼예요. 가슴과 등에 은색 반사 띠가 둘려 있어 어두운 곳에서도 보여요."},{"b":[0.57,0.394,0.2,0.353],"c":[0.558,0.3764,0.224,0.3883],"r":1.0256,"img":"img/L2/walk/p051_20_03.jpg","say":"가운데: 빨간 조끼예요. 색만으로도 멀리서 눈에 띄어요."},{"b":[0.783,0.409,0.19,0.426],"c":[0.771,0.3877,0.214,0.4686],"r":0.8119,"img":"img/L2/walk/p051_20_04.jpg","say":"오른쪽: '신호수', '화재감시자' 라고 글자가 적힌 조끼예요. 색과 글자로 역할까지 알려 줘요."}]}},{"p":52,"title":"안전시설 및 장구 7, 안전대","terms":["안전대","안전모","추락 방호망"],"pass1":[{"kind":"say","lines":["**안전대** 는 **안전모** 와 함께 반드시 착용해야 할 필수 장구예요.","높은 곳에서 일할 때 몸에 매고 안전줄이나 비계에 걸어 두는 띠예요.","줄에 매달려 있으면 떨어져도 바닥까지 가지 않아요."]}],"pass2":[{"kind":"points","head":"**안전대** 를 한 줄로","items":["작업자의 개인 안전 장구 중에서 **안전모** 와 함께 반드시 착용하여야 할 필수 장구예요.","안전띠는 높은 장소에서 작업할 때 작업장 주위에 설치된 안전줄이나 비계에 걸어요.","그렇게 해서 추락을 방지할 수 있도록 하는 장구예요."]},{"kind":"look","walked":1},{"kind":"compare","head":"**안전대** 두 가지","cols":["형태","감싸는 곳"],"rows":[["상체식 **안전대**","어깨와 허리"],["전체식(그네식) **안전대**","어깨, 허리, 허벅지까지 전체"]]},{"kind":"points","head":"시설과 장구는 짝이에요","items":["**추락 방호망** 은 떨어진 사람을 받아 주는 '시설' 이에요.","**안전대** 는 아예 떨어지지 않게 붙잡아 주는 '장구' 예요.","둘 다 있어야 높은 곳 작업이 안전해요.","머리부터 발끝까지 순서는 안전모, 보호면, 방진 마스크, 안전 조끼, 안전대, 각반, 안전화예요."]}],"pass3":[{"kind":"check","q":"**안전모** 와 함께 반드시 착용해야 할 필수 장구로, 안전줄이나 비계에 걸어 추락을 방지하는 것은?","choices":["각반","**안전 조끼**","보호면","**안전대**"],"a":3,"why":"안전대는 상체식과 전체식(그네식)이 있어요."},{"kind":"english","head":"목록형 서술 대비 문장","en":"안전시설 및 장구에는 안전펜스와 바리케이트, 낙하물 방지망, 추락 방호망, 안전표시가 있다.","ko":"개인 장구로는 안전모, 안전 조끼, 안전대가 있으며 안전모와 안전대는 반드시 착용한다.","tip":"시설은 '펜스, 낙하, 추락, 표시' 네 개, 장구는 '모, 조끼, 안전대' 세 개로 나눠 외워요."},{"kind":"warn","head":"마지막 정리","items":["**안전대** 와 **안전모** 는 '반드시' 착용이에요. 이 단어가 문제에 그대로 나와요.","**추락 방호망** 은 사람, 낙하물 방지망은 물건이에요.","안전시설과 장구는 공사 전에 갖춰 두는 것이지 사고가 난 뒤에 다는 것이 아니에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.6882,0.3315],"c":[0,0.0203,0.757,0.3647],"r":3.6901,"img":"img/L2/walk/p052_h.jpg"},"parts":[{"b":[0.068,0.437,0.14,0.44],"c":[0.038,0.415,0.2,0.484],"r":0.7346,"img":"img/L2/walk/p052_21_01.jpg","say":"상체식 **안전대**. 허리와 어깨에만 띠가 있어요."},{"b":[0.279,0.437,0.11,0.44],"c":[0.234,0.415,0.2,0.484],"r":0.7346,"img":"img/L2/walk/p052_21_02.jpg","say":"전체식(그네식) 안전대. 어깨와 허리와 허벅지까지 감싸서 매달렸을 때 몸이 빠지지 않아요."},{"b":[0.479,0.422,0.236,0.465],"c":[0.467,0.3987,0.26,0.5115],"r":0.9037,"img":"img/L2/walk/p052_21_03.jpg","say":"'올바른 안전대 사용 ABC' 포스터. A는 Anchorage(고정점), B는 Body Support(안전대), C는 Connector(연결 장치)예요."}]}},{"p":53,"title":"안전장구 (8) 안전화","terms":["안전화","안전대"],"pass1":[{"kind":"say","lines":["현장 바닥에는 못, 나사, 무거운 물건이 굴러다녀요.","**안전화**는 거기서 발을 지켜 주는 작업용 신발이에요.","안전모가 머리 헬멧이라면 **안전화**는 발에 신는 갑옷이에요."]}],"pass2":[{"kind":"points","head":"**안전화**가 막아 주는 것","items":["**안전화**는 현장 바닥에 떨어진 위험물로부터 발과 발목을 지키려고 신는 작업화예요.","못이나 나사가 밑창을 뚫고 올라오는 것을 막아 발바닥을 지켜요.","망치나 무거운 물건이 떨어질 때 발가락 부분을 지켜요."]},{"kind":"look","walked":1},{"kind":"points","head":"공사 순서에서의 자리","items":["**안전화**는 현장에 들어서는 순간부터 벗지 않는 기본 장구예요.","높은 곳에서 일할 때는 여기에 **안전대**를 더해서 추락을 막아요.","**안전대**는 안전모와 함께 반드시 착용하는 필수 장구라고 배웠지요."]}],"pass3":[{"kind":"check","q":"현장 바닥의 못이나 나사로부터 발바닥을 보호하려고 신는 것은?","choices":["안전대","안전화","각반","보호면"],"a":1,"why":"안전화는 발바닥과 발가락을 지켜요. 안전대는 추락 방지 장구예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.5023,0.3315],"c":[0,0.0203,0.5525,0.3647],"r":2.6932,"img":"img/L2/walk/p053_h.jpg"},"parts":[{"b":[0.68,0.55,0.11,0.06],"c":[0.635,0.525,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p053_21_01.jpg","say":"선심이에요. 쇠 소재로 앞코에 들어가 발가락을 보호해요."},{"b":[0.51,0.76,0.09,0.06],"c":[0.455,0.735,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p053_21_02.jpg","say":"갑혁이에요. 밑창을 제외한 윗부분 가죽을 말해요."},{"b":[0.64,0.76,0.09,0.06],"c":[0.585,0.735,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p053_21_03.jpg","say":"내답판이에요. 밑창으로 쓰는 단단한 방탄 재질이에요."}]}},{"p":54,"title":"안전장구 (9) 방진 마스크","terms":["방진 마스크"],"pass1":[{"kind":"say","lines":["철거를 하면 먼지가 방 안 가득 뿌옇게 떠다녀요.","**방진 마스크**는 그 먼지를 걸러 폐로 들어가지 못하게 막아요.","정수기 필터를 얼굴에 붙인다고 생각하면 쉬워요."]}],"pass2":[{"kind":"points","head":"**방진 마스크**는 언제 쓰나요","items":["**방진 마스크**는 분진이나 유독성 가스가 생길 가능성이 높은 작업에서 착용해요.","슬라이드가 든 예는 철거작업, 도장작업이에요.","먼지가 많은 작업은 현장 작업 순서 중 가설 다음의 철거 단계에 몰려 있어요."]},{"kind":"compare","head":"**방진 마스크**의 두 종류","cols":["종류","특징"],"rows":[["필터가 부착된 제품","분진 같은 것을 걸러 주는 필터가 달려 있어요"],["일반 마스크 제품","필터 없이 입과 코만 가리는 보통 마스크예요"]]},{"kind":"points","head":"이 장구의 자리","items":["**방진 마스크**는 철거가 시작되기 전에 인원수대로 준비해 두어야 해요.","분진을 줄이려고 물을 뿌리는 것과 **방진 마스크**는 같이 쓰는 대책이에요.","개인보호구 현황은 안전관리 기록으로 남겨요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"철거작업, 도장작업처럼 분진이나 유독성 가스가 발생할 수 있을 때 쓰는 것은?","choices":["각반","안전화","방진 마스크","안전대"],"a":2,"why":"방진 마스크는 분진과 유독성 가스를 막아요. 필터가 붙은 제품과 일반 마스크 제품이 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2362],"c":[0,0.0208,0.2111,0.2682],"r":1.3993,"img":"img/L2/walk/p054_h.jpg"},"parts":[{"b":[0.03,0.275,0.68,0.05],"c":[0,0.2244,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p054_23_01.jpg","say":"분진이나 유독성 가스가 발생할 가능성이 높은 경우에 착용한다는 줄이에요."},{"b":[0.03,0.325,0.46,0.05],"c":[0.007,0.295,0.506,0.11],"r":8.1778,"img":"img/L2/walk/p054_23_02.jpg","say":"필터가 부착된 제품과 일반 마스크 제품 두 종류가 있다는 줄이에요."},{"b":[0.25,0.42,0.24,0.41],"c":[0.238,0.3995,0.264,0.451],"r":1.0407,"img":"img/L2/walk/p054_23_03.jpg","say":"분홍색 필터가 양쪽에 달린 **방진 마스크**예요. 필터가 분진을 걸러요."},{"b":[0.55,0.52,0.13,0.17],"c":[0.515,0.504,0.2,0.202],"r":1.7602,"img":"img/L2/walk/p054_23_04.jpg","say":"필터 없이 입과 코만 가리는 일반 마스크 제품이에요."}]}},{"p":55,"title":"안전장구 (10) 보호면","terms":["보호면","방진 마스크","각반"],"pass1":[{"kind":"say","lines":["용접을 하면 눈이 부실 만큼 불꽃이 튀어요.","**보호면**은 그 불꽃과 파편에서 눈을 지키는 얼굴 가리개예요.","야구 포수가 쓰는 마스크를 떠올리면 비슷해요."]}],"pass2":[{"kind":"points","head":"**보호면**의 정체","items":["**보호면**은 각종 작업 중 발생하는 불꽃, 분진, 파편으로부터 눈을 보호하는 안전 장구예요.","슬라이드가 든 작업은 용접, 절단, 그라인딩이에요.","슬라이드 사진에는 용접용 천 보호면, 망사형, 투명 아크릴형이 나와요."]},{"kind":"compare","head":"무엇을 지키는 장구인지 구별해요","cols":["장구","지키는 곳","대표 상황"],"rows":[["**보호면**","눈, 얼굴","용접, 절단, 그라인딩"],["**방진 마스크**","코, 입, 폐","철거, 도장"],["**각반**","발목, 바짓단","걸림, 끼임"]]},{"kind":"points","head":"함께 지켜야 하는 것","items":["용접은 불꽃이 튀므로 페인트 도장, 우레탄 발포와 같은 날에 하지 않아요.","**보호면**을 썼다고 해서 안전모를 벗어도 되는 것은 아니에요.","용접 자리에는 **각반**도 함께 차서 불티가 바짓단으로 들어가지 않게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"용접, 절단, 그라인딩 작업에서 불꽃, 분진, 파편으로부터 눈을 보호하는 장구는?","choices":["각반","보호면","방진 마스크","안전모"],"a":1,"why":"보호면은 눈을 보호해요. 방진 마스크는 분진과 유독가스, 각반은 바짓단 끼임 방지예요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2362],"c":[0,0.0208,0.2111,0.2682],"r":1.3993,"img":"img/L2/walk/p055_h.jpg"},"parts":[{"b":[0.03,0.275,0.79,0.05],"c":[0,0.2122,0.869,0.1756],"r":8.7978,"img":"img/L2/walk/p055_23_01.jpg","say":"용접, 절단, 그라인딩의 불꽃, 분진, 파편에서 눈을 보호한다는 줄이에요."},{"b":[0.105,0.4,0.25,0.44],"c":[0.0925,0.378,0.275,0.484],"r":1.0101,"img":"img/L2/walk/p055_23_02.jpg","say":"용접용 천 **보호면**이에요. 어두운 창으로 불빛을 걸러 봐요."},{"b":[0.36,0.4,0.25,0.44],"c":[0.3475,0.378,0.275,0.484],"r":1.0101,"img":"img/L2/walk/p055_23_03.jpg","say":"망사형 **보호면**이에요. 파편은 막고 숨은 통하게 해요."},{"b":[0.61,0.4,0.25,0.44],"c":[0.5975,0.378,0.275,0.484],"r":1.0101,"img":"img/L2/walk/p055_23_04.jpg","say":"투명 **보호면**이에요. 잘 보이면서 얼굴 전체를 덮어요."}]}},{"p":56,"title":"안전장구 (11) 각반","terms":["각반","안전화","보호면","방진 마스크","안전대"],"pass1":[{"kind":"say","lines":["바짓단이 길면 철근이나 자재에 걸려 넘어지기 쉬워요.","**각반**은 발목에 둘러 바짓단을 묶어 주는 띠예요.","자전거 탈 때 바지 끝을 묶는 밴드와 같은 역할이에요."]}],"pass2":[{"kind":"points","head":"**각반**의 정체","items":["**각반**은 바지 하단이 걸리거나 끼임으로 생길 수 있는 사고를 막으려고 착용해요.","슬라이드 사진에는 짧은 밴드형 **각반**과 정강이까지 덮는 용접용 **각반**이 있어요.","용접용 **각반**은 불티가 바짓단 안으로 들어가는 것도 막아 줘요."]},{"kind":"points","head":"머리부터 발까지 순서로 외워요","items":["안전모, **보호면**, **방진 마스크**, 안전 조끼, **안전대**, **각반**, **안전화** 순서예요.","위에서 아래로 내려오면서 짚으면 하나도 빠뜨리지 않아요.","**안전대**와 안전모는 높은 곳 작업에서 반드시 함께 착용하는 짝이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 장구 짝","items":["눈을 지키면 **보호면**, 코와 입을 지키면 **방진 마스크**예요.","발바닥과 발가락은 **안전화**, 발목과 바짓단은 **각반**이에요.","추락을 막는 것은 **안전대**이고, 머리는 안전모예요."]},{"kind":"check","q":"바지 하단이 걸리거나 끼임으로 인한 사고를 막기 위해 착용하는 것은?","choices":["각반","안전대","보호면","안전화"],"a":0,"why":"각반은 바짓단을 잡아 줘요. 용접용 각반은 불티 유입도 막아요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.2362],"c":[0,0.0208,0.2111,0.2682],"r":1.3993,"img":"img/L2/walk/p056_h.jpg"},"parts":[{"b":[0.03,0.275,0.43,0.05],"c":[0.0085,0.245,0.473,0.11],"r":7.6444,"img":"img/L2/walk/p056_22_01.jpg","say":"바지 하단이 걸리거나 끼임으로 생기는 사고를 막는다는 줄이에요."},{"b":[0.05,0.35,0.27,0.4],"c":[0.0365,0.33,0.297,0.44],"r":1.2,"img":"img/L2/walk/p056_22_02.jpg","say":"밴드형 **각반**이에요. 발목에 둘러 바짓단을 잡아 줘요."},{"b":[0.37,0.34,0.26,0.46],"c":[0.357,0.317,0.286,0.506],"r":1.0048,"img":"img/L2/walk/p056_22_03.jpg","say":"용접용 **각반**이에요. 정강이까지 덮어 불티가 들어가지 못하게 해요."}]}},{"p":57,"title":"안전관리 업무 기록","terms":["안전관리업무일지"],"pass1":[{"kind":"say","lines":["안전은 마음만으로 관리되지 않고 반드시 종이로 남겨요.","**안전관리업무일지**는 현장 안전을 날짜별로 적어 둔 일기장이에요.","사고가 났을 때 무엇을 했는지 보여 주는 증거가 돼요."]}],"pass2":[{"kind":"points","head":"안전관리 기록에는 무엇이 있나요","items":["**안전관리업무일지**, 안전관리비 사용내역서, 항목별 사용내역서가 있어요.","안전시설 관련 사용현황, 개인보호구 및 개인장구 현황도 기록으로 남겨요.","안전교육 및 행사비 관련 사용현황도 포함돼요."]},{"kind":"points","head":"**안전관리업무일지**에 무엇을 적나요","items":["공사 현장의 안전관리 업무에 관한 제반 사항을 일자별로 기록한 문서예요.","당일의 재해 방지를 위한 중점 사항과 안전활동의 세부 내용을 적어요.","안전점검 결과와 재해사고의 발생 현황을 명확하게 기록해요."]},{"kind":"points","head":"왜 적어 두나요","items":["안전관리의 목적은 작업 중 생길 수 있는 안전사고를 막아 작업자의 안전과 회사의 자산을 지키는 것이에요.","기록이 있어야 재해사고의 위험 요인을 미리 대비할 수 있어요.","재해가 나도 기록을 보고 빠르게 대책을 세울 수 있어요."]},{"kind":"bg","src":"슬라이드 그림 속 참고 자료","lines":["슬라이드 오른쪽 카드는 중대산업재해를 설명해요.","상시근로자 5인 이상 기업에서 1명 이상 사망, 2명 이상 부상, 3명 이상 직업성 질병이 생긴 재해예요.","상시근로자에는 일용 근로자, 단시간 기간제 근로자, 외국인 근로자도 포함돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"공사 현장의 안전관리 업무에 관한 제반 사항을 일자별로 기록한 문서는?","choices":["실행내역서","안전관리업무일지","준공내역서","착공계"],"a":1,"why":"안전관리업무일지에는 재해 방지 중점 사항, 안전활동 세부 내용, 안전점검 결과, 재해사고 발생 현황을 적어요."},{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"안전관리 기록에는 안전관리업무일지, 안전관리비 사용내역서, 항목별 사용내역서, 안전시설 관련 사용현황, 개인보호구 및 개인장구 현황, 안전교육 및 행사비 관련 사용현황이 있다.","ko":"일지 하나, 돈 관련 둘, 시설과 장구 둘, 교육 하나로 나눠서 외워요.","tip":"일지 → 돈 → 시설 → 장구 → 교육 순서로 떠올리면 여섯 가지가 다 나와요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1944],"c":[0,0.0208,0.2111,0.2264],"r":1.6576,"img":"img/L2/walk/p057_h.jpg"},"parts":[{"b":[0.03,0.235,0.8,0.09],"c":[0,0.1911,0.88,0.1778],"r":8.7989,"img":"img/L2/walk/p057_24_01.jpg","say":"안전관리 기록 여섯 가지가 두 줄로 나열돼요. 일지, 돈, 시설, 장구, 교육이에요."},{"b":[0.03,0.33,0.6,0.05],"c":[0.0,0.2883,0.66,0.1333],"r":8.8022,"img":"img/L2/walk/p057_24_02.jpg","say":"**안전관리업무일지**의 정의예요. 일자별로 기록한 문서라는 말이 핵심이에요."},{"b":[0.03,0.375,0.58,0.05],"c":[0.001,0.3356,0.638,0.1289],"r":8.7992,"img":"img/L2/walk/p057_24_03.jpg","say":"안전관리의 목적이에요. 작업자의 안전과 회사의 자산 보호예요."},{"b":[0.03,0.42,0.85,0.05],"c":[0,0.3505,0.935,0.1889],"r":8.7995,"img":"img/L2/walk/p057_24_04.jpg","say":"일지에 적을 것이에요. 재해 방지 중점 사항, 안전점검 결과, 재해사고 발생 현황이에요."},{"b":[0.38,0.52,0.18,0.44],"c":[0.368,0.498,0.204,0.484],"r":0.7493,"img":"img/L2/walk/p057_24_05.jpg","say":"중대산업재해 카드예요. 상시근로자 5인 이상 기업의 인명피해를 뜻해요."}]}},{"p":58,"title":"안전관리 서식 예시","terms":["안전관리업무일지"],"pass1":[{"kind":"say","lines":["이 쪽은 글 없이 서류 양식 세 장만 보여 주는 쪽이에요.","실제 현장에서 쓰는 종이가 어떻게 생겼는지 눈에 익히면 돼요."]}],"pass2":[{"kind":"points","head":"세 장이 각각 무엇인지만 봐 두세요","items":["왼쪽은 안전관리자 선임계예요. 누구를 안전관리자로 정했는지 알리는 서류예요.","가운데는 안전일지, 즉 **안전관리업무일지** 양식이에요. 안전지시, 안전점검, 교육, 홍보, 안전사고 칸이 있어요.","오른쪽은 안전관리비 사용내역서예요. 항목별로 얼마를 썼는지 적는 표예요.","**안전관리업무일지** 양식에 안전점검 칸이 따로 있다는 점만 기억해 두세요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1944],"c":[0,0.0208,0.2111,0.2264],"r":1.6576,"img":"img/L2/walk/p058_h.jpg"},"parts":[{"b":[0.07,0.235,0.29,0.69],"c":[0.0555,0.2005,0.319,0.759],"r":0.7472,"img":"img/L2/walk/p058_21_01.jpg","say":"안전관리자 선임계예요. 누구를 안전관리자로 정했는지 알리는 서류예요."},{"b":[0.36,0.235,0.29,0.69],"c":[0.3455,0.2005,0.319,0.759],"r":0.7472,"img":"img/L2/walk/p058_21_02.jpg","say":"안전일지, 즉 **안전관리업무일지** 양식이에요. 안전지시와 안전점검 칸이 따로 있어요."},{"b":[0.655,0.235,0.29,0.69],"c":[0.6405,0.2005,0.319,0.759],"r":0.7472,"img":"img/L2/walk/p058_21_03.jpg","say":"안전관리비 사용내역서예요. 항목별로 얼마를 썼는지 적어요."}]}},{"p":59,"title":"품질관리(QC)와 자재관리","terms":["QC","자재관리","전수검사","발췌검사"],"pass1":[{"kind":"say","lines":["**품질관리(QC)**는 약속한 만큼 잘 만들어졌는지 챙기는 일이에요.","식당으로 치면 맛과 위생을 계속 점검하는 것과 같아요.","**자재관리**는 그 재료가 상하지 않게 지키는 일이에요."]}],"pass2":[{"kind":"points","head":"**품질관리(QC)**가 무엇인가요","items":["수요자의 요구사항을 충족하도록 경제성과 합리적 생산 과정에 쓰는 운영기법이에요.","공간의 설계부터 재료의 구입, 제조, 검사, 보관, 시공 과정의 지도까지 넓혀 종합적으로 관리해요.","시공현장의 **품질관리(QC)**는 재료뿐 아니라 인력, 장비, 공법, 자금에도 적용해요."]},{"kind":"points","head":"목적, 향상, 효과","items":["목적은 발주자의 요구에 맞는 합리적, 경제적, 내구적, 심미적 공간을 만드는 것이에요.","향상은 공사 품질의 신뢰성 확보와 생산 활동의 안정화, 품질과 원가의 최적 균형 유지예요.","효과는 시공 완성도 향상, 시공 불량 및 하자 감소, 원가절감, 시공의 효율성 증대, 품질의 균일화, 기업 신뢰성 증진이에요."]},{"kind":"points","head":"**자재관리**는 무슨 일을 하나요","items":["**자재관리**는 **품질관리(QC)**의 일환으로 기자재와 공사 목적물의 보존관리를 위해 해요.","기자재의 운반, 반입 및 반출방법에 필요한 취급방법을 정해요.","기자재의 품질유지를 위한 보관 장소와 보관방법, 시공된 공사 목적물의 품질보호 방안, 화재 및 보안관리를 포함해요."]},{"kind":"compare","head":"자재 품질검사의 두 방법","cols":["방법","무엇을 검사하나"],"rows":[["**전수검사**","제품 모두를 검사해요"],["**발췌검사**","제품의 일부 샘플을 선정해 검사해요"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"인테리어공사 **품질관리(QC)**의 목적으로 슬라이드가 든 네 가지는?","choices":["빠른, 싼, 예쁜, 튼튼한","합리적, 경제적, 내구적, 심미적","공정, 품질, 안전, 원가","시기, 내용, 수량, 인력"],"a":1,"why":"발주자의 요구에 맞는 합리적, 경제적, 내구적, 심미적 공간을 만드는 것이 목적이에요."},{"kind":"check","q":"자재의 품질검사 방법 중 제품의 일부 샘플만 뽑아 검사하는 것은?","choices":["전수검사","발췌검사","준공검사","정기점검"],"a":1,"why":"전수검사는 전부, 발췌검사는 일부 샘플이에요."},{"kind":"english","head":"서술형으로 외워 쓰기","en":"품질관리(QC)의 효과는 시공 완성도 향상, 시공 불량 및 하자 감소, 원가절감, 시공의 효율성 증대, 품질의 균일화, 기업 신뢰성 증진이다.","ko":"완성도는 올라가고 하자와 원가는 내려가며, 효율과 균일성, 신뢰가 올라가요.","tip":"올라가는 것 넷(완성도, 효율, 균일화, 신뢰), 내려가는 것 둘(하자, 원가)로 나눠 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1412],"c":[0,0.0208,0.2111,0.1732],"r":2.1668,"img":"img/L2/walk/p059_h.jpg"},"parts":[{"b":[0.02,0.18,0.72,0.05],"c":[0,0.125,0.792,0.16],"r":8.8,"img":"img/L2/walk/p059_24_01.jpg","say":"**품질관리(QC)**의 정의예요. 경제성과 합리적 생산 과정에 쓰는 운영기법이에요."},{"b":[0.02,0.275,0.7,0.05],"c":[0,0.2222,0.77,0.1556],"r":8.7975,"img":"img/L2/walk/p059_24_02.jpg","say":"목적 네 가지예요. 합리적, 경제적, 내구적, 심미적 공간이에요."},{"b":[0.03,0.58,0.31,0.17],"c":[0.0145,0.564,0.341,0.202],"r":3.0011,"img":"img/L2/walk/p059_24_03.jpg","say":"**자재관리** 업무 네 가지 상자예요. 취급방법, 보관, 품질보호, 화재와 보안이에요."},{"b":[0.02,0.81,0.63,0.05],"c":[0,0.765,0.693,0.14],"r":8.8,"img":"img/L2/walk/p059_24_04.jpg","say":"**전수검사**와 **발췌검사**가 나오는 줄이에요."}]}},{"p":60,"title":"자재관리 1) 반입 2) 양중 3) 저장","terms":["자재관리","대운반","소운반","양중"],"pass1":[{"kind":"say","lines":["자재는 현장에 와서 세 걸음을 거쳐요.","도착하고(반입), 쓸 자리에 올려놓고(**양중**), 당장 안 쓰면 보관해요(저장).","택배가 집에 오고, 방에 옮기고, 서랍에 넣는 것과 똑같아요."]},{"kind":"compare","head":"세 걸음을 한눈에","cols":["단계","쉬운 말"],"rows":[["반입","현장까지 도착"],["**양중**","쓸 자리에 올려 적재"],["저장","당장 안 쓰면 보관"]]}],"pass2":[{"kind":"steps","head":"**자재관리**의 세 단계","steps":["반입: 공사를 위한 자재와 제품을 외부에서 현장의 필요한 장소까지 도착시켜요.","**양중**: 공사에 필요한 자재들을 원하는 위치에 적재해요.","저장: 즉시 쓰지 않는 자재를 작업 현장 이외의 별도 장소에 보관해요."],"answer":"반입 → **양중** → 저장 순서예요."},{"kind":"compare","head":"**대운반**과 **소운반**의 구별","cols":["구분","무엇으로","거리"],"rows":[["**대운반**","트럭으로 배달받거나 폐자재를 반출","현장 밖과 현장 사이"],["**소운반**","인력이나 간단한 도구","수평거리 20m 이내"]]},{"kind":"points","head":"**양중**할 때 지킬 것","items":["현장에서 쓸 자재는 파손되지 않도록 정리 정돈해요.","**양중**하는 자재는 작업 공정의 순서에 따라 순차적으로 현장에 반입해요.","**양중**된 자재는 쉽게 쓸 수 있는 위치에 두되 작업에 방해가 되지 않게 해요.","운반 방법은 현장 상황에 따라 인력 운반, 사다리차, 리프트를 써요."]},{"kind":"points","head":"저장의 규칙","items":["반입 순서대로 쓸 수 있도록 저장해요.","먼지, 흙이 묻지 않게 하고 지면에 직접 닿지 않도록 고임목이나 파레트를 써요.","직사광선과 습기가 없고 통풍이 잘 되게 해요. 단 시멘트는 외기 유입이 되지 않는 장소에 보관해요.","화기에서 격리하고, 화재 원인이 될 수 있는 재료는 방화구조의 창고에 보관해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"자재 반입에서 **소운반**의 기준 거리는?","choices":["수평거리 20m 이내","수직거리 20m 이내","수평거리 50m 이내","수평거리 100m 이내"],"a":0,"why":"소운반은 수평거리 20m 이내의 자재 이동으로 주로 인력이나 간단한 도구로 해요. 대운반은 트럭이에요."},{"kind":"check","q":"자재 저장 방법으로 옳지 않은 것은?","choices":["화재 원인이 될 수 있는 재료는 방화구조 창고에 보관한다","반입 순서대로 사용할 수 있도록 저장한다","고임목이나 파레트로 지면에 닿지 않게 한다","시멘트는 통풍이 잘 되도록 외기가 유입되는 곳에 둔다"],"a":3,"why":"시멘트는 외기 유입이 되지 않는 장소에 보관해요. 공기 중 습기를 만나면 수화반응으로 굳기 시작해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["시멘트만 예외예요. 다른 자재는 통풍, 시멘트는 외기 차단이에요.","유성 페인트, 신나, 휘발유는 화재 위험 재료라 방화구조 창고에 넣어요.","장마철 원목은 습기를 먹으니 사용 전에 검사나 시험을 하고 써요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1412],"c":[0,0.0208,0.2111,0.1732],"r":2.1668,"img":"img/L2/walk/p060_h.jpg"},"parts":[{"b":[0.02,0.18,0.6,0.22],"c":[0,0.164,0.66,0.252],"r":4.6561,"img":"img/L2/walk/p060_24_01.jpg","say":"1) 반입이에요. **대운반**은 트럭, **소운반**은 수평거리 20m 이내예요."},{"b":[0.02,0.41,0.6,0.22],"c":[0,0.394,0.66,0.252],"r":4.6561,"img":"img/L2/walk/p060_24_02.jpg","say":"2) **양중**이에요. 원하는 위치에 적재하고 공정 순서대로 반입해요."},{"b":[0.02,0.66,0.62,0.28],"c":[0,0.644,0.682,0.312],"r":3.886,"img":"img/L2/walk/p060_24_03.jpg","say":"3) 저장이에요. 시멘트와 유성 페인트 주의 문구가 빨간 글씨로 붙어 있어요."}]}},{"p":61,"title":"준공 1) 준공청소 2) 준공정산","terms":["준공청소","준공정산","준공도면","준공검사","유지관리 계획"],"pass1":[{"kind":"say","lines":["드디어 공사가 끝났어요. 이제 손님에게 열쇠를 건네는 단계예요.","먼저 깨끗이 치우고(**준공청소**), 돈 계산을 맞춰요(**준공정산**).","준공은 공사를 완료하고 시설물을 인도하는 과정이에요."]}],"pass2":[{"kind":"steps","head":"준공의 네 단계","steps":["**준공청소**: 현장을 정리하고 사용자가 불편 없이 쓰도록 청소해요.","**준공정산**: 공사의 경과와 바뀐 공사비를 정리해요.","**준공검사**: 시공 결과가 설계도서와 기준에 맞는지 확인해요.","**유지관리 계획**: 준공 뒤 시설물을 어떻게 지킬지 계획해요."],"answer":"**준공청소** → **준공정산** → **준공검사** → **유지관리 계획**"},{"kind":"points","head":"**준공청소**의 정체","items":["모든 공사가 완료되면 현장을 정리하고 사용자가 입주해 쓰는 데 불편이 없도록 청소하는 것이에요.","조력공을 동원해 하는 것이 일반적이에요.","대형 현장이거나 세심한 관리가 필요하면 청소를 전문으로 하는 업체에 의뢰하기도 해요.","슬라이드 위쪽 띠는 준공상태 최종 점검 → 공사 완료를 발주처에 알리기 → 공사 후 관리 계획 순서예요."]},{"kind":"points","head":"**준공정산**과 두 가지 서류","items":["**준공정산**은 준공 후 공사의 경과를 정리하는 과정이에요.","준공내역서는 설계 변경, 현장 상황 변화, 물가 변동으로 공사비가 바뀐 경우 계약금액을 정산하려고 만들어요.","준공내역서는 계약 당시 공사비 내역서를 기준으로 작성해요.","수정부위, 변경, 수정사항을 포함한 최종 시공 결과 도면이 **준공도면**이고, 추후 시설의 유지, 보수에 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"공사 중 변경사항을 반영한 최종 시공 결과 도면으로 추후 유지, 보수에 쓰는 것은?","choices":["먹도면","실시설계도","준공도면","상세도"],"a":2,"why":"준공정산 때 준공내역서와 함께 최종 시공 결과를 준공도면으로 작성해요."},{"kind":"english","head":"준공 순서 외워 쓰기","en":"준공은 준공청소, 준공정산, 준공검사, 유지관리 계획의 순서로 진행한다.","ko":"청소로 치우고, 정산으로 돈을 맞추고, 검사로 확인받고, 계획으로 넘겨줘요.","tip":"청소 → 정산 → 검사 → 계획. 치우고 계산하고 합격받고 넘긴다고 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2698,0.1527],"c":[0,0.0208,0.2968,0.1847],"r":2.8568,"img":"img/L2/walk/p061_h.jpg"},"parts":[{"b":[0.03,0.195,0.44,0.05],"c":[0.008,0.165,0.484,0.11],"r":7.8222,"img":"img/L2/walk/p061_23_01.jpg","say":"준공상태 최종 점검 → 발주처에 알리기 → 공사 후 관리 계획 순서 띠예요."},{"b":[0.03,0.305,0.73,0.09],"c":[0,0.2689,0.803,0.1622],"r":8.8012,"img":"img/L2/walk/p061_23_02.jpg","say":"**준공청소** 두 줄이에요. 조력공이 일반적이고 대형 현장은 전문 업체에 맡겨요."},{"b":[0.03,0.42,0.93,0.25],"c":[0,0.404,1,0.282],"r":6.3042,"img":"img/L2/walk/p061_23_03.jpg","say":"청소 장비와 청소 작업 사진이에요. 물청소 기계와 사다리 작업이 보여요."},{"b":[0.03,0.8,0.73,0.05],"c":[0,0.7439,0.803,0.1622],"r":8.8012,"img":"img/L2/walk/p061_23_04.jpg","say":"준공내역서 줄이에요. 공사비가 바뀐 경우 계약금액 정산을 위해 만들어요."},{"b":[0.03,0.895,0.8,0.05],"c":[0,0.8222,0.88,0.1778],"r":8.7989,"img":"img/L2/walk/p061_23_05.jpg","say":"**준공도면** 줄이에요. 최종 시공 결과 도면이고 유지, 보수에 써요."}]}},{"p":62,"title":"준공 3) 준공검사 4) 유지관리 계획","terms":["준공검사","유지관리 계획","준공도면","준공정산"],"pass1":[{"kind":"say","lines":["**준공검사**는 공사의 마지막 시험이에요.","설계도서와 계약조건대로 다 됐는지 확인해서 합격 도장을 받아요.","합격한 다음에는 앞으로 어떻게 관리할지 **유지관리 계획**을 세워요."]}],"pass2":[{"kind":"points","head":"**준공검사**의 정의","items":["공사 완료 후 시공 결과가 설계도서, 계약조건 및 관련 기준에 적합하게 완료되었는지 확인하는 검사예요.","이 검사로 공사의 완료 여부를 판단해요.","**준공검사**는 **준공정산** 다음, **유지관리 계획** 앞에 오는 단계예요."]},{"kind":"compare","head":"**준공검사** 확인사항과 제출서류","cols":["주요 확인사항 7","주요 제출서류 7"],"rows":[["인허가 및 승인조건의 이행 여부","준공계 및 준공검사원"],["관계 법규 및 관련 기준의 준수 여부","준공도서 (최종 도면)"],["설계도서 및 계약조건에 따른 시공 여부","준공사진 및 공사사진"],["시공상태 및 품질의 적정성","주요 자재 관련서류"],["미시공, 미완료 또는 하자 사항의 유무","안전관리 관련서류"],["안전 관련 사항","폐기물 처리 관련서류"],["환경 및 폐기물 처리 관련 사항","기타 발주처가 요구하는 서류"]]},{"kind":"points","head":"**유지관리 계획**은 왜 세우나요","items":["공사 완료 후 시설물의 기능과 성능을 적정하게 유지하고 수명을 연장하며 재산가치를 보존하려고 세워요.","기능 저하와 사고를 예방하고 이상 징후를 조기에 발견해 점검과 보수가 이뤄지게 해요.","비상상황에서 관리 담당자의 참고자료가 되고, 관리인력이 바뀔 때 인수인계에 써요.","하자보수 기간 이후에도 점검, 보수, 교체 자료로 쓰고, 준공 시 관련 자료를 관리주체에 인계해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**준공검사**의 주요 제출서류가 아닌 것은?","choices":["준공계 및 준공검사원","준공도서","입찰보증금 납부서","폐기물 처리 관련서류"],"a":2,"why":"입찰보증금은 입찰 단계의 서류예요. 준공 제출서류는 준공계와 준공검사원, 준공도서, 준공사진, 주요 자재, 안전관리, 폐기물, 기타 발주처 요구 서류예요."},{"kind":"english","head":"서술형으로 외워 쓰기","en":"유지관리 계획은 공사 완료 후 시설물의 기능과 성능을 유지하고 수명을 연장하며 재산가치를 보존하기 위한 계획으로, 사고 예방과 조기 발견, 비상상황 참고, 업무 인수인계, 하자보수 기간 이후의 지속 관리에 활용한다.","ko":"지키고(기능), 늘리고(수명), 보존하고(재산가치) 세 가지가 목적이에요.","tip":"기능, 수명, 재산가치 세 낱말만 잡으면 첫 문장이 나와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["제출서류와 절차는 발주처, 계약조건, 공사의 종류와 규모에 따라 달라질 수 있다고 슬라이드가 밝혀 두었어요.","**준공도면**과 준공도서는 이름이 비슷해요. 준공도서는 **준공검사** 제출서류의 이름이에요.","준공사진은 추후 문제가 생길 경우 매우 중요한 근거가 된다고 슬라이드가 강조해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.7001,0.1921],"c":[0,0.0208,0.7701,0.2241],"r":6.1092,"img":"img/L2/walk/p062_h.jpg"},"parts":[{"b":[0.04,0.24,0.21,0.33],"c":[0.028,0.2235,0.234,0.363],"r":1.146,"img":"img/L2/walk/p062_23_01.jpg","say":"왼쪽 상자가 **준공검사**의 주요 확인사항 일곱 가지예요."},{"b":[0.26,0.24,0.4,0.37],"c":[0.24,0.2215,0.44,0.407],"r":1.9219,"img":"img/L2/walk/p062_23_02.jpg","say":"오른쪽 상자가 주요 제출서류예요. 준공도서 옆에 최종 도면, 준공사진 옆에 중요한 근거라는 메모가 있어요."},{"b":[0.02,0.65,0.6,0.28],"c":[0,0.634,0.66,0.312],"r":3.7607,"img":"img/L2/walk/p062_23_03.jpg","say":"아래는 **유지관리 계획** 문단이에요. 수명 연장과 재산가치 보존이 핵심이에요."}]}},{"p":63,"title":"준공 서식 예시","terms":["준공검사"],"pass1":[{"kind":"say","lines":["이 쪽도 서류 양식 세 장만 있는 쪽이에요.","**준공검사** 때 실제로 내는 종이의 모습을 눈에 담아 두면 돼요."]}],"pass2":[{"kind":"points","head":"세 장이 각각 무엇인가요","items":["왼쪽은 준공검사원이에요. 감리원을 경유한다는 칸이 위에 있어요.","가운데와 오른쪽은 준공계 양식 두 가지예요. 공사명, 계약금액, 준공금액, 착공년월일, 준공기한을 적어요.","세 장 모두 **준공검사** 단계에서 발주처에 내는 서류예요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.1871,0.1479],"c":[0,0.0208,0.2111,0.1799],"r":2.0861,"img":"img/L2/walk/p063_h.jpg"},"parts":[{"b":[0.05,0.19,0.29,0.72],"c":[0.0355,0.154,0.319,0.792],"r":0.716,"img":"img/L2/walk/p063_21_01.jpg","say":"준공검사원이에요. 위쪽에 감리원 경유 칸이 있어요."},{"b":[0.35,0.19,0.29,0.72],"c":[0.3355,0.154,0.319,0.792],"r":0.716,"img":"img/L2/walk/p063_21_02.jpg","say":"준공계 양식 예시1이에요. 계약금액과 준공금액, 착공년월일을 적어요."},{"b":[0.655,0.19,0.3,0.72],"c":[0.64,0.154,0.33,0.792],"r":0.7407,"img":"img/L2/walk/p063_21_03.jpg","say":"준공계 양식 예시2예요. 같은 내용을 표 형태로 적는 양식이에요."}]}},{"p":64,"title":"#2 가설공사 표지","terms":["가설공사"],"pass1":[{"kind":"say","lines":["여기부터 2강의 두 번째 덩어리, #2 **가설공사**예요.","앞에서는 사람과 계약과 관리를 배웠고, 이제 현장에서 몸으로 하는 일이 시작돼요.","현장 작업 순서는 가설 → 철거 → 경량철골 → 마감이에요."]}],"pass2":[{"kind":"points","head":"이 덩어리에서 배울 것","items":["**가설공사**의 뜻과 가설재의 구분을 먼저 배워요.","그다음 먹매김, 비계 다섯 종류, 가설 전기, 보양, 현장사무실, 공사장 가림막이 이어져요.","표지 아래의 참고문헌은 인테리어 디자인 시공 실무, 실내건축재료, 실내건축실무, 다시 인테리어 도면 이해하기예요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.0,0.0,0.49,0.99],"c":[0,0,0.539,1],"r":0.9582,"img":"img/L2/walk/p064_21_01.jpg","say":"표지 사진이 바로 비계예요. 구멍 뚫린 발판과 클램프가 보여요."},{"b":[0.52,0.53,0.11,0.06],"c":[0.475,0.505,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p064_21_02.jpg","say":"#2 **가설공사**예요. 여기부터 두 번째 덩어리가 시작돼요."},{"b":[0.73,0.845,0.26,0.12],"c":[0.714,0.829,0.286,0.152],"r":3.345,"img":"img/L2/walk/p064_21_03.jpg","say":"참고문헌 네 권이에요. #3 철거공사 표지에도 같은 목록이 나와요."}]}},{"p":65,"title":"가설공사의 뜻과 가설재의 구분","terms":["가설공사","가설재","비계","현장소장"],"pass1":[{"kind":"analogy","head":"**가설공사**는 공사를 위한 공사예요","scene":"연극 무대를 생각해 보세요. 무대 뒤에는 배우가 올라설 발판, 조명 줄, 분장실이 있어요. 공연이 끝나면 그것들은 전부 걷어 내요. 관객에게 남는 것은 무대 위 장면뿐이에요.","map":[["무대 뒤 발판과 조명 줄","**비계**, 가설전기 같은 **가설재**"],["분장실과 대기실","가설사무실, 가설창고"],["공연이 끝나면 걷어 냄","본 공사가 끝나면 철거"],["관객에게 남는 무대 장면","완성된 실내 공간"]]}],"pass2":[{"kind":"points","head":"**가설공사**의 정의","items":["본 공사를 시공하기 위한 준비과정의 공사로, 본 공사가 완료된 후에는 철거하는 것을 전제로 해요.","공사의 수행과 운영 및 지원을 위한 공사예요.","공사의 규모에 따라 달라지고, 설계도에는 일반적으로 표시되지 않아요.","시방서에 간단한 지시만 있으며 **현장소장**의 책임하에 실시돼요."]},{"kind":"compare","head":"**가설재**의 두 갈래","cols":["구분","무엇을 위한 것","예"],"rows":[["직접 공사성 **가설재**","공사 수행을 위한 가설 시설","단관파이프 **비계**, 조립식 **비계**, 안전발판, 이동식 테이블 리프트, 브라켓, 안전 난간대, 가설전기시설재, 보양재"],["간접 공사성 **가설재**","운영 관리상 필요한 시설","가설 사무실, 공사 안전 시설재, 안전 장구"]]},{"kind":"points","head":"슬라이드가 든 가설 시설 목록","items":["공사 수행에 필요한 것: **비계** 설치, 낙하물 방지망, 가설전기 등이에요.","운영 관리에 필요한 것: 가설사무소, 가설창고, 가설작업장, 가설화장실, 휘장막, 가설칸막이 등이에요.","두 목록을 합치면 **가설공사**가 무엇을 다루는지 한눈에 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**가설공사**에 대한 설명으로 옳지 않은 것은?","choices":["공사 규모에 따라 달라진다","시방서에 간단한 지시만 있다","설계도에 상세히 표시되며 설계자 책임하에 실시된다","본 공사 완료 후 철거하는 것을 전제로 한다"],"a":2,"why":"가설공사는 설계도에 일반적으로 표시되지 않고 현장소장의 책임하에 실시돼요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["설계도 표시 여부와 책임자를 바꿔 내는 문제가 많아요. 표시 안 됨, **현장소장** 책임이에요.","안전 장구는 직접이 아니라 간접 공사성 **가설재**예요.","보양재는 간접이 아니라 직접 공사성 **가설재**예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.6992,0.2899],"c":[0,0.0208,0.7691,0.3219],"r":4.2476,"img":"img/L2/walk/p065_h.jpg"},"parts":[{"b":[0.22,0.58,0.08,0.06],"c":[0.16,0.555,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p065_23_01.jpg","say":"맨 왼쪽이 **가설재**예요. 여기서 두 갈래로 갈라져요."},{"b":[0.33,0.51,0.14,0.06],"c":[0.3,0.485,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p065_23_02.jpg","say":"위쪽 갈래가 직접 공사성 **가설재**, 공사 수행을 위한 가설 시설이에요."},{"b":[0.49,0.46,0.24,0.16],"c":[0.478,0.444,0.264,0.192],"r":2.4444,"img":"img/L2/walk/p065_23_03.jpg","say":"직접 공사성 **가설재**의 목록 상자예요. **비계**부터 보양재까지 일곱 가지가 적혀 있어요."},{"b":[0.33,0.67,0.14,0.06],"c":[0.3,0.645,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p065_23_04.jpg","say":"아래 갈래가 간접 공사성 **가설재**, 운영 관리상 필요한 시설이에요."},{"b":[0.49,0.67,0.23,0.06],"c":[0.478,0.645,0.254,0.11],"r":4.1051,"img":"img/L2/walk/p065_23_05.jpg","say":"간접 공사성 **가설재**는 가설 사무실, 공사 안전 시설재, 안전 장구 셋이에요."}]}},{"p":66,"title":"가설공사의 내용 1) 먹매김","terms":["먹매김","현장소장","가설공사"],"pass1":[{"kind":"analogy","head":"**먹매김**은 바닥에 그리는 실물 크기 도면이에요","scene":"종이에 그린 집 도면을 그대로 바닥에 1:1 크기로 베껴 그린다고 생각해 보세요. 벽이 설 자리, 문이 들어갈 자리가 바닥에 선으로 그려져요. 목수는 그 선만 보고 뼈대를 세워요.","map":[["종이 도면","설계도서"],["바닥에 그린 실물 크기 선","**먹매김**"],["선을 그리는 사람들","설계자, **현장소장**, 목수"],["선을 보고 세우는 뼈대","벽체와 칸막이 공사"]]}],"pass2":[{"kind":"points","head":"**먹매김**의 정의와 숫자","items":["설계도서의 치수에 준하여 현장에 1:1 스케일로 도면을 옮겨 그리는 과정이에요.","높이의 기준으로 벽면에 1m 높이에 수평으로 기준먹을 놓아요.","**먹매김**은 **가설공사**의 첫 작업이고, 그다음에 벽체와 칸막이 뼈대가 서요."]},{"kind":"points","head":"누가 하고 무엇을 준비하나요","items":["**먹매김** 작업에는 설계자, **현장소장** 및 목수가 참여해요.","설계자는 **먹매김**을 위해 먹도면을 준비해요.","설계도서에 적히지 않은 치수는 설계자와 감리자 또는 **현장소장**의 지시에 따라요."]},{"kind":"points","head":"슬라이드 사진에서 무엇을 보나요","items":["기준 먹의 표시 사례, 높이의 기준이 되는 수평먹, 문틀 표시가 있어요.","등구멍 위치의 먹매김, 천장에 구조물의 바닥 먹, 마감선까지 표시한 먹매김도 있어요.","오른쪽 큰 도면이 치수가 잔뜩 적힌 먹도면이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**먹매김**에 대한 설명으로 옳은 것은?","choices":["시공자만 참여한다","벽면 1m 높이에 수평으로 기준먹을 놓는다","감리자가 먹도면을 준비한다","도면을 1:50 스케일로 옮겨 그린다"],"a":1,"why":"먹매김은 1:1 스케일이고 설계자, 현장소장, 목수가 참여하며 설계자가 먹도면을 준비해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["참여자 셋을 꼭 외워요. 설계자, **현장소장**, 목수예요. 감리자가 아니에요.","먹도면을 준비하는 사람은 설계자예요.","스케일은 1:1, 기준먹 높이는 1m. 이 두 숫자가 그대로 나와요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.185,0.42,0.045],"c":[0.009,0.1525,0.462,0.11],"r":7.4667,"img":"img/L2/walk/p066_23_01.jpg","say":"**먹매김**의 정의예요. 현장에 1:1 스케일로 도면을 옮겨 그려요."},{"b":[0.03,0.23,0.36,0.045],"c":[0.012,0.1975,0.396,0.11],"r":6.4,"img":"img/L2/walk/p066_23_02.jpg","say":"참여자 세 사람이에요. 설계자, **현장소장** 및 목수예요."},{"b":[0.03,0.275,0.36,0.045],"c":[0.012,0.2425,0.396,0.11],"r":6.4,"img":"img/L2/walk/p066_23_03.jpg","say":"높이 기준이에요. 벽면 1m 높이에 수평으로 기준먹을 놓아요."},{"b":[0.03,0.415,0.27,0.045],"c":[0.0165,0.3825,0.297,0.11],"r":4.8,"img":"img/L2/walk/p066_23_04.jpg","say":"설계자가 먹도면을 준비한다는 줄이에요."},{"b":[0.46,0.02,0.53,0.65],"c":[0.417,0,0.583,0.715],"r":1.4496,"img":"img/L2/walk/p066_23_05.jpg","say":"오른쪽 큰 도면이 먹도면이에요. 치수가 빼곡하게 적혀 있어요."}]}},{"p":67,"title":"2) 비계의 뜻과 네 가지 종류","terms":["비계","강관비계","안전 발판"],"pass1":[{"kind":"analogy","head":"**비계**는 공사판의 임시 계단이에요","scene":"천장에 조명을 다는데 키가 닿지 않아요. 의자 하나로는 위험하고 오래 못 해요. 그래서 튼튼한 뼈대를 세우고 그 위에 발판을 깔아 사람이 올라서서 일하게 만들어요.","map":[["임시로 세운 뼈대와 발판","**비계**"],["올라서서 일하는 자리","작업 발판"],["일이 끝나면 걷어 냄","가설공사의 성질"]]},{"kind":"say","lines":["**비계**는 한자로 날 비(飛)에 계단 계(階)를 써요.","공중에 만든 계단이라는 뜻이에요."]}],"pass2":[{"kind":"points","head":"**비계**의 정의","items":["건물의 내부, 외부의 벽면이나 천장 등 높은 장소의 작업을 위하여 설치하는 임시시설물이에요.","장시간 작업이 예정되고 자재의 양이 많을 경우에는 **비계**의 설치가 필수적이에요.","**비계**는 가설공사의 대표 가설재라서 시험에 가장 많이 나와요."]},{"kind":"compare","head":"**비계** 네 가지 종류","cols":["종류","구조"],"rows":[["**강관**(단관)**비계**","파이프와 클램프로 연결하여 사용하는 구조"],["시스템 **비계**","규격화된 부재를 전용 연결방식으로 조립하는 구조"],["조립식 **비계** (이동틀**비계**)","간단한 조립식이며, 바퀴를 달아 이동 가능"],["말**비계**","낮은 높이의 실내 작업에 사용하는 간단한 작업발판 구조"]]},{"kind":"points","head":"설치 시 기본 안전 사항 네 가지","items":["작업장소에 적합한 높이와 충분한 작업공간을 확보하고 작업발판을 설치할 것.","작업자의 추락과 재료, 공구 등의 낙하를 방지할 수 있도록 안전시설을 설치할 것.","작업하중을 충분히 지지할 수 있는 강도를 확보하고 흔들림, 전도 등에 대한 안정성을 확보할 것.","작업자의 통행에 지장을 주지 않도록 설치하고 안전한 승강 및 이동통로를 확보할 것."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"규격화된 부재를 전용 연결방식으로 조립하는 **비계**는?","choices":["강관비계","시스템 비계","조립식 비계","말비계"],"a":1,"why":"시스템 비계는 별도 클램프 없이 일체형으로 조립해요. 강관비계는 파이프와 클램프예요."},{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"비계의 종류에는 강관(단관)비계, 시스템비계, 조립식(이동틀)비계, 말비계가 있으며, 여기에 시저 리프트를 더해 쓰기도 한다.","ko":"네 가지에 장비 하나를 더해 넷 더하기 하나로 외워요.","tip":"강관, 시스템, 조립식, 말. 그리고 리프트 하나."}],"walk":{"head":{"b":[0.0092,0.0368,0.5142,0.2346],"c":[0,0.0208,0.5657,0.2666],"r":3.7723,"img":"img/L2/walk/p067_h.jpg"},"parts":[{"b":[0.13,0.31,0.11,0.05],"c":[0.085,0.28,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p067_23_01.jpg","say":"**강관비계**, 즉 단관**비계**예요. 파이프와 클램프로 이어요."},{"b":[0.13,0.39,0.09,0.05],"c":[0.075,0.36,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p067_23_02.jpg","say":"시스템 **비계**예요. 규격화된 부재를 전용 연결방식으로 조립해요."},{"b":[0.13,0.47,0.17,0.05],"c":[0.115,0.44,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p067_23_03.jpg","say":"조립식 **비계**, 이동틀**비계**예요. 바퀴가 달려 움직여요."},{"b":[0.13,0.55,0.06,0.05],"c":[0.06,0.52,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p067_23_04.jpg","say":"말**비계**예요. 낮은 높이의 실내 작업용이에요."}]}},{"p":68,"title":"(1) 강관 비계의 특징과 클램프","terms":["강관비계","비계","클램프"],"pass1":[{"kind":"say","lines":["**강관비계**는 쇠 파이프를 조임 철물로 이어 만든 **비계**예요.","레고처럼 파이프 하나하나를 **클램프**로 물려서 원하는 모양을 만들어요.","그래서 자유롭지만 사람 손을 많이 타요."]}],"pass2":[{"kind":"points","head":"**강관비계**의 특징","items":["강관을 **클램프** 등의 연결철물로 결합하여 설치해요.","설치 장소와 구조물의 형태에 따라 높이와 폭을 조절하여 설치할 수 있어요.","조립, 해체 및 부재의 반복 사용이 가능하며 운반과 보관이 비교적 쉬워요.","현장 조건에 유연하게 대응할 수 있으나, 부재를 개별적으로 연결하므로 설치 시 숙련도와 안전관리가 중요해요."]},{"kind":"points","head":"꼭 외울 숫자","items":["**강관비계**는 일반적으로 외경 약 48.6mm의 강관을 사용해요.","48.6mm는 **강관비계** 하면 바로 따라 나오는 숫자예요.","단관**비계**라는 다른 이름도 같이 외워 두세요."]},{"kind":"points","head":"부속품 1: **클램프**(커플러)","items":["**클램프**는 강관과 강관을 연결하는 조임 철물이에요. 커플러라고도 불러요.","고정 **클램프**는 직각으로 고정된 형태라 각도가 바뀌지 않아요.","회전 **클램프**는 가운데가 돌아가서 가새처럼 비스듬한 부재를 물릴 수 있어요.","이형 **클램프**는 서로 다른 굵기나 모양의 부재를 잇는 데 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**강관비계**에 일반적으로 사용하는 강관의 외경은?","choices":["38.1mm","48.6mm","60.5mm","101.6mm"],"a":1,"why":"강관 비계는 일반적으로 외경 약 48.6mm의 강관을 사용해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**클램프**와 커플러는 같은 물건의 두 이름이에요.","고정, 회전, 이형 세 가지 **클램프** 이름을 바꿔 내는 문제가 나와요.","**강관비계**는 파이프 더하기 **클램프**, 시스템 **비계**는 **클램프** 없는 일체형이에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.5541,0.4512],"c":[0,0.0143,0.6096,0.4963],"r":2.1836,"img":"img/L2/walk/p068_h.jpg"},"parts":[{"b":[0.02,0.49,0.3,0.05],"c":[0.005,0.46,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p068_23_01.jpg","say":"외경 약 48.6mm 강관을 사용한다는 줄이에요. 시험에 그대로 나와요."},{"b":[0.01,0.66,0.34,0.25],"c":[0,0.644,0.374,0.282],"r":2.3578,"img":"img/L2/walk/p068_23_02.jpg","say":"고정 **클램프** 사진이에요. 직각으로 고정돼요."},{"b":[0.36,0.66,0.32,0.25],"c":[0.344,0.644,0.352,0.282],"r":2.2191,"img":"img/L2/walk/p068_23_03.jpg","say":"회전 **클램프**예요. 가운데가 돌아가 비스듬한 부재를 물려요."},{"b":[0.69,0.66,0.3,0.25],"c":[0.67,0.644,0.33,0.282],"r":2.0804,"img":"img/L2/walk/p068_23_04.jpg","say":"이형 **클램프**예요. 모양이 다른 부재를 이어요."}]}},{"p":69,"title":"(1) 강관 비계의 부속품: 연결핀, 받침대","terms":["강관비계","클램프","비계"],"pass1":[{"kind":"say","lines":["파이프가 짧으면 이어 붙이고, 땅이 물렁하면 발을 받쳐 줘야 해요.","이어 붙이는 것이 연결핀, 발을 받치는 것이 받침대예요.","**강관비계**는 이런 작은 부속품들이 모여 완성돼요."]}],"pass2":[{"kind":"points","head":"부속품 2: 연결핀","items":["연결핀은 강관의 길이를 연장할 때 사용하는 연결 철물이에요.","파이프 속에 끼워 넣어 두 강관을 한 줄로 이어 줘요.","옆으로 잇는 것은 **클램프**, 길게 잇는 것은 연결핀이라고 구별해요."]},{"kind":"points","head":"부속품 3: 받침대","items":["받침대는 **비계** 기둥의 밑면에 미끄럼 방지 및 침하 방지를 위해 설치해요.","바닥 면이 수평인 곳에 사용해요.","**비계** 받침대 밑에는 받침목이나 받침 철물을 쓰라고 슬라이드가 강조해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**비계** 기둥의 밑면에 미끄럼 방지와 침하 방지를 위해 설치하며 바닥이 수평인 곳에 쓰는 부속품은?","choices":["연결핀","받침대","브라켓","클램프"],"a":1,"why":"받침대는 기둥 밑을 받쳐요. 밑에 받침목이나 받침 철물을 덧대요. 연결핀은 강관을 길게 잇는 철물이에요."}],"walk":{"head":{"b":[0.0092,0.0368,0.5421,0.1012],"c":[0,0.0208,0.5963,0.1332],"r":7.9586,"img":"img/L2/walk/p069_h.jpg"},"parts":[{"b":[0.56,0.14,0.1,0.05],"c":[0.51,0.11,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p069_22_01.jpg","say":"파이프 연결핀 표시예요. 강관을 길게 이어 주는 자리예요."},{"b":[0.58,0.26,0.11,0.05],"c":[0.535,0.23,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p069_22_02.jpg","say":"고정형 **클램프**예요. 가로와 세로가 직각으로 만나는 곳에 써요."},{"b":[0.7,0.25,0.11,0.05],"c":[0.655,0.22,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p069_22_03.jpg","say":"회전형 **클램프**예요. 비스듬한 가새를 물리는 자리예요."},{"b":[0.58,0.52,0.11,0.05],"c":[0.535,0.49,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p069_22_04.jpg","say":"앙카판, 즉 받침대예요. **강관비계** 기둥의 밑면을 받쳐 줘요."}]}},{"p":70,"title":"(1) 강관 비계의 부속품: 안전 발판","terms":["안전 발판","강관비계","비계"],"pass1":[{"kind":"say","lines":["뼈대만 세워 놓으면 사람이 딛고 설 자리가 없어요.","**안전 발판**은 **비계** 틀 위에 까는 철제 바닥판이에요.","구멍이 숭숭 뚫려 있어 미끄럽지 않고 가벼워요."]}],"pass2":[{"kind":"points","head":"**안전 발판**의 정체","items":["높은 장소에 설치한 **비계** 틀 위에서 작업이 쉽도록 설치하는 발판이에요.","자체의 강도가 높으며 설치 및 시공이 간단해요.","공사 이외의 다양한 목적으로도 사용할 수 있어요.","**안전 발판**은 걸이의 형태에 따라 종류가 나뉘어요."]},{"kind":"points","head":"설치 방법과 이동 통로","items":["발판의 설치는 갈고리를 단관파이프에 정확하게 연결하고 흔들리지 않도록 견고하게 고정해요.","**비계**와 **비계** 사이의 수직이동은 가설계단을 설치하여 하도록 해요.","슬라이드 사진에는 계단 발판과 틀**비계**용 계단이 함께 나와요."]},{"kind":"bg","src":"슬라이드 그림 속 치수","lines":["오른쪽 아래 발판 그림에 1829와 400이라는 치수가 적혀 있어요.","길이 1,829mm, 폭 400mm짜리 **안전 발판**을 그린 것이에요.","1,829는 6피트를 mm로 바꾼 값이라 **강관비계** 부재에서 자주 보이는 숫자예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**안전 발판**에 대한 설명으로 옳지 않은 것은?","choices":["자체의 강도가 높으며 설치와 시공이 간단하다","걸이의 형태에 따라 종류가 나뉜다","비계와 비계 사이의 수직이동에 사용하는 계단을 대신한다","갈고리를 단관파이프에 연결하고 흔들리지 않게 고정한다"],"a":2,"why":"비계와 비계 사이의 수직이동은 가설계단을 따로 설치해서 해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.0812],"c":[0,0.0208,0.2,0.1132],"r":3.141,"img":"img/L2/walk/p070_h.jpg"},"parts":[{"b":[0.03,0.36,0.36,0.045],"c":[0.012,0.3275,0.396,0.11],"r":6.4,"img":"img/L2/walk/p070_23_01.jpg","say":"**안전 발판**의 정의예요. 비계 틀 위에서 작업이 쉽도록 까는 발판이에요."},{"b":[0.03,0.5,0.33,0.045],"c":[0.0135,0.4675,0.363,0.11],"r":5.8667,"img":"img/L2/walk/p070_23_02.jpg","say":"걸이의 형태에 따라 종류가 나뉜다는 줄이에요."},{"b":[0.03,0.59,0.35,0.045],"c":[0.0125,0.5575,0.385,0.11],"r":6.2222,"img":"img/L2/walk/p070_23_03.jpg","say":"비계와 비계 사이의 수직이동은 가설계단으로 한다는 줄이에요."},{"b":[0.54,0.12,0.24,0.33],"c":[0.528,0.1035,0.264,0.363],"r":1.2929,"img":"img/L2/walk/p070_23_04.jpg","say":"계단 발판 사진이에요. **강관비계**에 걸어 쓰는 계단이에요."},{"b":[0.52,0.56,0.4,0.39],"c":[0.5,0.5405,0.44,0.429],"r":1.8234,"img":"img/L2/walk/p070_23_05.jpg","say":"발판 치수 그림이에요. 길이 1,829mm, 폭 400mm로 적혀 있어요."}]}},{"p":71,"title":"(1) 강관 비계의 부속품: 브라켓","terms":["브라켓","안전 난간대","비계"],"pass1":[{"kind":"say","lines":["**브라켓**은 벽에 붙이는 까치발이에요.","선반을 벽에 달 때 밑을 받치는 삼각 철물을 떠올리면 돼요.","여기서는 그 위에 **안전 난간대**나 **비계**를 붙들어 매요."]}],"pass2":[{"kind":"points","head":"**브라켓**의 정체","items":["**브라켓**은 추락의 위험 요소가 있는 곳에 난간대를 고정시키기 위하여 사용해요.","외부 **비계**를 고정시킬 때에도 사용되는 가설자재예요.","특히 주의를 필요로 하는 곳에는 감시원을 배치하는 것이 안전해요."]},{"kind":"points","head":"**브라켓**의 종류","items":["슬라이드 본문이 든 종류는 발코니용 **브라켓**, 측벽용 외줄 **브라켓**, 측벽용 쌍줄 **브라켓**이에요.","슬라이드 사진에는 슬라브 **브라켓**, 유로폼 **브라켓**, 비계버팀대도 함께 나와요.","사진 아래 L과 H는 길이와 높이 규격이에요. 예를 들어 측벽용 외줄은 L500, H600으로 적혀 있어요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**브라켓**은 **안전 난간대**를 세우기 바로 전에 벽이나 슬라브에 먼저 붙여요.","**브라켓**이 있어야 그 위에 **안전 난간대**를 고정할 수 있어요.","**브라켓**은 직접 공사성 가설재로 분류돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"추락의 위험이 있는 곳에 난간대를 고정시키고 외부 **비계**를 고정할 때도 쓰는 가설자재는?","choices":["연결핀","브라켓","받침대","안전 발판"],"a":1,"why":"브라켓은 발코니용, 측벽용 외줄, 측벽용 쌍줄 등이 있어요. 받침대는 기둥 밑을 받치는 부속이에요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.36,0.41,0.045],"c":[0.0095,0.3275,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p071_23_01.jpg","say":"**브라켓**의 정의예요. 추락 위험이 있는 곳에 난간대를 고정해요."},{"b":[0.03,0.45,0.45,0.045],"c":[0.0075,0.4175,0.495,0.11],"r":8.0,"img":"img/L2/walk/p071_23_02.jpg","say":"종류 세 가지예요. 발코니용, 측벽용 외줄, 측벽용 쌍줄 **브라켓**이에요."},{"b":[0.48,0.02,0.17,0.3],"c":[0.465,0.004,0.2,0.332],"r":1.071,"img":"img/L2/walk/p071_23_03.jpg","say":"발코니용 **브라켓**이에요. L1000(외줄), L1200(쌍줄)으로 적혀 있어요."},{"b":[0.82,0.02,0.17,0.3],"c":[0.8,0.004,0.2,0.332],"r":1.071,"img":"img/L2/walk/p071_23_04.jpg","say":"측벽용 외줄 **브라켓**이에요. L500 곱하기 H600이에요."},{"b":[0.48,0.325,0.17,0.28],"c":[0.465,0.309,0.2,0.312],"r":1.1396,"img":"img/L2/walk/p071_23_05.jpg","say":"측벽용 쌍줄 **브라켓**이에요. L950 곱하기 H1200이에요."}]}},{"p":72,"title":"(1) 강관 비계의 부속품: 안전 난간대","terms":["안전 난간대","브라켓"],"pass1":[{"kind":"say","lines":["**안전 난간대**는 떨어지지 말라고 세우는 울타리예요.","계단이나 베란다에 있는 난간과 같은 생각이에요.","다만 공사 중에는 임시로 세웠다가 나중에 걷어 내요."]}],"pass2":[{"kind":"points","head":"**안전 난간대**의 정의와 자리","items":["작업자의 추락을 방지하기 위해 작업 발판, 개구부, 계단, 통로 등의 가장자리에 설치하는 안전시설이에요.","가장자리라는 말이 중요해요. 떨어질 수 있는 끝자리마다 세워요.","벽이나 슬라브에 **브라켓**을 먼저 붙이고 그 위에 **안전 난간대**를 고정해요."]},{"kind":"points","head":"세 부분으로 이루어져요","items":["상부 난간대, 중간 난간대, 발끝막이판 등으로 구성해요.","상부와 중간 난간대는 사람의 추락을, 발끝막이판은 자재와 공구의 낙하를 막아요.","충분한 강도와 견고성을 확보하고, 작업 중 임의로 해체하거나 변형하지 않도록 관리해요."]},{"kind":"points","head":"슬라이드 사진 세 가지","items":["슬라브/계단용 난간대는 계단 옆을 따라 비스듬히 설치해요.","발코니용 난간대는 노란색으로 발코니 개구부에 세워져 있어요.","엘리베이터용 난간대는 승강기 출입구를 막는 문짝 모양이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**안전 난간대**의 구성요소로 슬라이드가 든 것이 아닌 것은?","choices":["상부 난간대","중간 난간대","발끝막이판","낙하물 방지망"],"a":3,"why":"안전 난간대는 상부 난간대, 중간 난간대, 발끝막이판으로 구성해요. 낙하물 방지망은 따로 설치하는 가설 시설이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**브라켓**은 붙드는 철물, **안전 난간대**는 울타리 그 자체예요.","발끝막이판은 사람이 아니라 물건이 떨어지는 것을 막아요.","작업이 불편하다고 **안전 난간대**를 임의로 해체하면 안 돼요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2309,0.3212],"c":[0,0.0208,0.2549,0.3533],"r":1.2826,"img":"img/L2/walk/p072_h.jpg"},"parts":[{"b":[0.03,0.36,0.52,0.045],"c":[0.004,0.3247,0.572,0.1156],"r":8.7966,"img":"img/L2/walk/p072_23_01.jpg","say":"정의예요. 작업 발판, 개구부, 계단, 통로의 가장자리에 설치해요."},{"b":[0.03,0.408,0.5,0.045],"c":[0.005,0.3749,0.55,0.1111],"r":8.8009,"img":"img/L2/walk/p072_23_02.jpg","say":"구성 세 가지예요. 상부 난간대, 중간 난간대, 발끝막이판이에요."},{"b":[0.05,0.51,0.28,0.38],"c":[0.036,0.491,0.308,0.418],"r":1.3099,"img":"img/L2/walk/p072_23_03.jpg","say":"슬라브, 계단용 난간대예요. 계단을 따라 비스듬히 설치해요."},{"b":[0.335,0.51,0.28,0.38],"c":[0.321,0.491,0.308,0.418],"r":1.3099,"img":"img/L2/walk/p072_23_04.jpg","say":"발코니용 난간대예요. 노란색으로 개구부를 막고 있어요."},{"b":[0.62,0.51,0.27,0.38],"c":[0.6065,0.491,0.297,0.418],"r":1.2632,"img":"img/L2/walk/p072_23_05.jpg","say":"엘리베이터용 난간대예요. 승강기 출입구를 문짝처럼 막아요."}]}},{"p":73,"title":"(1) 강관 비계의 설치 기준 (숫자)","terms":["강관비계","띠장","장선","가새","벽이음","브라켓"],"pass1":[{"kind":"say","lines":["이 쪽은 이 과목에서 숫자가 가장 많이 나오는 쪽이에요.","**강관비계**를 얼마 간격으로 세워야 하는지를 법으로 정해 두었어요.","숫자는 그림 안에 있으니 그림을 꼭 봐야 해요."]}],"pass2":[{"kind":"points","head":"먼저 방향 이름부터 익혀요","items":["**띠장**방향은 앞에서 봤을 때 긴 가로 방향이에요.","**장선**방향은 옆에서 봤을 때 두께 방향이에요.","**띠장**간격은 앞에서 봤을 때 긴 가로 방향으로 설치된 작업 발판의 사이 높이예요."]},{"kind":"compare","head":"산업안전보건기준에 관한 규칙의 네 가지 기준","cols":["무엇","기준"],"rows":[["**비계**기둥의 간격 (**띠장** 방향)","1.85m 이하"],["**비계**기둥의 간격 (**장선** 방향)","1.5m 이하"],["**띠장** 간격","2.0m 이하"],["제일 윗부분으로부터 31m 되는 지점 밑부분","2개의 강관으로 묶어 세울 것"],["**비계**기둥 간의 적재하중","400kg을 초과하지 않을 것"]]},{"kind":"points","head":"예외도 함께 읽어요","items":["선박, 보트 건조작업이나 장비 반입, 반출 공간이 필요한 작업은 구조검토와 조립도를 만들면 각각 2.7m 이하로 할 수 있어요.","**띠장** 간격 2.0m는 쌍기둥틀 등으로 보강한 경우에는 그러하지 아니해요.","31m 규정은 **브라켓**(까치발) 등으로 보강해 2개의 강관으로 묶는 것 이상의 강도가 유지되면 예외예요."]},{"kind":"points","head":"그림 안에만 있는 기준","items":["**벽이음**은 수평, 수직 방향 5m 이하로 잡아요.","기둥과 구조물 사이의 틈 간격은 300mm 이하예요.","**가새**는 40도에서 60도 방향으로 설치하고 기둥에 결속하며, 기둥간격 10m마다 교차부를 결속해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"산업안전보건기준에 관한 규칙상 **강관비계**의 설치 기준으로 옳지 않은 것을 고르시오.","qko":"비계 숫자 네 개 중에 하나를 틀리게 바꿔 놓고 찾으라는 문제예요.","solve":["기둥 간격은 **띠장** 방향 1.85m 이하, **장선** 방향 1.5m 이하예요.","**띠장** 간격은 2.0m 이하예요.","제일 윗부분으로부터 31m 되는 지점 밑부분은 2개의 강관으로 묶어 세워요.","**비계**기둥 간의 적재하중은 400kg을 초과하지 않아요.","그러므로 적재하중을 600kg이라고 쓴 보기가 틀린 보기예요."],"answer":"적재하중 600kg이라고 적은 보기가 답이에요. 바른 값은 400kg이에요."},{"kind":"english","head":"숫자 네 개를 한 문장으로","en":"기둥 간격은 띠장 방향 1.85m 이하, 장선 방향 1.5m 이하, 띠장 간격은 2.0m 이하로 한다. 윗부분에서 31m 밑부분은 강관 2개로 묶고, 기둥 간 적재하중은 400kg을 넘기지 않는다.","ko":"가로 1.85, 두께 1.5, 높이 2.0, 아래 31m는 2본, 하중 400kg이에요.","tip":"1.85, 1.5, 2.0, 31, 400 다섯 숫자를 순서대로 외워요."},{"kind":"check","q":"**강관비계** **비계**기둥 간의 적재하중 한도는?","choices":["200kg","400kg","600kg","800kg"],"a":1,"why":"비계기둥 간의 적재하중은 400kg을 초과하지 않도록 해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["1.85m는 **띠장** 방향, 1.5m는 **장선** 방향이에요. 둘을 바꿔 내는 문제가 많아요.","2.0m는 기둥 간격이 아니라 **띠장** 간격이에요.","31m는 위에서부터 재요. 아래에서부터가 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.06,0.555,0.38,0.045],"c":[0.041,0.5225,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p073_24_01.jpg","say":"1번 조문이에요. **띠장** 방향 1.85m 이하, **장선** 방향 1.5m 이하."},{"b":[0.06,0.742,0.16,0.045],"c":[0.04,0.7095,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p073_24_02.jpg","say":"2번 조문이에요. **띠장** 간격은 2.0m 이하."},{"b":[0.06,0.818,0.44,0.045],"c":[0.038,0.7855,0.484,0.11],"r":7.8222,"img":"img/L2/walk/p073_24_03.jpg","say":"3번 조문이에요. 윗부분에서 31m 되는 지점 밑부분은 2개의 강관으로 묶어요."},{"b":[0.06,0.902,0.3,0.045],"c":[0.045,0.8695,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p073_24_04.jpg","say":"4번 조문이에요. **비계**기둥 간의 적재하중은 400kg 초과 금지."},{"b":[0.575,0.365,0.09,0.085],"c":[0.52,0.349,0.2,0.117],"r":3.0389,"img":"img/L2/walk/p073_24_05.jpg","say":"그림의 **벽이음** 메모예요. 수평, 수직 방향 5m 이하."},{"b":[0.61,0.045,0.17,0.09],"c":[0.595,0.029,0.2,0.122],"r":2.9144,"img":"img/L2/walk/p073_24_06.jpg","say":"그림의 **가새** 메모예요. 40도에서 60도, 기둥간격 10m마다 교차부 결속."}]}},{"p":74,"title":"(1) 강관 비계 설치 기준 상세도","terms":["강관비계","띠장","장선","벽이음","가새","안전 난간대"],"pass1":[{"kind":"say","lines":["앞쪽의 숫자를 그림 한 장으로 다시 보여 주는 쪽이에요.","글은 제목뿐이고 전부 도면이라 눈으로 확인해야 해요."]}],"pass2":[{"kind":"points","head":"오른쪽 큰 도면에서 읽을 치수","items":["위쪽 가로 치수는 1,850 이하가 이어지고, 맨 왼쪽 한 칸만 1,500 이하예요.","오른쪽 세로 치수는 2,000 이하가 층층이 반복돼요. 이것이 **띠장** 간격이에요.","맨 위 한 칸은 600으로 적혀 있어요. **안전 난간대** 높이 쪽 치수예요."]},{"kind":"points","head":"A, B, C, D 확대 그림","items":["A는 전용 **클램프**를 쓴 **벽이음**이에요.","B는 안전 발판이 **장선**과 **띠장** 위에 얹히는 자리예요.","C는 샛트앙카와 **벽이음**철물로 벽에 고정하는 또 다른 **벽이음**이에요.","D는 받침널이에요. 밑둥잡이와 고정형 베이스 철물이 함께 보여요."]},{"kind":"points","head":"도면 아래 메모 두 개","items":["**벽이음** 부재를 제거하면 횡력 저항이 모자라므로 세 가지를 보완하라고 적혀 있어요.","첫째 **가새** 설치, 둘째 전도방지 버팀대 설치, 셋째 구조계산서 확인이에요.","오른쪽 아래에는 구조계산서상 최대하중을 명기하라는 메모가 있고, 바닥에는 배수로와 수직방망이 그려져 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"슬라이드 도면에서 **벽이음** 부재를 제거할 때 횡력 저항을 보완하는 방법으로 적힌 것이 아닌 것은?","choices":["가새 설치","전도방지 버팀대 설치","구조계산서 확인","적재하중 600kg으로 상향"],"a":3,"why":"가새 설치, 전도방지 버팀대 설치, 구조계산서 확인 세 가지가 적혀 있어요. 적재하중은 400kg을 넘길 수 없어요."}],"walk":{"head":null,"parts":[{"b":[0.5,0.06,0.22,0.12],"c":[0.488,0.044,0.244,0.152],"r":2.8538,"img":"img/L2/walk/p074_23_01.jpg","say":"위쪽 가로 치수예요. 1,850 이하가 이어지고 맨 왼쪽 한 칸만 1,500 이하예요."},{"b":[0.755,0.31,0.06,0.39],"c":[0.685,0.2905,0.2,0.429],"r":0.8288,"img":"img/L2/walk/p074_23_02.jpg","say":"오른쪽 세로 치수예요. 2,000 이하가 층층이 반복되고 맨 위 한 칸은 600이에요."},{"b":[0.29,0.04,0.12,0.2],"c":[0.25,0.024,0.2,0.232],"r":1.5326,"img":"img/L2/walk/p074_23_03.jpg","say":"A 확대예요. 전용 **클램프**를 쓴 **벽이음**이에요."},{"b":[0.29,0.28,0.12,0.2],"c":[0.25,0.264,0.2,0.232],"r":1.5326,"img":"img/L2/walk/p074_23_04.jpg","say":"B 확대예요. 안전 발판이 **장선**과 **띠장** 위에 얹히는 자리예요."},{"b":[0.29,0.755,0.12,0.2],"c":[0.25,0.739,0.2,0.232],"r":1.5326,"img":"img/L2/walk/p074_23_05.jpg","say":"D 확대예요. 받침널, 밑둥잡이, 고정형 베이스 철물이 보여요."},{"b":[0.42,0.87,0.11,0.1],"c":[0.375,0.854,0.2,0.132],"r":2.6936,"img":"img/L2/walk/p074_23_06.jpg","say":"**벽이음** 부재 제거 시 **가새** 설치, 전도방지 버팀대, 구조계산서 확인이에요."}]}},{"p":75,"title":"강관 비계 대 시스템 비계 사진 비교","terms":["강관비계","시스템비계","클램프"],"pass1":[{"kind":"say","lines":["사진 두 장으로 두 **비계**의 차이를 보여 주는 쪽이에요.","왼쪽은 **클램프**로 문 파이프, 오른쪽은 처음부터 끼워지게 만든 부재예요."]}],"pass2":[{"kind":"compare","head":"사진 속 문구 그대로 비교","cols":["가설구조물 (**강관비계**)","일체형 작업발판 (**시스템비계**)"],"rows":[["파이프 **클램프** 풀림 등으로 발판 붕괴사고 위험","조립형 구조로 생산되어 단단하게 설치"],["부재를 하나씩 물려서 사람 손을 많이 탐","조금 더 안전한 구조로 결합됨"]]},{"kind":"points","head":"슬라이드의 참고 문장","items":["최근 건설현장에서는 안전성과 시공 효율성이 높은 **시스템비계**의 사용이 확대되는 추세예요.","**강관비계**는 자유롭지만 **클램프**가 풀릴 수 있다는 약점이 있어요.","**시스템비계**는 일체형이라 풀릴 **클램프**가 아예 없어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"최근 건설현장에서 사용이 확대되는 추세인 **비계**는?","choices":["강관비계","시스템비계","말비계","조립식 비계"],"a":1,"why":"안전성과 시공 효율성이 높은 시스템비계의 사용이 확대되는 추세라고 슬라이드가 두 번 적어 두었어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2698,0.2383],"c":[0,0.0208,0.2968,0.2703],"r":1.9521,"img":"img/L2/walk/p075_h.jpg"},"parts":[{"b":[0.05,0.285,0.51,0.045],"c":[0.0245,0.2508,0.561,0.1133],"r":8.8026,"img":"img/L2/walk/p075_22_01.jpg","say":"참고 문장이에요. **시스템비계**의 사용이 확대되는 추세예요."},{"b":[0.055,0.35,0.27,0.54],"c":[0.0415,0.323,0.297,0.594],"r":0.8889,"img":"img/L2/walk/p075_22_02.jpg","say":"**강관비계**예요. 파이프 **클램프** 풀림 등으로 발판 붕괴사고 위험이라고 적혀 있어요."},{"b":[0.33,0.35,0.3,0.54],"c":[0.315,0.323,0.33,0.594],"r":0.9877,"img":"img/L2/walk/p075_22_03.jpg","say":"**시스템비계**의 일체형 작업발판이에요. 조립형 구조로 생산되어 단단하게 설치돼요."},{"b":[0.645,0.345,0.32,0.39],"c":[0.629,0.3255,0.352,0.429],"r":1.4587,"img":"img/L2/walk/p075_22_04.jpg","say":"**시스템비계**의 결합부예요. 조금 더 안전한 구조로 결합된다고 적혀 있어요."}]}},{"p":76,"title":"(2) 시스템 비계","terms":["시스템비계","강관비계","클램프","가새","벽이음","안전 난간대"],"pass1":[{"kind":"analogy","head":"**시스템비계**는 조립식 가구예요","scene":"나사와 공구로 나무판을 하나씩 물려 만드는 가구가 있고, 구멍과 돌기가 처음부터 맞게 만들어져 끼우기만 하면 되는 조립식 가구가 있어요. 뒤쪽이 훨씬 빠르고 튼튼하게 맞아요.","map":[["나사로 하나씩 물리는 가구","**강관비계**와 **클램프**"],["끼우기만 하면 되는 조립식 가구","**시스템비계**"],["항상 같은 모양으로 완성됨","시공 품질을 일정하게 유지"]]}],"pass2":[{"kind":"points","head":"**시스템비계**의 정의","items":["수직재, 수평재, **가새**재, 작업 발판 등 규격화된 부재를 전용 연결방식으로 조립하는 **비계**예요.","부재 연결을 위한 별도의 **클램프**가 없고 일체형이에요.","부재와 연결방식이 표준화되어 있어 조립, 해체가 비교적 간편하고 시공 품질을 일정하게 유지하기 쉬워요."]},{"kind":"points","head":"장점 네 가지","items":["구조적 안정성과 작업자의 안전 확보에 유리해요.","작업 발판과 **안전 난간대** 등을 체계적으로 설치할 수 있어요.","부재의 반복 사용이 가능하고 현장 관리 및 자재 관리가 비교적 쉬워요.","최근 건설현장에서 **강관비계**보다 **시스템비계**의 사용이 확대되는 추세예요."]},{"kind":"points","head":"오른쪽 설치도의 부위 이름","items":["위에서부터 수직재, **벽이음** 철물(벽연결 철물), **안전 난간대**, **띠장**, **장선**, **가새**가 붙어 있어요.","아래쪽에는 작업발판과 조절형 받침철물이 있어요.","이름들이 **강관비계**와 거의 같아서 부재 이름 문제는 함께 나와요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시스템비계**에 대한 설명으로 옳은 것은?","choices":["부재 연결을 위해 클램프를 반드시 사용한다","규격화된 부재를 전용 연결방식으로 조립하는 일체형이다","최근 사용이 줄어드는 추세이다","부재를 한 번만 쓰고 버린다"],"a":1,"why":"시스템비계는 별도 클램프 없는 일체형이고 부재의 반복 사용이 가능하며 사용이 확대되는 추세예요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["**강관비계**는 파이프 더하기 **클램프**로 숙련이 필요해요.","**시스템비계**는 규격 부재의 **클램프** 없는 일체형이에요.","요즘 확대되는 쪽은 **시스템비계**예요. 반대로 적은 보기는 틀린 보기예요."]}],"walk":{"head":null,"parts":[{"b":[0.2,0.243,0.24,0.04],"c":[0.188,0.208,0.264,0.11],"r":4.2667,"img":"img/L2/walk/p076_23_01.jpg","say":"체크 문구예요. 부재 연결을 위한 별도의 **클램프**가 없고 일체형이에요."},{"b":[0.03,0.283,0.5,0.045],"c":[0.005,0.2499,0.55,0.1111],"r":8.8009,"img":"img/L2/walk/p076_23_02.jpg","say":"정의예요. 수직재, 수평재, **가새**재, 작업 발판 등 규격화된 부재를 조립해요."},{"b":[0.03,0.328,0.57,0.045],"c":[0.0015,0.2872,0.627,0.1267],"r":8.7977,"img":"img/L2/walk/p076_23_03.jpg","say":"표준화되어 조립, 해체가 간편하고 시공 품질을 일정하게 유지하기 쉬워요."},{"b":[0.03,0.463,0.41,0.045],"c":[0.0095,0.4305,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p076_23_04.jpg","say":"**강관비계**보다 **시스템비계**의 사용이 확대되는 추세라는 줄이에요."},{"b":[0.635,0.06,0.36,0.84],"c":[0.604,0.018,0.396,0.924],"r":0.7619,"img":"img/L2/walk/p076_23_05.jpg","say":"오른쪽 설치도예요. 수직재, **벽이음** 철물, **안전 난간대**, **띠장**, **장선**, **가새** 이름이 붙어 있어요."}]}},{"p":77,"title":"(3) 조립식 비계 (이동 틀비계)","terms":["조립식 비계","비계"],"pass1":[{"kind":"say","lines":["**조립식 비계**는 바퀴 달린 **비계**예요.","한자리에 고정하지 않고 밀고 다니면서 일해요.","이동 틀**비계**라는 이름으로도 불러요."]}],"pass2":[{"kind":"points","head":"언제 쓰나요","items":["천장 또는 벽면에 고정**비계**를 설치할 수 없는 경우에 써요.","단기간 공사에 써요.","작업 대상이 넓거나 좁은 공간에서 이동하면서 쓸 수 있어 작업의 효율성이 높아요."]},{"kind":"points","head":"장점과 만드는 방법","items":["넓은 면적 전체에 **비계** 설치를 하지 않아도 되므로 공사비용을 절감할 수 있어요.","공장에서 만들어진 틀과 부품들을 현장에서 조립해서 써요.","슬라이드 사진은 구형(사각 틀)과 신형(말**비계** 모양 틀)을 나란히 보여 줘요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["실내 천장 마감이나 설비 작업처럼 자리를 자주 옮기는 일에 **조립식 비계**가 들어와요.","고정 **비계**를 세울 만큼 오래 걸리지 않는 공사에 맞아요.","더 편하게 움직이고 싶으면 시저 리프트로 바꾸지만 비용이 올라가요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"천장이나 벽면에 고정**비계**를 설치할 수 없는 경우와 단기간 공사에 사용하며 이동하면서 쓰는 **비계**는?","choices":["추락 방호망","시스템 비계","강관 비계","조립식 비계"],"a":3,"why":"공장에서 만든 틀과 부품을 현장에서 조립하고 바퀴로 이동해요. 이동 틀비계라고도 해요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.283,0.4,0.045],"c":[0.01,0.2505,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p077_23_01.jpg","say":"언제 쓰는지예요. 고정비계를 설치할 수 없는 경우와 단기간 공사예요."},{"b":[0.03,0.328,0.55,0.045],"c":[0.0025,0.2894,0.605,0.1222],"r":8.8016,"img":"img/L2/walk/p077_23_02.jpg","say":"이동하면서 쓸 수 있어 작업의 효율성이 높다는 줄이에요."},{"b":[0.03,0.373,0.41,0.045],"c":[0.0095,0.3405,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p077_23_03.jpg","say":"넓은 면적 전체에 비계를 세우지 않아 공사비용을 절감한다는 줄이에요."},{"b":[0.54,0.03,0.17,0.36],"c":[0.525,0.012,0.2,0.396],"r":0.8979,"img":"img/L2/walk/p077_23_04.jpg","say":"구형이에요. 네모난 세로틀을 쌓은 모양이에요."},{"b":[0.71,0.03,0.14,0.36],"c":[0.68,0.012,0.2,0.396],"r":0.8979,"img":"img/L2/walk/p077_23_05.jpg","say":"신형이에요. 바퀴와 아웃트리거가 달려 더 안정적이에요."}]}},{"p":78,"title":"(3) 조립식 비계의 부속품","terms":["조립식 비계","말비계","가새","띠장","안전 난간대"],"pass1":[{"kind":"say","lines":["**조립식 비계**를 이루는 부품들의 이름을 사진으로 보여 주는 쪽이에요.","이름 하나하나를 그림에서 찾아 두면 시험에서 헷갈리지 않아요."]}],"pass2":[{"kind":"points","head":"뼈대가 되는 부품","items":["수직 또는 세로틀(구형)이 기본 틀이고, 신형은 수직 말**비계** 모양이에요.","수평틀은 **띠장**틀이라고도 불러요. 옆으로 누운 틀이에요.","교차 **가새**는 X자로 걸어 틀이 흔들리지 않게 잡아 줘요."]},{"kind":"points","head":"붙는 부품과 굴러가는 부품","items":["난간대와 횡대가 위쪽에 붙어 **안전 난간대** 역할을 해요.","연결핀으로 틀을 위로 이어 쌓아요.","아래에는 조절잭, 바퀴, 스토퍼가 달려요. 조절잭으로 높이를 맞추고 스토퍼로 굴러가지 않게 잠가요."]},{"kind":"points","head":"그림에 적힌 치수","items":["난간대와 횡대는 1,829와 1,219 두 가지 길이가 있어요.","수평틀(**띠장**틀)은 1,829 곱하기 1,050이에요.","수직 또는 세로틀은 1,219 곱하기 1,700, 교차 **가새**는 1,829 곱하기 1,219, 연결핀은 225예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**조립식 비계** 부속품 중 제자리에서 굴러가지 않도록 잠가 주는 것은?","choices":["조절잭","스토퍼","연결핀","횡대"],"a":1,"why":"바퀴로 움직이고 스토퍼로 잠가요. 조절잭은 높이를 맞추는 부품이에요."},{"kind":"warn","head":"옮길 때 조심할 점","items":["슬라이드는 교차 **가새**를 교차 가세로 적어 두었어요. 바른 표기는 **가새**예요.","수평틀과 **띠장**틀은 같은 부품의 두 이름이에요.","구형은 세로틀, 신형은 수직 말**비계** 모양이라는 점만 구별해 두세요."]}],"walk":{"head":null,"parts":[{"b":[0.03,0.66,0.09,0.12],"c":[0,0.644,0.2,0.152],"r":2.3392,"img":"img/L2/walk/p078_23_01.jpg","say":"조절잭이에요. 바닥이 고르지 않을 때 높이를 맞춰요."},{"b":[0.13,0.66,0.09,0.12],"c":[0.075,0.644,0.2,0.152],"r":2.3392,"img":"img/L2/walk/p078_23_02.jpg","say":"바퀴예요. **조립식 비계**를 밀고 다닐 수 있게 해 줘요."},{"b":[0.23,0.6,0.15,0.18],"c":[0.205,0.584,0.2,0.212],"r":1.6771,"img":"img/L2/walk/p078_23_03.jpg","say":"스토퍼예요. 제자리에서 굴러가지 않게 잠가 줘요."},{"b":[0.76,0.02,0.22,0.22],"c":[0.748,0.004,0.244,0.252],"r":1.7213,"img":"img/L2/walk/p078_23_04.jpg","say":"수평틀, 즉 **띠장**틀이에요. 1,829 곱하기 1,050이에요."},{"b":[0.76,0.33,0.22,0.3],"c":[0.748,0.314,0.244,0.332],"r":1.3066,"img":"img/L2/walk/p078_23_05.jpg","say":"왼쪽이 수직 또는 세로틀(구형), 오른쪽이 수직 말**비계**(신형)예요."},{"b":[0.76,0.65,0.22,0.28],"c":[0.748,0.634,0.244,0.312],"r":1.3903,"img":"img/L2/walk/p078_23_06.jpg","say":"교차 **가새**예요. X자로 걸어 흔들림을 막아요."}]}},{"p":79,"title":"(4) 말비계 (우마)","terms":["말비계","비계"],"pass1":[{"kind":"say","lines":["**말비계**는 다리 네 개 위에 발판을 올린 작은 **비계**예요.","생김새가 말을 닮아서 현장에서는 우마라고 불러요.","낮은 천장 작업에 제일 많이 쓰는 물건이에요."]}],"pass2":[{"kind":"points","head":"**말비계**의 정체","items":["다리 형태의 지지대 위에 작업발판을 설치하여 사용하는 간이 **비계**예요.","비교적 낮은 높이에서의 천장, 벽체 마감, 도장, 설비 등의 실내 작업에 주로 써요.","구조가 간단하고 설치, 이동이 편리하여 소규모 작업에 적합해요."]},{"kind":"points","head":"쓸 때 조심할 점","items":["사용 시 작업 발판의 고정상태와 지지부의 안정성을 확인해요.","전도, 추락에 주의해야 해요.","**말비계**는 실내 마감 공정 내내 쓰이는 가장 흔한 **비계**예요."]},{"kind":"bg","src":"슬라이드 사진 속 조립 기준","lines":["슬라이드 오른쪽 사진에 **말비계** 조립 기준이 적혀 있어요.","발판 길이 2m 이하, 높이 120cm 이하, 작업발판 40cm 이상이에요.","지주부재는 75도 이하로 벌리고 하단에는 미끄럼 방지장치를 달아요.","지주부재와 지주부재 사이를 고정시키는 보조부재를 설치해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"다리 형태의 지지대 위에 작업발판을 설치한 간이 **비계**로 우마라고도 하는 것은?","choices":["말비계","시스템비계","강관비계","조립식 비계"],"a":0,"why":"말비계는 낮은 높이의 실내 작업에 주로 써요."},{"kind":"english","head":"짧은 서술로 외워 쓰기","en":"말비계는 다리 형태의 지지대 위에 작업발판을 설치하여 사용하는 간이 비계로, 비교적 낮은 높이의 실내 마감, 도장, 설비 작업에 주로 사용하며 전도와 추락에 주의한다.","ko":"낮은 높이, 실내, 간이, 전도와 추락 주의 네 낱말이면 돼요.","tip":"말비계 하면 우마, 낮은 높이, 실내 작업을 같이 떠올려요."}],"walk":{"head":{"b":[0.0092,0.0368,0.2309,0.2383],"c":[0,0.0208,0.2549,0.2703],"r":1.6765,"img":"img/L2/walk/p079_h.jpg"},"parts":[{"b":[0.03,0.283,0.36,0.045],"c":[0.012,0.2505,0.396,0.11],"r":6.4,"img":"img/L2/walk/p079_23_01.jpg","say":"정의예요. 다리 형태의 지지대 위에 작업발판을 설치한 간이 비계예요."},{"b":[0.03,0.328,0.43,0.045],"c":[0.0085,0.2955,0.473,0.11],"r":7.6444,"img":"img/L2/walk/p079_23_02.jpg","say":"쓰임새예요. 낮은 높이의 천장, 벽체 마감, 도장, 설비 등 실내 작업이에요."},{"b":[0.03,0.418,0.54,0.045],"c":[0.003,0.3805,0.594,0.12],"r":8.8,"img":"img/L2/walk/p079_23_03.jpg","say":"주의할 점이에요. 발판 고정상태와 지지부 안정성을 확인하고 전도, 추락에 주의해요."},{"b":[0.345,0.495,0.24,0.4],"c":[0.333,0.475,0.264,0.44],"r":1.0667,"img":"img/L2/walk/p079_23_04.jpg","say":"**말비계** 조립 기준 그림이에요. 지주부재 75도 이하, 하단에 미끄럼 방지장치예요."},{"b":[0.58,0.495,0.41,0.4],"c":[0.549,0.475,0.451,0.44],"r":1.8222,"img":"img/L2/walk/p079_23_05.jpg","say":"실물 치수예요. 발판 길이 2m 이하, 높이 120cm 이하로 적혀 있어요."}]}},{"p":80,"title":"(5) 시저 리프트 (Scissor Lift)","terms":["Scissor Lift","조립식 비계"],"pass1":[{"kind":"say","lines":["**시저 리프트(Scissor Lift)**는 가위처럼 접혔다 펴지는 승강 장비예요.","사람이 발판 위에 서서 직접 운전해 원하는 자리로 이동해요.","**조립식 비계**의 장점에 이동의 편리성을 보탠 물건이에요."]}],"pass2":[{"kind":"points","head":"**시저 리프트(Scissor Lift)**의 정체","items":["이동틀**비계**, 즉 **조립식 비계**의 장점에 이동의 편리성을 보완한 장비예요.","작업자가 운전을 하여 작업 위치로 이동할 수 있어요.","6~15m의 높이 조절이 자유로워요."]},{"kind":"points","head":"장단점과 실내 사용","items":["작업의 효율성을 높일 수 있으나 이동 틀**비계**보다 사용 비용이 높아요.","전기충전식과 디젤엔진 방식이 있어요.","실내에서는 충전식을 사용하는 것이 바람직해요. 디젤은 매연이 나오기 때문이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시저 리프트(Scissor Lift)**에 대한 설명으로 옳은 것은?","choices":["이동 틀비계보다 사용 비용이 낮다","높이 조절 범위는 1~3m이다","작업자가 운전할 수 없다","실내에서는 전기충전식을 사용하는 것이 바람직하다"],"a":3,"why":"작업자가 운전해 이동하며 6~15m 높이 조절이 자유롭고, 이동 틀비계보다 비용이 높아요."},{"kind":"warn","head":"옮길 때 조심할 점","items":["슬라이드는 디젤엔진 방식을 디젤엔진 빙식으로 적어 두었어요. 오타예요.","6~15m는 **시저 리프트(Scissor Lift)** 하면 바로 따라 나오는 숫자예요.","비용은 이동 틀**비계**보다 높다는 점을 꼭 기억해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.2309,0.2383],"c":[0,0.0208,0.2549,0.2703],"r":1.6765,"img":"img/L2/walk/p080_h.jpg"},"parts":[{"b":[0.03,0.283,0.3,0.045],"c":[0.015,0.2505,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p080_22_01.jpg","say":"정의예요. 이동틀비계의 장점에 이동의 편리성을 보완한 장비예요."},{"b":[0.03,0.328,0.43,0.045],"c":[0.0085,0.2955,0.473,0.11],"r":7.6444,"img":"img/L2/walk/p080_22_02.jpg","say":"핵심 숫자예요. 작업자가 운전하고 6~15m의 높이 조절이 자유로워요."},{"b":[0.03,0.418,0.45,0.045],"c":[0.0075,0.3855,0.495,0.11],"r":8.0,"img":"img/L2/walk/p080_22_03.jpg","say":"실내에서는 충전식을 쓰는 것이 바람직하다는 줄이에요."},{"b":[0.31,0.47,0.27,0.45],"c":[0.2965,0.4475,0.297,0.495],"r":1.0667,"img":"img/L2/walk/p080_22_04.jpg","say":"가위 모양으로 접혔다 펴지는 다리가 보여요. 그래서 시저 리프트예요."}]}},{"p":81,"title":"가설 전기 1) 가설 분전반","terms":["가설 전기","가설 분전반","누전 차단기","안전 릴 케이블"],"pass1":[{"kind":"say","lines":["공사 현장에도 전기가 필요해요. 그런데 아직 정식 전기가 없어요.","그래서 임시로 전기를 끌어다 쓰는 것이 **가설 전기**예요.","그 전기를 나눠 주는 노란 상자가 **가설 분전반**이에요."]}],"pass2":[{"kind":"points","head":"**가설 전기**의 정의","items":["공사에 필요한 전력을 공급하기 위하여 임시 전기를 사용하기 위한 시설이에요.","현장 작업에 쓰는 장비와 조명에 필요한 전력량을 파악하여 적정용량의 전원을 공급해야 해요.","**가설 전기**는 직접 공사성 가설재인 가설전기시설재에 들어가요."]},{"kind":"points","head":"**가설 분전반**과 **누전 차단기**","items":["**가설 분전반**은 공사에 필요한 전력을 임시로 공급해 주는 전기설비예요.","과부하 등의 전기 재해 방지를 위해 반드시 분전함을 이용하여 전기를 사용해야 해요.","분전함에는 **누전 차단기**가 설치되어 있어 과부하가 발생하는 것을 방지해요.","**가설 분전반**의 박스는 스틸 또는 FRP(Fiber Reinforced plastics)를 이용하여 제작돼요."]},{"kind":"points","head":"**안전 릴 케이블**과 관리 수칙","items":["전선의 연결은 **안전 릴 케이블**을 이용하여 작업할 장소까지 연장해 각종 공구를 사용해요.","담당자 이름 및 연락처를 명기하여 분전반을 열어야 할 때 신속히 조치할 수 있게 해요.","지정된 관리자 이외에 조작하지 않도록 시건장치를 설치해야 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**가설 분전반**에 대한 설명으로 옳지 않은 것은?","choices":["박스는 스틸 또는 FRP로 제작한다","분전함에 누전 차단기가 설치되어 과부하를 방지한다","누구나 쉽게 열 수 있도록 시건장치를 달지 않는다","전선은 안전 릴 케이블로 작업 장소까지 연장한다"],"a":2,"why":"지정된 관리자 이외에 조작하지 않도록 시건장치를 설치해야 해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["FRP는 Fiber Reinforced plastics, 즉 섬유강화플라스틱이에요.","**누전 차단기**는 분전함 바깥이 아니라 안에 들어 있어요.","**안전 릴 케이블**은 전선을 감아 두는 통이지 전기를 나눠 주는 장치가 아니에요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p081_h.jpg"},"parts":[{"b":[0.03,0.185,0.41,0.045],"c":[0.0095,0.1525,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p081_23_01.jpg","say":"**가설 전기**의 정의예요. 임시 전기를 사용하기 위한 시설이에요."},{"b":[0.03,0.33,0.71,0.045],"c":[0,0.2736,0.781,0.1578],"r":8.7988,"img":"img/L2/walk/p081_23_02.jpg","say":"반드시 분전함을 이용하여 전기를 사용해야 한다는 줄이에요."},{"b":[0.03,0.375,0.45,0.045],"c":[0.0075,0.3425,0.495,0.11],"r":8.0,"img":"img/L2/walk/p081_23_03.jpg","say":"**누전 차단기**가 설치되어 과부하를 방지한다는 줄이에요."},{"b":[0.03,0.42,0.48,0.045],"c":[0.006,0.3875,0.528,0.11],"r":8.5333,"img":"img/L2/walk/p081_23_04.jpg","say":"박스 재질이에요. 스틸 또는 FRP로 제작돼요."},{"b":[0.22,0.545,0.15,0.34],"c":[0.195,0.528,0.2,0.374],"r":0.9507,"img":"img/L2/walk/p081_23_05.jpg","say":"열린 **가설 분전반**이에요. 안에 **누전 차단기**가 줄지어 있어요."},{"b":[0.785,0.545,0.14,0.24],"c":[0.755,0.529,0.2,0.272],"r":1.3072,"img":"img/L2/walk/p081_23_06.jpg","say":"**안전 릴 케이블**이에요. 전선을 감았다 풀며 작업 장소까지 늘려요."}]}},{"p":82,"title":"가설 전기 2) 가설 조명","terms":["가설 조명","가설 전기"],"pass1":[{"kind":"say","lines":["공사 중인 실내는 창이 막혀 있어 낮에도 캄캄해요.","**가설 조명**은 그 어둠을 밝히려고 임시로 다는 등이에요.","**가설 전기**를 끌어다 **가설 조명**을 켜요."]}],"pass2":[{"kind":"points","head":"**가설 조명**의 정의와 종류","items":["**가설 조명**은 시공 현장 내의 작업을 원활하게 하기 위해 설치한 임시 조명을 말해요.","슬라이드 사진에는 가설 투광등과 받침대가 있어요. 삼각대 위에 큰 등을 올린 모양이에요.","매달기식 가설 전등도 있어요. 천장이나 줄에 매달아 쓰는 알전구 모양이에요."]},{"kind":"points","head":"사진 속 안전 메모","items":["전등파손 방지조치라는 메모가 붙어 있어요.","전등에 보호갓을 설치하여 전등의 파손을 방지하고 감전을 예방해요.","점검 시 등의 파손 및 보호갓의 파손 등을 점검해요."]},{"kind":"warn","head":"옮길 때 조심할 점","items":["슬라이드는 시공 현장을 사공 현장으로 적어 두었어요. 오타예요.","**가설 조명**은 **가설 전기**의 두 번째 항목이라는 자리를 기억해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**가설 조명**에 대한 설명으로 옳은 것은?","choices":["준공 후에도 그대로 두고 사용하는 정식 조명이다","현장 작업을 원활하게 하기 위해 설치한 임시 조명이다","가설 분전반 안에 들어 있는 부품이다","낙하물을 막기 위한 안전시설이다"],"a":1,"why":"가설 조명은 임시 조명이에요. 가설 투광등과 받침대, 매달기식 가설 전등이 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.0966,0.0262],"c":[0,0.0208,0.2,0.0582],"r":6.1092,"img":"img/L2/walk/p082_h.jpg"},"parts":[{"b":[0.03,0.232,0.43,0.045],"c":[0.0085,0.1995,0.473,0.11],"r":7.6444,"img":"img/L2/walk/p082_23_01.jpg","say":"**가설 조명**의 정의예요. 작업을 원활하게 하려고 설치한 임시 조명이에요."},{"b":[0.08,0.355,0.26,0.46],"c":[0.067,0.332,0.286,0.506],"r":1.0048,"img":"img/L2/walk/p082_23_02.jpg","say":"가설 투광등과 받침대예요. 삼각대 위에 큰 등을 올린 모양이에요."},{"b":[0.54,0.065,0.34,0.47],"c":[0.523,0.0415,0.374,0.517],"r":1.2861,"img":"img/L2/walk/p082_23_03.jpg","say":"매달기식 가설 전등이에요. 철망 보호갓을 씌운 알전구와 LED 등이에요."},{"b":[0.63,0.625,0.15,0.3],"c":[0.605,0.609,0.2,0.332],"r":1.071,"img":"img/L2/walk/p082_23_04.jpg","say":"전등파손 방지조치 메모예요. 보호갓으로 파손과 감전을 예방해요."}]}},{"p":83,"title":"보양과 보양재 (1) 합판 (2) 비닐","terms":["보양"],"pass1":[{"kind":"analogy","head":"**보양**은 새 폰에 붙이는 보호필름이에요","scene":"새로 산 휴대폰에 필름을 붙이고 케이스를 씌우지요. 흠집이 날까 봐서요. 다 쓰고 나면 필름은 떼어 내요. 공사장에서도 이미 끝난 마감재 위에 똑같이 덮개를 씌워요.","map":[["보호필름과 케이스","**보양**재"],["흠집, 얼룩 방지","파손, 오손, 훼손 방지"],["다 쓰고 떼어 냄","일정기간 동안 임시로 설치"]]}],"pass2":[{"kind":"points","head":"**보양**의 정의","items":["**보양**은 공사 중 기존시설 또는 완성된 제작물의 파손, 오손, 훼손 등으로부터 방지하기 위한 목적이에요.","일정기간 동안 임시로 설치하는 보호 방법을 말해요.","합판, MDF, 골판지, 하드보드, PVC 패널 등의 재료를 사용해요."]},{"kind":"points","head":"언제 무엇으로 덮나요","items":["벽면 마감이 끝난 뒤 천장에 도장 공사를 할 때는 벽면을 비닐 계열 재료로 **보양**해요.","도장재료가 벽면을 손상시키지 않도록 하는 것이 목적이에요.","바닥 마감 공정이 끝난 뒤에는 주로 합판을 이용하여 **보양**해요."]},{"kind":"compare","head":"**보양**재 (1) 합판과 (2) 비닐","cols":["**보양**재","언제 쓰나","고정 방법"],"rows":[["합판","바닥에 타일이나 석재를 시공했을 경우","합판과 합판의 이음매는 강력한 테이프"],["비닐","벽체 또는 천장 마감재 보호, 도장공사 때 페인트 오염 방지","테이프를 이용하여 고정"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"바닥에 타일이나 석재를 시공한 후 사용하는 **보양**재로 이음매를 강력한 테이프로 붙이는 것은?","choices":["비닐","합판","에어매트","각대"],"a":1,"why":"비닐은 도장 오염 방지, 각대는 코너와 문틀, 에어매트는 충격이 적은 장소에 써요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p083_h.jpg"},"parts":[{"b":[0.03,0.185,0.8,0.045],"c":[0,0.1186,0.88,0.1778],"r":8.7989,"img":"img/L2/walk/p083_23_01.jpg","say":"**보양**의 정의예요. 파손, 오손, 훼손을 막는 임시 보호 방법이에요."},{"b":[0.03,0.23,0.34,0.045],"c":[0.013,0.1975,0.374,0.11],"r":6.0444,"img":"img/L2/walk/p083_23_02.jpg","say":"재료예요. 합판, MDF, 골판지, 하드보드, PVC 패널을 써요."},{"b":[0.03,0.322,0.35,0.045],"c":[0.0125,0.2895,0.385,0.11],"r":6.2222,"img":"img/L2/walk/p083_23_03.jpg","say":"바닥 마감 완료 후에는 주로 합판으로 **보양**한다는 줄이에요."},{"b":[0.035,0.63,0.29,0.3],"c":[0.0205,0.614,0.319,0.332],"r":1.7082,"img":"img/L2/walk/p083_23_04.jpg","say":"합판 **보양** 사진이에요. 이음매를 파란 테이프로 붙여 두었어요."},{"b":[0.36,0.63,0.42,0.3],"c":[0.339,0.614,0.462,0.332],"r":2.4739,"img":"img/L2/walk/p083_23_05.jpg","say":"비닐 **보양** 사진이에요. 가구와 벽을 비닐로 통째로 덮었어요."}]}},{"p":84,"title":"보양재 (3) 골판지 (4) 각대 (5) 고무판 (6) 에어매트","terms":["보양","각대","고무판","에어매트"],"pass1":[{"kind":"say","lines":["**보양**재 여섯 가지 중 나머지 네 가지를 배우는 쪽이에요.","어디를 지키느냐에 따라 재료가 달라져요.","모서리는 **각대**, 곡면은 **고무판**, 약한 충격은 **에어매트**예요."]}],"pass2":[{"kind":"compare","head":"네 가지 **보양**재","cols":["**보양**재","재질","쓰는 곳","숫자"],"rows":[["골판지","플라스틱 또는 종이 제품","흠집의 발생이 예상되는 마감재 보호용","-"],["**각대**","플라스틱 또는 종이 제품","벽체의 코너부분, 목재 문틀의 파손 방지용","-"],["**고무판**","연질 제품","곡면이나 충격이 빈번한 부위","3~5mm 두께"],["**에어매트**","작은 공기주머니가 있는 비닐 제품","비교적 충격이 적은 장소","-"]]},{"kind":"points","head":"사진에서 확인할 것","items":["종이 골판지는 두루마리로 말려 있고 바닥 전체에 깔아 테이프로 이음매를 붙여요.","PVC 골판지는 파란 플라스틱 판이에요. 엘리베이터 안과 복도 벽에 붙여 놓은 사진이 있어요.","**각대**는 문틀 모서리에 세로로 길게 붙어 있고, **고무판**은 바닥 전체에 깐 검은 판이에요.","**에어매트**는 천막지와 함께 써서 큰 면을 덮어요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**보양**은 마감이 끝난 곳에 하는 일이에요. 아직 마감 전이면 덮을 것이 없어요.","**각대**는 사람과 자재가 자주 스치는 모서리에 먼저 붙여요.","**고무판**과 **에어매트**는 충격의 세기에 따라 골라 써요. 강하면 **고무판**, 약하면 **에어매트**예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"보양재의 종류에는 합판, 비닐, 골판지, 각대, 고무판, 에어매트가 있다.","ko":"바닥은 합판, 벽과 천장은 비닐, 흠집은 골판지, 모서리는 각대, 곡면은 고무판, 약한 충격은 에어매트예요.","tip":"합, 비, 골, 각, 고, 에 여섯 글자로 끊어 외워요."},{"kind":"check","q":"3~5mm 두께의 연질 제품으로 곡면이나 충격이 빈번한 부위에 쓰는 **보양**재는?","choices":["에어매트","고무판","각대","골판지"],"a":1,"why":"고무판은 3~5mm 두께예요. 에어매트는 충격이 적은 장소에 써요."},{"kind":"check","q":"벽체의 코너부분과 목재 문틀의 파손 방지용으로 쓰는 **보양**재는?","choices":["각대","고무판","합판","에어매트"],"a":0,"why":"각대는 플라스틱 또는 종이 제품으로 모서리를 지켜요."}],"walk":{"head":{"b":[0.0092,0.0368,0.5102,0.2392],"c":[0,0.0208,0.5612,0.2712],"r":3.6788,"img":"img/L2/walk/p084_h.jpg"},"parts":[{"b":[0.03,0.278,0.39,0.045],"c":[0.0105,0.2455,0.429,0.11],"r":6.9333,"img":"img/L2/walk/p084_23_01.jpg","say":"골판지 줄이에요. 흠집의 발생이 예상되는 마감재 보호용이에요."},{"b":[0.03,0.368,0.41,0.045],"c":[0.0095,0.3355,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p084_23_02.jpg","say":"**각대** 줄이에요. 벽체의 코너부분, 목재 문틀의 파손 방지용이에요."},{"b":[0.03,0.46,0.41,0.045],"c":[0.0095,0.4275,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p084_23_03.jpg","say":"**고무판** 줄이에요. 3~5mm 두께, 곡면이나 충격이 빈번한 부위예요."},{"b":[0.03,0.552,0.4,0.045],"c":[0.01,0.5195,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p084_23_04.jpg","say":"**에어매트** 줄이에요. 작은 공기주머니가 있고 충격이 적은 장소에 써요."},{"b":[0.36,0.6,0.18,0.32],"c":[0.348,0.584,0.204,0.352],"r":1.0303,"img":"img/L2/walk/p084_23_05.jpg","say":"**각대** 사진이에요. 문틀 모서리에 세로로 길게 붙어 있어요."},{"b":[0.54,0.6,0.22,0.32],"c":[0.528,0.584,0.244,0.352],"r":1.2323,"img":"img/L2/walk/p084_23_06.jpg","say":"**고무판** 사진이에요. 바닥 전체에 깐 검은 판이에요."}]}},{"p":85,"title":"현장사무실","terms":["현장사무실","컨테이너 하우스","샌드위치 패널"],"pass1":[{"kind":"say","lines":["공사가 길어지면 도면을 펴고 회의할 자리가 필요해요.","**현장사무실**은 그 일을 하려고 현장에 세운 임시 사무실이에요.","가설사무실이라고도 불러요."]}],"pass2":[{"kind":"points","head":"**현장사무실**의 정의","items":["가설사무실은 공사 진행을 위하여 현장에 설치된 임시 사무실을 말해요.","공사의 규모와 공사기간을 고려하여 설치의 여부 및 규모를 결정해요.","규모에 따라 다르지만 기본적으로 업무용 책상, PC, 프린터, 팩스, 전화기 등이 설치돼요."]},{"kind":"compare","head":"공사 종류에 따라 어디에 두나","cols":["공사","**현장사무실**의 자리"],"rows":[["대형공사 또는 건축과 동시에 진행되는 공사","건물 외부의 별도 건물이나 **컨테이너 하우스**를 이용해 개설"],["건축공사가 마무리되고 마감 공정만 남은 경우","건물 내부에 설치하기도 함"],["중소형 공사 또는 개보수 공사","현장 내에 사무실을 개설"]]},{"kind":"points","head":"현장 내 사무실은 어떻게 만드나요","items":["합판이나 석고보드로 임시용 칸막이를 설치하거나 기존의 구획된 실을 사용해요.","슬라이드 사진 세 장은 건물 내 임시 사무실, **컨테이너 하우스** 사무실, **샌드위치 패널** 사무실(PRE-FAB)이에요.","**컨테이너 하우스**와 **샌드위치 패널** 사무실은 주로 건축 현장이나 건축과 인테리어가 같이 진행되는 현장에서 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**현장사무실**의 설치 여부와 규모를 결정할 때 고려하는 것은?","choices":["발주자의 취향","공사의 규모와 공사기간","감리자의 지시","계약서의 간인 여부"],"a":1,"why":"가설사무실은 공사의 규모와 공사기간을 고려하여 설치의 여부 및 규모를 결정해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p085_h.jpg"},"parts":[{"b":[0.03,0.185,0.37,0.045],"c":[0.0115,0.1525,0.407,0.11],"r":6.5778,"img":"img/L2/walk/p085_23_01.jpg","say":"정의예요. 공사 진행을 위하여 현장에 설치된 임시 사무실이에요."},{"b":[0.03,0.23,0.51,0.045],"c":[0.0045,0.1958,0.561,0.1133],"r":8.8026,"img":"img/L2/walk/p085_23_02.jpg","say":"공사의 규모와 공사기간을 고려해 설치 여부와 규모를 정한다는 줄이에요."},{"b":[0.07,0.515,0.3,0.35],"c":[0.055,0.4975,0.33,0.385],"r":1.5238,"img":"img/L2/walk/p085_23_03.jpg","say":"건물 내 임시 사무실이에요. 책상과 복합기만 놓인 단출한 방이에요."},{"b":[0.38,0.515,0.29,0.35],"c":[0.3655,0.4975,0.319,0.385],"r":1.473,"img":"img/L2/walk/p085_23_04.jpg","say":"**컨테이너 하우스** 사무실이에요. 2층으로 쌓아 계단을 달았어요."},{"b":[0.665,0.515,0.25,0.35],"c":[0.6525,0.4975,0.275,0.385],"r":1.2698,"img":"img/L2/walk/p085_23_05.jpg","say":"**샌드위치 패널** 사무실(PRE-FAB)이에요. 패널로 지은 임시 건물이에요."}]}},{"p":86,"title":"현장사무실의 세 가지 유형","terms":["현장사무실","컨테이너 하우스","샌드위치 패널"],"pass1":[{"kind":"say","lines":["**현장사무실**을 만드는 방법은 세 가지예요.","건물 안에 칸을 막거나, 컨테이너를 놓거나, 패널로 짓거나예요."]},{"kind":"compare","head":"세 가지 유형 한눈에","cols":["유형","한마디로"],"rows":[["임시 칸막이 사무실","건물 안에 칸을 막아 만들어요"],["**컨테이너 하우스**","컨테이너를 개조해 놓아요"],["**샌드위치 패널** 가설 사무실","패널로 임시 건물을 지어요"]]}],"pass2":[{"kind":"points","head":"(1) 임시 칸막이 사무실","items":["건축물 내부에 **현장사무실**을 개설하는 방식이에요.","일반인의 출입이 통제된 장소에서는 각재 또는 메탈 스터드를 골조로 하고 합판이나 석고보드로 마감한 칸막이를 설치해요.","외부 벽체는 임시로 페인트나 벽지 등을 이용하여 마감하기도 해요."]},{"kind":"points","head":"(2) **컨테이너 하우스**","items":["컨테이너를 사무공간으로 사용하도록 개조한 방식이에요.","이동 및 재설치가 간편하며 설치 즉시 사용 가능하므로 시간을 절약할 수 있어요.","대량생산하는 구조물로서 가격이 저렴하며 타 구조물에 비해 경제적이에요.","기능의 측면에서 방수와 차음 및 단열이 우수해요."]},{"kind":"points","head":"(3) **샌드위치 패널** 가설 사무실","items":["강판과 강판 사이에 고밀도의 폴리스티렌을 단열재로 충진한 패널을 사용해요.","단열재가 내장되어 있어 에너지가 절약되고, 냉난방 효율이 높으며 균일한 단열성으로 결로 현상을 방지해요.","아연도 강판을 사용하여 방수 및 방습효과가 높아요.","청소하기 쉽고 벌레 등의 해충이 발생하지 않아 위생적인 환경을 연출할 수 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"현장사무실의 유형에는 임시 칸막이 사무실, 컨테이너 하우스, 샌드위치 패널 가설 사무실이 있다.","ko":"안에 막기, 컨테이너 놓기, 패널로 짓기 세 가지예요.","tip":"칸막이, 컨테이너, 패널. 셋만 외우면 돼요."},{"kind":"check","q":"강판과 강판 사이에 고밀도의 폴리스티렌을 단열재로 충진한 패널로 만든 가설 사무실은?","choices":["임시 칸막이 사무실","컨테이너 하우스","샌드위치 패널 가설 사무실","가설창고"],"a":2,"why":"샌드위치 패널은 아연도 강판을 써서 방수, 방습효과가 높고 결로를 막아요."}],"walk":{"head":{"b":[0.0092,0.0368,0.6368,0.0912],"c":[0,0.0208,0.7005,0.1232],"r":10.1082,"img":"img/L2/walk/p086_h.jpg"},"parts":[{"b":[0.53,0.13,0.21,0.28],"c":[0.518,0.114,0.234,0.312],"r":1.3333,"img":"img/L2/walk/p086_23_01.jpg","say":"건물 내 임시 사무실이에요. **샌드위치 패널**, 경량벽체 등으로 공간을 구획해 써요."},{"b":[0.74,0.13,0.24,0.28],"c":[0.728,0.114,0.264,0.312],"r":1.5043,"img":"img/L2/walk/p086_23_02.jpg","say":"책상, 의자, 컴퓨터, 복합기, 팩스, 회의 테이블이 놓이고 Shop Drawing 설계팀이 상주해요."},{"b":[0.75,0.55,0.2,0.3],"c":[0.738,0.534,0.224,0.332],"r":1.1995,"img":"img/L2/walk/p086_23_03.jpg","say":"벽면에는 도면과 공정표를 붙여 모든 직원이 현장 내용을 볼 수 있게 해요. 안전모 거치대도 있어요."}]}},{"p":87,"title":"공사장 가림막","terms":["공사장 가림막","가설공사"],"pass1":[{"kind":"say","lines":["백화점 한쪽만 공사할 때 큰 벽으로 가려 둔 것을 본 적 있을 거예요.","그것이 **공사장 가림막**이에요.","안이 보이지 않게 가리고 바람도 막아 줘요."]}],"pass2":[{"kind":"points","head":"**공사장 가림막**의 기능","items":["시공 현장의 시각적 차단과 바람을 막아주거나 회사의 홍보를 위한 기능을 가져요.","일시적인 공간이지만 공공 디자인의 역할을 해내요.","동시에 기업의 브랜드 이미지를 높이는 마케팅 도구로서의 역할까지 하고 있어요."]},{"kind":"points","head":"어디에 어떻게 세우나요","items":["백화점, 사무실 등과 같은 넓은 공간에서 부분적 공사를 할 경우에 적용해요.","합판 또는 패널을 이용하며, 도배나 페인트로 도장을 해요.","가설칸막이는 시공하여야 할 면적에서 1m 정도를 내어서 설치해요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["**공사장 가림막**은 **가설공사** 단계에서 제일 먼저 세우는 축에 들어요.","가림막을 세운 다음에야 철거를 시작할 수 있어요.","슬라이드 사진처럼 가림막 면에 그림을 그려 공공 디자인으로 쓰기도 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"가설칸막이, 즉 **공사장 가림막**은 시공하여야 할 면적에서 얼마를 내어서 설치하나요?","choices":["0.5m 정도","1m 정도","2m 정도","3m 정도"],"a":1,"why":"시공할 면적에서 1m 정도를 내어서 설치해요. 작업할 자리를 확보하기 위해서예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1m는 **공사장 가림막**을 내어 세우는 거리예요.","먹매김의 기준먹 높이도 1m라서 헷갈리기 쉬워요. 하나는 거리, 하나는 높이예요.","**공사장 가림막**은 합판 또는 패널로 만들고 도배나 페인트로 마감해요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1477,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p087_h.jpg"},"parts":[{"b":[0.03,0.185,0.5,0.045],"c":[0.005,0.1519,0.55,0.1111],"r":8.8009,"img":"img/L2/walk/p087_23_01.jpg","say":"기능이에요. 시각적 차단, 바람 막기, 회사의 홍보예요."},{"b":[0.03,0.23,0.66,0.045],"c":[0,0.1792,0.726,0.1467],"r":8.798,"img":"img/L2/walk/p087_23_02.jpg","say":"공공 디자인의 역할과 브랜드 이미지 마케팅 도구 역할까지 한다는 줄이에요."},{"b":[0.03,0.368,0.35,0.045],"c":[0.0125,0.3355,0.385,0.11],"r":6.2222,"img":"img/L2/walk/p087_23_03.jpg","say":"핵심 숫자예요. 가설칸막이는 시공할 면적에서 1m 정도를 내어서 설치해요."},{"b":[0.34,0.47,0.27,0.36],"c":[0.3265,0.452,0.297,0.396],"r":1.3333,"img":"img/L2/walk/p087_23_04.jpg","say":"실제 **공사장 가림막** 사진이에요. 도로를 따라 길게 둘러쳤어요."}]}},{"p":88,"title":"기타 가설 관련 시설물","terms":["가설창고","안내간판","가설공사","현장사무실"],"pass1":[{"kind":"say","lines":["**가설공사**의 마지막은 자잘하지만 꼭 있어야 하는 시설들이에요.","창고, 작업장, 화장실, 그리고 **안내간판**이에요.","다 임시로 두었다가 공사가 끝나면 걷어 내요."]}],"pass2":[{"kind":"compare","head":"네 가지 기타 가설 시설물","cols":["시설","무엇을 하나"],"rows":[["**가설창고**","공사와 관련된 기기, 공구류 및 각종 중요 자재들을 보관해요"],["가설작업장","현장 내에서 작업을 할 수 없을 때 현장 근처에 작업실을 만들어 시공 관련 작업을 해요"],["가설화장실","작업의 효율을 위하여 작업장 근처에 임시 화장실을 설치해요"],["**안내간판**","현장의 공사 상황을 알리는 내용을 적어 현장 입구의 벽에 게시해요"]]},{"kind":"points","head":"**안내간판**에 무엇을 적나요","items":["공사개요, 시공회사, 현장소장, 공사기간 등을 기록해요.","현장 입구의 벽에 게시해서 지나가는 사람도 볼 수 있게 해요.","슬라이드 사진 맨 오른쪽의 보라색 판이 실제 **안내간판**이에요."]},{"kind":"points","head":"간접 공사성 가설재로 묶어요","items":["**가설창고**, 가설작업장, 가설화장실, **현장사무실**은 운영 관리상 필요한 시설이에요.","그래서 간접 공사성 가설재로 분류돼요.","**가설공사**를 정리할 때 직접과 간접을 나눠 떠올리면 빠뜨리지 않아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**안내간판**에 기록하는 내용으로 슬라이드가 든 것이 아닌 것은?","choices":["공사개요","시공회사","실행내역서 금액","공사기간"],"a":2,"why":"안내간판에는 공사개요, 시공회사, 현장소장, 공사기간 등을 적어요. 실행내역은 대외비예요."},{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"기타 가설 관련 시설물에는 가설창고, 가설작업장, 가설화장실, 안내간판이 있다.","ko":"보관은 가설창고, 작업은 가설작업장, 생활은 가설화장실, 알림은 안내간판이에요.","tip":"창고, 작업장, 화장실, 간판 네 가지로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1724,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p088_h.jpg"},"parts":[{"b":[0.03,0.185,0.38,0.045],"c":[0.011,0.1525,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p088_23_01.jpg","say":"**가설창고**예요. 기기, 공구류, 중요 자재들을 보관해요."},{"b":[0.03,0.23,0.71,0.045],"c":[0,0.1736,0.781,0.1578],"r":8.7988,"img":"img/L2/walk/p088_23_02.jpg","say":"가설작업장이에요. 현장 근처에 작업실을 만들어 시공 관련 작업을 해요."},{"b":[0.03,0.276,0.39,0.045],"c":[0.0105,0.2435,0.429,0.11],"r":6.9333,"img":"img/L2/walk/p088_23_03.jpg","say":"가설화장실이에요. 작업의 효율을 위해 작업장 근처에 설치해요."},{"b":[0.03,0.322,0.66,0.045],"c":[0,0.2712,0.726,0.1467],"r":8.798,"img":"img/L2/walk/p088_23_04.jpg","say":"**안내간판**이에요. 공사개요, 시공회사, 현장소장, 공사기간을 적어요."},{"b":[0.78,0.46,0.17,0.38],"c":[0.765,0.441,0.2,0.418],"r":0.8506,"img":"img/L2/walk/p088_23_05.jpg","say":"실제 **안내간판** 사진이에요. 공사개요라는 제목이 보여요."}]}},{"p":89,"title":"#3 철거공사 표지","terms":["철거공사","가설공사"],"pass1":[{"kind":"say","lines":["여기부터 2강의 세 번째 덩어리, #3 **철거공사**예요.","현장 작업 순서는 가설 → 철거 → 경량철골 → 마감이에요.","**가설공사**로 판을 깔았으니 이제 옛것을 뜯어낼 차례예요."]}],"pass2":[{"kind":"points","head":"이 덩어리에서 배울 것","items":["**철거공사**가 무엇인지와 공사 전에 해 둘 조치를 먼저 봐요.","그다음 철거공사계획 수립, 철거 공법과 장비, 폐기물 처리가 이어져요.","표지 아래 참고문헌은 **가설공사** 표지와 같은 네 권이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.0,0.0,0.49,0.99],"c":[0,0,0.539,1],"r":0.9582,"img":"img/L2/walk/p089_21_01.jpg","say":"표지 사진은 비계예요. #2 가설공사 표지와 같은 사진을 쓰고 있어요."},{"b":[0.52,0.53,0.11,0.06],"c":[0.475,0.505,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p089_21_02.jpg","say":"#3 **철거공사**예요. 여기부터 세 번째 덩어리가 시작돼요."},{"b":[0.73,0.845,0.26,0.12],"c":[0.714,0.829,0.286,0.152],"r":3.345,"img":"img/L2/walk/p089_21_03.jpg","say":"참고문헌 네 권이에요. **가설공사** 표지와 같은 목록이에요."}]}},{"p":90,"title":"철거공사의 뜻과 주의사항","terms":["철거공사","가설공사"],"pass1":[{"kind":"analogy","head":"**철거공사**는 새로 칠하기 전에 옛 벽지를 뜯는 일이에요","scene":"방 분위기를 바꾸려고 벽지를 새로 바르기로 했어요. 그런데 옛 벽지를 그대로 두고 덧바르면 울퉁불퉁해져요. 먼저 옛 벽지를 깨끗이 뜯고, 뜯은 종이도 다 치워야 새 벽지를 붙일 수 있어요.","map":[["옛 벽지를 뜯는 일","**철거공사**"],["뜯은 종이를 치우는 일","폐자재 정리"],["그다음 새 벽지 붙이기","본 공사 시작"],["뜯기 전에 가구를 덮어 두기","**가설공사**의 보양과 가림막"]]}],"pass2":[{"kind":"points","head":"**철거공사**의 정의와 자리","items":["기존 건축물 내에서 새로이 인테리어 디자인 공사를 할 경우에 기존 시설들을 철거하는 공사예요.","기존 시설이 완전히 철거되고 철거된 폐자재들이 정리되는 선행 작업이 된 후에 본 공사를 시작해요.","그래서 **철거공사**는 **가설공사** 다음, 경량철골공사 앞에 와요."]},{"kind":"compare","head":"**철거공사**는 두 가지로 나뉘어요","cols":["구분","무엇을 뜯나"],"rows":[["마감재를 철거하는 작업","바닥재, 벽재, 천장재 같은 마감재"],["해제작업","구조체를 철거하는 작업"]]},{"kind":"points","head":"왜 안전이 특히 중요한가요","items":["인테리어 디자인 공사의 철거작업 중에는 시설물의 붕괴사고가 발생할 빈도가 높아요.","주로 인력에 의한 작업이 이루어지므로 사고예방을 위해 작업자의 안전교육을 실시해요.","**가설공사** 때 설치한 안전시설이 여기서 제 역할을 해요."]},{"kind":"points","head":"철거 공사 시 주의사항 세 가지","items":["건물 내에 인입되어 있는 상하수도, 전기, 전화, 인터넷, 스프링클러, 덕트 등의 배관설비에 봉인 및 필요한 조치를 미리 해야 해요.","소음, 분진, 비산, 낙하에 대비하여 분진흡입기, 안전망, 방음벽 등을 설치해야 해요.","분진방지를 위해 수시로 물을 뿌려야 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**철거공사** 전에 미리 해야 하는 조치로 옳은 것은?","choices":["상하수도, 전기, 인터넷, 스프링클러, 덕트 등의 배관설비를 봉인한다","분진이 날리도록 창을 모두 연다","안전교육은 철거가 끝난 뒤에 한다","방음벽은 소음이 생긴 뒤에 세운다"],"a":0,"why":"배관설비 봉인은 철거 전에 해요. 분진 방지를 위해 수시로 물을 뿌리는 것도 주의사항이에요."},{"kind":"english","head":"서술형으로 외워 쓰기","en":"철거공사 시에는 배관설비를 미리 봉인하고, 소음과 분진, 비산, 낙하에 대비해 분진흡입기, 안전망, 방음벽을 설치하며, 분진방지를 위해 수시로 물을 뿌린다.","ko":"봉인, 설치, 물 뿌리기 세 가지예요.","tip":"잠그고(봉인), 막고(안전망과 방음벽), 적신다(물)로 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.0966,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L2/walk/p090_h.jpg"},"parts":[{"b":[0.03,0.105,0.56,0.045],"c":[0.002,0.0653,0.616,0.1245],"r":8.7961,"img":"img/L2/walk/p090_24_01.jpg","say":"**철거공사**의 정의예요. 기존 시설들을 철거하는 공사예요."},{"b":[0.03,0.15,0.54,0.045],"c":[0.003,0.1125,0.594,0.12],"r":8.8,"img":"img/L2/walk/p090_24_02.jpg","say":"선행 작업이 된 후 본 공사를 시작한다는 줄이에요. 순서가 여기 나와요."},{"b":[0.03,0.196,0.68,0.045],"c":[0,0.1429,0.748,0.1511],"r":8.8006,"img":"img/L2/walk/p090_24_03.jpg","say":"마감재 철거와 구조체를 철거하는 해제작업으로 나뉜다는 줄이에요."},{"b":[0.03,0.345,0.44,0.22],"c":[0.008,0.329,0.484,0.252],"r":3.4145,"img":"img/L2/walk/p090_24_04.jpg","say":"철거 공사 시 주의사항 상자예요. 배관설비 봉인, 안전망과 방음벽, 물 뿌리기예요."},{"b":[0.03,0.585,0.63,0.33],"c":[0,0.5685,0.693,0.363],"r":3.3939,"img":"img/L2/walk/p090_24_05.jpg","say":"철거 현장 사진이에요. 천장을 뜯고 소형 장비로 바닥을 깨는 모습이에요."}]}},{"p":91,"title":"철거공사계획 수립","terms":["철거공사계획","철거공사","석면"],"pass1":[{"kind":"say","lines":["뜯기 전에 먼저 계획서를 써요.","**철거공사계획**은 무엇을, 어떤 순서로, 어떤 장비로 뜯을지 정해 두는 일이에요.","계획 없이 뜯으면 건물이 무너지거나 남의 배관을 끊어요."]}],"pass2":[{"kind":"points","head":"무엇을 조사하고 정하나요","items":["설계도서와 현장 사전조사를 통해 철거 범위, 대상, 공법 및 작업량을 파악해요.","현장 여건과 철거 대상의 구조, 특성을 고려하여 철거 순서와 공법, 가설 및 보강계획을 수립해요.","작업량에 따라 장비의 종류, 규격, 수량, 작업인원 및 투입시기를 결정하고 공정계획을 수립해요."]},{"kind":"points","head":"안전과 환경에 관한 계획","items":["관련 안전보건기준을 준수하여 추락, 낙하, 붕괴 등의 위험에 대한 안전대책을 수립해요.","작업에 필요한 개인보호구를 준비하고 작업자 안전교육 계획을 수립해요.","주변 환경을 고려하여 소음, 진동, 분진 등의 발생 저감대책을 수립해요."]},{"kind":"points","head":"다른 사람과 미리 이야기할 것","items":["수도, 전기, 가스, 통신 등 기존 설비의 차단과 철거가 필요하면 관계기관 및 관리주체와 사전 협의해요.","구조체를 해체하는 경우 관련 법령에 따른 허가, 신고 대상 여부와 구조안전성 및 가설보강 필요 여부를 검토해요.","장비, 자재, 철거물의 반출입 동선과 운반계획을 수립해요."]},{"kind":"points","head":"폐기물과 **석면**","items":["철거, 해체 폐기물의 분리, 적치, 반출, 운반, 처리 및 재활용 계획을 수립해요.","**석면** 등 유해, 위험물질의 존재 여부를 사전에 조사해요.","**석면**에 해당되는 경우 관련 법령에 따른 별도의 해체, 제거계획을 수립해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**철거공사계획** 수립에 관한 설명으로 옳지 않은 것은?","choices":["설계도서와 현장 사전조사로 철거 범위와 공법을 파악한다","구조체 해체는 허가, 신고 대상 여부를 검토한다","석면 조사는 철거를 시작한 뒤에 한다","소음, 진동, 분진의 발생 저감대책을 세운다"],"a":2,"why":"석면 등 유해, 위험물질은 사전에 조사하고, 해당되면 별도의 해체, 제거계획을 세워요."},{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"철거공사계획에는 철거 범위와 공법 파악, 철거 순서와 가설 보강계획, 장비와 인원 및 공정계획, 안전대책과 안전교육, 소음과 진동, 분진 저감대책, 관계기관 사전 협의, 폐기물 처리계획, 석면 사전조사가 포함된다.","ko":"범위, 순서, 장비, 안전, 환경, 협의, 폐기물, 석면 여덟 덩어리예요.","tip":"무엇을 → 어떻게 → 누가 → 안전 → 이웃 → 쓰레기 → **석면** 순서로 떠올려요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1605,0.1017],"c":[0,0.0208,0.2,0.1337],"r":2.6594,"img":"img/L2/walk/p091_h.jpg"},"parts":[{"b":[0.03,0.155,0.4,0.042],"c":[0.01,0.121,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p091_24_01.jpg","say":"설계도서와 현장 사전조사로 철거 범위, 대상, 공법, 작업량을 파악해요."},{"b":[0.03,0.202,0.49,0.042],"c":[0.0055,0.168,0.539,0.11],"r":8.7111,"img":"img/L2/walk/p091_24_02.jpg","say":"철거 순서와 공법, 가설 및 보강계획을 수립한다는 줄이에요."},{"b":[0.03,0.34,0.4,0.042],"c":[0.01,0.306,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p091_24_03.jpg","say":"추락, 낙하, 붕괴 등의 위험에 대한 안전대책을 수립해요."},{"b":[0.03,0.387,0.37,0.042],"c":[0.0115,0.353,0.407,0.11],"r":6.5778,"img":"img/L2/walk/p091_24_04.jpg","say":"소음, 진동, 분진 등의 발생 저감대책을 수립한다는 줄이에요."},{"b":[0.03,0.478,0.56,0.042],"c":[0.002,0.4368,0.616,0.1245],"r":8.7961,"img":"img/L2/walk/p091_24_05.jpg","say":"구조체를 해체하면 허가, 신고 대상 여부와 구조안전성을 검토해요."},{"b":[0.03,0.616,0.63,0.042],"c":[0,0.567,0.693,0.14],"r":8.8,"img":"img/L2/walk/p091_24_06.jpg","say":"**석면** 등 유해, 위험물질을 사전에 조사하고 별도의 해체 계획을 세워요."}]}},{"p":92,"title":"철거 공법","terms":["압쇄공법","Crusher","backhoe","스프레더","철거공사"],"pass1":[{"kind":"say","lines":["철거하는 방법은 힘을 어디서 가져오느냐로 나뉘어요.","기계 힘, 유압 힘, 폭발 힘, 사람 힘 네 가지예요.","실내 **철거공사**에서는 사람 힘을 쓰는 인력 철거가 가장 흔해요."]},{"kind":"compare","head":"네 가지 힘","cols":["힘","쓰는 곳"],"rows":[["기계력","장비로 뜯기"],["유압력","눌러서 부수기"],["폭발력","거의 사용 안 함"],["인력","실내에서 가장 보편적"]]}],"pass2":[{"kind":"points","head":"실내에서는 인력 철거가 보편적이에요","items":["철거공법에는 기계력, 유압력, 폭발력, 인력 등의 공법이 있어요.","실내건축공사 현장에서의 **철거공사**는 대부분 간단한 공구나 기계 또는 소형 장비들을 이용한 인력에 의한 철거가 보편적이에요.","폭발력에 의한 철거는 화약, 가스의 폭발력을 이용하며 실내에서는 거의 사용하지 않아요."]},{"kind":"points","head":"**압쇄공법**이란","items":["**압쇄공법**은 유압의 힘으로 압축하여 콘크리트 또는 벽돌을 철거하는 방법이에요.","소음과 진동을 방지해요.","콘크리트를 분쇄하여 해체하므로 폐기물 처리가 용이하고 철근의 재생이 가능하므로 경제적이에요."]},{"kind":"points","head":"기계력과 인력에 쓰는 도구","items":["기계력에 의한 철거: **백호우(backhoe)**, 브레이커, 착압기, 커터기, **스프레더**, 잭, **압쇄기(Crusher)**, 각종 드릴류 등이에요.","인력에 의한 철거: 해머, 망치, 정, 톱, 삽 등의 공구를 써요.","**압쇄기(Crusher)**는 **압쇄공법**에 쓰는 장비이고, **백호우(backhoe)**는 팔 끝에 삽이 달린 굴착 장비예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"유압의 힘으로 콘크리트나 벽돌을 압축해 철거하며 소음, 진동이 적고 철근 재생이 가능한 공법은?","choices":["폭발력에 의한 철거","인력에 의한 철거","압쇄공법","핸드 브레이커 철거"],"a":2,"why":"압쇄공법은 폐기물 처리가 용이하고 철근 재생이 가능해 경제적이에요."},{"kind":"check","q":"기계력에 의한 철거 장비로 슬라이드가 들지 않은 것은?","choices":["백호우","스프레더","압쇄기","해머"],"a":3,"why":"해머, 망치, 정, 톱, 삽은 인력에 의한 철거 공구예요."},{"kind":"english","head":"목록형 서술로 외워 쓰기","en":"철거공법에는 기계력, 유압력, 폭발력, 인력에 의한 철거가 있으며, 실내건축공사에서는 인력에 의한 철거가 보편적이고 폭발력은 거의 사용하지 않는다.","ko":"기계, 유압, 폭발, 인력 네 가지에 실내는 인력이라는 한마디를 붙여요.","tip":"기유폭인. 그리고 실내는 인력, 폭발은 거의 안 씀."}],"walk":{"head":{"b":[0.0092,0.0368,0.1091,0.1017],"c":[0,0.0208,0.2,0.1337],"r":2.6594,"img":"img/L2/walk/p092_h.jpg"},"parts":[{"b":[0.03,0.152,0.58,0.09],"c":[0.001,0.1326,0.638,0.1289],"r":8.7992,"img":"img/L2/walk/p092_23_01.jpg","say":"실내건축공사에서는 인력에 의한 철거가 보편적이라는 두 줄이에요."},{"b":[0.03,0.245,0.46,0.09],"c":[0.007,0.229,0.506,0.122],"r":7.3734,"img":"img/L2/walk/p092_23_02.jpg","say":"**압쇄공법** 설명이에요. 소음과 진동을 막고 철근의 재생이 가능해요."},{"b":[0.02,0.355,0.71,0.042],"c":[0,0.2971,0.781,0.1578],"r":8.7988,"img":"img/L2/walk/p092_23_03.jpg","say":"기계력에 의한 철거 장비예요. **백호우(backhoe)**부터 각종 드릴류까지예요."},{"b":[0.02,0.402,0.41,0.042],"c":[0,0.368,0.451,0.11],"r":7.2889,"img":"img/L2/walk/p092_23_04.jpg","say":"폭발력에 의한 철거예요. 옆에 거의 사용 안 함이라고 적혀 있어요."},{"b":[0.02,0.448,0.39,0.042],"c":[0.0005,0.414,0.429,0.11],"r":6.9333,"img":"img/L2/walk/p092_23_05.jpg","say":"인력에 의한 철거예요. 해머, 망치, 정, 톱, 삽을 써요."}]}},{"p":93,"title":"철거 장비: 스프레더, 핸드 브레이커, 유압압쇄기","terms":["스프레더","핸드 브레이커","Crusher","압쇄공법"],"pass1":[{"kind":"say","lines":["장비 세 가지를 사진으로 보여 주는 쪽이에요.","**스프레더**는 벌려서, **핸드 브레이커**는 쪼아서, **압쇄기(Crusher)**는 눌러서 부숴요.","생김새와 소리가 다 달라요."]}],"pass2":[{"kind":"compare","head":"세 장비 비교","cols":["장비","어떻게 부수나","특징"],"rows":[["**스프레더**","쐐기를 틈에 넣고 벌려요","슬라이드에는 사진만 있어요"],["**핸드 브레이커**","끝을 대고 쪼아요","공기압을 연결하여 사용, 전기식과 연료식이 있음, 소음 최고"],["유압**압쇄기(Crusher)**","집게로 눌러서 깨거나 부숴요","소음, 진동 공해 없음"]]},{"kind":"points","head":"**핸드 브레이커** 자세히","items":["공기압을 연결하여 사용해요. 그래서 호스가 늘 함께 다녀요.","전기식과 연료식이 있어요.","슬라이드는 **핸드 브레이커**에 소음 최고라고 적어 두었어요."]},{"kind":"points","head":"유압**압쇄기(Crusher)** 자세히","items":["집게 모양으로 생겼으며, 유압력으로 구조물을 눌러서 깨거나 부숴요.","시공 시 소음, 진동 공해가 없어요.","콘크리트 구조물, 벽돌벽 철거 시 사용해요. 이것이 **압쇄공법**이에요.","슬라이드 사진은 아파트 내 화단 벽체를 철거하는 모습이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["**압쇄기(Crusher)**는 유압 집게, 소음과 진동이 없고 철근 재생이 가능해요.","**핸드 브레이커**는 공기압, 소음이 가장 커요.","둘을 바꿔 내는 문제가 자주 나와요. 유압은 조용, 공기압은 시끄럽다고 외워요."]},{"kind":"check","q":"공기압을 연결하여 사용하며 소음이 가장 큰 철거 장비는?","choices":["유압압쇄기","핸드 브레이커","스프레더","콘크리트 절단기"],"a":1,"why":"핸드 브레이커는 공기압을 연결해 쓰고 전기식과 연료식이 있어요. 유압압쇄기는 소음, 진동 공해가 없어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.0966,0.0551],"c":[0,0.0208,0.2,0.0871],"r":4.0822,"img":"img/L2/walk/p093_h.jpg"},"parts":[{"b":[0.025,0.17,0.17,0.26],"c":[0.01,0.154,0.2,0.292],"r":1.2177,"img":"img/L2/walk/p093_23_01.jpg","say":"**스프레더**예요. 쐐기를 틈에 밀어 넣고 벌려서 깨요."},{"b":[0.245,0.095,0.25,0.105],"c":[0.2325,0.079,0.275,0.137],"r":3.5685,"img":"img/L2/walk/p093_23_02.jpg","say":"**핸드 브레이커** 설명이에요. 공기압을 연결해 쓰고 전기식과 연료식이 있어요."},{"b":[0.46,0.2,0.14,0.25],"c":[0.43,0.184,0.2,0.282],"r":1.2608,"img":"img/L2/walk/p093_23_03.jpg","say":"**핸드 브레이커**에 호스로 공기압을 연결하는 그림이에요."},{"b":[0.59,0.095,0.33,0.135],"c":[0.5735,0.079,0.363,0.167],"r":3.8643,"img":"img/L2/walk/p093_23_04.jpg","say":"유압**압쇄기(Crusher)** 설명이에요. 집게 모양, 소음과 진동 공해가 없어요."},{"b":[0.79,0.27,0.2,0.2],"c":[0.776,0.254,0.224,0.232],"r":1.7165,"img":"img/L2/walk/p093_23_05.jpg","say":"유압**압쇄기(Crusher)** 본체예요. 집게와 유압 펌프가 붙어 있어요."}]}},{"p":94,"title":"철거 장비: 콘크리트 절단기 (커터기)","terms":["콘크리트 절단기"],"pass1":[{"kind":"say","lines":["**콘크리트 절단기**는 커다란 원형 톱이에요.","부수는 것이 아니라 깨끗하게 잘라 내는 장비예요.","현장에서는 커터기라고 부르기도 해요."]}],"pass2":[{"kind":"points","head":"**콘크리트 절단기**의 정체","items":["고속으로 회전하는 원형 톱날이나 앞, 뒤로 움직이는 날을 이용해요.","벽체나 슬라브 절단 시 사용해요.","슬라이드는 이 장비를 커터기라고도 적어 두었어요."]},{"kind":"points","head":"사진에서 볼 것","items":["위쪽 사진은 손에 드는 형태의 **콘크리트 절단기**예요. 커다란 파란 톱날이 달려 있어요.","아래 왼쪽은 벽체 절단, 아래 오른쪽은 바퀴 달린 기계로 바닥 슬라브를 절단하는 모습이에요.","슬라브 절단기는 밀고 다니는 손수레처럼 생겼어요."]},{"kind":"points","head":"공사 순서에서의 자리","items":["문을 새로 뚫거나 벽 일부만 잘라 낼 때 **콘크리트 절단기**를 써요.","부수는 장비와 달리 잘라 내는 장비라 자른 면이 깔끔해요.","물과 함께 써서 분진과 열을 줄여요. 슬라이드 사진에도 바닥이 젖어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"고속으로 회전하는 원형 톱날을 이용해 벽체나 슬라브를 자를 때 쓰는 장비는?","choices":["스프레더","콘크리트 절단기","백호우","압쇄기"],"a":1,"why":"콘크리트 절단기는 커터기라고도 불러요. 앞, 뒤로 움직이는 날을 쓰는 것도 있어요."}],"walk":{"head":{"b":[0.0092,0.0368,0.152,0.1512],"c":[0,0.0208,0.2,0.1832],"r":1.9408,"img":"img/L2/walk/p094_h.jpg"},"parts":[{"b":[0.03,0.19,0.31,0.032],"c":[0.0145,0.151,0.341,0.11],"r":5.5111,"img":"img/L2/walk/p094_23_01.jpg","say":"원리예요. 고속으로 회전하는 원형 톱날이나 앞, 뒤로 움직이는 날을 써요."},{"b":[0.03,0.222,0.17,0.032],"c":[0.015,0.183,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p094_23_02.jpg","say":"쓰는 곳이에요. 벽체나 슬라브 절단 시 사용해요."},{"b":[0.035,0.26,0.22,0.27],"c":[0.023,0.244,0.244,0.302],"r":1.4364,"img":"img/L2/walk/p094_23_03.jpg","say":"손에 드는 **콘크리트 절단기**예요. 커다란 원형 톱날이 달려 있어요."},{"b":[0.035,0.53,0.21,0.38],"c":[0.023,0.511,0.234,0.418],"r":0.9952,"img":"img/L2/walk/p094_23_04.jpg","say":"벽체 절단 장면이에요. 사람이 들고 벽을 세로로 잘라요."},{"b":[0.24,0.53,0.29,0.38],"c":[0.2255,0.511,0.319,0.418],"r":1.3567,"img":"img/L2/walk/p094_23_05.jpg","say":"슬라브 절단 장면이에요. 손수레처럼 밀고 다니는 기계로 바닥을 잘라요."}]}},{"p":95,"title":"폐기물 처리","terms":["건설폐기물","건설폐재류","철거공사"],"pass1":[{"kind":"say","lines":["뜯고 나면 산더미 같은 쓰레기가 남아요.","그것을 종류별로 나눠 담고 허가받은 업체에 넘기는 일이 폐기물 처리예요.","집에서 분리수거하는 것과 원리가 같아요."]}],"pass2":[{"kind":"points","head":"따라야 하는 법과 분리 원칙","items":["건설폐기물의 재활용촉진에 관한 법률 및 관련 처리기준을 준수해요.","철거 과정에서 발생한 폐기물은 종류와 처리방법에 따라 분리하고, 재활용 가능한 폐기물은 우선 분리해요.","폐콘크리트, 폐벽돌 등의 **건설폐재류**와 목재, 금속, 합성수지 등의 폐기물을 종류별로 분리하여 배출, 보관해요."]},{"kind":"points","head":"현장에서 어떻게 두고 어떻게 내보내나요","items":["발생한 폐기물은 현장 내 지정된 장소에 종류별로 구분하여 적정하게 보관해요.","폐기물의 반출경로와 운반방법을 계획하고, 적정한 수집, 운반 방법에 따라 반출해요.","직접 처리하지 않는 **건설폐기물**은 적법한 허가를 받은 수집, 운반업자 및 처리업자에게 위탁하여 처리해요."]},{"kind":"points","head":"재활용과 소규모 현장","items":["재활용 가능한 폐기물은 가능한 범위에서 재활용하여 폐기물 발생량을 최소화해요.","소규모 현장에서 인력으로 반출하는 폐기물은 작업자가 안전하게 취급할 수 있도록 적정 단위로 나누어 포장해요.","슬라이드 사진은 폐자재 마대, 폐자재 임시 야적, 폐자재 수거, 폐자재 운반 순서로 이어져요.","폐기물 정리가 끝나야 **철거공사**가 끝나고 본 공사를 시작할 수 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**철거공사** 폐기물 처리에 관한 설명으로 옳지 않은 것은?","choices":["재활용 가능한 폐기물은 우선 분리한다","현장 내 지정된 장소에 종류별로 구분해 보관한다","직접 처리하지 않는 건설폐기물은 허가받은 업자에게 위탁한다","소규모 현장에서는 한 번에 최대한 많이 담아 옮긴다"],"a":3,"why":"인력으로 반출하는 폐기물은 작업자가 안전하게 취급할 수 있도록 적정 단위로 나누어 포장해요."}],"walk":{"head":{"b":[0.0092,0.0368,0.1219,0.1017],"c":[0,0.0208,0.2,0.1337],"r":2.6594,"img":"img/L2/walk/p095_h.jpg"},"parts":[{"b":[0.03,0.152,0.36,0.042],"c":[0.012,0.118,0.396,0.11],"r":6.4,"img":"img/L2/walk/p095_23_01.jpg","say":"따라야 하는 법이에요. 건설폐기물의 재활용촉진에 관한 법률이에요."},{"b":[0.03,0.245,0.56,0.042],"c":[0.002,0.2038,0.616,0.1245],"r":8.7961,"img":"img/L2/walk/p095_23_02.jpg","say":"**건설폐재류**와 목재, 금속, 합성수지를 종류별로 분리해 배출, 보관해요."},{"b":[0.03,0.383,0.56,0.042],"c":[0.002,0.3418,0.616,0.1245],"r":8.7961,"img":"img/L2/walk/p095_23_03.jpg","say":"직접 처리하지 않는 **건설폐기물**은 허가받은 업자에게 위탁한다는 줄이에요."},{"b":[0.02,0.55,0.19,0.36],"c":[0.008,0.532,0.214,0.396],"r":0.9607,"img":"img/L2/walk/p095_23_04.jpg","say":"폐자재 마대예요. 종류별로 나눠 담아 안전하게 들 수 있는 단위로 포장해요."},{"b":[0.72,0.55,0.26,0.36],"c":[0.707,0.532,0.286,0.396],"r":1.284,"img":"img/L2/walk/p095_23_05.jpg","say":"폐자재 운반이에요. 트럭에 실어 현장 밖으로 반출해요."}]}},{"p":96,"title":"건설 폐기물","terms":["건설폐기물","건설폐재류","오니","건설오니","유리섬유","Rock wool","석면"],"pass1":[{"kind":"say","lines":["무엇이 **건설폐기물**인지는 법이 품목으로 정해 두었어요.","이 쪽은 그 목록과, 헷갈리는 몇 가지 낱말을 설명해요.","시험에는 목록에서 빠지는 것을 고르라는 문제가 나와요."]}],"pass2":[{"kind":"points","head":"법이 지정한 품목","items":["건설폐기물의 재활용촉진에 관한 법률의 시행령이 지정한 목록이에요.","콘크리트, 아스팔트콘크리트, 벽돌, 블럭, 기와, 목재, 합성수지, 섬유, 벽지, **건설오니**, 금속류, 유리예요.","이어서 타일, 도자기, 보드류, 판넬, 토석까지가 **건설폐기물**이에요."]},{"kind":"compare","head":"품목별 설명","cols":["품목","무엇이 들어가나"],"rows":[["합성수지","장판, 스티로폼 등"],["섬유","**유리섬유**, **암면(Rock wool)**, 보온덮개 등"],["보드","석고를 주원료로 한 석고보드, 인테리어 내외 수장재, 보드형태의 마감재 등"],["판넬","콘크리트, 그라스울, 우레탄, 메탈, 목재 등으로 제작된 샌드위치판넬 등"],["토석","공사나 중간 처리 과정에서 나온 흙, 모래, 자갈 등 (자연 상태의 것은 제외)"],["**건설폐재류**","폐콘크리트, 폐아스팔트 콘크리트, 폐벽돌, 폐블럭, 폐기와, 폐토석"]]},{"kind":"points","head":"헷갈리는 낱말 풀이","items":["**오니**는 슬러지라고도 해요. 하수처리 또는 정수과정에서 생긴 침전물이에요.","**건설오니**는 지하 구조물이나 우물 등을 시공할 때 파낸 흙이나, 지반을 견고하게 하려고 주입한 안정화제 같은 무기물질을 함유한 **오니**예요.","**유리섬유**는 유리에 열을 가해서 실처럼 가늘게 뽑아낸 것이에요.","**암면(Rock wool)**은 불연 단열재로, 현무암, 안산암, 사문암, 광재 등을 전기로에 녹여 작은 구멍으로 내뿜으며 냉각시킨 섬유예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"폐**석면**이 함유된 슬레이트와 텍스는 **건설폐기물** 중 보드류에 포함된다.","choices":["맞다","아니다"],"a":1,"why":"폐석면 함유 슬레이트와 텍스 등은 건설폐기물에서 제외돼요."},{"kind":"check","q":"**건설폐재류**에 해당하지 않는 것은?","choices":["폐콘크리트","폐벽돌","폐기와","폐목재"],"a":3,"why":"건설폐재류는 폐콘크리트, 폐아스팔트 콘크리트, 폐벽돌, 폐블럭, 폐기와, 폐토석이에요. 목재는 따로 분류해요."},{"kind":"warn","head":"시험에서 잘 걸리는 함정","items":["폐**석면** 슬레이트와 텍스는 **건설폐기물**에서 제외예요.","토석도 자연 상태의 것은 제외예요. 공사에서 나온 것만 해당돼요.","**오니**는 침전물, **건설오니**는 공사에서 나온 무기물질 섞인 **오니**예요."]}],"walk":{"head":{"b":[0.0092,0.0368,0.1221,0.1312],"c":[0,0.0208,0.2,0.1632],"r":2.1786,"img":"img/L2/walk/p096_h.jpg"},"parts":[{"b":[0.02,0.17,0.86,0.1],"c":[0,0.1244,0.946,0.1911],"r":8.8005,"img":"img/L2/walk/p096_23_01.jpg","say":"법이 지정한 **건설폐기물** 품목이 두 줄로 쭉 나열돼요."},{"b":[0.02,0.37,0.79,0.05],"c":[0,0.3072,0.869,0.1756],"r":8.7978,"img":"img/L2/walk/p096_23_02.jpg","say":"보드 줄이에요. 끝에 폐**석면** 함유 슬레이트와 텍스는 제외라는 함정이 숨어 있어요."},{"b":[0.02,0.51,0.45,0.05],"c":[0,0.48,0.495,0.11],"r":8.0,"img":"img/L2/walk/p096_23_03.jpg","say":"**건설폐재류** 줄이에요. 폐콘크리트부터 폐토석까지 여섯 가지예요."},{"b":[0.02,0.84,0.42,0.09],"c":[0,0.824,0.462,0.122],"r":6.7322,"img":"img/L2/walk/p096_23_04.jpg","say":"왼쪽 아래가 **오니**와 **건설오니** 설명이에요."},{"b":[0.45,0.85,0.5,0.08],"c":[0.425,0.834,0.55,0.112],"r":8.7302,"img":"img/L2/walk/p096_23_05.jpg","say":"오른쪽 아래가 **유리섬유**와 **암면(Rock wool)** 설명이에요."}]}},{"p":97,"title":"폐기물 처리 용역","terms":["폐기물 처리 용역","건설폐기물"],"pass1":[{"kind":"say","lines":["폐기물을 직접 처리하지 않고 전문 업체에 맡기는 것이 **폐기물 처리 용역**이에요.","아무 업체나 되는 것이 아니라 허가받은 업체여야 해요.","그리고 계약서를 3년간 보관해야 해요."]}],"pass2":[{"kind":"points","head":"누구에게 맡기나요","items":["**건설폐기물**은 폐기물의 종류와 처리방법에 적합한 허가를 받은 처리업자에게 위탁하여 적정하게 처리해요.","재활용이 불가능한 가연성 폐기물은 해당 폐기물을 적법하게 소각, 처분할 수 있는 허가업체에 위탁해요.","허가를 받았는지가 **폐기물 처리 용역**의 첫 조건이에요."]},{"kind":"points","head":"계약서에 적을 것과 보관 기간","items":["위, 수탁 계약서에는 폐기물의 종류와 물량, 처리방법 및 장소, 운반경로를 적어요.","계약기간과 금액, 배출자, 운반자, 처리자 등의 정보도 명시해요.","**건설폐기물** 처리용역 위, 수탁 계약서는 3년간 보관해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**건설폐기물** 처리용역 위, 수탁 계약서의 보관 기간은?","choices":["1년","2년","3년","5년"],"a":2,"why":"위, 수탁 계약서는 3년간 보관해요."},{"kind":"english","head":"서술형으로 외워 쓰기","en":"건설폐기물은 종류와 처리방법에 적합한 허가를 받은 처리업자에게 위탁하며, 위, 수탁 계약서에는 폐기물의 종류와 물량, 처리방법과 장소, 운반경로, 계약기간과 금액, 배출자와 운반자, 처리자 정보를 명시하고 3년간 보관한다.","ko":"허가받은 업체, 계약서에 적을 것들, 3년 보관 세 덩어리예요.","tip":"3년이라는 숫자 하나만은 꼭 외워요."}],"walk":{"head":{"b":[0.0092,0.0368,0.15,0.1437],"c":[0,0.0208,0.2,0.1757],"r":2.0237,"img":"img/L2/walk/p097_h.jpg"},"parts":[{"b":[0.03,0.185,0.54,0.042],"c":[0.003,0.146,0.594,0.12],"r":8.8,"img":"img/L2/walk/p097_22_01.jpg","say":"종류와 처리방법에 적합한 허가를 받은 처리업자에게 위탁한다는 줄이에요."},{"b":[0.03,0.232,0.52,0.042],"c":[0.004,0.1952,0.572,0.1156],"r":8.7966,"img":"img/L2/walk/p097_22_02.jpg","say":"가연성 폐기물은 소각, 처분할 수 있는 허가업체에 위탁한다는 줄이에요."},{"b":[0.03,0.278,0.67,0.042],"c":[0,0.2246,0.737,0.1489],"r":8.7993,"img":"img/L2/walk/p097_22_03.jpg","say":"위, 수탁 계약서에 적을 것이에요. 종류, 물량, 처리방법, 운반경로, 금액이에요."},{"b":[0.03,0.325,0.3,0.042],"c":[0.015,0.291,0.33,0.11],"r":5.3333,"img":"img/L2/walk/p097_22_04.jpg","say":"핵심 숫자예요. 위, 수탁 계약서는 3년간 보관해요."}]}},{"p":98,"title":"건설폐기물 처리용역 위수탁 표준계약서 예시","terms":["폐기물 처리 용역"],"pass1":[{"kind":"say","lines":["이 쪽은 표준계약서 세 장을 사진으로 보여 주는 쪽이에요.","**폐기물 처리 용역** 계약서가 실제로 어떻게 생겼는지 눈에 담아 두면 돼요."]}],"pass2":[{"kind":"points","head":"계약서에서 눈에 띄는 칸","items":["맨 위에 건설폐기물 수집, 운반 및 처리용역 위수탁계약서라는 제목이 있어요.","용역명, 배출 장소, 운반 장소(출발지와 도착지), 처리 장소, 결제 조건, 위수탁 계약기간 칸이 있어요.","아래 표에는 폐기물 종류, 단위, 물량, 단가(운반비와 처리비), 용역금액, 처리방법을 적어요.","갑(위탁자, 배출자), 을(수탁자, 수집 운반자), 병(수탁자, 처리자)으로 세 당사자를 적는 점이 특징이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":{"b":[0.0092,0.0368,0.2558,0.1612],"c":[0,0.0208,0.2814,0.1932],"r":2.5894,"img":"img/L2/walk/p098_h.jpg"},"parts":[{"b":[0.05,0.2,0.29,0.73],"c":[0.0355,0.1635,0.319,0.803],"r":0.7062,"img":"img/L2/walk/p098_21_01.jpg","say":"첫 장이에요. 용역명, 배출 장소, 운반 장소, 처리 장소, 폐기물 종류 표가 있어요."},{"b":[0.35,0.2,0.29,0.73],"c":[0.3355,0.1635,0.319,0.803],"r":0.7062,"img":"img/L2/walk/p098_21_02.jpg","say":"용역계약 일반조건 앞부분이에요. 갑, 을, 병 세 당사자의 의무가 적혀 있어요."},{"b":[0.655,0.2,0.31,0.73],"c":[0.6395,0.1635,0.341,0.803],"r":0.7549,"img":"img/L2/walk/p098_21_03.jpg","say":"일반조건 뒷부분이에요. 대가 지급, 계약 해제와 해지 조항이 이어져요."}]}},{"p":99,"title":"[실습] 실측 도면 그리기: 주의사항과 준비물","terms":["실측","레이저 줄자","천장고"],"pass1":[{"kind":"say","lines":["여기부터는 실습이에요. 직접 공간에 가서 치수를 재는 **실측**이에요.","도면은 **실측**에서 시작돼요. 잘못 재면 그 뒤가 전부 틀려요.","그래서 재는 법과 적는 법에 규칙이 있어요."]}],"pass2":[{"kind":"points","head":"**실측** 주의사항","items":["단위는 mm로 적어요. 이것이 첫 번째 규칙이에요.","사진 촬영은 원경과 근경으로 빠지는 곳 없이 찍고, 각 사진이 살짝씩 겹치는 것이 좋아요.","영상도 함께 찍어 두면 나중에 빠진 것이 있을 때 참고하기 좋아요.","천장 및 분전함 내외부 촬영을 잊지 마세요."]},{"kind":"points","head":"적는 요령과 잊기 쉬운 것","items":["외부 파사드 공사도 포함이면 외부 사진도 여러 각도로 찍어요. 나중에 간판이나 사인 디자인에 합성할 수 있어요.","벽체는 검정, 전기는 초록, 수도는 파랑처럼 종류에 따라 색을 구분하면 좋아요.","**천장고**와 벽 두께를 재는 것도 잊지 마세요."]},{"kind":"points","head":"**실측** 준비물","items":["색이 여러 개 있는 볼펜, 딱딱한 클립보드, A4종이 여러 장(방안지면 더 좋아요).","줄자는 5M 이상, 두께가 두꺼운 것으로 준비해요. **레이저 줄자**도 챙겨요.","카메라와 계산기(핸드폰), 편한 복장, 줄자가 무섭다면 3M 장갑도 준비해요.","**레이저 줄자**는 긴 거리와 **천장고**를 잴 때 특히 편해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**실측**할 때 치수를 적는 단위는?","choices":["cm","mm","m","자"],"a":1,"why":"실측 단위는 mm로 적어요. 도면도 mm 단위로 그려요."},{"kind":"warn","head":"잊기 쉬운 것들","items":["천장 및 분전함 내외부 촬영을 빠뜨리기 쉬워요.","**천장고**와 벽 두께도 꼭 재요.","사진은 살짝씩 겹치게 찍어야 빠진 구간이 생기지 않아요."]}],"walk":{"head":{"b":[0.0065,0.0377,0.1927,0.1265],"c":[0,0.0217,0.2167,0.1585],"r":2.4306,"img":"img/L2/walk/p099_h.jpg"},"parts":[{"b":[0.03,0.17,0.16,0.035],"c":[0.01,0.1325,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p099_23_01.jpg","say":"첫 번째 규칙이에요. 단위는 mm로 적어요."},{"b":[0.03,0.213,0.74,0.035],"c":[0,0.1483,0.814,0.1645],"r":8.797,"img":"img/L2/walk/p099_23_02.jpg","say":"사진 촬영 규칙이에요. 원경과 근경으로 빠짐없이, 살짝씩 겹치게 찍어요."},{"b":[0.03,0.385,0.27,0.035],"c":[0.0165,0.3475,0.297,0.11],"r":4.8,"img":"img/L2/walk/p099_23_03.jpg","say":"잊기 쉬운 것이에요. **천장고**와 벽 두께도 꼭 재요."},{"b":[0.08,0.49,0.2,0.38],"c":[0.068,0.471,0.224,0.418],"r":0.9527,"img":"img/L2/walk/p099_23_04.jpg","say":"**실측** 준비물 목록이에요. 볼펜, 클립보드, 종이, 줄자, 카메라예요."},{"b":[0.37,0.45,0.07,0.3],"c":[0.305,0.434,0.2,0.332],"r":1.071,"img":"img/L2/walk/p099_23_05.jpg","say":"**레이저 줄자**예요. 긴 거리와 **천장고**를 잴 때 편해요."}]}},{"p":100,"title":"[실습] 실측 순서, 평면도, 입면도","terms":["실측","평면도","입면도","천장도","레이저 줄자","천장고","커튼박스"],"pass1":[{"kind":"say","lines":["**실측**은 정해진 순서로 해야 빠뜨리지 않아요.","먼저 전체 모습을 대충 그리고, 바닥(**평면도**), 벽(**입면도**), 천장(**천장도**) 순서로 재요.","아래에서 위로 올라간다고 생각하면 쉬워요."]},{"kind":"compare","head":"**실측** 순서","cols":["순서","무엇을 재나"],"rows":[["0. 전체 스케치","공간의 모습을 대략적으로 그려요"],["1. **평면도**","가로 세로 길이와 벽을 따라간 길이"],["2. **입면도**","각 방의 4면, 높이"],["3. **천장도**","천장에 붙은 것들"]]}],"pass2":[{"kind":"steps","head":"2. **평면도** 재는 순서","steps":["전체 가로, 세로 길이 측정: **레이저 줄자**를 쓰고 양쪽 끝과 가운데 3곳을 재서 가장 작은 치수로 결정해요.","입구 위치부터 벽을 따라서 길이를 재요. 벽에 문이나 창문이 뚫려 있는 곳도 재요.","콘센트(C), 스위치(S), 랜(L) 위치를 재요.","공간 중앙에 기둥이 서 있으면 기둥의 사이즈와 벽에서 떨어진 위치도 재요.","분전반, 배수구, 수도, 난방 분배기 등의 위치를 재요."],"answer":"**평면도**는 전체 → 벽 따라 → 설비 위치 순서로 재요."},{"kind":"steps","head":"3. **입면도** 재는 순서","steps":["**천장고**: **레이저 줄자**를 추천해요. 각 방에서 양 끝과 중앙 3군데를 잰 후 가장 낮은 치수로 정해요.","노출천장인 경우 보 높이, 슬라브 높이를 재요.","**커튼박스** 높이: 바닥에서 **커튼박스** 안쪽까지의 높이를 재요.","창문과 문의 높이, 창문이 바닥에서 얼마나 올라왔는지 재요. 필요하면 문틀, 창틀 두께도 재요.","필요한 경우 걸레받이 높이도 재요."],"answer":"**입면도**는 **천장고** → **커튼박스** → 창문과 문 → 걸레받이 순서예요."},{"kind":"points","head":"가장 작은 값을 쓰는 이유","items":["실제 벽은 완전히 반듯하지 않아서 재는 자리마다 길이가 달라요.","가장 작은(낮은) 치수로 정해야 나중에 짠 가구나 벽체가 들어가요.","**평면도**의 가로 세로도, **입면도**의 **천장고**도 똑같이 3곳을 재서 가장 작은 값을 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"exam","src":"문제은행 l23","q":"**실측**에서 전체 가로, 세로 길이를 정하는 방법으로 옳은 것을 고르시오.","qko":"세 군데를 재고 나서 어느 값을 쓰느냐를 묻는 문제예요.","solve":["양쪽 끝과 가운데 3곳을 **레이저 줄자**로 재요.","벽이 반듯하지 않아 세 값이 다르게 나와요.","가장 작은 치수로 정해야 나중에 물건이 들어가요.","**천장고**도 같은 원리로 가장 낮은 치수를 써요."],"answer":"양쪽 끝과 가운데 3곳을 재서 가장 작은 치수로 정해요."},{"kind":"check","q":"**실측** 시 **천장고**는 각 방에서 3군데를 측정한 후 가장 높은 치수로 정한다.","choices":["맞다","아니다"],"a":1,"why":"천장고는 양 끝과 중앙 3군데를 재서 가장 낮은 치수로 정해요."},{"kind":"english","head":"순서 외워 쓰기","en":"실측은 전체 스케치를 먼저 하고 평면도, 각 방 4면의 입면도, 천장도의 순서로 측정하며, 3곳을 재서 가장 작은 치수로 정한다.","ko":"아래에서 위로 올라가고, 값은 늘 가장 작은 것을 써요.","tip":"스케치 → 평면 → 입면 → 천장. 그리고 3곳, 최솟값."}],"walk":{"head":{"b":[0.0065,0.0141,0.1927,0.0591],"c":[0,0,0.2167,0.0911],"r":4.2288,"img":"img/L2/walk/p100_h.jpg"},"parts":[{"b":[0.02,0.085,0.32,0.1],"c":[0.004,0.069,0.352,0.132],"r":4.7407,"img":"img/L2/walk/p100_23_01.jpg","say":"1. **실측** 순서예요. 전체 스케치 다음 **평면도**, **입면도**, **천장도**예요."},{"b":[0.02,0.205,0.6,0.2],"c":[0,0.189,0.66,0.232],"r":5.0575,"img":"img/L2/walk/p100_23_02.jpg","say":"2. **평면도**예요. 3곳을 재서 가장 작은 치수, 콘센트 C, 스위치 S, 랜 L 표기가 핵심이에요."},{"b":[0.02,0.43,0.75,0.2],"c":[0,0.414,0.825,0.232],"r":6.3218,"img":"img/L2/walk/p100_23_03.jpg","say":"3. **입면도**예요. **천장고** 3군데, **커튼박스** 안쪽 높이가 핵심이에요."}]}},{"p":101,"title":"[실습] 천장도","terms":["천장도","천장고","우물조명","점검구","커튼박스","실측"],"pass1":[{"kind":"say","lines":["**천장도**는 천장을 올려다본 모습을 그린 도면이에요.","천장에는 조명, **점검구**, 냉난방기가 붙어 있어요.","그것들의 위치와 크기를 재는 것이 **천장도** **실측**이에요."]}],"pass2":[{"kind":"points","head":"조명과 **우물조명**","items":["조명은 중심 기준으로 간격을 재요. 전체를 다 바꾸는 경우에는 측정이 필요 없어요.","**우물조명**이 있는 경우 **우물조명**의 위치와 크기를 재요.","**우물조명** 부분은 **천장고**가 다르므로 레벨 차이도 재요."]},{"kind":"points","head":"**점검구**와 설비","items":["**점검구** 위치 및 크기를 재요. **점검구**는 천장 속 설비를 살피려고 뚫어 둔 뚜껑이에요.","노출천장인 경우 대략적인 배관 위치를 재고 사진은 필수예요.","냉난방기 위치 및 크기도 재요."]},{"kind":"points","head":"마감재와 **커튼박스**","items":["천장 마감재 사이즈를 재요. 텍스, 루버 등이 있는 경우예요.","**커튼박스**가 있는 경우 너비를 재요.","**입면도**에서는 **커튼박스** 높이를, **천장도**에서는 너비를 잰다는 점을 구별해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**천장도** **실측**에서 재지 않아도 되는 경우는?","choices":["점검구 위치와 크기","조명을 전체 다 변경하는 경우의 조명 간격","냉난방기 위치와 크기","커튼박스 너비"],"a":1,"why":"조명은 중심 기준으로 간격을 재지만, 전체를 다 변경하는 경우에는 측정이 필요 없어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**커튼박스**는 **입면도**에서 높이, **천장도**에서 너비를 재요.","**우물조명**은 위치와 크기에 더해 **천장고** 레벨 차이까지 재요.","노출천장이면 배관 사진이 필수예요."]}],"walk":{"head":{"b":[0.0065,0.0141,0.1927,0.1618],"c":[0,0,0.2167,0.1938],"r":1.9878,"img":"img/L2/walk/p101_h.jpg"},"parts":[{"b":[0.03,0.183,0.42,0.035],"c":[0.009,0.1455,0.462,0.11],"r":7.4667,"img":"img/L2/walk/p101_23_01.jpg","say":"조명은 중심 기준으로 간격을 재요. 전체를 다 바꾸면 측정이 필요 없어요."},{"b":[0.03,0.226,0.38,0.035],"c":[0.011,0.1885,0.418,0.11],"r":6.7556,"img":"img/L2/walk/p101_23_02.jpg","say":"**우물조명**이 있으면 위치와 크기, **천장고** 레벨 차이를 재요."},{"b":[0.03,0.268,0.4,0.035],"c":[0.01,0.2305,0.44,0.11],"r":7.1111,"img":"img/L2/walk/p101_23_03.jpg","say":"**점검구** 위치 및 크기를 재요. 노출천장이면 배관 사진이 필수예요."},{"b":[0.03,0.311,0.19,0.035],"c":[0.018,0.2735,0.214,0.11],"r":3.4586,"img":"img/L2/walk/p101_23_04.jpg","say":"냉난방기 위치 및 크기도 재요."},{"b":[0.03,0.396,0.24,0.035],"c":[0.018,0.3585,0.264,0.11],"r":4.2667,"img":"img/L2/walk/p101_23_05.jpg","say":"**커튼박스**가 있으면 너비를 재요. 높이는 **입면도**에서 쟀어요."},{"b":[0.6,0.35,0.24,0.22],"c":[0.588,0.334,0.264,0.252],"r":1.8624,"img":"img/L2/walk/p101_23_06.jpg","say":"텍스 천장 사진이에요. 마감재 사이즈를 재는 대상이 이런 것이에요."}]}},{"p":102,"title":"[실습] 실측 평면도 예시","terms":["평면도","실측"],"pass1":[{"kind":"say","lines":["글 없이 실제 **실측** 도면 한 장만 있는 쪽이에요.","선 위에 손으로 적은 숫자들이 **실측** 결과예요."]}],"pass2":[{"kind":"points","head":"이 **평면도**에서 볼 것","items":["가운데 넓은 공간이 매장이고, 오른쪽에 방, 화장실, 창고가 붙어 있어요.","빨간 글씨는 잰 치수예요. 벽을 따라 한 칸씩 끊어 적은 것이 보여요.","위쪽에 스테인리스 선홈통(직경 101.6 곱하기 1.2), T80 외단열공법(미장스톤), 철근콘크리트옹벽 같은 재료 메모가 있어요.","아래쪽에는 T30 화강석물갈기, T30 시멘트몰탈, T9 폴리싱타일, 바닥모르타르 같은 마감 메모가 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.25,0.075,0.55,0.06],"c":[0.2225,0.0439,0.605,0.1222],"r":8.8016,"img":"img/L2/walk/p102_21_01.jpg","say":"상단 치수 띠예요. 벽을 따라 한 칸씩 끊어 적은 **실측** 치수예요."},{"b":[0.27,0.03,0.18,0.045],"c":[0.258,0,0.204,0.11],"r":3.297,"img":"img/L2/walk/p102_21_02.jpg","say":"재료 메모예요. 스테인리스 선홈통, 직경 101.6 곱하기 1.2로 적혀 있어요."},{"b":[0.69,0.025,0.23,0.06],"c":[0.678,0.0,0.254,0.11],"r":4.1051,"img":"img/L2/walk/p102_21_03.jpg","say":"재료 메모예요. T80 외단열공법(미장스톤), 철근콘크리트옹벽이에요."},{"b":[0.77,0.19,0.2,0.46],"c":[0.758,0.167,0.224,0.506],"r":0.787,"img":"img/L2/walk/p102_21_04.jpg","say":"오른쪽 실 구성이에요. 방, 화장실, 창고가 차례로 붙어 있어요."},{"b":[0.58,0.845,0.21,0.075],"c":[0.568,0.8275,0.234,0.11],"r":3.7818,"img":"img/L2/walk/p102_21_05.jpg","say":"바닥 마감 메모예요. T30 화강석물갈기, T30 시멘트몰탈, T9 폴리싱타일이에요."}]}},{"p":103,"title":"[실습] 손으로 그린 평면 실측도","terms":["평면도","실측","천장고"],"pass1":[{"kind":"say","lines":["이 쪽은 현장에서 손으로 그린 **평면도** **실측** 스케치예요.","자를 대지 않고 그려도 치수만 정확하면 돼요."]}],"pass2":[{"kind":"points","head":"손그림 **실측**도의 특징","items":["검은 선으로 벽과 문, 창을 그리고 빨간 글씨로 치수를 적었어요.","치수선을 벽 바깥쪽에 여러 겹으로 그어서 부분 치수와 전체 치수를 함께 적어요.","화장실 안의 변기와 세면대처럼 고정된 설비도 자리와 크기를 적어 두었어요.","배운 대로 단위는 mm이고, **천장고**는 따로 적어 두어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.35,0.08,0.33,0.085],"c":[0.3335,0.064,0.363,0.117],"r":5.5157,"img":"img/L2/walk/p103_21_01.jpg","say":"위쪽 치수선이에요. 부분 치수와 전체 치수를 여러 겹으로 그어 적었어요."},{"b":[0.19,0.29,0.075,0.48],"c":[0.1248,0.266,0.2053,0.528],"r":0.6912,"img":"img/L2/walk/p103_21_02.jpg","say":"왼쪽 세로 치수선이에요. 가로와 세로를 따로 재서 적어요."},{"b":[0.26,0.68,0.17,0.2],"c":[0.245,0.664,0.2,0.232],"r":1.5326,"img":"img/L2/walk/p103_21_03.jpg","say":"화장실이에요. 변기와 세면대 같은 고정 설비도 자리와 크기를 적어요."},{"b":[0.18,0.06,0.65,0.87],"c":[0.1475,0.0165,0.715,0.957],"r":1.3282,"img":"img/L2/walk/p103_21_04.jpg","say":"검은 선은 벽과 문, 빨간 글씨는 잰 치수예요. 단위는 mm예요."}]}},{"p":104,"title":"[실습] 손으로 그린 입면 실측도","terms":["입면도","실측","평면도"],"pass1":[{"kind":"say","lines":["마지막 쪽은 손으로 그린 **입면도** **실측** 스케치예요.","벽을 정면에서 본 모습이라 높이 치수가 많아요."]}],"pass2":[{"kind":"points","head":"손그림 **입면도**에서 볼 것","items":["왼쪽 그림은 벽에 뚫린 개구부의 폭과 높이를 적었어요. 아래 1,975 같은 가로 치수가 보여요.","오른쪽 그림은 창문을 정면에서 본 것이에요. 창틀 분할과 높이가 적혀 있어요.","바닥선에서 창이 얼마나 올라왔는지, 창 높이는 얼마인지가 함께 적혀 있어요.","**평면도**에서 벽을 따라 잰 길이와 이 **입면도**의 높이를 합쳐야 공간이 완성돼요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.14,0.34,0.37,0.39],"c":[0.1215,0.3205,0.407,0.429],"r":1.6866,"img":"img/L2/walk/p104_21_01.jpg","say":"왼쪽은 벽에 뚫린 개구부예요. 폭과 높이를 빨간 글씨로 적었어요."},{"b":[0.24,0.665,0.11,0.06],"c":[0.195,0.64,0.2,0.11],"r":3.2323,"img":"img/L2/walk/p104_21_02.jpg","say":"바닥선 아래 가로 치수예요. 1,975로 읽혀요."},{"b":[0.52,0.34,0.33,0.3],"c":[0.5035,0.324,0.363,0.332],"r":1.9438,"img":"img/L2/walk/p104_21_03.jpg","say":"오른쪽은 창문을 정면에서 본 그림이에요. 창틀 분할까지 그렸어요."},{"b":[0.55,0.48,0.07,0.12],"c":[0.485,0.464,0.2,0.152],"r":2.3392,"img":"img/L2/walk/p104_21_04.jpg","say":"창 높이 치수예요. 바닥에서 창이 얼마나 올라왔는지 함께 적어요."}]}}]};
